import { BaseItem1 } from "../common/BaseItem1"
import { BaseItemRenderer } from "../common/BaseItemRenderer"
import { Config } from "../common/Config"
import { CustomHeadItem } from "../common/CustomHeadItem"
import { EventName } from "../common/EventName"
import { ResManager } from "../common/ResManager"
import { WordManager } from "../common/WordManager"
//import { BaseDungeonModel } from "../commonModel/BaseDungeonModel"
import { GoodsModel } from "../commonModel/GoodsModel"
import { GuildModel, GuildEvent } from "../commonModel/GuildModel"
import { RoleManager } from "../role/RoleManager"
import { ColorUtil } from "../util/ColorUtil"
import { GlobalEventSystem } from "../util/DeclareGlobalVar"
import { ErlangParser } from "../util/ErlangParser"
import { Util, Trim, HtmlColorTxt } from "../util/Util"

export class GuildHelpItem extends BaseItemRenderer {
	Emp_btn_cancel
	Emp_btn_go
	_model
	brightSea_model
	role_mgr
	BePlunderText = "<font color=\"#4c3d35\">%s(战力：%s)\n掠夺了%s</font>"

	public WIDTH = 610
	public HEIGT = 120
	is_set
	head
	public constructor(parent) {
		super()
		this.is_set = false
		this.base_file = "guild"
		this.layout_file = "GuildHelpItem"
		this._model = GuildModel.GetInstance()
		// this.brightSea_model = BrightSeaModel.GetInstance()
		this.role_mgr = RoleManager.GetInstance()
		this.head = null

		this.load_callback = () => {
			this.InitEvent()

			if (!this.is_set) {
				this.SetData()
				this.is_set = true
			}
		}

		this.Load()
	}

	public InitEvent() {

		Util.AddClickEvent(
			this._btn_go, () => {
				// 璀璨之海
				if (this.data.type == 3) {
					GlobalEventSystem.Fire(EventName.OPEN_VIEW, "GuildHelpTipsView", this.data)
					return
				}

				if (this.data.is_assist == 0) {
					GlobalEventSystem.Fire(EventName.OPEN_VIEW, "GuildHelpTipsView", this.data)
				} else {
					// let pos = BossModel.GetInstance().GetBossPos(this.data.target_cfg_id, this.data.sub_type)
					// if (pos) {
					// 	this._model.FindWay(pos.x, pos.y)
					// }
				}
			},
			this,
			true
		)
		Util.AddClickEvent(
			this._btn_cancel, () => {
				// 璀璨之海 立即夺回
				if (this.data.type == 3) {
					let extra = this.data.extra[1]
					this.brightSea_model.enemy_fight = extra.rober_power

					let ser_id = this.role_mgr.GetMainRoleVo().server_unique_id
					this.brightSea_model.LaunchBattle(this.data.target_id, ser_id, this.role_mgr.GetMainRoleId(), 2)
				} else {
					this._model.Fire(GuildEvent.REQUEST_PROTO, 40403, "l", this.data.assist_id)
				}
			},
			this,
			true
		)
	}

	public DeleteMe() {

		if (this.head) {
			this.head.DeleteMe()
			this.head = null
		}
		super.DeleteMe()
	}


	SetData() {
		if (!this.data) return
		let data = this.data
		let lv = 0
		let unlock = false
		let role_vo = RoleManager.GetInstance().GetMainRoleVo()
		let is_this = role_vo.role_id == data.role_id
		if (data.type == 1) {
			let mon_desc = ""
			if (data.sub_type == 17) {
				this._lb_module.text = "幻域首领"
				mon_desc = "幻饰首领争夺层"
				//let kv_cfg = ResManager.GetInstance().GetGameConfigFromCache(this, "Decorationbosskv", false)
				//let spec_boss_id = kv_cfg[2].value
				//if (data.target_cfg_id == spec_boss_id ) {
				//unlock = true
				//}else{
				ResManager.GetInstance().LoadGameConfig(this.base_item, "config_decoration_boss", false, null, (decoration_boss) => {
					let cfg = decoration_boss
					let vo = cfg[data.target_cfg_id]
					let condition = ErlangParser.GetInstance().Parse(vo.condition)
					let need_lv = 0
					let need_sorce = 0
					let need_eq_type = 0
					let need_eq_num = 0
					for (let key in condition) {

						let element = condition[key]
						if (element[1] == "lv") {
							need_lv = Number(element[2])
						} else if (element[1] == "decoration_rating") {
							need_sorce = Number(element[2])
						} else if (element[1] == "constellation_suit") {
							need_eq_type = Number(element[2])
							need_eq_num = Number(element[3])
						}
					}
					if (role_vo.level < need_lv) {
						let lv_str = need_lv > 370 && "神创" + (need_lv - 370) || need_lv
						// if (PlatformMgr.GetInstance().IsEyouEnPlatform()) {
						// 	this._lb_cond.text = "Lv." + lv_str + " to unlock"
						// } else {
						this._lb_cond.text = lv_str + "级可解锁"
						// }
					} else {
						let sorce = 0
						let list = GoodsModel.GetInstance().wear_unreal_dic
						for (let key in list) {

							let vo = list[key]
							if (vo) {
								sorce = sorce + vo.overall_rating
							}
						}
						if (sorce < need_sorce) {
							this._lb_cond.text = "幻饰" + WordManager.ConvertNum(need_sorce) + "评分"
						} else {
							if (need_eq_type > 0 && need_eq_num > 0) {
								let num = GoodsModel.GetInstance().GetStarEquipPageNum(need_eq_type, true)
								unlock = num >= need_eq_num
								if (!unlock) {
									ResManager.GetInstance().LoadGameConfig(this.base_item, "config_constellation_page", false, null, (cfg) => {
										let page_cfg = cfg
										let info = page_cfg[need_eq_type]
										this._lb_cond.text = Trim(info.normal_name) + "套装" + need_eq_num + "件"
										ResManager.GetInstance().DestoryGameConfig(this.base_item, "config_constellation_page")
									})
								}
							} else {
								unlock = true
							}
						}
					}
					ResManager.GetInstance().DestoryGameConfig(this.base_item, "config_decoration_boss")
				})

				//}
			} else {
				ResManager.GetInstance().LoadGameConfig(this.base_item, "config_boss_type", false, null, (boss_type) => {
					ResManager.GetInstance().LoadGameConfig(this.base_item, "config_eudemons_boss_cfg", false, null, (eudemons_boss_cfg) => {
						ResManager.GetInstance().LoadGameConfig(this.base_item, "config_boss_cfg", false, null, (boss_cfg) => {

							let cfg = boss_type
							let title = Trim(cfg[data.sub_type].bossname)
							this._lb_module.text = title
							let vo = null
							// if (data.sub_type == BossModel.BossType.eudaemon) {
							// 	vo =eudemons_boss_cfg[data.target_cfg_id]
							// } else {
							vo = boss_cfg[data.target_cfg_id]
							// }
							if (vo) {
								let cond = ErlangParser.GetInstance().Parse(vo.condition)
								for (let _tmpi in cond) {
									var value = cond[_tmpi]
									if (value[1] == "lv") {
										lv = Number(value[2])
										break
									}
								}
								mon_desc = title + vo.layers + "层"
								unlock = role_vo.level >= lv
								let lv_str = lv > 370 && "神创" + (lv - 370) || lv
								// if (PlatformMgr.GetInstance().IsEyouEnPlatform()) {
								// 	this._lb_cond.text = !unlock && "Lv. " + lv_str + " to unlock" || ""
								// } else {
								this._lb_cond.text = !unlock && lv_str + "级可解锁" || ""
								// }

							}
							let bossVo = Config.GetConfigVo(Config.ConfigHasDefaultValue.config_mon.name, data.target_cfg_id, false)
							mon_desc = mon_desc + "\n" + "[" + Trim(bossVo.name) + "] Lv." + bossVo.lv
							this._lb_mon.text = mon_desc
							this._Label2.text = "取消请求"
							ResManager.GetInstance().DestoryGameConfig(this.base_item, "config_boss_cfg")
						})
						ResManager.GetInstance().DestoryGameConfig(this.base_item, "config_eudemons_boss_cfg")
					})

					ResManager.GetInstance().DestoryGameConfig(this.base_item, "config_boss_type")
				})
			}

		} else if (this.data.type == 2) {
			this._Label2.text = "取消请求"
			let dun_cfg = Config.GetConfigVo(Config.ConfigHasDefaultValue.config_dungeon.name, data.target_cfg_id, false)
			let dun_name = ""
			if (data.sub_type == 5) {
				dun_name = "装备副本"
			} else if (data.sub_type == 32) {
				dun_name = "龙纹副本"
			}
			this._lb_module.text = dun_name
			this._lb_mon.text = Trim(dun_cfg.name)
			let cond = ErlangParser.GetInstance().Parse(dun_cfg.condition)
			let dun_id = null
			for (let _tmpi in cond) {
				var value = cond[_tmpi]
				if (value[1] == "lv") {
					lv = Number(value[2])
				} else if (value[1] == "finish_dun_id") {
					dun_id = Number(value[2])
				}
			}
			if (role_vo.level < lv) {
				let lv_str = lv > 370 && "神创" + (lv - 370) || lv
				// if (PlatformMgr.GetInstance().IsEyouEnPlatform()) {
				// 	this._lb_cond.text = "Lv." + lv_str + " to unlock"
				// } else {
				this._lb_cond.text = lv_str + "级可解锁"
				// }
			} else {
				if (dun_id) {
					unlock = true//BaseDungeonModel.GetInstance().IsDragonDunDone(dun_id, dun_cfg)
					if (unlock) {
						this._lb_cond.text = ""
					} else {
						dun_cfg = Config.GetConfigVo(Config.ConfigHasDefaultValue.config_dungeon.name, dun_id, false)
						this._lb_cond.text = "需通关" + Trim(dun_cfg.name)
					}
				} else {
					unlock = true
				}
			}
		} else if (this.data.type == 3) {
			// 璀璨之海
			unlock = true
			this._lb_module.text = "璀璨之海"
			this._Label2.text = "立即夺回"
			let extra = this.data.extra[1]
			let role_name = "<font color=0xa376ff>" + extra.rober_name + "</font>"
			let power = extra.rober_power || 0

			let goods_name = ""
			let goods_tab = []
			if (extra.rober_reward) {
				for (let _tmpi in extra.rober_reward) {
					var info = extra.rober_reward[_tmpi]
					let goods = Config.GetConfigVo(Config.ConfigHasDefaultValue.config_goods.name, info.typeId, false)
					if (goods) {
						goods_tab[info.typeId] = goods_tab[info.typeId] || {}
						let goods_data = goods_tab[info.typeId]
						let color_name = HtmlColorTxt(Trim(goods.goods_name + "X" + info.count), ColorUtil.GetColorLight(goods.color)) || ""
						goods_name = color_name
						goods_data.rober = goods_name
					}
				}
			}

			if (extra.back_reward) {
				for (let _tmpi in extra.back_reward) {
					var info = extra.back_reward[_tmpi]
					let goods = Config.GetConfigVo(Config.ConfigHasDefaultValue.config_goods.name, info.typeId, false)
					if (goods) {
						let goods_data = goods_tab[info.typeId] || {}
						goods_data.back_cnt = info.count
					}
				}
			}

			if (goods_tab) {
				let goods_name = ""
				for (let type_id in goods_tab) {
					var goods_data = goods_tab[type_id]
					goods_name = goods_name + goods_data.rober || ""
					if (goods_data.back_cnt) {
						goods_name = goods_name + "(已追回" + goods_data.back_cnt + "个)"
					}
				}
			}

			this._lb_mon.text = "<font color=0x4c3d35>" + role_name + "(战力：" + String(power) + ")\n掠夺了" + goods_name + "</font>" //string.format(this.BePlunderText, role_name, String(power), goods_name)

			//let head_res = this.brightSea_model.GetHeadRes(this.data)
			//lua_resM:SetOutsideImageSprite(this, this._head, head_res)
			//lua_resM:SetImageSprite(this, this._frame, "mainUI_asset", "uizjm_005")
		}
		this._gp_lock.visible = !unlock
		this._btn_go.visible = unlock && !is_this
		this._btn_cancel.visible = is_this

		this._lb_name.text = data.name
		if (this.head == null) {
			this.head = new CustomHeadItem(this._head)
			this.head.SetActiveLevel(false)
			this.head.Load()
		}
		let head_data = { role_id: data.role_id, career: data.career, picture: data.pic, picture_ver: data.pic_ver }
		this.head.SetRoleVoData(head_data)
	}


	public dataChanged() {


		if (!super.dataChanged()) {
			return
		}
		if (!this.is_loaded) {
			this.is_set = false
		} else {
			this.SetData()
			this.is_set = true
		}

	}
	_Image1: Laya.Image
	_Image2: Laya.Image
	_lb_name: Laya.Label
	_Image4: Laya.Image
	_lb_module: Laya.Label
	_lb_mon: Laya.Label
	_head: Laya.Box
	_btn_go: Laya.Box
	_Image3: Laya.Image
	_Label1: Laya.Label
	_btn_cancel: Laya.Box
	_Image41: Laya.Image
	_Label2: Laya.Label
	_gp_lock: Laya.Box
	_Image5: Laya.Image
	_lb_cond: Laya.Label
	public GetComponents() {
		[
			this._Image1,
			this._Image2,
			this._lb_name,
			this._Image4,
			this._lb_module,
			this._lb_mon,
			this._head,
			this._btn_go,
			this._Image3,
			this._Label1,
			this._btn_cancel,
			this._Image41,
			this._Label2,
			this._gp_lock,
			this._Image5,
			this._lb_cond,
		]
			= this.GetChildrenByNames([

				"_Image1",
				"_Image2",
				"_lb_name",
				"_Image4",
				"_lb_module",
				"_lb_mon",
				"_head",
				"_btn_go",
				"_Image3",
				"_Label1",
				"_btn_cancel",
				"_Image41",
				"_Label2",
				"_gp_lock",
				"_Image5",
				"_lb_cond",
			])
	}
}
window["GuildHelpItem"] = GuildHelpItem