import { BaseView1 } from "../common/BaseView1";
import { LoginModel } from "./LoginModel";
import { PlatformManager } from "../PlatformManager";
import { GlobalEventSystem, ClientConfig } from "../util/DeclareGlobalVar";
import { LoginManager } from "./LoginManager";
import { EventName, LoginStateEvent } from "../common/EventName";
import { Util } from "../util/Util";
import { ResManager } from "../common/ResManager";
import { LOAD_QUEUE } from "../util/DeclareGlobalVar";
import { RoleManager } from "../role/RoleManager";
import { ServerTimeModel } from "../serverTime/ServerTimeModel";
import { Runner } from "../util/Runner";
import { FRAME_TYPE } from "../util/DeclareGlobalVar";
// import { UIDragonBonesModelClass } from "../common/UIDragonBonesModelClass";
import { MovieClip } from "../common/MovieClip";
import { Enum_UILayer } from "../common/LayerManager";
// import { StoryAnimationModel } from "../storyAnimation/StoryAnimationModel";
import { TimeUtil } from "../util/TimeUtil";
import { Message } from "../sysinfo/SysInfoController";
export class LoginLoadingView extends BaseView1 {
    private _img_bg: Laya.Image;
    private _front_img: Laya.Image;
    private _gp_con: Laya.Box;
    private _gp_progress: Laya.Box;
    private _img_line: Laya.Image;
    private _gp_dragon: Laya.Box;
    private _gp_effect: Laya.Box;
    private _gp_effect0: Laya.Box;
    private _lb_load: Laya.Label;
    private down_txt: Laya.Label;
    private copy_right: Laya.Label;
    private _gp_con0: Laya.Box;
    private _img_bg0: Laya.Image;
    private _img_bg1: Laya.Image;
    private _img_icon: Laya.Image;
    private _gp_effect1: Laya.Box;
    Local_Open;
    InitEvent;
    Update;
    SetCopyRight;
    LoadSuccess;
    LoadOtherRes;
    OnChange;
    ShowTipsTween;
    TryCloseLoading;
    ClearTimer;
    Remove;
    public constructor() {
        super();
        let login_model = LoginModel.GetInstance(), platform_mgr = PlatformManager.GetInstance(), local_GlobalEventSystem = GlobalEventSystem, local_LoginManager_Instance = LoginManager.GetInstance(), local_EventName = EventName, local_LoginStateEvent = LoginStateEvent, local_LoginModel = LoginModel, local_Util = Util, res_mgr = ResManager.GetInstance(), role_mgr = RoleManager.GetInstance(), server_time_model = ServerTimeModel.GetInstance(), runner = Runner.GetInstance(), count_down_state_, game_start_state_, _move_speed_ = 80, left_time_ = 12, //超时多久关闭加载界面
        time_id_, mc_obj_: MovieClip, _front_img_width_ = 632, _should_be_close_ = false, alpha_state_to_close_ = false, _last_curr_target_value_ = 0, tween_trigger_ = true;
        this.base_file = "login";
        this.layout_file = "LoginLoadingView";
        this.layer_value = Enum_UILayer.Top;
        this.is_center = true;
        this.destroy_imm = true;
        this.is_delay_callback = false;
        this.need_loading_view = false;
        this.not_show_main_msg = true;
        this.not_show_attr_main_msg = true;
        this.use_background = true;
        this.background_alpha = 2;
        this.not_close_by_android_back_key = true;
        this.load_callback = function () {
        };
        this.open_callback = function () {
            this.LoadSuccess();
        };
        this.destroy_callback = function () {
            // if (login_model.is_new_career && login_model.new_select_sex && !platform_mgr.is_alpha && !platform_mgr.need_alpha_open_charge
            //     && !ClientConfig.not_show_story_animation) {
            //     local_GlobalEventSystem.Fire(local_EventName.OPEN_STORY_ANIMATION_VIEW, login_model.new_select_sex);
            // }
            // else {
                local_GlobalEventSystem.Fire(local_EventName.HIDE_OR_SHOW_CANVAS_LAYER, true);
                // if (login_model.is_new_career) {
                //     StoryAnimationModel.GetInstance().Fire(StoryAnimationModel.STORYANIMATION_CLOSE);
                // }
            // }
            platform_mgr.DataPlacement(90009); //到达游戏场景
            this.Remove();
        };
        this.preload_client_config = {
            "ConfigLoadingBgTime": false
        };
        this.Local_Open = () => {
            count_down_state_ = game_start_state_ = _should_be_close_ = false;
            this.InitEvent();
            super.Open();
        };
        this.InitEvent = () => {
            this.BindEvent(local_GlobalEventSystem, local_EventName.GAME_START, () => {
                Laya.timer.callLater(this, () => {
                    game_start_state_ = true;
                    _move_speed_ = 200;
                    login_model.curr_enter_game_loading_step += 5;
                    this.TryCloseLoading();
                });
            });
            this.BindEvent(local_LoginManager_Instance, local_LoginStateEvent.REFRESH_LODINGVIEW_LOCK_FLAG, () => {
                login_model.curr_enter_game_loading_step += 3;
                this.TryCloseLoading();
            });
            this.BindEvent(local_GlobalEventSystem, local_EventName.CHANGE_ACCOUNT, () => {
                this.Close();
            });
        };
        this.Update = (now_time, elapse_time) => {
            if (this._front_img) {
                let curr_target_value = this._front_img.width + _move_speed_ * Math.min(elapse_time, 0.1);
                // let curr_target_value
                // if (1 || login_model.reconnect_on_game) {
                // 	curr_target_value = _front_img_width_
                // } else {
                // 	curr_target_value = Math.min(Math.floor(login_model.curr_enter_game_loading_step / login_model.max_enter_game_loading_step * _front_img_width_), _front_img_width_)
                // }
                // curr_target_value = Math.max(curr_target_value, _last_curr_target_value_)
                // _last_curr_target_value_ = curr_target_value
                // if (this._front_img.width >= curr_target_value) {
                // 	this._front_img.width = curr_target_value
                // }
                if (curr_target_value >= (_front_img_width_ * 0.98)) {
                    this._front_img.width = _front_img_width_ * 0.98;
                    count_down_state_ = true;
                    // Message.show("------COUNT_DOWN------")
                    // runner.RemoveRunObj(this)
                    this.TryCloseLoading();
                }
                else {
                    this._front_img.width = curr_target_value;
                }
                this.OnChange();
            }
            if (_should_be_close_) {
                _should_be_close_ = false;
                this.Close();
            }
        };
        this.SetCopyRight = () => {
            if (ClientConfig && ClientConfig.copy_right && String(ClientConfig.copy_right).trim() != "") {
                this.copy_right.visible = true;
                this.copy_right.text = ClientConfig.copy_right;
            }
            else {
                this.copy_right.visible = false;
            }
        };
        this.LoadSuccess = async () => {
            [this._img_bg,
                this._front_img,
                this._gp_con,
                this._gp_progress,
                this._img_line,
                this._gp_dragon,
                this._gp_effect,
                this._gp_effect0,
                this._lb_load,
                this.down_txt,
                this.copy_right,
                this._gp_con0,
                this._img_bg0,
                this._img_bg1,
                this._img_icon,
                this._gp_effect1] = this.GetChildrenByNames([
                    "_img_bg",
"_front_img",
"_gp_con",
"_gp_progress",
"_img_line",
"_gp_dragon",
"_gp_effect",
"_gp_effect0",
"_lb_load",
"down_txt",
"copy_right",
"_gp_con0",
"_img_bg0",
"_img_bg1",
"_img_icon",
"_gp_effect1"
                ])
            //超时关闭 防止卡在加载界面
            //  time_id_ = Laya.setTimeout(() => {
            //  	this.Close()
            //  }, this, left_time_ * 1000 + 500)
            // this.copy_right.visible = PlatformManager.IsAiFengGamePlatform()
            this.down_txt.centerX = 0;
            if (PlatformManager.IsEyouEnPlatform()) {
                this.down_txt.visible = false;
            }
            this.SetCopyRight();
            login_model.is_show_loading_view = true;
            local_GlobalEventSystem.Fire(local_EventName.DELAY_SHOW_FIGHTUP, true);
            // let login_cfg = await local_Util.LoadClientConfig("ConfigLogin")
            login_model.curr_enter_game_loading_step += 1;
            let validata_list = [];
            if (local_Util.IsWXGame() || local_Util.IsDouYinGame() || local_Util.IsMeiTuanGame() || local_Util.IsBiLiBiLiGame() || local_Util.IsQQGame() || local_Util.IsBaiduGame() || (!platform_mgr.is_alpha && !platform_mgr.need_alpha_open_charge)) {
                let cfg = res_mgr.GetGameConfigFromCache(this, "ConfigLoadingBgTime", true);
                let mainrole_level = role_mgr.GetMainRoleVo().level;
                let curr_open_server_day = server_time_model.GetOpenServerDay();
                let curr_merge_server_day = server_time_model.GetMergeServerDay();
                let curr_time = TimeUtil.getServerTime();
                let list;
                let curr_week = new Date(curr_time).getDay();
                for (let id in cfg) {
                    list = cfg[id];
                    for (let vo of list) {
                        if (mainrole_level >= vo.min_level && mainrole_level <= vo.max_level
                            && curr_open_server_day >= vo.open_server_day && curr_open_server_day <= vo.end_server_day
                            && curr_merge_server_day >= vo.merge_server_start_day && curr_merge_server_day <= vo.merger_server_end_day
                            && vo.open_week.indexOf(curr_week) >= 0
                            && curr_time >= vo.custom_open_time && curr_time <= vo.custom_end_time) {
                            validata_list.push(id);
                            break;
                        }
                    }
                }
            }
            let onLoadCallback = async (texture) => {
                if (texture) {
                    Util.SetLargeScreenImageSize(this._img_bg, texture.textureWidth, texture.textureHeight);
                }
                // }, this, 1000)
                // if(!login_model.plat_name)
                // {
                // 	login_model.PreLoadGameRes()
                // }
            };
            let len = validata_list.length;
            if (len > 0) {
                let id = validata_list[local_Util.RandomRange(0, len - 1)];
                res_mgr.SetTexture(this, this._img_bg, `resource/game/login/texture/load_bg${id}.jpg`, onLoadCallback, this, true, LOAD_QUEUE.HIGHT);
            }
            else {
                if (PlatformManager.GetInstance().is_alpha) {
                    let source = `resource/game/login/texture/load_bg9.jpg`;
                    if (PlatformManager.IsSuyouNativePlatform()) {
                        source = `resource/game/login/texture/load_bg2.jpg`;
                    }
                    res_mgr.SetTexture(this, this._img_bg, source, onLoadCallback, this, true, LOAD_QUEUE.HIGHT);
                }
                else {
                    res_mgr.SetTexture(this, this._img_bg, platform_mgr.GetEnterGameLoadingBgPath(), onLoadCallback, this, true, LOAD_QUEUE.HIGHT);
                }
            }
            runner.AddRunObj(this, 1, FRAME_TYPE.total);
            if (!local_Util.IsWXGame() && !local_Util.IsDouYinGame() && !local_Util.IsMeiTuanGame() && !local_Util.IsBiLiBiLiGame() && !local_Util.IsQQGame() && !local_Util.IsBaiduGame() && (platform_mgr.is_alpha || platform_mgr.need_alpha_open_charge)) {
                this._gp_con.visible = false;
                // alpha_state_to_close_ = true
                // local_GlobalEventSystem.Fire(local_EventName.PRELOAD_LOADING_COMPLETED)
                // Laya.setTimeout(() => {
                // 	count_down_state_ = true
                // 	this.TryCloseLoading()
                // }, this, 5 * 1000 + 500)
                // return
            }
            else {
                // runner.AddRunObj(this, 1, FRAME_TYPE.total)
                this._gp_con.visible = true;
            }
            let career = role_mgr.GetMainRoleVo().career;
            // this._img_icon.source = career == 1 ? "login_json.uidl_031_png" : "login_json.uidl_032_png";
            this._img_line.visible = this._gp_con0.visible = login_model.is_new_career;
            local_GlobalEventSystem.Fire(local_EventName.PRELOAD_LOADING_COMPLETED);
            if (login_model.is_new_career) {
                this.BindEvent(local_GlobalEventSystem, local_EventName.LOAD_LOADING_OTHER_RES, () => {
                    this.LoadOtherRes();
                });
            }
            else {
                this.LoadOtherRes();
            }
        };
        this.LoadOtherRes = () => {
            if (login_model.is_new_career) {
                platform_mgr.DataPlacement(90008); //创角成功后加载
                res_mgr.SetTexture(this, this._img_bg0, `resource/game/login/texture/uizspzwq_001.png`);
                this.AddUIEffect("ui_register_iconlizi", this._gp_effect1, null, null, true);
            }
            this.AddUIEffect("ui_loading_glow1", this._gp_effect0, null, null, true);
            // if (local_Util.IsWebGLRenderMode())
                // show_model_ = new UIDragonBonesModelClass(this._gp_dragon, "eggangle", { x: 0, y: 0 }, { scale_x: 1.5, scale_y: 1.5 });
        };
        this.OnChange = () => {
            if (this._front_img) {
                let value = this._front_img.width / _front_img_width_;
                this._gp_progress.x = this._front_img.x + value * _front_img_width_;
                let pro = (value * 100).toFixed(2);
                this._lb_load.text = `loading......${pro}%`;
                if (tween_trigger_ && Number(pro) >= 55 && login_model.is_new_career) {
                    tween_trigger_ = false;
                    // this.ShowTipsTween();
                }
            }
        };
        this.ShowTipsTween = () => {
            if (this._gp_con.visible) {
                Message.show("奖励领取成功～");
            }
            this._img_line.visible = false;
            this._img_bg0.visible = this._img_bg1.visible = true;
            this.ClearUIEffect(this._gp_effect1);
            Laya.Tween.to(this._gp_con0, { y: -500 }, 1500);
        };
        this.TryCloseLoading = () => {
            if (alpha_state_to_close_) {
                this.Close();
            }
            else {
                if (count_down_state_ && (game_start_state_) && !login_model.HasLockFlag()) {
                    count_down_state_ = false;
                    _should_be_close_ = true;
                    if (this._front_img) {
                        this._front_img.width = _front_img_width_;
                    }
                    this.OnChange();
                    // this.Close()
                }
            }
        };
        this.ClearTimer = () => {
            // if (time_id_) {
            //     Laya.clearTimeout(time_id_);
            //     time_id_ = undefined;
            // }
        };
        this.Remove = () => {
            local_GlobalEventSystem.Fire(local_EventName.DELAY_SHOW_FIGHTUP, false);
            local_GlobalEventSystem.Fire(local_EventName.LOGIN_LOADING_VIEW_CLOSE);
            login_model.is_show_loading_view = false;
            runner.RemoveRunObj(this.hashCode);
            if (this._gp_con0 && this._gp_con0["tween_count"]) {
                Laya.Tween.clearAll(this._gp_con0);
            }
            this.ClearTimer();
            // if (tween_id_) {
            // 	tween_id_.removeEventListener("change", this.OnChange, this);
            // 	tween_id_ = undefined
            // }
            // if (show_model_) {
            //     show_model_.DeleteMe();
            //     show_model_ = null;
            // }
        };
    }
    public Open() {
        this.Local_Open();
    }
}
window["LoginLoadingView"] = LoginLoadingView
