import { BaseView1 } from "../common/BaseView1"
import { EventName } from "../common/EventName"
import { Enum_UILayer } from "../common/LayerManager"
import { ResManager } from "../common/ResManager"
import { LuaSoundManager, SoundManager } from "../common/SoundManager"
import { BaseDungeonModel, DUN_TYPE } from "../commonModel/BaseDungeonModel"
import { TaskTipType } from "../commonModel/TaskModel"
import { RoleManager } from "../role/RoleManager"
import { SceneManager } from "../scene/SceneManager"
import { GlobalEventSystem } from "../util/DeclareGlobalVar"
import { GameResPath } from "../util/GameResPath"
import { TimeUtil } from "../util/TimeUtil"
import { GlobalTimerQuest, Util } from "../util/Util"
import { DungeonEnterView } from "./DungeonEnterView"
import { DungeonFailureStrengItem } from "./DungeonFailureStrengItem"

export class DungeonFailureView extends BaseView1 {


	CancelTime
	LoadSuccess
	Local_Open
	Remove
	StartTime

	public static LeftTime = 5
	public static StrengType = 4
	public static PetType = 5
	public constructor() {
		super()

		this.base_file = "dungeonCommon"
		this.layout_file = "DungeonFailureView"
		this.layer_value = Enum_UILayer.Activity
		this.use_background = true
		this.background_alpha = 0.8
		this.not_show_main_msg = true
		this.is_center = true
		this.destroy_imm = true
		this.click_bg_toClose = true
		let model = BaseDungeonModel.GetInstance()


		let local_TimeUtil = TimeUtil
		let local_DUN_TYPE = DUN_TYPE
		let local_GlobalEventSystem = GlobalEventSystem
		let local_EventName = EventName
		let local_DungeonEnterView = DungeonEnterView
		let local_laya = Laya
		let dun_type_ = null
		let activity_jump_id_ = null
		let item_list_ = null
		let time_id_ = null
		let time_func_ = null
		let fail_sound_name = [
			"Boy_Lose",
			"Girl_Lose"
		]


		this.load_callback = () => {
			this.LoadSuccess()
		}

		this.preload_server_config = {
			config_to_be_strong: false
		}

		this.open_callback = () => {
			let mainVo = RoleManager.GetInstance().GetMainRoleVo()
			let fail_sound = fail_sound_name[mainVo.sex]
			if (fail_sound) {
				SoundManager.GetInstance().PlaySoundEffect(this, fail_sound, false)
			}
			// this.AddUIEffect('UI_2105', this.layer_value , this._gp_failure_effect, null, null, false, {last_time = DungeonFailureView.LeftTime + 3})
		}

		this.close_callback = () => {
			this.Remove()
		}

		this.Local_Open = (...new_args) => {
			let param = new_args
			if (param.length > 0) {
				dun_type_ = param[0]
			}
		}

		this.LoadSuccess = () => {
			ResManager.GetInstance().SetOutsideImageSprite(this, this._img_bg, GameResPath.GetIcon("dungeonCommon", "com_up_bg2"))
			ResManager.GetInstance().SetOutsideImageSprite(this, this._img_title, GameResPath.GetIcon("dungeonCommon", "ui_copy_67"))
			ResManager.GetInstance().SetOutsideImageSprite(this, this._img_title_bg, GameResPath.GetIcon("dungeonCommon", "ui_copy_69"))

			this._lb_activity_Jump.text = "前往"
			// AddUnderLineAndClick(this, this._lb_activity_Jump)

			Util.AddClickEvent(this._lb_activity_Jump, () => {
				if (activity_jump_id_) {
					model.SetDunFailureJumpData(activity_jump_id_)
					this.Close()
				}
			}
				, this, true)


			// let effect_scale = [x=1.14, y=1.14]
			// this.AddUIEffect2("ui_defeated_glow1", this._gp_failure_effect, null, effect_scale, false, null, null, null, true, true)
			// this.AddUIEffect2("ui_activity_frame", this._gp_activity_effect, null, null, true, null, null, null, true, true)

			// this.AddUIEffect("UI_2105", this.layer_value, this._gp_failure_effect, null, effect_scale, true, {load_call_back =() => {
			// 	this.CoverEffect(this._gp_failure_effect)
			// }})


			let level = RoleManager.GetInstance().GetMainRoleVo().level
			let cfg = ResManager.GetInstance().GetGameConfigFromCache(this, "config_to_be_strong", false) //Config.Tobestrong
			if (!cfg) {
				return
			}
			let list = []
			let type = DungeonFailureView.StrengType
			if (dun_type_ == local_DUN_TYPE.Pet) {
				type = DungeonFailureView.PetType
			}
			for (let key in cfg) {

				let vo = cfg[key]
				if (vo) {
					if (vo.type == type && level >= vo.lv) {
						// table.insert(list, vo)
						list.push(vo)
					}
				}
			}

			// table.sort(list,(a?,b?) => {
			//	 return a.star > b.star
			// })

			list.sort((a, b) => {
				return - a.star + b.star
			})

			if (!item_list_) {
				item_list_ = []
			}
			let click_jump_func = () => {
				this.Close()
			}

			let item, vo
			for (let index = 0; index < 3; index++) {
				// for (let key in list) {

				vo = list[index]
				if (vo) {
					item = item_list_[index]
					if (!item) {
						item = new DungeonFailureStrengItem(this._gp_streng)
						item_list_[index] = item
						item.Load()
					}
					item.SetData(vo, click_jump_func)
					item.SetPosition(0, index *100)
				}
			}
			let end_time = DungeonFailureView.LeftTime + local_TimeUtil.getServerTime()

			let time_func = () => {
				let left_time = end_time - local_TimeUtil.getServerTime()
				if (left_time < 0) {
					this.Close()
				}
			}

			this.StartTime(time_func)

			// let first_recharge_state = FirstRechargeModel.GetInstance().IsDoneFirstRecharge()
			// if (! first_recharge_state ) {
			// 	 ResManager.GetInstance().SetOutsideImageSprite(this, this._img_activity, GameResPath.GetIcon("dungeonCommon","uijs_072a"))
			// 	 activity_jump_id_ = 70
			// 	 return
			// }
			// let vip_six_info = VipModel.GetInstance().GetNobleCardInfo(6)
			// let vip_six_state = vip_six_info && vip_six_info.is_active == 1 || false
			// if (! vip_six_state ) {
			// 	 ResManager.GetInstance().SetOutsideImageSprite(this, this._img_activity, GameResPath.GetIcon("dungeonCommon","uijs_072c"))
			// 	 activity_jump_id_ = 23
			// 	 return
			// }
			ResManager.GetInstance().SetOutsideImageSprite(this, this._img_activity, GameResPath.GetIcon("dungeonCommon", "uijs_072b"))
			activity_jump_id_ = 71
		}

		this.Remove = () => {
			switch (dun_type_) {
				case local_DUN_TYPE.Material_Mount:
				case local_DUN_TYPE.Material_Partner:
				case local_DUN_TYPE.Material_WING:
				case local_DUN_TYPE.Material_Copper:
					let MainLineTaskVo = this.task_model.GetMainLineTaskVo()
					if ((!MainLineTaskVo || MainLineTaskVo.task_tips_type != TaskTipType.FinDunType) || (MainLineTaskVo.id != local_DUN_TYPE.Material_Mount && MainLineTaskVo.id != local_DUN_TYPE.Material_Partner) && MainLineTaskVo.id != local_DUN_TYPE.Material_WING) {
						if (!model.streng_item_click) {
							local_GlobalEventSystem.Fire(local_EventName.OPEN_VIEW, "DungeonEnterView", local_DungeonEnterView.Index.Material)
						}
					}
					break
				case local_DUN_TYPE.Partner:
					if (!model.streng_item_click) {
						GlobalEventSystem.Fire(EventName.OPEN_VIEW, "DungeonEnterView", DungeonEnterView.Index.DungeonPartner)
					}
					break
				case local_DUN_TYPE.Partner:
					model.pet_Monster_instance_id_list = []
					model.select_pet_instance_id = null
					if (!model.streng_item_click) {
						//local_GlobalEventSystem:Fire(local_EventName.OPEN_VIEW, "DungeonEnterView", local_DungeonEnterView.Index.Pet)
					}
					break
				case local_DUN_TYPE.Rune:
					if (!model.streng_item_click) {
						setTimeout(() => {
							local_GlobalEventSystem.Fire(local_EventName.OPEN_VIEW, "DungeonEnterView", local_DungeonEnterView.Index.Rune)
						}, 1)
					}
					break
				case local_DUN_TYPE.Vip_Rerson_Boss:
					if (!model.streng_item_click) {
						// local_GlobalEventSystem.Fire(local_EventName.OPEN_VIEW, "BossEnterView", BossModel.Index.Vip_Person_Boss)
					}
					break

			}

			this.CancelTime()

			// if (this._gp_activity_effect ) {
			// 	Laya.Tween.removeTweens(this._gp_activity_effect)
			// 	Laya.Tween.removeTweens(this._gp_failure_effect)
			// }

			if (item_list_) {
				for (let _tmpi in item_list_) {
					var obj = item_list_[_tmpi]
					obj.DeleteMe()
				}
				item_list_ = null
			}

			if (SceneManager.GetInstance().IsDungeonScene() && model.IsInDunTypeScene(dun_type_)) {
				model.Fire(BaseDungeonModel.SCMD_REQUEST, 61002)
			}
			model.SetDungeonResultInfo(null)
			model.SetDungeonMonsterDeadPos(null)
			model.streng_item_click = false
			local_GlobalEventSystem.Fire(local_EventName.CLOSE_DUNGEON_RESULT_VIEW)
		}

		this.StartTime = (time_func?) => {
			this.CancelTime()
			// time_func_ = time_func
			// time_id_ = local_laya. new Timer(1000, 0)
			// time_id_.addEventListener(Laya.TimerEvent.TIMER, time_func_, this)
			// time_id_.start()

			time_id_ = GlobalTimerQuest.AddPeriodQuest(time_func, 1, -1)
			time_func()
		}

		this.CancelTime = () => {
			if (time_id_) {
				GlobalTimerQuest.CancelQuest(time_id_)
				time_id_ = null
			}
		}
	}

	public Open(...new_args) {
		this.Local_Open(...new_args)
		super.Open()
	}

	_img_bg: Laya.Image
	_gp_failure_effect: Laya.Box
	_img_title_bg: Laya.Image
	_img_title2: Laya.Image
	_gp_streng: Laya.Box
	_img_title: Laya.Image
	_img_activity_bg: Laya.Image
	_img_activity: Laya.Image
	_lb_activity_Jump: Laya.Label
	_Label1: Laya.Label
	_gp_activity_effect: Laya.Box
	public GetComponents() {
		[
			this._img_bg,
			this._gp_failure_effect,
			this._img_title_bg,
			this._img_title2,
			this._gp_streng,
			this._img_title,
			this._img_activity_bg,
			this._img_activity,
			this._lb_activity_Jump,
			this._Label1,
			this._gp_activity_effect,
		]
			= this.GetChildrenByNames([

				"_img_bg",
				"_gp_failure_effect",
				"_img_title_bg",
				"_img_title2",
				"_gp_streng",
				"_img_title",
				"_img_activity_bg",
				"_img_activity",
				"_lb_activity_Jump",
				"_Label1",
				"_gp_activity_effect",
			])
	}
}
window["DungeonFailureView"] = DungeonFailureView


