import { GlobalEventSystem } from "../util/DeclareGlobalVar";
import { BaseView1 } from "./BaseView1";
import { EquipmentItem } from "./EquipmentItem";
import { EventName } from "./EventName";
import { Enum_UILayer } from "./LayerManager";
import { ResManager } from "./ResManager";

// TypeScript file
export class CongratulationRareView extends BaseView1 {


    public _img_matrix: Laya.Image;
    public _gp_effect: Laya.Box;
    public _img_horn_right: Laya.Image;
    public _img_horn_left: Laya.Image;
    public _img_leaf_right: Laya.Image;
    public _img_leaf_left: Laya.Image;
    public _img_top: Laya.Image;
    public _lb_time: Laya.Label;
    public _gp_item: Laya.Box;
    public _special: Laya.Image;



    private timer: Laya.Timer
    private reward_item: EquipmentItem
    InitView
    OnTimer
    SetData
    SetSpecialImg
    DestroyCallback
    constructor() {
        super()

        let res_mgr = ResManager.GetInstance(),
            local_laya = Laya,
            _reward,
            _time_down,
            _count = 0,
            _special_url

        this.base_file = "common"
        this.layout_file = "CongratulationRareView"
        this.layer_value = Enum_UILayer.Activity
        this.destroy_imm = true
        this.use_background = true
        this.click_bg_toClose = false
        this.show_open_movie = true
        this.is_center = true
        this.load_callback = () => {
        }
        this.open_callback = () => {
            this.InitView()
        }
        this.destroy_callback = () => {
            this.DestroyCallback()
        }
        this.InitView = () => {
            res_mgr.SetTexture(this, this._img_matrix, "resource/game/common/texture/uizxjl_002.png")
            res_mgr.SetTexture(this, this._img_horn_right, "resource/game/common/texture/uizxjl_003.png")
            res_mgr.SetTexture(this, this._img_horn_left, "resource/game/common/texture/uizxjl_003.png")
            res_mgr.SetTexture(this, this._img_leaf_left, "resource/game/common/texture/uizxjl_004.png")
            res_mgr.SetTexture(this, this._img_leaf_right, "resource/game/common/texture/uizxjl_004.png")
            res_mgr.SetTexture(this, this._img_top, "resource/game/common/texture/uizxjl_005.png")
            _count = 0
            if (_time_down) {
                if (!this.timer) {
                    this.timer = new local_laya.Timer()
                    this.timer.loop(1000, this, this.OnTimer)
                }
                // this.timer.currTimer = 0
                // this.timer.resume()
                // this.timer.start()
                this.OnTimer()
            }
            if (this._gp_effect.numChildren == 0)
                this.AddUIEffect(`ui_Special_glow`, this._gp_effect, undefined, undefined, true)
            if (_special_url) {
                res_mgr.SetTexture(this, this._special, _special_url)
                return
            }
            if (!_reward) return
            if (!this.reward_item) {
                this.reward_item = new EquipmentItem(this._gp_item)
                this.reward_item.Load()
            }
            this.reward_item.ExcuteCallback(() => {
                this.reward_item.SetData(_reward[0], _reward[1])
            })
        }

        this.OnTimer = () => {
            _count++
            if (_count == 1) {
                this.click_bg_toClose = true
            }
            if (_count % 2 != 0) return
            this._lb_time.text = `点击任意空白处关闭(${_time_down})`
            _time_down--
            if (_time_down < 0) {
                this.timer.pause()
                this.Close()
            }
        }

        this.SetData = (reward, time_down) => {
            _reward = reward
            _time_down = time_down
        }

        this.SetSpecialImg = (url) => {
            _special_url = url
        }

        this.DestroyCallback = () => {
            GlobalEventSystem.Fire(EventName.CONGRA_RARE_VIEW)
            if (this.timer) {
                this.timer.pause()
                this.timer.clear(this, this.OnTimer)
                this.timer = null
            }
            if (this.reward_item) {
                this.reward_item.DeleteMe()
                this.reward_item = null
            }
        }
    }
    public GetComponents() {
        [
            this._img_matrix,
            this._gp_effect,
            this._img_horn_right,
            this._img_horn_left,
            this._img_leaf_right,
            this._img_leaf_left,
            this._img_top,
            this._lb_time,
            this._gp_item,
            this._special,
        ]
            = this.GetChildrenByNames([

                "_img_matrix",
                "_gp_effect",
                "_img_horn_right",
                "_img_horn_left",
                "_img_leaf_right",
                "_img_leaf_left",
                "_img_top",
                "_lb_time",
                "_gp_item",
                "_special",
            ])
    }
}
window["CongratulationRareView"] = CongratulationRareView