import { BaseView1 } from "../common/BaseView1"
import { Enum_UILayer } from "../common/LayerManager"
import { LoopScrCon, LoopScrowViewMgr } from "../common/LoopScrowViewMgr"
import { ResManager } from "../common/ResManager"
import { LuaSoundManager } from "../common/SoundManager"
import { table } from "../common/table"
import { UIToolTipMgr } from "../common/UIToolTipMgr"
import { EquipModel } from "../commonModel/EquipModel"
import { GoodsModel } from "../commonModel/GoodsModel"
import { GuildModel, GuildDefine } from "../commonModel/GuildModel"
import { Util } from "../util/Util"
import { GuildDepotItem } from "./GuildDepotItem"

export class GuildDepotSelectView extends BaseView1 {
	Clear
	ClickCallBack
	GetShowEquips
	InitEvent
	LoadSuccess
	UpdateView
	_ac_data
	_group_data
	click_bg_toClose
	destroy_callback
	destroy_imm
	is_center
	loop_mgr
	open_callback
	preload_server_config
	show_open_movie
	use_background

	public constructor() {
		super()


		this.base_file = "guild"
		this.layout_file = "GuildDepotSelectView"
		this.layer_value = Enum_UILayer.Activity
		this.use_background = true
		this.click_bg_toClose = true
		this.is_center = true
		this.destroy_imm = true
		this.show_open_movie = true
		//this.preload_server_config = [Goods=false, Equipattr=false, Guilddepotscore=false]

		this.load_callback = () => {
			this.LoadSuccess()
		}

		this.open_callback = () => {
			// this.RegisterMask(this._group_data,1)
		}

		this.destroy_callback = () => {
			this.Clear()
		}

		let model = GuildModel.GetInstance()
		let local_ResManager = ResManager.GetInstance()
		let local_GoodsModel = GoodsModel.GetInstance()
		this.Clear = () => {

		}

		this.ClickCallBack = (info?) => {
			let utm = UIToolTipMgr.GetInstance()
			if (info.type == 10) {
				// utm.AppendEquipTips(info.type_id, null, null, info, null, { 2})
			} else {
				utm.AppendGoodsTips(info.type_id)
			}
		}

		this.LoadSuccess = () => {



			//this._ac_data = eui. new ArrayCollection()
			//this._group_data.dataProvider = this._ac_data
			//this._group_data.itemRenderer = GuildDepotItem

			let list = this.GetShowEquips()
			this.loop_mgr = new LoopScrowViewMgr()
			this.loop_mgr.SetData(this._list_item, GuildDepotItem, list, LoopScrCon.Vertical)


			this.InitEvent()
			this.UpdateView()
		}

		this.InitEvent = () => {
			Util.AddClickEvent(this._btn_close, () => {
				this.Close()
			}
				, this, true, null, null, null, null, LuaSoundManager.SOUND_UI.CLOSE)

			this.BindVar(model, "depot_score", () => {
				this.UpdateView()
			}
			)
		}

		this.UpdateView = () => {
			let list = this.GetShowEquips()
			if (this.loop_mgr) {
				this.loop_mgr.replaceAll(list)
			}
		}

		this.GetShowEquips = () => {
			let list = []
			//let Guilddepotscore = local_ResManager.GetGameConfigFromCache(this, "Guilddepotscore", false)
			let limit = { stage: 4, star: 1, color: 3, score_plus: 23662, score_cost: 23662 } // model.GetDepotLimit(Guilddepotscore)
			let equips = local_GoodsModel.bag_goods_list
			let emodel = EquipModel.GetInstance()
			for (let _tmpi in equips) {
				var info = equips[_tmpi]
				if (info.bind == 0) {
					if (info.type == 10) {
						let equip_attr_cfg = local_ResManager.GetGameConfigFromCache(this, "config_equip_attr", false)
						if (emodel.GetStageByTypeId(info.type_id, equip_attr_cfg) < limit.stage) {
						} else {
							if (emodel.GetStarByTypeId(info.type_id, equip_attr_cfg) < limit.star) {
							} else {
								if (info.color >= limit.color) {
									if (info.color != GuildDefine.DEPOT_LIMIT_COLOR) {
										info.is_depot_select = true
										table.insert(list, info)
									}
								}
							}
						}
					}
				}
			}
			return list
		}
	}


	public DeleteMe() {
		if (this.loop_mgr) {
			this.loop_mgr.DeleteMe()
			this.loop_mgr = null
		}

		super.DeleteMe()
	}

	_Image1: Laya.Image
	_Image3: Laya.Image
	_Image2: Laya.Image
	_lb_win_name: Laya.Label
	_Group1: Laya.Box
	_btn_close: Laya.Box
	_Image11: Laya.Image
	_Label2: Laya.Label
	_Label3: Laya.Label
	_list_item: Laya.List
	public GetComponents() {
		[
			this._Image1,
			this._Image3,
			this._Image2,
			this._lb_win_name,
			this._Group1,
			this._btn_close,
			this._Image11,
			this._Label2,
			this._Label3,
			this._list_item,
		]
			= this.GetChildrenByNames([

				"_Image1",
				"_Image3",
				"_Image2",
				"_lb_win_name",
				"_Group1",
				"_btn_close",
				"_Image11",
				"_Label2",
				"_Label3",
				"_list_item",
			])
	}
}
window["GuildDepotSelectView"]=GuildDepotSelectView