		this.RefreshIconPos = (list?, line_no?, firsr_line_list?, second_line_list?) => {
			let count = 1
			let init_y = 0
			if (line_no != 1) {
				if (line_no == 2) {
					if (firsr_line_list && firsr_line_list.length > 0) {
						init_y = local_ActivityIcon.HEIGHT + GAP_
					}
				} else if (line_no == 3) {
					if (firsr_line_list && firsr_line_list.length > 0) {
						init_y = local_ActivityIcon.HEIGHT + GAP_
					}
					if (second_line_list && second_line_list.length > 0) {
						init_y = init_y + local_ActivityIcon.HEIGHT + GAP_
					}
				}
			}
			if (list) {
				let have_time_icon_index = 0
				if (line_no == 3) {
					let vo = null
					let info = null
					for (let i = 0; i < list.length; i++) {
						vo = list[i]
						if (vo) {
							info = local_CommonManager_Instance.GetFunctionIconCfg(vo.iconType)
							if (info && info.location_type == 6) {
								have_time_icon_index = i
								break
							}
						}
					}
				}
				let line_max_num = this.GetLineMaxIconNum()
				let not_second_line_num = local_Mathf.Floor(have_time_icon_index / line_max_num)
				let now_line_no = null
				for (let _tmpi in list) {
					var item = list[_tmpi]
					if (item) {
						if (item.to_add) {
							item.SetVisible(true)
							item.to_add = false
						}
						let y

						// item.display_obj.x = (count - 1) % line_max_num * local_ActivityIcon.WIDTH
						now_line_no = local_Mathf.Floor((count - 1) / line_max_num)
						if (not_second_line_num >= now_line_no) {
							y = init_y + now_line_no * (local_ActivityIcon.HEIGHT - GAP_)
						} else {
							y = init_y + not_second_line_num * (local_ActivityIcon.HEIGHT - GAP_) + (now_line_no - not_second_line_num) * local_ActivityIcon.HEIGHT
						}
						// item.display_obj.y = y
						item.SetPosition((count - 1) % line_max_num * local_ActivityIcon.WIDTH, y)
						item.SetAlpha(1)
						item.SetIconScale(1)

						count = count + 1
						if (item.RefreshPos) {
							item.RefreshPos()
						}
					}
				}
			}
		}

		this.ShowAnimation = (bool?) => {
			if (is_show_ == bool) {
				return is_show_
			}

			is_show_ = bool
			is_moving_ = true
			this.ClearTween()

			if (bool) {
				if (first_line_icon_list_.length > 0) {
					this.PlayOpen(1, first_line_icon_list_)
				}
				if (second_line_icon_list_.length > 0) {
					this.PlayOpen(2, second_line_icon_list_)
				}
				if (other_line_icon_list_.length > 0) {
					this.PlayOpen(3, other_line_icon_list_)
				}
			} else {
				this.PlayHide()
			}



			if (delay_refresh_time_id_) {
				clearTimeout(delay_refresh_time_id_)
				delay_refresh_time_id_ = false
				ani_end_need_refresh_icon_ = true
			}

			if (time_id_) {
				clearTimeout(time_id_)
				time_id_ = null
			}

			time_id_ =
				setTimeout(() => {
					is_moving_ = false
					if (ani_end_need_refresh_icon_) {
						ani_end_need_refresh_icon_ = false
						this.ClearTween()
						this.TryRefreshAllIcon()
					}
				},
					local_MainUIModel.Move_Time_Interval + 0.2 // 加0.2容错
				)
			return is_show_
		}

		this.PlayOpen = (line_no?, list?) => {
			if (list) {
				let count = 1
				let init_y = 0
				if (line_no == 2) {
					if (first_line_icon_list_ && first_line_icon_list_.length > 0) {
						init_y = local_ActivityIcon.HEIGHT + GAP_
					}
				} else if (line_no == 3) {
					if (first_line_icon_list_ && first_line_icon_list_.length > 0) {
						init_y = local_ActivityIcon.HEIGHT + GAP_
					}
					if (second_line_icon_list_ && second_line_icon_list_.length > 0) {
						init_y = init_y + local_ActivityIcon.HEIGHT + GAP_
					}
				}
				let have_time_icon_index = 0
				if (line_no == 3) {
					let vo = null
					let info = null
					for (let i = 0; i < list.length; i++) {
						if (vo) {
							info = local_CommonManager_Instance.GetFunctionIconCfg(vo.iconType)
							if (info && info.location_type == 6) {
								have_time_icon_index = i
								break
							}
						}
					}
				}
				let line_max_num = this.GetLineMaxIconNum()
				let not_second_line_num = local_Mathf.Floor(have_time_icon_index / line_max_num)
				let now_line_no = null
				for (let key in list) {

					let item = list[key]
					if (item && item.SetVisible) {
						if (item.to_add) {
							item.to_add = false
						}

						item.SetVisible(true)

						let x = (count - 1) % line_max_num * local_ActivityIcon.WIDTH

						now_line_no = local_Mathf.Floor((count - 1) / line_max_num)

						let y = null
						if (not_second_line_num >= now_line_no) {
							y = init_y + now_line_no * (local_ActivityIcon.HEIGHT + GAP_)
						} else {
							y = init_y + not_second_line_num * (local_ActivityIcon.HEIGHT + GAP_) + (now_line_no - not_second_line_num) * local_ActivityIcon.HEIGHT
						}

						count = count + 1
						table.insert(
							tween_list_,
							SYTweenLite.to(
								this,
								item.display_obj,
								SYTweenLite.UiAnimationType.POSX,
								x,
								local_MainUIModel.Move_Time_Interval,
								null,
								SYTweenFunc.LINEAR
							)
						)
						table.insert(
							tween_list_,
							SYTweenLite.to(
								this,
								item.display_obj,
								SYTweenLite.UiAnimationType.POSY,
								y,
								local_MainUIModel.Move_Time_Interval,
								null,
								SYTweenFunc.LINEAR
							)
						)
						table.insert(
							tween_list_,
							SYTweenLite.to(
								this,
								item._gp_icon,
								SYTweenLite.UiAnimationType.SCALE,
								Vector3.one,
								local_MainUIModel.Move_Time_Interval,
								null,
								SYTweenFunc.LINEAR
							)
						)
						table.insert(
							tween_list_,
							SYTweenLite.to(
								this,
								item._gp_icon,
								SYTweenLite.UiAnimationType.ALPHA,
								1,
								local_MainUIModel.Move_Time_Interval,
								null,
								SYTweenFunc.LINEAR
							)
						)
					}
				}
			}
		}

