import { BaseItem1 } from "../common/BaseItem1"
import { BaseItemRenderer } from "../common/BaseItemRenderer"
import { ResManager } from "../common/ResManager"

export class EveningBossDamageItem extends BaseItemRenderer {

	public WIDTH = 198
	public HEIGT = 36
	is_set

	public constructor(parent) {
		super()
		this.is_set = false
		this.base_file = "evening"
		this.layout_file = "EveningBossDamageItem"

		this.load_callback = () => {
			if (!this.is_set) {
				this.SetDate()
				this.is_set = true
			}
		}
		this.Load()
	}


	public DeleteMe() {
		super.DeleteMe()
	}

	public dataChanged() {
		if (!super.dataChanged()) return
		if (this.is_loaded) {
			this.SetDate()
			this.is_set = true
		} else {
			this.is_set = false
		}
	}

	SetDate() {
		if (!this.data) return
		this._lb_name.text = this.data.player_name

		this._lb_hurt.text = `${Number(this.data.modulus).toFixed(2)}%`//string.format("%.2f%%", this.data.modulus)

		//let str_list = ["uijjsh_006biga", "uijjsh_006bigb", "uijjsh_006bigc"]
		let str_list = ["ui_phb_1a", "ui_phb_1b", "ui_phb_1c"]
		let index = this.index
		let bool = index < 4
		this.img_rank.visible = bool
		this._lb_rank.visible = !bool
		if (bool) {
			let str = str_list[index]
			ResManager.GetInstance().SetImageSprite(this, this.img_rank, "evening_asset", str, true)
		} else {
			this._lb_rank.text = index
		}
	}


img_rank:Laya.Image
_lb_rank:Laya.Label
_lb_name:Laya.Label
_lb_hurt:Laya.Label
img_line:Laya.Image
public GetComponents() {
[
this.img_rank,
this._lb_rank,
this._lb_name,
this._lb_hurt,
this.img_line,
]
 = this.GetChildrenByNames([

"img_rank",
"_lb_rank",
"_lb_name",
"_lb_hurt",
"img_line",
])
}
}
 window["EveningBossDamageItem"]= EveningBossDamageItem