    public async PreloadSkillRes(career) {
        let list = ResManager.CareerSkillEffect[career]
        if (list) {

            let load_completed
            let promise = new Promise<any>((resolve, reject) => {
                load_completed = resolve;
            })

            let delte_time_id = setTimeout(() => {
                load_completed()
            }, 10000);

            let load_count = 0
            let total_count = list.length
            let load_call_back = (obj) => {
                load_count++
                if (load_count >= total_count) {
                    if (delte_time_id) {
                        clearTimeout(delte_time_id)
                    }
                    load_completed()
                }
            }

            for (let name of list) {
                this.CreatePrefab(this.hashCode, GameResPath.GetEffectPath(name), load_call_back)
            }
            await promise;
        }
    }

