import { BaseAwardItem } from "../common/BaseAwardItem";
import { BaseItemRenderer } from "../common/BaseItemRenderer";
import { EventName } from "../common/EventName";
import { ResManager } from "../common/ResManager";
import { UIToolTipMgr } from "../common/UIToolTipMgr";
import { RuneEvent, RuneModel } from "../commonModel/RuneModel";
import { TaskModel, TaskTipType } from "../commonModel/TaskModel";
import { ColorUtil } from "../util/ColorUtil";
import { GlobalEventSystem } from "../util/DeclareGlobalVar";
import { Util } from "../util/Util";

export class RuneBagItem extends BaseItemRenderer {
	public WIDTH = 534
	public HEIGT = 123

	task_model:TaskModel
	item 
	model:RuneModel
	public constructor() {
		super()
		this.base_file = "rune"
		this.layout_file = "RuneBagItem"
		this.task_model = TaskModel.GetInstance()
		this.model = RuneModel.GetInstance()
		this.Load()
	}

	public load_callback(){
		this.item = new BaseAwardItem(this.icon_conta)
		this.item.Load()
		this.item.SetItemSize(85, 85)

		let btn_fun = () => {
			if (this.data) {
				this.model.Fire(RuneEvent.RUNE_REQUEST_PROTO, 16701, "cl", this.data.pos_id, this.data.goods_vo.goods_id)
			}
		}
		Util.AddClickEvent(this.insertBtn, btn_fun, this, true)
	}

	public dataChanged() {
		if (super.dataChanged()){
			if (this.data) {
				let awake = false
				if (this.data.goods_vo) {
					if (this.model.guide_goods_id && this.task_model.IsCurrMainLineTaskTipType(TaskTipType.RuneNum) && !this.task_model.IsCurrMainTaskHasFinish()) {
						if (this.model.guide_goods_id == this.data.goods_vo.goods_id) {
							let setp_cfg = { "step": 2, "direction": 6, "text": "点击<font color='0xFFFF00'>镶嵌</font>按钮，\n属性嗖嗖的~" }
							GlobalEventSystem.Fire(EventName.SHOW_FINGER, this, this.insertBtn, "Activity", null, null, null, null, setp_cfg)
						} else {
							GlobalEventSystem.Fire(EventName.HIDE_FINGER, this, this.insertBtn)
						}
					}
					if (this.item) {
						this.item.SetData(this.data.goods_vo.type_id, null, null, null, null, true)
						this.item.SetClickCallBack(() => {
							UIToolTipMgr.GetInstance().AppendGoodsTips(this.data.goods_vo.type_id, null, null, this.data.goods_vo)
						})
					}
					let color_str = ColorUtil.GetColorDark(this.data.goods_vo.color)
					let goods_name = "<font style='font-size:20px' color=" + color_str + ">" + (this.data.goods_vo.goods_name).trim() + "  Lv." + this.data.goods_vo.level + "</font>"
					
					this.goods_name.width = 269
					this.goods_name.style.fontSize = 20
					this.goods_name.innerHTML = goods_name
					let source = "rune_001"
					if (this.data.goods_vo.subtype == 22 || this.data.goods_vo.subtype == 23) {
						source = "uifu_009"
					}
					ResManager.GetInstance().SetImageSprite(this, this.icon_bg, "rune_asset", source, true)
					for (let _tmpi in this.data.goods_vo.awake_list) {
						var vo = this.data.goods_vo.awake_list[_tmpi]
						if (vo.awake_lv > 0) {
							awake = true
							break
						}
					}
				}
				
				

				this.pro.style.fontSize = 20
				this.pro.style.leading = 8
				this.pro.width = 269
				this.pro.height = 51
				this.pro.style.color = "#5a1c20"
				this.pro.innerHTML = this.model.GetProStr(this.data.pro_list, ColorUtil.GetColorLight(4))
				this.pro.style.padding = [(this.pro.height - this.pro.contextHeight) / 2, 0, 0, 0];     //垂直居中
				this.awakeIcon.visible = awake
				if (this.data.can_use) {
					this.not_state.visible = false
					this.insertBtn.visible = true
					this.not_suit.visible = false
					if (this.data.type == 1) {
						this.labelDisplay.text = "镶嵌"
					} else {
						this.labelDisplay.text = "替换"
					}
				} else {
					this.insertBtn.visible = false
					if (this.data.pos_id == 9 || this.data.pos_id == 10 || this.data.goods_vo.subtype == RuneModel.IgnoreAttackSubType || this.data.goods_vo.subtype == RuneModel.IgnoreDefendSubType) {
						this.not_suit.visible = true
						this.not_state.visible = false
					} else {
						this.not_suit.visible = false
						this.not_state.visible = true
					}
				}
			}
		}
	}

	public DeleteMe(){
		if (this.item) {
			this.item.DeleteMe()
			this.item = null
		}
		super.DeleteMe()
	}
	
	bg: Laya.Image
	icon_bg: Laya.Image
	goods_name: Laya.HTMLDivElement
	pro: Laya.HTMLDivElement
	insertBtn: Laya.Box
	_Image1: Laya.Image
	labelDisplay: Laya.Label
	not_state: Laya.Image
	not_suit: Laya.Image
	icon_conta: Laya.Box
	awakeIcon: Laya.Image
	public GetComponents() {
		[
			this.bg,
			this.icon_bg,
			this.goods_name,
			this.pro,
			this.insertBtn,
			this._Image1,
			this.labelDisplay,
			this.not_state,
			this.not_suit,
			this.icon_conta,
			this.awakeIcon,
		]
			= this.GetChildrenByNames([

				"bg",
				"icon_bg",
				"goods_name",
				"pro",
				"insertBtn",
				"_Image1",
				"labelDisplay",
				"not_state",
				"not_suit",
				"icon_conta",
				"awakeIcon",
			])
	}
}
window["RuneBagItem"] = RuneBagItem