import { BaseWindowComponent } from "../common/BaseWindowComponent"
import { EventName } from "../common/EventName"
import { FashionModel } from "../commonModel/FashionModel"
import { MainFunc } from "../commonModel/MainUIModel"
import { GlobalEventSystem } from "../util/DeclareGlobalVar"
import "./FashionMainView"
import "./HeadFashionMainView"
import "../dress/DressView"
import "../dress/DressSubView"
import { DressEvent, DressModel } from "../commonModel/DressModel"


export class FashionBaseView extends BaseWindowComponent {
	InitMyEvent
	Local_CloseFunc
	bg_list
	destroy_imm
	is_open
	money_list
	tabStrList
	titleStr
	viewClassList
	window_load_back

	public constructor() {
		super()


		this.is_open = false;
		let fashion_model = FashionModel.GetInstance()
		let local_FashionModel = FashionModel
		let local_GlobalEventSystem = GlobalEventSystem
		let UPDATE_BASE_WINDOWS_COMPONENT_RED_STATE = EventName.UPDATE_BASE_WINDOWS_COMPONENT_RED_STATE
		let isbackId_ = false
		this.destroy_imm = true
		this.dependent_res = ["fashion", "dress"]
		this.tabStrList = [{ label: "时装", icon_down_source: "fashion_json.uirw_013_r2_c1_png", icon_up_source: "fashion_json.uirw_013_r2_c2_png" },
		//{label:"武器", icon_down_source:"fashion_asset.uirw_013_r1_c1", icon_up_source:"fashion_asset.uirw_013_r1_c2"}, 
		{ label: "发饰", icon_down_source: "fashion_json.uibb_005a_01_png", icon_up_source: "fashion_json.uibb_005a_02_png" },
		{ label: "装扮", icon_down_source: "fashion_json.uirw_013_r5_c1v_png", icon_up_source: "fashion_json.uirw_013_r5_c2_png" }]
		// [ts2lua]window下标访问可能不正确
		this.viewClassList = ["FashionMainView", "HeadFashionMainView", "DressView"] // WeaponFashionMainView
		this.titleStr = "fashion.fashion_icon_image_png"
		//this.money_list = [2, 1, 0]s
		this.bg_list = ["ui_role_bg3.jpg", "ui_role_bg3.jpg", "ui_role_bg4.jpg"] //[2]="uiszv3_001_720x1222.jpg",
		this.window_load_back = () => {
			this.InitMyEvent()
			let red0 = fashion_model.IsPosShowRed(local_FashionModel.ClothesType)
			local_GlobalEventSystem.Fire(UPDATE_BASE_WINDOWS_COMPONENT_RED_STATE, "FashionBaseView", 0, red0)
			//let red1 = fashion_model.IsPosShowRed(local_FashionModel.WeaponType)
			//local_GlobalEventSystem:Fire(UPDATE_BASE_WINDOWS_COMPONENT_RED_STATE, "FashionBaseView", 2, red1)
			let red2 = fashion_model.IsPosShowRed(local_FashionModel.HeadType)
			local_GlobalEventSystem.Fire(UPDATE_BASE_WINDOWS_COMPONENT_RED_STATE, "FashionBaseView", 1, red2)
		}

		this.InitMyEvent = () => {
			let dot_fun = () => {
				local_GlobalEventSystem.Fire(UPDATE_BASE_WINDOWS_COMPONENT_RED_STATE, "FashionBaseView", 2, DressModel.GetInstance().DressCanShowRedDot())
			}

			this.BindEvent(DressModel.GetInstance(), DressEvent.DRESS_UPDATE_RED_DOT, dot_fun)
			dot_fun()
		}

		this.Local_CloseFunc = () => {
			super.CloseFunc()
			if (!isbackId_) {
				local_GlobalEventSystem.Fire(EventName.SWITCH_MAIN_FUNC_VIEW, MainFunc.Role)
			}
			isbackId_ = false
		}


	}

	public Open(...new_args) {

		let parms = new_args
		if (parms && parms.length > 0) {
			this.SetIndexParameter(parms[0], parms[1], parms[3])
		}
		super.Open()
	}

	public CloseFunc() {

		this.Local_CloseFunc()
	}
}
window["FashionBaseView"]=FashionBaseView