import { BaseView1 } from "../common/BaseView1"
import { EquipmentItem } from "../common/EquipmentItem"
import { Enum_UILayer } from "../common/LayerManager"
import { ResManager } from "../common/ResManager"
import { GoodsModel } from "../commonModel/GoodsModel"
import { ErlangParser } from "../util/ErlangParser"
import { Util } from "../util/Util"

export class EveningNewRankRewardView extends BaseView1 {
	background_alpha
	click_bg_toClose
	data
	destroy_callback
	destroy_imm
	item_list
	model
	needRefreshData
	use_background2


	res_mgr

	public constructor() {
		super()


		this.base_file = "evening"
		this.layout_file = "EveningNewRankRewardView"
		this.layer_value = Enum_UILayer.Activity
		this.destroy_imm = true
		this.use_background2 = true
		this.click_bg_toClose = true
		this.background_alpha = 0
		this.item_list = []
		this.preload_client_config={"config_guild_point_rank.json":false}
		this.res_mgr = ResManager.GetInstance(),
		//this.model = DungeonPartnerModel.GetInstance()



		this.load_callback = () => {



			this.InitEvent()

			// let mask = this.GetChild("sv/Viewport").GetComponent("Image")

			// this.RegisterMask(mask)

			if (this.needRefreshData) {

				this.UpdateView()

				this.needRefreshData = null

			}

		}



		this.destroy_callback = () => {

			this.Clear()

		}

	}



	public InitEvent() {


		var onClickBtnHandler = (target, x, y) => {

			if (target == this.close) {

				this.Close()

			}

		}

		Util.AddClickEvent(this.close, onClickBtnHandler, this, true)

	}



	public Open(data?) {


		super.Open()

		this.data = data

		this.UpdateView()

	}



	//data:  {level, stage_info = [score, status]]

	public UpdateView() {


		if (!this.is_loaded) {

			this.needRefreshData = true

			return

		}

		// this._tip.visible = 0 == stage_info.status  //未领取

		this.txt_title.text = `第${this.data.rank}名奖励`   //string.format("第%d名奖励", this.data.rank)

		this.txt_tip.text = `公会答题结算第${this.data.rank}名，全部公会成员可获得` //string.format("公会答题结算第%d名，全部公会成员可获得", this.data.rank)

		this.data.rank = Math.min(this.data.rank, 4)

		let reward_list = this.res_mgr.GetGameConfigFromCache(this, "ConfigGodBeast", false)//JSON.parse(Config.Guildpointrank[this.data.rank].reward_list)

		let goods_model = GoodsModel.GetInstance()

		for (let i = 0; i < reward_list.length; i++) {
			var v = reward_list[i]

			this.item_list[i] = this.item_list[i] || new EquipmentItem(this.Content, null, this.layer_value)

			let item = this.item_list[i]

			item.SetMaskId(1)

			item.Load()

			item.SetItemSize(96, 96)

			let type_id, lock = goods_model.GetMappingTypeId(v[1], v[2])

			let goods_vo = goods_model.GetGoodsBasicByTypeId(type_id)

			if (goods_vo) {

				item.SetData(goods_vo.type_id, v[3], lock)

				item.SetVisible(true)

			}

		}

	}



	public Clear() {


		for (let i = 0; i < this.item_list.length; i++) {
			var v = this.item_list[i]

			v.DeleteMe()

		}

		this.item_list = []

	}



	bg: Laya.Image
	txt_title: Laya.Label
	close: Laya.Image
	img_tip: Laya.Image
	txt_tip: Laya.Label
	sv: Laya.Panel
	Content: Laya.HBox
	public GetComponents() {
		[
			this.bg,
			this.txt_title,
			this.close,
			this.img_tip,
			this.txt_tip,
			this.sv,
			this.Content,
		]
			= this.GetChildrenByNames([

				"bg",
				"txt_title",
				"close",
				"img_tip",
				"txt_tip",
				"sv",
				"Content",
			])
	}
}


window["EveningNewRankRewardView"] = EveningNewRankRewardView