		this.BtnClickFun = (mode?, value?, force?) => {
			let is_simple_mode = model.GetBlockProperty(SysSetting, "simple_mode")
			let ok_func = () => {
				let setting_list = []
				if (is_simple_mode == 1) {
					//this:SendProtocal(Config.ClientBlockConfig.BlockSubType["simple_mode"], 0)
					table.insert(setting_list, model.Package10203ItemData(this.preload_client_config["ClientBlockConfig"].BlockSubType["simple_mode"], 0))
				}
				let subtype = this.preload_client_config["ClientBlockConfig"].BlockSubType[mode]
				let is_open = model.GetBlockProperty(type_, mode)
				// [ts2lua]lua中0和空字符串也是true，此处is_open == 1需要确认
				is_open = (is_open == 1 && (0) || (1))
				if (value != null) {
					is_open = value
				}
				//this:SendProtocal(subtype, is_open)
				table.insert(setting_list, model.Package10203ItemData(subtype, is_open))
				if (setting_list.length > 0) {
					model.PackageAndSend10203(setting_list)
				}
			}

			let cancle_fun = () => {

			}

			if (is_simple_mode == 1) {
				Alert.Show("您当前处于极简模式，是否确定退出该模式？", Alert_Type.Two, ok_func, cancle_fun, "退出", "取消")
			} else {
				ok_func()
			}
		}

