import { BaseWindowComponent } from "../common/BaseWindowComponent"
import { EventName } from "../common/EventName"
import { InstructionType } from "../common/InstructionType"
import { GuildModel, GuildEvent } from "../commonModel/GuildModel"
import { ServerTimeModel } from "../serverTime/ServerTimeModel"
import { GlobalEventSystem } from "../util/DeclareGlobalVar"
import "./GuildMainView"
import "./GuildMemberView"
import "./GuildRewardBoxView"
import "./GuildJoinView"
import { RedPacketModel } from "../redPacket/RedPacketModel"




export class GuildMainBaseView extends BaseWindowComponent {
	CheckApplyRed
	CheckBoxRed
	CheckRedStatus
	InitSubEvent
	bg_list
	destroy_imm
	instruction_list
	money_list
	tabStrList
	titleStr
	viewClassList
	viewClassModuleDic
	window_load_back
	window_open_back

	public constructor() {
		super()
		this.dependent_res = ["guild"]
		this.destroy_imm = true
		this.titleStr = "guild.guild_001"
		this.money_list = [2, 1, 0]
		this.instruction_list = [InstructionType.Guild]
		this.window_load_back = () => {
			this.InitSubEvent()
		}

		this.window_open_back = () => {
			this.CheckRedStatus()
			this.CheckBoxRed()
			this.CheckApplyRed()
		}

		this.InitSubEvent = () => {
			this.BindEvent(GuildModel.GetInstance(), GuildEvent.UPDATE_BASE_RED_STATUS, () => {
				this.CheckRedStatus()
			}
			)
			this.BindEvent(GuildModel.GetInstance(), GuildEvent.UPDATE_REWARD_BOX_RED, () => {
				this.CheckBoxRed()
			}
			)
			this.BindVar(GuildModel.GetInstance(), "apply_red", () => {
				this.CheckApplyRed()
			}
			)
			this.BindVar(GuildModel.GetInstance(), "exchang_red", () => {
				this.CheckRedStatus()
			}
			)

		}

		this.CheckRedStatus = () => {
			let gmodel = GuildModel.GetInstance()
			let is_show = RedPacketModel.GetInstance().GetAllRedStatus()||
				!gmodel.apply_red_mark
				|| gmodel.CheckEveningRedDot()
				|| gmodel.CheckGiftRedDot()
				|| gmodel.CheckSkillRedDotAll()
				|| gmodel.CheckGuildguardRedDot()
				|| gmodel.guildIdolRed()
				|| gmodel.exchang_red
			GlobalEventSystem.Fire(EventName.UPDATE_BASE_WINDOWS_COMPONENT_RED_STATE, "GuildMainBaseView", 0, is_show)
		}

		this.CheckBoxRed = () => {
			let gmodel = GuildModel.GetInstance()
			let is_show = gmodel.rewardBoxRed()
			GlobalEventSystem.Fire(EventName.UPDATE_BASE_WINDOWS_COMPONENT_RED_STATE, "GuildMainBaseView", 2, is_show)
		}

		this.CheckApplyRed = () => {
			let is_show = GuildModel.GetInstance().apply_red
			GlobalEventSystem.Fire(EventName.UPDATE_BASE_WINDOWS_COMPONENT_RED_STATE, "GuildMainBaseView", 1, is_show)
		}

	}

	public CloseFunc() {

		let openHolyTerritoryView = false
		if (this.nowSelectIndex == 2) {
			openHolyTerritoryView = true
		}
		super.CloseFunc()
		// if (openHolyTerritoryView && HolyTerritoryModel.BackIndex) {
		// 	HolyTerritoryModel.GetInstance().Fire(HTEvent.OPEN_VIEW, "holyTerritoryMainView", HolyTerritoryModel.BackIndex)
		// }
		// HolyTerritoryModel.BackIndex = null
	}

	public Open(...new_args) {

		let parm =new_args[0]
		if (parm) {
			this.SetDefaultIndex(parm[0]||0)
			//this.SetIndexParameter(parm[1], parm[2])
		}

		this.bg_list = ["ui_Guild_bg.jpg", "daily_bg.jpg", "daily_bg.jpg", "daily_bg.jpg"]
		this.viewClassList = ["GuildMainView", "GuildMemberView", "GuildRewardBoxView", "GuildJoinView"]
		this.tabStrList = [{ label: "信息", icon_up_source: "guild_asset.guild_022", icon_down_source: "guild_asset.guild_021" },
		{ label: "成员", icon_up_source: "guild_asset.guild_024", icon_down_source: "guild_asset.guild_023" },
		{ label: "宝箱", icon_up_source: "guild_asset.uigh_018_20", icon_down_source: "guild_asset.uigh_018_19" },
		{ label: "其他", icon_up_source: "guild_asset.uigh_018_26", icon_down_source: "guild_asset.uigh_018_25" }]

		super.Open()
	}
}
window["GuildMainBaseView"] = GuildMainBaseView
