import { BaseItem1 } from "../common/BaseItem1"
import { Config } from "../common/Config"
import { DownDropBtn } from "../common/DownDropBtn"
import { LoopScrCon, LoopScrowViewMgr } from "../common/LoopScrowViewMgr"
import { ResManager } from "../common/ResManager"
import { table } from "../common/table"
import { EquipModel } from "../commonModel/EquipModel"
import { GoodsModel } from "../commonModel/GoodsModel"
import { GuildModel, GuildEvent, GuildPermission } from "../commonModel/GuildModel"
import { RoleManager } from "../role/RoleManager"
import { GameResPath } from "../util/GameResPath"
import { SetAnchoredPositionX, Util } from "../util/Util"
import { GuildDepotItem } from "./GuildDepotItem"
import { GuildDepotRecordItem } from "./GuildDepotRecordItem"

export class GuildDepotView extends BaseItem1 {
	ClickBtnColor
	ClickBtnStage
	FireEvent
	GetGoodDatas
	InitDepotGoodItems
	InitEvent
	InitView
	LoadSuccess
	UpdateDepotItems
	UpdateDepotItemsWithConditon
	UpdateRecordItems
	UpdateTimer
	UpdateView
	_group_depot
	_group_record
	cacheDepotList
	cache_cor
	cache_cor1
	color_btn
	loop_mgr
	loop_mgr1
	model
	stage_btn
	_fixed_good_list

	public constructor(parent?) {
		super(parent)

		this.model = GuildModel.GetInstance();
		this._fixed_good_list = [];
		this.base_file = "guild"
		this.layout_file = "GuildDepotView"
		let stage_cfg = null
		let color_cfg = null
		let goods_cfg = null
		let _set_stage = -1
		let _set_color = -1
		let _set_carrer = false
		let local_ResManager = ResManager.GetInstance()
		let local_GuildEvent = GuildEvent
		let local_RoleManager = RoleManager.GetInstance()
		let local_EquipModel = EquipModel.GetInstance()
		let local_GoodsModel = GoodsModel.GetInstance()
		let local_Config = Config
		let updateTimer
		this.preload_client_config = {
			"ConfigGuild": false
		}
		this.load_callback = () => {

			// this.RegisterMask(this._group_depot)
			// this.cache_cor = GetWorldCorners(this._group_depot)

			// this.cache_cor1 = GetWorldCorners(this._group_record)
			this.LoadSuccess()

			// if (PlatformMgr.GetInstance().IsEyouEnPlatform() ) {
			// 	SetAnchoredPositionX(this._lb_point,187)
			// } else if (PlatformMgr.GetInstance().IsEyouThPlatform() ) {
			//SetAnchoredPositionX(this._lb_point, 187)
			// }


		}

		this.LoadSuccess = () => {
			let cfg = ResManager.GetInstance().GetGameConfigFromCache(this, "ConfigGuild", true)

			this._list_item.vScrollBarSkin = ""
			this._list_msg.vScrollBarSkin = ""

			stage_cfg = cfg.down_drop_depot_stage
			color_cfg = cfg.down_drop_depot_color
			goods_cfg = cfg.depot_goods

			//local_ResManager.SetOutsideImageSprite(this, this.Image3, GameResPath.GetIcon("guild", "uifh_026cjghhuizhang.png"), true)
			//local_ResManager.SetOutsideImageSprite(this, this._Image3, GameResPath.GetIcon("guild", "uifh_026cjghexds"))

			this.InitEvent()
			this.FireEvent()
			this.InitView()
			this.UpdateView()
		}


		this.FireEvent = () => {
			this.model.Fire(local_GuildEvent.REQUEST_PROTO, 40101)
		}

		this.InitEvent = () => {
			Util.AddClickEvent(this._btn_destroy, () => {
				this.model.Fire(local_GuildEvent.OPEN_VIEW, "GuildCleanView")
			}
				, this, true)
			Util.AddClickEvent(this._btn_donate, () => {
				this.model.Fire(local_GuildEvent.OPEN_VIEW, "GuildDepotSelectView")
			}
				, this, true)
			this.BindVar(this.model, "depot_info", () => {
				this.UpdateView()
			}
			)
			this.BindVar(this.model, "depot_score", () => {
				this._lb_point.text = this.model.GetDepotScore()||"0"
			}
			)

			Util.AddClickEvent(this.GameObject, () => {
				_set_carrer = !_set_carrer
				if (_set_carrer) {
					ResManager.GetInstance().SetImageSprite(this, this.image, "common_asset", "com_ui_gx1")
				} else {
					ResManager.GetInstance().SetImageSprite(this, this.image, "common_asset", "com_ui_gx")
				}
				this.UpdateDepotItemsWithConditon(true)
			}, this)
		}

		this.UpdateView = () => {
			let depot_info = this.model.GetDepotInfo()
			if (!depot_info) {
				return
			}
			this._lb_point.text = depot_info.depot_score||"0"
			this.UpdateRecordItems(depot_info.exchange_records)
			this.UpdateDepotItemsWithConditon(false)
		}

		this.InitView = () => {
			this._btn_destroy.visible = this.model.HasPermission(GuildPermission.WAREHOUSE_MANAGER)
			let list = []
			for (let _ in stage_cfg) {
				var vo = stage_cfg[_]
				table.insert(list, vo)
			}
			table.sort(list, (a?, b?) => {
				return a.cond < b.cond
			})
			this.stage_btn = new DownDropBtn(this._dd_stage)
			this.stage_btn.Init(list, this.ClickBtnStage, "品阶选择", "content", this.layer_value, 5)
			this.stage_btn.Load()

			let color_list = []
			for (let _ in color_cfg) {
				var vo = color_cfg[_]
				table.insert(color_list, vo)
			}
			table.sort(color_list, (a?, b?) => {
				return a.cond < b.cond
			})
			this.color_btn = new DownDropBtn(this._dd_color)
			this.color_btn.Init(color_list, this.ClickBtnColor, "品质选择", "content", this.layer_value, 5)
			this.color_btn.Load()



			//this._ac_depot = eui. new ArrayCollection()
			//this._group_depot.dataProvider = this._ac_depot
			//this._group_depot.itemRenderer = GuildDepotItem

			this.loop_mgr1 = new LoopScrowViewMgr()
			this.loop_mgr1.SetData(this._list_msg, GuildDepotRecordItem, {}, LoopScrCon.Vertical)


			//this._ac_record = eui. new ArrayCollection()
			//this._group_record.dataProvider = this._ac_record
			//this._group_record.itemRenderer = GuildDepotRecordItem

			this.InitDepotGoodItems()
		}

		this.ClickBtnStage = (index?, data?) => {
			_set_stage = data.cond
			this.UpdateDepotItemsWithConditon(true)
		}

		this.ClickBtnColor = (index?, data?) => {
			_set_color = data.cond
			this.UpdateDepotItemsWithConditon(true)
		}

		this.UpdateDepotItems = (list?, updateNow?, forceReset?) => {
			if (!updateNow) {
				clearTimeout(this.UpdateTimer)
				this.cacheDepotList = list
				this.UpdateTimer = setTimeout(() => {
					this.UpdateDepotItems(this.cacheDepotList, true, forceReset)
				}, 0.2)
				return
			}
			let equip_attr_cfg = local_ResManager.GetGameConfigFromCache(this, "Equipattr", false)
			let role_sex = RoleManager.GetInstance().GetMainRoleSex()
			table.sort(list, (v2?, v1?) => {
				if (v1.color > v2.color) {
					return false
				} else if (v1.color < v2.color) {
					return true
				}
				if (v1.stage > v2.stage) {
					return false
				} else if (v1.stage < v2.stage) {
					return true
				}
				if (v1.star > v2.star) {
					return false
				} else if (v1.star < v2.star) {
					return true
				}
				if (v1.sex != v2.sex) {
					if (v1.sex == 0) {
						return true
					} else if (v2.sex == 0) {
						return false
					} else {
						return v1.sex != role_sex
					}
				}
				if (v1.equip_type > v2.equip_type) {
					return false
				} else if (v1.equip_type < v2.equip_type) {
					return true
				}
			})

			let goods_list = []

			for (let _tmpi in this._fixed_good_list) {
				var info = this._fixed_good_list[_tmpi]
				info.is_item = true
				table.insert(goods_list, info)
			}

			for (let _ in list) {
				var value = list[_]
				value.is_item = true
				table.insert(goods_list, value)
			}

			//goods_list = table.merge(goods_list, list)

			if (!this.loop_mgr) {
				this.loop_mgr = new LoopScrowViewMgr()
				this.loop_mgr.SetData(this._list_item, GuildDepotItem, goods_list, LoopScrCon.Vertical)
			} else {
				this.loop_mgr.replaceAll(goods_list, forceReset)
			}

		}

		this.UpdateRecordItems = (list?) => {
			this.loop_mgr1.replaceAll(list)
			//this._ac_record.source = list
		}
		//forceReset 设置位置到初始
		this.UpdateDepotItemsWithConditon = (forceReset?) => {
			let depot_info = this.model.GetDepotInfo()
			if (!depot_info) {
				return
			}
			if ((_set_carrer == false && _set_color == -1) && _set_stage == -1) {
				this.UpdateDepotItems(depot_info.depot_goods, null, forceReset)
			} else {
				let list = []
				let career = local_RoleManager.GetMainRoleVo().career
				let sex = local_RoleManager.GetMainRoleVo().sex
				for (let _tmpi in depot_info.depot_goods) {
					var info = depot_info.depot_goods[_tmpi]
					let cfg = local_Config.GetConfigVo(local_Config.ConfigHasDefaultValue.config_goods.name, info.type_id, false)
					if (_set_color != -1 && _set_color != cfg.color) {
					} else {
						let equip_attr_cfg = local_ResManager.GetGameConfigFromCache(this, "Equipattr", false)
						if (_set_stage != -1 && _set_stage != local_EquipModel.GetStageByTypeId(info.type_id, equip_attr_cfg)) {
						} else {
							if ((_set_carrer && cfg.career_id != 0) && career != cfg.career_id) {
							} else {
								if ((_set_carrer && cfg.sex != 0) && sex != cfg.sex) {
								} else {
									table.insert(list, info)
								}
							}
						}
					}
				}
				this.UpdateDepotItems(list, null, forceReset)
			}
		}

		this.InitDepotGoodItems = () => {
			this._fixed_good_list = this.GetGoodDatas()
		}

		this.GetGoodDatas = () => {
			let list = []
			for (let _tmpi in goods_cfg) {
				var cfg = goods_cfg[_tmpi]
				let info = Util.DeepCopy(cfg)
				local_GoodsModel.SetBaseInfo(info)
				info.is_depot_fixed = true
				table.insert(list, info)
			}
			return list
		}
	}

	public DeleteMe() {

		if (this.loop_mgr) {
			this.loop_mgr.DeleteMe()
			this.loop_mgr = null
		}
		if (this.loop_mgr1) {
			this.loop_mgr1.DeleteMe()
			this.loop_mgr1 = null
		}
		if (this.stage_btn) {
			this.stage_btn.DeleteMe()
			this.stage_btn = null
		}
		if (this.color_btn) {
			this.color_btn.DeleteMe()
			this.color_btn = null
		}
		if (this.UpdateTimer) {
			clearTimeout(this.UpdateTimer)
			this.UpdateTimer = null
		}
		super.DeleteMe()
	}


	_Image11: Laya.Image
	_img_bg: Laya.Image
	_Image2: Laya.Image
	Image3: Laya.Image
	_list_item: Laya.List
	_Image3: Laya.Image
	_list_msg: Laya.List
	_Label1: Laya.Label
	_lb_point: Laya.Label
	_btn_destroy: Laya.Box
	_Image1: Laya.Image
	labelDisplay: Laya.Label
	_btn_donate: Laya.Box
	_Image111: Laya.Image
	labelDisplay1: Laya.Label
	_dd_stage: Laya.Box
	_dd_color: Laya.Box
	GameObject: Laya.Box
	image: Laya.Image
	text: Laya.Label
	public GetComponents() {
		[
			this._Image11,
			this._img_bg,
			this._Image2,
			this.Image3,
			this._list_item,
			this._Image3,
			this._list_msg,
			this._Label1,
			this._lb_point,
			this._btn_destroy,
			this._Image1,
			this.labelDisplay,
			this._btn_donate,
			this._Image111,
			this.labelDisplay1,
			this._dd_stage,
			this._dd_color,
			this.GameObject,
			this.image,
			this.text,
		]
			= this.GetChildrenByNames([

				"_Image11",
				"_img_bg",
				"_Image2",
				"Image3",
				"_list_item",
				"_Image3",
				"_list_msg",
				"_Label1",
				"_lb_point",
				"_btn_destroy",
				"_Image1",
				"labelDisplay",
				"_btn_donate",
				"_Image111",
				"labelDisplay1",
				"_dd_stage",
				"_dd_color",
				"GameObject",
				"image",
				"text",
			])
	}
}

window["GuildDepotView"]=GuildDepotView