	public static GetModelClotheRes(obj_type, obj_id, is_god_wing = false) {
		if (!obj_id || Number(obj_id) == 0) {
			return ""
		}
		let abName
		if (is_god_wing) {
			abName = ModelPartName[7] + obj_id;
		} else if (obj_type == SceneBaseType.Pet || obj_type == SceneBaseType.God) {
			abName = ModelPartName[obj_type] + obj_id
		} else if (obj_type == SceneBaseType.Horse) {//坐骑
			abName = ModelPartName[10] + obj_id
		} else if (obj_type == SceneBaseType.Sprite) {//精灵
			abName = ModelPartName[13] + obj_id
		} else if (obj_type == SceneBaseType.Shengqi) {//圣器
			abName = ModelPartName[12] + obj_id
		} else if (obj_type == SceneBaseType.Partner) {//契灵/伙伴
			abName = ModelPartName[14] + obj_id
		} else if (obj_type == SceneBaseType.Demon) {//使魔
			abName = ModelPartName[15] + obj_id
		} else {
			abName = ModelPartName[1] + obj_id
		}
		return abName
	}

	public static GetTypePath(obj_type, res_name) {
		let mName
		if (obj_type == SceneBaseType.Role || obj_type == SceneBaseType.MainRole) {
			mName = "role"
		} else if (obj_type == SceneBaseType.Monster) {
			mName = "monster"
		} else if (obj_type == SceneBaseType.Horse) {
			mName = "mount"
		} else if (obj_type == SceneBaseType.Sprite) {
			mName = "spirit"
		} else if (obj_type == SceneBaseType.Partner) {
			mName = "pet"
		} else if (obj_type == SceneBaseType.Demon) {
			mName = "littlepet"
		}else if (obj_type == SceneBaseType.Npc){
			mName = "npc"
		} else if (obj_type == SceneBaseType.Shengqi) {
			mName = "fabao"
		}
		return GameResPath.GetObjectPath(mName, res_name)
	}

