			// }
		
			// if (this.stand_init_time && Math.ceil(this.stand_init_time + 0.1) % 10 == 0 ) {
			//	 if (rawget(this, "last_casula_time") == null || now_time - this.last_casula_time >= 8 ) {
			//		 this.last_casula_time = now_time
			//		 if (! this.IsJoinWedding()  && ! StoryController.Instance.IsPlaying() &&  ! this.IsGodState() && ! this.IsInMagic() && this.IsInState(PoseState.STAND) && ! this.IsSwimState() && ! this.IsMoveBrickState() && ! SceneManager.GetInstance().IsBeachScene() ) {
