		public UpdateStateMove(state_name?, elapse_time?){ 
			
			this.main_camera.AddAverageTime(elapse_time);
			elapse_time = this.main_camera.GetAverageTime() || elapse_time;
			if (elapse_time > 0.1) {
				elapse_time = 0.1;
			}
			if (elapse_time > 0.1 ) {
				elapse_time = 0.1
			}
			if (this.last_elapse_time && elapse_time - this.last_elapse_time > (0.25 * this.last_elapse_time) ) {
				this.last_elapse_time = this.last_elapse_time + (elapse_time - this.last_elapse_time) * 0.25
				elapse_time = this.last_elapse_time
			} else if (this.last_elapse_time && this.last_elapse_time - elapse_time > (0.25 * this.last_elapse_time) ) {
				this.last_elapse_time = this.last_elapse_time - (this.last_elapse_time - elapse_time) * 0.25
				elapse_time = this.last_elapse_time
			}else{
				this.last_elapse_time = elapse_time
			}
			//普通移动方式刷新
			let move_dist = this.GetMoveSpeed(this.dir_move_param && this.dir_move_param.direction || this.state_move_dir) * elapse_time
			if (this.cache_move_dist != null ) {
				move_dist = (move_dist + this.cache_move_dist) / 2
			}
			this.cache_move_dist = move_dist
			if (! this.dir_move_param ) {
				//移动状态更新
				this.state_move_pass_distance = this.state_move_pass_distance + move_dist
		
				let state_move_pass_distance = this.state_move_pass_distance
				if (! this.state_move_total_distance ) {
					this.state_move_total_distance = 0
				}
				if (state_move_pass_distance >= this.state_move_total_distance ) {
					this.state_move_pass_distance = this.state_move_total_distance
		
					this.SetRealPos(this.state_move_end_pos.x, this.state_move_end_pos.y)
					this.ChangeState(PoseState.WAITSTAND)
				}else{
					let new_x = this.state_move_start_pos.x + this.state_move_dir.x * state_move_pass_distance
					let new_y = this.state_move_start_pos.y + this.state_move_dir.y * state_move_pass_distance
					//异常情况下如果将要从非障碍区走进障碍区，就停止移动
					// if (! this.IsFlying() && ! this.ignore_block ) {
					// 	let lx = new_x / SceneObj.GetLogicRealRatio().x
					// 	let ly = new_y / SceneObj.GetLogicRealRatio().y
					// 	if (! SceneManager.GetInstance().IsBlockXY(this.logic_pos.x, this.logic_pos.y) && SceneManager.GetInstance().IsBlockXY(lx, ly) ) {
					// 		console.log("//-障碍区//-", this.logic_pos.x, this.logic_pos.y, lx, ly)
					// 		OperateManager.Instance.StopMove()
					// 		GlobalEventSystem.Fire(SceneEventType.MAIN_ROLE_MOVE_TO_BLOCK)
					// 		return
					// 	}
					// }
					//////////////////////////////////////////////-
					this.SetRealPos(new_x, new_y)
				}
		
				//方向型移动方式刷新
			}else{
				let direction = this.dir_move_param.direction
				let mx = direction.x * move_dist
				let my = direction.y * move_dist
				let rx = this.real_pos.x + mx
				let ry = this.real_pos.y + my
				let lx = rx / SceneObj.GetLogicRealRatio().x
				let ly = ry / SceneObj.GetLogicRealRatio().y
		
				//新坐标不是障碍，直接走过去
				if (! SceneManager.GetInstance().IsBlockXY(lx, ly) || this.IsFlying() ) {
					this.SetRealPos(rx, ry)
					this.state_move_pass_distance = this.state_move_pass_distance + move_dist
		
					//如果是障碍，就尝试沿一个方向进行平移
				}else{
					GlobalEventSystem.Fire(SceneEventType.MAIN_ROLE_MOVE_TO_BLOCK, lx, ly, true)
					rx =  this.real_pos.x + mx
					ry = this.real_pos.y
					lx = rx / SceneObj.GetLogicRealRatio().x,
					ly =  ry / SceneObj.GetLogicRealRatio().y
					if (! SceneManager.GetInstance().IsBlockXY(lx, ly) ) {
						this.SetRealPos(rx, ry)
						this.state_move_pass_distance = this.state_move_pass_distance + Math.abs(mx)
					}else{
						rx = this.real_pos.x
						ry =  this.real_pos.y + my
						lx = rx / SceneObj.GetLogicRealRatio().x
						ly =  ry / SceneObj.GetLogicRealRatio().y
						if (! SceneManager.GetInstance().IsBlockXY(lx, ly) ) {
							this.SetRealPos(rx, ry)
							this.state_move_pass_distance = this.state_move_pass_distance + Math.abs(my)
						}
					}
				}
			}
		
			this.TrySendPos()
		}
		
