    //判断字典表是否长度为0
    public static IsTableEmpty(table) {
        if (table) {
            for (let i in table) {
                if (table[i] != null) {
                    return false;
                }
            }
        }
        return true;
    }
    //获取table长度 
    //judge_value 是否判断表的值
    public static TableSize(table, judge_value: boolean = false) {
        let len = 0;
        if (table) {
            if (judge_value) {
                let obj
                for (let index in table) {
                    obj = table[index]
                    if (obj) {
                        len++;
                    }
                }
            } else {
                for (let index in table) {
                    len++;
                }
            }

        }
        return len;
    }
    //无符号的32位转换成有符号的32位
    public static UnsignToSigned(number) {
        if (number >= 4000000000) //无符号的数大于这个数默认为负数了
            return -1 * ~(number - 1);
        else
            return number;
    }
    public static ErrorCodeShow(code, strParam?: string) {
        ResManager.GetInstance().GetGameConfigWithAutoDestory("config_error_code", (cfg) => {
            let tmp = cfg[code];
            let str = `未知返回码 ${code}`;
            if (tmp) {
                str = tmp.about ? tmp.about : tmp;
                if (strParam) {
                    let args = strParam.split("#&");
                    let v: string;
                    for (let i = 0; i < args.length; i++) {
                        v = args[i];
                        str = str.replace("{" + (i + 1) + "}", v);
                    }
                }
            }
            let Message = window["Message"]
            Message.show(str);
        }, false);
    }
