    //是否大屏手机
    public static IsLargeScreenDevice() {
        let stage = LayerManager.GetInstance().stage;
        if (stage) {
            if (stage.width / stage.height > 870 / 1560) {
                return true;
            }
        }
        return false;
    }
    public static SetLargeScreenImageSize(obj: Laya.Image, img_width, img_height) {
        if (!Laya.Browser.onPC && obj) {
            let stage = LayerManager.GetInstance().stage;
            if (Util.IsLargeScreenDevice()) {
                obj.width = stage.width;
                obj.height = img_height * (stage.width / img_width);
            }
        }
    }
    //获取设备系统
    public static GetDeviceOS() {
        let curr_os = -1;
        if (Util.IsWXGame() || Util.IsDouYinGame() || Util.IsMeiTuanGame() || Util.IsBiLiBiLiGame()) {
            if (!Util._wx_sys_info && window["wx"] && window["wx"].getSystemInfoSync) {
                let sys_info = window["wx"].getSystemInfoSync();
                Util._wx_sys_info = sys_info;
            }
            if (Util._wx_sys_info) {
                if (Util._wx_sys_info.system.indexOf("Android") >= 0 || Util._wx_sys_info.system.indexOf("android") >= 0) {
                    curr_os = DEVICE_OS.ANDORID;
                }
                else {
                    curr_os = DEVICE_OS.IOS;
                }
            }
        }
        else if (Util.IsQQGame()) {
            let sys_info = window["qq"] && window["qq"].getSystemInfoSync();
            if (sys_info) {
                if (sys_info.system.indexOf("Android") >= 0) {
                    curr_os = DEVICE_OS.ANDORID;
                }
                else {
                    curr_os = DEVICE_OS.IOS;
                }
            }
        }
        else if (Util.IsBaiduGame()) {
            let sys_info = window["swan"] && window["swan"].getSystemInfoSync();
            if (sys_info) {
                if (sys_info.system.indexOf("Android") >= 0) {
                    curr_os = DEVICE_OS.ANDORID;
                }
                else {
                    curr_os = DEVICE_OS.IOS;
                }
            }
        }
        else if (Util.IsQuickGame()) {
            curr_os = DEVICE_OS.ANDORID;
        }
        else {
            // let os = window["Capabilities_os"] || egret.Capabilities.os;
            // if (os == "iOS") {
            //     if (egret.Capabilities.runtimeType == egret.RuntimeType.RUNTIME2) {
            //         curr_os = DEVICE_OS.IOS_APP;
            //     }
            //     else {
            //         curr_os = DEVICE_OS.IOS;
            //     }
            // }
            // else if (os == "Android") {
            //     curr_os = DEVICE_OS.ANDORID;
            // }
            // else if (os == "Windows PC") {
            //     curr_os = DEVICE_OS.WINDOWS_PC;
            // }
        }
        return curr_os;
    }
    //深拷贝对象
    public static DeepCopy(source) {
        var result: any;
        if (source) {
            //  let _type = Object.getPrototypeOf(source) 
            //  if (_type && _type.constructor.name == "Array"){
            if (Array.isArray(source)) {
                result = [];
            }
            else {
                result = {};
            }
            for (var key in source) {
                result[key] = typeof source[key] == 'object' ? Util.DeepCopy(source[key]) : source[key];
            }
        }
        return result;
    }
