    //删除游戏启动界面
    public static RemoveGameStartLoading() {
        if (Util.IsMiniGame()) {
            let loading_view = window["wxLoadingView"];
            if (loading_view) {
                if (Util.IsDouYinGame() || Util.IsMeiTuanGame() || Util.IsBiLiBiLiGame()) {
                    window["wxLoadingView"].scaleX = 0;
                }
                else {
                    if (loading_view.parent) {
                        loading_view.parent.removeChild(loading_view);
                    }
                    window["wxLoadingView"] = null;
                }
            }
        }
        else if (Util.IsRuntime2()) {
            let loading_view = window["wxLoadingView"];
            if (loading_view && loading_view["CloseMyself"] && loading_view.parent) {
                loading_view.parent.setChildIndex(loading_view, 999);
                loading_view["CloseMyself"]();
            }
        }
        else {
            var d = document.getElementById("loadingDiv");
            if (d) {
                // d.style.top = "0%"
                // d.style.left = "0%"
                document.body.removeChild(d);
            }
        }
        if (window["timeSi"] > 0) {
            clearInterval(window["timeSi"]);
            window["timeSi"] = null;
        }
    }
