    public static CheckMoney(value, call_back?, is_bind_diamond = true, not_show = true, go_to_recharge = false) {
        let RoleManager = window["RoleManager"]
        let bool = false, vo = RoleManager.GetInstance().GetMainRoleVo(), bind_diamond = vo.jinLock, diamond = vo.jin;
        let go_to_recharge_func = () => {
            if (not_show)
                return;
        };
        if (is_bind_diamond) {
            if (value > bind_diamond) {
                if (value > bind_diamond + diamond) {
                    go_to_recharge_func();
                }
                else {
                    let Alert = window["Alert"]
                    let Alert_Type = window["Alert_Type"]
                    Alert.Show("绑钻不足是否使用钻石代替？", Alert_Type.Two, () => {
                        call_back();
                    });
                }
            }
            else {
                bool = true;
            }
        }
        else {
            if (value > diamond) {
                go_to_recharge_func();
            }
            else {
                bool = true;
            }
        }
        return bool;
    }
