    public static MeiTuanSupportRecharge() {
        if (Util.IsMeiTuanGame() && window["mt_sys_info"] && window["mt_sys_info"].version && Util.GetDeviceOS() == DEVICE_OS.ANDORID
            && Util.meituan_is_support_recharge == null) {
            let version = window["mt_sys_info"].version;
            let arr = version.split(".");
            console.warn("美团当前版本-----------:", arr);
            Util.meituan_is_support_recharge = false;
            if (arr && arr[0] && arr[1] && arr[2]) {
                let version_no = Number(arr[2]) * 1 + Number(arr[1]) * 1000 + Number(arr[0]) * 1000000;
                let min_version = 200 * 1 + 6 * 1000 + 11 * 1000000; //最低版本号 "11.6.200"
                if (version_no >= min_version) {
                    console.warn("美团当前版本-----支持充值----");
                    Util.meituan_is_support_recharge = true;
                }
            }
        }
        if (Util.meituan_is_support_recharge) {
            console.warn("美团当前版本-----支持充值----");
        }
        else {
            console.warn("美团当前版本-----不支持充值----");
        }
        return Util.meituan_is_support_recharge;
    }

