    public static IsNull(obj: Laya.Sprite | Laya.Sprite3D) {
        if (!obj || !obj) { return true }
        return obj.destroyed
    }

    public static FindBone(sprite: Laya.Sprite3D | Laya.Sprite3D, bone_name) {
        let find_sprite
        if (!Util.IsNull(sprite)) {

            let num = sprite.numChildren
            let child: Laya.Sprite3D
            for (let i = 0; i < num; i++) {
                child = sprite.getChildAt(i) as Laya.Sprite3D
                if (child) {
                    if (child.name == bone_name) {
                        find_sprite = child
                    }
                    else {
                        find_sprite = Util.FindBone(child, bone_name)
                    }
                }
                if (find_sprite) {
                    break
                }
            }
        }
        return find_sprite
    }

    public static GetComponentsInChildren(sprite: Laya.Sprite3D, type) {
        let list = []

        let loop_func = (sprite) => {
            let num = sprite.numChildren
            let child
            for (let i = 0; i < num; i++) {
                child = sprite.getChildAt(i)
                if (child instanceof type) {
                    list.push(child)
                }
                else {
                    loop_func(child)
                }
            }
        }
        loop_func(sprite)
        return list
    }

