import { HashEventDispatcher } from "../common/HashEventDispatcher";
import { Vector2 } from "../util/Vector2";
import { LayerManager, Enum_UILayer } from "../common/LayerManager";
import { MapManager } from "./MapManager";
// import { RoleManager } from "../role/RoleManager";
import { GlobalEventSystem } from "../util/DeclareGlobalVar";
import { EventName, SceneEventType } from "../common/EventName";
// import { Scene } from "./Scene";
// import { SceneObj } from "./sceneobj/SceneObj";
import { Util, DEVICE_OS, Set3DLocalPosition } from "../util/Util";
import { Scene } from "./Scene";
import { RoleManager } from "../role/RoleManager";
import { MainRole } from "./sceneobj/MainRole";
// import { MainRole } from "./sceneobj/MainRole";
export class CameraManager extends HashEventDispatcher {
	private static _instance: CameraManager;
	private _camera_pos: Vector2 = new Vector2(0, 0);
	private _scene_layer: Laya.Sprite = LayerManager.GetInstance().GetUILayer(Enum_UILayer.Scene);
	// private _sceneObj_layer = LayerManager.GetInstance().GetUILayer(Enum_UILayer.local_SceneObj)
	// private _name_board_layer = LayerManager.GetInstance().GetUILayer(Enum_UILayer.NameBoard)
	private _half_stage_width = LayerManager.GetInstance().stageWidth * 0.5;
	private _half_stage_height = LayerManager.GetInstance().stageHeight * 0.5;
	public main_camera:Laya.Camera
	curr_size = 1;
	base_size = 1;
	private _shake_info_list = [];
	private _is_updating = false;
	//摄像头缓动参数
	private _max_speed_move = 1000;
	private _is_start_move = false;
	private _curr_move_pos_x = 0;
	private _curr_move_pos_y = 0;
	private _end_pos_x = 0;
	private _end_pos_y = 0;
	private _move_dir = new Vector2();
	private _total_dist = 0;
	private _update_average_time_queue = [];
	private _mainrole_move_average_time = 0;
	private _scene_layer_x_off = 0;
	InitEvents;
	UpdateSceneLayerXOff;
	AddAverageTime;
	GetAverageTime;
	GetCameraRatio;
	StartMove;
	StopMove;
	SetCameraPos;
	Update;
	ShakeCamera;
	UpdateShake;
	UpdateCamera;
	CheckInScreen;
	CheckMainCameraX
	CheckMainCameraY
	CheckToStopUpdate;
	WorldToViewPortY;
	WorldToViewPortX;
	ViewPortYToWorld;
	ViewPortXToWorld;
	public constructor() {
		super();
		let _map_mgr = MapManager.GetInstance(),  _mainrole_vo = RoleManager.GetInstance().mainRoleInfo, local_GlobalEventSystem = GlobalEventSystem, local_EventName = EventName, local_Math = Math, local_SceneEventType = SceneEventType;
		this.InitEvents = () => {
			let onStateSizeReset = (x, y) => {
				// let monster_list = Scene.GetInstance().monster_list
				// for (let id in monster_list) {
				//	 monster_list[id].UpdateModelPos();
				// }
				// let main_role:MainRole = Scene.GetInstance().GetMainRole()
				// if (main_role)
				// {
				// 	main_role.SetRealPos(main_role.real_pos.x, main_role.real_pos.y, true);
				// }
				if(this.main_camera)
				{
					this.main_camera.orthographicVerticalSize = y * 0.01; //bitmap放大了多少倍 摄像机投影的尺寸就要缩小多少倍，防止模型跟着bitmap一块变大
				}
				this._half_stage_width = x * 0.5;
				this._half_stage_height = y * 0.5;
				this.UpdateSceneLayerXOff();
				this.UpdateCamera(this._camera_pos.x, this._camera_pos.y, true);
			};
			local_GlobalEventSystem.Bind(local_EventName.STATE_RESET_SIZE, onStateSizeReset);
		};
		this.UpdateSceneLayerXOff = () => {
			let x_off = 0;
			if (Util.GetDeviceOS() == DEVICE_OS.WINDOWS_PC) {
				// if (scene.IsSceneLoaded()) {
				// 	let scene_width = MapManager.GetInstance().GetSceneWidth();
				// 	if (scene_width) {
				// 		if (scene_width < LayerManager.GetInstance().stageWidth) {
				// 			x_off = (LayerManager.GetInstance().stageWidth - scene_width) * 0.5;
				// 		}
				// 	}
				// }
			}
			this._scene_layer_x_off = x_off;
		};
		this.AddAverageTime = (elapse_time) => {
			if (elapse_time < 0.06) {
				if (this._update_average_time_queue.length > 10) {
					this._update_average_time_queue.shift();
				}
				this._update_average_time_queue.push(elapse_time);
			}
		};
		this.GetAverageTime = () => {
			let size = this._update_average_time_queue.length;
			if (size > 0) {
				let total_time = 0;
				for (let time of this._update_average_time_queue) {
					total_time += time;
				}
				this._mainrole_move_average_time = total_time / size;
			}
			return this._mainrole_move_average_time;
		};
		this.GetCameraRatio = () => {
			return this.curr_size / this.base_size;
		};
		this.StartMove = (speed?) => {
			this._is_start_move = true;
			if (speed) {
				this._max_speed_move = speed;
			}
			else {
				this._max_speed_move = _mainrole_vo.move_speed;
			}
			if (this._curr_move_pos_x == 0 && this._curr_move_pos_y == 0) {
				let main_role:MainRole = Scene.GetInstance().GetMainRole();
				if (main_role) {
					this._curr_move_pos_x = main_role.real_pos.x;
					this._curr_move_pos_y = main_role.real_pos.y;
				}
				else {
					this._curr_move_pos_x = _mainrole_vo.pos_x;
					this._curr_move_pos_y = _mainrole_vo.pos_y;
				}
			}
		};
		this.StopMove = () => {
			this._is_start_move = false;
		};
		this.SetCameraPos = (x, y, force_update: boolean = false) => {
			
			if (1 || force_update) {
				this._is_start_move = false;
				this._total_dist = 0;
				this.CheckToStopUpdate();
				this.UpdateCamera(x, y, force_update);
			}
			else {
				this._end_pos_x = x;
				this._end_pos_y = y;
				this._move_dir.x = this._end_pos_x - this._curr_move_pos_x;
				this._move_dir.y = this._end_pos_y - this._curr_move_pos_y;
				this._total_dist = this._move_dir.normalise();
				this._is_updating = true;
			}
			Set3DLocalPosition(this.main_camera.transform,  this.CheckMainCameraX(x) * 0.01, this.CheckMainCameraY(y) * 0.01, -10);
		};
		this.Update = (now_time, elapse_time) => {
			if (!this._is_updating)
				return;
			elapse_time = this._mainrole_move_average_time || elapse_time;
			this.UpdateShake(now_time, elapse_time);
			if (this._is_start_move == false && this._total_dist == 0) {
				this.CheckToStopUpdate();
			}
			else {
				let curr_step_dist = (1 - (130 - this._total_dist) / 130) * elapse_time * this._max_speed_move;
				let move_end = false;
				if (this._total_dist > curr_step_dist && this._total_dist > 1) {
					this._total_dist -= curr_step_dist;
				}
				else {
					curr_step_dist = this._total_dist;
					this._total_dist = 0;
					move_end = true;
				}
				if (!move_end) {
					// console.log("--------------------------------curr_step_dist", curr_step_dist)
					this._curr_move_pos_x += this._move_dir.x * curr_step_dist;
					this._curr_move_pos_y += this._move_dir.y * curr_step_dist;
					this.UpdateCamera(this._curr_move_pos_x, this._curr_move_pos_y);
				}
				else {
					if (this._is_start_move == false) {
						this.CheckToStopUpdate();
						this.UpdateCamera(this._end_pos_x, this._end_pos_y);
					}
				}
			}
		};
		this.CheckToStopUpdate = () => {
			if (this._is_start_move == false && this._total_dist == 0) {
				this._curr_move_pos_x = 0;
				this._curr_move_pos_y = 0;
				if (this._shake_info_list.length == 0) {
					// this._layer_manager.SetFrameRate(30)
					this._is_updating = false;
				}
			}
		};
		this.ShakeCamera = (shake_type, max_range, shake_speed, shake_cycle) => {
			let curr_dir;
			if (shake_type == "leftandright") {
				curr_dir = 4;
			}
			else if (shake_type == "upanddown") {
				curr_dir = 8;
			}
			else if (shake_type == "less") {
				curr_dir = 5;
			}
			else if (shake_type == "large") {
				curr_dir = 0;
			}
			else {
				return;
			}
			this._shake_info_list.push({ 
				shake_type: shake_type, 
				curr_range: 0, 
				total_range: 0, 
				curr_dir: curr_dir, 
				max_range: max_range, 
				shake_speed: shake_speed, 
				shake_cycle: shake_cycle 
			});
			this._is_updating = true;
		};
		this.UpdateShake = (now_time, elapse_time) => {
			let size = this._shake_info_list.length;
			if (size > 0) {
				let info, x = 0, x_count = 0, y = 0, y_count = 0, scale = 0, s_count = 0, elapse_range;
				for (let i = size - 1; i >= 0; i--) {
					info = this._shake_info_list[i];
					if (info.shake_type == "leftandright") {
						elapse_range = elapse_time * info.shake_speed;
						x_count++;
						let need_change_dir = false;
						if (info.curr_dir == 4) {
							info.curr_range -= elapse_range;
							if (-info.curr_range > info.max_range) {
								elapse_range = elapse_range + info.curr_range + info.max_range;
								info.curr_range = -info.max_range;
								need_change_dir = true;
							}
						}
						else {
							info.curr_range += elapse_range;
							if (info.curr_range > info.max_range) {
								elapse_range = elapse_range - info.curr_range + info.max_range;
								info.curr_range = info.max_range;
								need_change_dir = true;
							}
						}
						info.total_range += elapse_range;
						x += info.curr_range;
						if (info.total_range >= info.shake_cycle * 4 * info.max_range) {
							this._shake_info_list.splice(i, 1);
						}
						else {
							if (need_change_dir) {
								if (info.curr_dir == 4) {
									info.curr_dir = 6;
								}
								else {
									info.curr_dir = 4;
								}
							}
						}
					}
					else if (info.shake_type == "upanddown") {
						y_count++;
						elapse_range = elapse_time * info.shake_speed;
						let need_change_dir = false;
						if (info.curr_dir == 8) {
							info.curr_range -= elapse_range;
							if (-info.curr_range > info.max_range) {
								elapse_range = elapse_range + info.curr_range + info.max_range;
								info.curr_range = -info.max_range;
								need_change_dir = true;
							}
						}
						else {
							info.curr_range += elapse_range;
							if (info.curr_range > info.max_range) {
								elapse_range = elapse_range - info.curr_range + info.max_range;
								info.curr_range = info.max_range;
								need_change_dir = true;
							}
						}
						info.total_range += elapse_range;
						y += info.curr_range;
						if (info.total_range >= info.shake_cycle * 4 * info.max_range) {
							this._shake_info_list.splice(i, 1);
						}
						else {
							if (need_change_dir) {
								if (info.curr_dir == 8) {
									info.curr_dir = 2;
								}
								else {
									info.curr_dir = 8;
								}
							}
						}
					}
					else if (info.shake_type == "less" || info.shake_type == "large") {
						s_count++;
						elapse_range = elapse_time * info.shake_speed;
						let need_change_dir = false;
						if (info.curr_dir == 5) {
							info.curr_range -= elapse_range;
							if (-info.curr_range > info.max_range) {
								elapse_range = elapse_range + info.curr_range + info.max_range;
								info.curr_range = -info.max_range;
								need_change_dir = true;
							}
						}
						else {
							info.curr_range += elapse_range;
							if (info.curr_range > info.max_range) {
								elapse_range = elapse_range - info.curr_range + info.max_range;
								info.curr_range = info.max_range;
								need_change_dir = true;
							}
						}
						info.total_range += elapse_range;
						scale += info.curr_range + 1;
						if( scale < 0 ){
							scale = 0
						}
						if (info.total_range >= info.shake_cycle * 4 * info.max_range) {
							this._shake_info_list.splice(i, 1);
						}
						else {
							if (need_change_dir) {
								if (info.curr_dir == 5) {
									info.curr_dir = 0;
								}
								else {
									info.curr_dir = 5;
								}
							}
						}
					}
				}
				let map_parent = _map_mgr.map_parent;
				if (x_count) {
					map_parent.x = x / x_count;
				}
				if (y_count) {
					map_parent.y = y / y_count;
				}
				if (s_count) {
					map_parent.scaleX = scale;
					map_parent.scaleY = scale;
				}
				if (this._shake_info_list.length == 0) {
					map_parent.x = 0;
					map_parent.y = 0;
					map_parent.scaleX = 1;
					map_parent.scaleY = 1;
					this.CheckToStopUpdate();
				}
			}
		};
		this.UpdateCamera = function (x, y, force_update: boolean = false) {
			x = local_Math.floor(x + 0.5);
			y = local_Math.floor(y + 0.5);
			if (this._camera_pos.x == x && this._camera_pos.y == y && force_update == false) {
				return;
			}
			let pos_off, 
			h_w = this._half_stage_width, 
			h_h = this._half_stage_height, 
			curr_scene_width = _map_mgr.GetSceneWidth(), 
			curr_scene_height = _map_mgr.GetSceneHeight();
			if (curr_scene_width <= 2 * h_w) {
				this._scene_layer.x = this._scene_layer_x_off;
				// this._name_board_layer.x = 0
				// this._sceneObj_layer.x = 0
				this._camera_pos.x = h_w;
			}
			else {
				pos_off = local_Math.floor(x - h_w + 0.5);
				if (pos_off > 0) {
					if (x > (curr_scene_width - h_w)) {
						this._scene_layer.x = -curr_scene_width + 2 * h_w + this._scene_layer_x_off;
						// this._name_board_layer.x = this._scene_layer.x
						// this._sceneObj_layer.x = this._scene_layer.x
						this._camera_pos.x = curr_scene_width - h_w;
					}
					else {
						this._scene_layer.x = -pos_off + this._scene_layer_x_off;
						// this._name_board_layer.x = -pos_off
						// this._sceneObj_layer.x = -pos_off
						this._camera_pos.x = x;
					}
				}
				else {
					this._scene_layer.x = this._scene_layer_x_off;
					// this._name_board_layer.x = 0
					// this._sceneObj_layer.x = 0
					this._camera_pos.x = h_w;
				}
			}
			if (curr_scene_height <= 2 * h_h) {
				this._scene_layer.y = 0;
				// this._name_board_layer.y = 0
				// this._sceneObj_layer.y = 0
				this._camera_pos.y = h_h;
			}
			else {
				pos_off = local_Math.floor(y - h_h + 0.5);
				if (pos_off > 0) {
					if (y > (curr_scene_height - h_h)) {
						this._scene_layer.y = -curr_scene_height + 2 * h_h;
						// this._name_board_layer.y = this._scene_layer.y
						// this._sceneObj_layer.y = this._scene_layer.y
						this._camera_pos.y = curr_scene_height - h_h;
					}
					else {
						this._scene_layer.y = -pos_off;
						// this._name_board_layer.y = -pos_off
						// this._sceneObj_layer.y = -pos_off
						this._camera_pos.y = y;
					}
				}
				else {
					this._scene_layer.y = 0;
					// this._name_board_layer.y = 0
					// this._sceneObj_layer.y = 0
					this._camera_pos.y = h_h;
				}
			}
			local_GlobalEventSystem.Fire(local_SceneEventType.CAMERA_MOVE, this._camera_pos.x, this._camera_pos.y);
		};
		this.CheckInScreen = (x, y, half_w = 0, h = 0) => {
			if (x + half_w < this._camera_pos.x - this._half_stage_width || x - half_w > this._camera_pos.x + this._half_stage_width
				|| y < this._camera_pos.y - this._half_stage_height + 80 || y > this._camera_pos.y + this._half_stage_height + h - 150) {
				return false;
			}
			return true;
		};
		this.CheckMainCameraX =(x) =>
		{
			if(x < this._half_stage_width || x > (_map_mgr.GetSceneWidth() - this._half_stage_width))
			{
				if(this._camera_pos.x <= 0)
				{
					if(x < this._half_stage_width)
					{
						return this._half_stage_width
					}else
					{
						return _map_mgr.GetSceneWidth() - this._half_stage_width
					}
				}else
				{
					return this._camera_pos.x
				}
			}
			return x
		}
		this.CheckMainCameraY =(y) =>
		{
			if(y < this._half_stage_height || y > (_map_mgr.GetSceneHeight() - this._half_stage_height))
			{
				if(this._camera_pos.y <= 0)
				{
					if(y < this._half_stage_height)
					{
						return this._half_stage_height
					}else
					{
						return _map_mgr.GetSceneHeight() - this._half_stage_height
					}
				}else
				{
					return this._camera_pos.y
				}
			}
			return y
		}
		this.ViewPortXToWorld = (x: number) => {
			return x - this._scene_layer.x;
		};
		this.ViewPortYToWorld = (y: number) => {
			return y - this._scene_layer.y;
		};
		this.WorldToViewPortX = (x: number) => {
			return this._scene_layer.x + x;
		};
		this.WorldToViewPortY = (y: number) => {
			return this._scene_layer.y + y;
		};
		this.InitEvents();
	}

	public static GetInstance() {
		if (!CameraManager._instance) {
			CameraManager._instance = new CameraManager();
		}
		return CameraManager._instance;
	}
}

window["CameraManager"] = CameraManager