import { WorldArtFontManager, SceneFontType } from "./WorldArtFontManager";
import { Scene } from "../Scene";
import { SceneBaseType } from "../SceneConfig";
import { SceneManager } from "../SceneManager";
import { SceneObj } from "../sceneobj/SceneObj";
export enum DamageFlag {
	//服务端
	NORMAL = 0,// 普通
	DUO_BI = 1,// 闪避
	BAO_JI = 2,// 暴击
	MIAN_YI = 3,// 免疫伤害(无敌)
	HUI_XIN = 4,// 会心
	HU_DUN_MIAN_SHANG = 5,// 护盾免伤
	PARRY = 6,// 格挡
	NOTHING = 7,// 无伤害##不触发效果,比如被动技能
	EXC = 8,// 卓越一击
	CRIT_HEART = 9,// 暴击会心
	EXC_HEART = 10,// 卓越会心

	//客户端
	SUCK_BLOOD = 1001,//吸血
	REVERT_DAMAGE = 1002,//反弹
}
window["DamageFlag"] = DamageFlag;
export class FightDamageDisplayer {
	static Instance: FightDamageDisplayer;
	private _fontMgr = WorldArtFontManager.GetInstance();
	private _multi_damage_queue = [];
	ShowFont;
	ShowMainRoleAddHp;
	public constructor() {
		// if (Util.IsMiniGame()) {
		//	 Runner.GetInstance().AddRunObjByHashCode(new BaseClass().hashCode, this, 1, FRAME_TYPE.even)
		// } else {
		//	 Runner.GetInstance().AddRunObjByHashCode(new BaseClass().hashCode, this, 1, FRAME_TYPE.odd)
		// }
		let scene_base_type = SceneBaseType, scene_mgr = SceneManager.GetInstance(), scene_font_type = SceneFontType, damage_flag = DamageFlag;
		this.ShowFont = (flag: DamageFlag, value, attacker?, defender?: SceneObj) => {
			if (!value)
				return;
			if (!attacker)
				return;


			let attacker_type = attacker.GetType();

			let is_attacker = attacker_type == scene_base_type.MainRole || (
				(
					attacker_type == scene_base_type.Partner
				) 
				&& attacker.owner && attacker.owner.GetType() == scene_base_type.MainRole
					
				)


			let can_show = scene_mgr.ShowAllDamageScene()
				|| defender.GetType() == scene_base_type.MainRole
				|| is_attacker

			if (!can_show) {
				return;
			}

			let value_str = value, font_type;

			if(is_attacker)
			{
				font_type = scene_font_type.DAMAGE_MAINROLE
				if (attacker_type == scene_base_type.Partner) {
					font_type = scene_font_type.PARTNER_DAMAGE;
					value_str = `f${value}`;
				}
				else {
					if (flag == damage_flag.BAO_JI) {
						font_type = scene_font_type.BAOJI_MAINROLE;
						value_str = `f${value}`;
					}else if (flag == damage_flag.DUO_BI) {
						font_type = scene_font_type.SHAN_BI_MAINROLE;
						value_str = "s";
					}else if (flag == damage_flag.HUI_XIN || flag == damage_flag.CRIT_HEART) {
						font_type = scene_font_type.HUI_XIN;
						value_str = `${value}`;
					} else if (flag == damage_flag.EXC || flag == damage_flag.EXC_HEART) {
						font_type = scene_font_type.EXC;
						value_str = `${value}`;
					}
				}
				let x = defender.real_pos.x;
				let y = defender.real_pos.y - defender.GetBodyHeight() / 2;
				this._fontMgr.ShowFont(font_type, value_str, x, y, attacker.GetDirection());
			}
			else{
				font_type = scene_font_type.DAMAGE_OTHER;
				value_str = `${value}`;
				if (flag == damage_flag.DUO_BI) {
					font_type = scene_font_type.SHAN_BI_MAINROLE;
					value_str = "s";
				}
				else if (flag == damage_flag.BAO_JI) {
					font_type = scene_font_type.BAOJI_OTHER;
					value_str = `f${value}`;
				}

				let x = defender.real_pos.x;
				let y = defender.real_pos.y - defender.GetBodyHeight() - 25;
				this._fontMgr.ShowFont(font_type, value_str, x, y, attacker.GetDirection());
			}
		};

		//主角血量增加
		this.ShowMainRoleAddHp = (delta, damage_flag?) => {
			let main_role = Scene.GetInstance().GetMainRole();
			if (main_role && delta > 0) {
				let x = main_role.real_pos.x;
				let y = main_role.real_pos.y - main_role.GetBodyHeight() - 25;
				let font_type = SceneFontType.HP_CHANGE;
				let value_str = `+${delta}`;
				if (damage_flag == DamageFlag.SUCK_BLOOD) {
					font_type = SceneFontType.SUCK_BLOOD;
					value_str = `+${delta}`;
				}
				this._fontMgr.ShowFont(font_type, value_str, x, y, main_role.GetDirection());
			}
		};
	}
	public static GetInstance() {
		if (!FightDamageDisplayer.Instance) {
			FightDamageDisplayer.Instance = new FightDamageDisplayer();
		}
		return FightDamageDisplayer.Instance;
	}
}

window["FightDamageDisplayer"] = FightDamageDisplayer