import { BaseWindowComponent } from "../common/BaseWindowComponent"
import { EventName } from "../common/EventName"
import { InstructionType } from "../common/InstructionType"
import { GuildModel, GuildEvent } from "../commonModel/GuildModel"
import { GlobalEventSystem } from "../util/DeclareGlobalVar"
import "./GuildSkillView"

export class GuildSkillBaseView extends BaseWindowComponent {
InitWindowEvent
RefreshIdolRed
RefreshSkillRed
bg_list
destroy_imm
instruction_list
model
money_list

tabStrList
titleStr
viewClassList
viewClassModuleDic
window_load_back

public constructor(){
super() 
	
	this.model = GuildModel.GetInstance()
	this.dependent_res = ["guild"]
	this.destroy_imm = true
	this.viewClassList = ["GuildSkillView", "GuildIdolMainView"]
	this.titleStr = "guild.guild_001"
	this.money_list = [2, 1, 0]
	this.instruction_list = [null, InstructionType.GuildIdol]
	this.tabStrList = [{label:"公会技能"},
		{label:"公会神像"}]
	//this.viewClassModuleDic = [{module_name="guildIdol", class_name="GuildIdolMainView"]}
	//this.preload_server_config = [Guildskillresearch=false]
	this.RefreshSkillRed = () => {
		let skill_bool = this.model.CheckSkillRedDotAll()
		GlobalEventSystem.Fire(EventName.UPDATE_BASE_WINDOWS_COMPONENT_RED_STATE, "GuildSkillBaseView", 1, skill_bool)
	}
	
	this.RefreshIdolRed = () => {
		let idol_bool = this.model.guildIdolRed()
		GlobalEventSystem.Fire(EventName.UPDATE_BASE_WINDOWS_COMPONENT_RED_STATE, "GuildSkillBaseView", 2, idol_bool)
	}
	this.bg_list = [
		"ui_role_bg5.jpg",
		"uigh_020.jpg"
	]


	this.InitWindowEvent = () => {
		let guild_model = this.model
		let local_GuildEvent = GuildEvent
		this.BindEvent(guild_model, local_GuildEvent.UPDATE_SKILL_RED_STATUS,() => {
				this.RefreshSkillRed()
			}
		)
		this.BindEvent(guild_model, local_GuildEvent.IDOL_AWAKEN_RED_UPDATE,() => {
				this.RefreshIdolRed()
			}
		)
		this.BindEvent(guild_model, local_GuildEvent.IDOL_ACT_RED_UPDATE,() => {
				this.RefreshIdolRed()
			}
		)
		this.BindEvent(guild_model, local_GuildEvent.IDOL_RUNE_RED_UPDATE,() => {
				this.RefreshIdolRed()
			}
		)
		this.RefreshSkillRed()
		this.RefreshIdolRed()
	}

	this.window_load_back = () => {
		this.InitWindowEvent()
	}


}

public Open(...new_args){ 
	
	let parms = new_args
	if (parms && parms[1] ) {
		this.SetDefaultIndex(parms[1])
	}
	super.Open()
}
}

window["GuildSkillBaseView"]=GuildSkillBaseView
