		this.CreatDes = (str?, effect_list?) => {
			if (effect_list) {
				for (let _tmpi in effect_list) {
					var vo = effect_list[_tmpi]
					if ("attr" == vo[0]) {
						let re_str: string = ""

						for (let i = 1; i <= vo[1].length; i++) {
							if (i == vo[1].length) {
								re_str = re_str + "<font color='#00b11d'>" + local_WordManager.GetProperties(vo[0][i][0]) + (" + ") + local_WordManager.ConvertToPercentValue(vo[0][i][0], vo[0][i][1]) + "</font>"
							} else {
								re_str = re_str + "<font color='#00b11d'>" + local_WordManager.GetProperties(vo[0][i][0]) + (" + ") + local_WordManager.ConvertToPercentValue(vo[0][i][0], vo[0][i][1]) + "</font>,"
							}
						}
						//将re_str里的%替换成%%
						re_str = re_str.replace("%%", "%%%%")
						str = str.replace("attr", re_str)
					} else if ("coin" == vo[0]) {
						str = str.replace("coin", Util.HtmlColorTxt(`铜钱`, "'#00b11d'"))
					} else if ("exp_mon" == vo[0]) {
						str = str.replace("exp_mon", Util.HtmlColorTxt(`${vo[1] * 100}%`, "'#00b11d'"))
					}
				}
			}
			return Trim(str)
		}

