import { BaseView1 } from "../common/BaseView1";
import { EquipmentItem } from "../common/EquipmentItem";
import { SceneEventType } from "../common/EventName";
import { Enum_UILayer } from "../common/LayerManager";
import { ResManager } from "../common/ResManager";
import { WordManager } from "../common/WordManager";
import { GoodsModel } from "../commonModel/GoodsModel";
import { TaskModel, TaskType } from "../commonModel/TaskModel";
import { RoleManager } from "../role/RoleManager";
import { SceneManager } from "../scene/SceneManager";
import { GlobalEventSystem } from "../util/DeclareGlobalVar";
import { ErlangParser } from "../util/ErlangParser";
import { GlobalTimerQuest, Util } from "../util/Util";

export class TaskFinishView extends BaseView1 {

    SetTaskReward
    destroy_imm
    use_local_view
    open_callback
    InitEvent
    _Local_Open
    is_delay_callback
    use_background
    CancelTime
    destroy_callback
    LoadSuccess
    StartTime
    show_open_movie
    click_bg_toClose
    OnTime
    InitView

    public constructor() {
        super()
        this.base_file = "task"
        this.layout_file = "TaskFinishView"
        this.layer_value = Enum_UILayer.Activity
        this.destroy_imm = true
        this.use_background = true
        this.click_bg_toClose = true
        this.show_open_movie = true
        this.is_delay_callback = false
        this.is_center = true
        let model = TaskModel.GetInstance()
        let local_TaskModel = TaskModel
        let local_WordManager = WordManager
        let local_TaskType = TaskType
        let local_Util = Util
        let task_vo_ = null
        let item_list_ = null
        let close_time_ = 10
        let time_event_id_ = null
        let has_send_ = false
        this.load_callback = () => {
            this.LoadSuccess()
            this.InitEvent()
        }

        this.open_callback = () => {
            this.InitView()
        }

        this.destroy_callback = () => {
            has_send_ = false
            this.CancelTime()
            if (item_list_) {
                for (let _tmpi in item_list_) {
                    var item = item_list_[_tmpi]
                    item.DeleteMe()
                    item = null
                }
                item_list_ = null
            }
            if (this.finifsh_effect) {
                this.ClearUIEffect(this.finifsh_effect)
            }
        }

        this.LoadSuccess = () => {
            this._Scroller1.hScrollBar.visible = false
            ResManager.GetInstance().SetOutsideImageSprite(this, this.bg, "resource/game/task/texture/uixrw_001b.png", true)
            item_list_ = []
            close_time_ = 10
        }

        this.InitEvent = () => {
            let do_task_fun = () => {
                if (task_vo_) {
                    let finish = this.task_model.IsAllStepFinish(task_vo_.task_id)
                    if (finish) {
                        //this.task_model.Fire(local_TaskModel.CLICK_DO_TASK, task_vo_.task_id, task_vo_.task_type)
                        model.finish_task_vo = null
                        has_send_ = true
                        model.Fire(local_TaskModel.REQUEST_CCMD_EVENT, 30004, task_vo_.task_id)
                        this.Close()
                    }
                }
            }
            local_Util.AddClickEvent(this.finishBtn, do_task_fun, this, true)

            local_Util.AddClickEvent(this.closeBtn, () => {
                this.Close()
            }
                , this, true, null, null, null, null)

            this.BindEvent(GlobalEventSystem, SceneEventType.SCENE_CHANGED, () => {
                if (!SceneManager.GetInstance().IsFieldScene()) {
                    if (!has_send_) {
                        model.finish_task_vo = task_vo_
                    }
                    this.Close()
                }
            }
            )
        }

        this._Local_Open = (param?) => {
            task_vo_ = param
            super.Open()
        }

        this.InitView = () => {
            if (!task_vo_) {
                return
            }
            let tip_str = ""
            let finish = this.task_model.IsAllStepFinish(task_vo_.task_id)
            this.finishBtn.visible = finish
            let task_tips_msg = model.GetTaskTipsMsg(task_vo_)
            if (finish) {
                tip_str = task_tips_msg + "<font color='#639c12'>(完成)</font>"
                //this:AddUIEffect2("ui_completionoftask", this.finifsh_effect, null, null, true)
            } else {
                if (task_vo_.show_num) {
                    let now_str = local_WordManager.FormatNumber(task_vo_.show_num)
                    tip_str = task_tips_msg + "(<font color='#ff4f50'>0/" + now_str + ")</font>"
                } else {
                    let now_str = local_WordManager.FormatNumber(task_vo_.now_num)
                    let need_str = local_WordManager.FormatNumber(task_vo_.need_num)
                    let color_str = (task_vo_.need_num > task_vo_.now_num && ("#ff4f50") || ("#639c12"))
                    tip_str = task_tips_msg + "(<font color='" + color_str + "'>" + now_str + "/" + need_str + ")</font>"
                }
            }
            this.task_target.style.fontSize = 20
            this.task_target.style.valign = "center"
            this.task_target.style.padding = [(this.task_target.height - this.task_target.contextHeight) / 2, 0, 0, 0];     //垂直居中
            this.task_target.innerHTML = Util.StrToHTML((tip_str).trim())
            this.content.text = Util.StrToHTML((task_vo_.desc).trim())
            this.SetTaskReward()
            this.StartTime()
        }

        this.SetTaskReward = () => {
            if (!task_vo_) {
                return
            }
            let award_list = []
            if (task_vo_.task_type == local_TaskType.GUILD || task_vo_.task_type == local_TaskType.DAILY) {
                if (task_vo_.circle_task_normal_reward) {
                    let format_fun = (list?) => {
                        for (let _tmpi in list) {
                            var vo = list[_tmpi]
                            let obj = []
                            obj[0] = vo.type
                            obj[1] = vo.type_id
                            obj[2] = vo.count
                            award_list.push(obj)
                        }
                    }

                    format_fun(task_vo_.circle_task_normal_reward)
                    format_fun(task_vo_.circle_task_extra_reward)
                }
            } else {
                if (task_vo_.special_goods_list) {
                    let list = ErlangParser.GetInstance().Parse(task_vo_.special_goods_list)
                    if (list) {
                        for (let _tmpi in list) {
                            var vo = list[_tmpi]
                            if (Number(vo[1]) == RoleManager.GetInstance().mainRoleInfo.career) {
                                let obj = null
                                obj = []
                                obj[0] = 0
                                obj[1] = Number(vo[2])
                                obj[2] = Number(vo[3])
                                award_list.push(obj)
                            }
                        }
                    }
                }
                let list2 = ErlangParser.GetInstance().Parse(task_vo_.award_list)
                if (list2) {
                    for (let _tmpi in list2) {
                        var vo = list2[_tmpi]
                        award_list.push(vo)
                    }
                }
            }
            //悬赏任务经验值
            if (task_vo_.task_type == local_TaskType.EUDAEMON_TASK) {
                let role_lv = RoleManager.GetInstance().GetMainRoleLevel()
                let obj = [5, 0, Math.ceil(21000000 * Math.pow(1.5, (role_lv - 60) / 120))]
                award_list.push(obj)
            }
            if (item_list_) {
                for (let _tmpi in item_list_) {
                    var item = item_list_[_tmpi]
                    item.SetVisible(false)
                }
            }
            this.reward_con.visible = award_list && award_list.length > 0
            if (this.reward_con.visible) {
                this.finishBtnLabel.text = "领取奖励"
            } else {
                this.finishBtnLabel.text = "提交任务"
            }
            if (award_list && award_list.length) {
                let item = null
                let vo = null
                let i = 0
                do {
                    vo = award_list[i]
                    if (vo) {
                        item = item_list_[i]
                        if (!item) {
                            item = new EquipmentItem(this.Content)
                            item_list_[i] = item
                            item.Load()
                            item.SetScale(0.6)
                        }
                        let [type_id, lock] = GoodsModel.GetInstance().GetMappingTypeId(vo[0], vo[1])
                        item.SetData(type_id, vo[2])
                    }
                    i = i + 1
                } while ((i < award_list.length))
                this.Content.width = award_list.length * 80

            }
        }

        this.StartTime = () => {
            this.CancelTime()
            if (!this.task_model.GetAutoTaskSetting()) {
                if (this.time_label) {
                    this.time_label.text = ""
                }
                return
            }
            var peorid_func = () => {
                if (!this.use_delete_method) {
                    this.OnTime()
                }
            }
            time_event_id_ = GlobalTimerQuest.AddPeriodQuest(peorid_func, 1, -1)
            peorid_func()
        }

        this.OnTime = () => {
            close_time_ = close_time_ - 1
            if (close_time_ <= 0) {
                this.time_label.text = ""
                if (task_vo_) {
                    if (task_vo_.has_finish == 1) {
                        model.Fire(local_TaskModel.REQUEST_CCMD_EVENT, 30004, task_vo_.task_id)
                        this.Close()
                    }
                }
                return
            }
            this.time_label.text = close_time_ + "s后自动提交任务"
        }

        this.CancelTime = () => {
            if (time_event_id_) {
                GlobalTimerQuest.CancelQuest(time_event_id_)
                time_event_id_ = null
            }
        }
    }

    public Open(...new_args) {
        this._Local_Open(...new_args)
    }
    bg: Laya.Image
    image2: Laya.Image
    finifsh_effect: Laya.Box
    closeBtn: Laya.Image
    _Image1: Laya.Image
    content: Laya.Label
    image3: Laya.Image
    image4: Laya.Image
    _Label2: Laya.Label
    icon_tag: Laya.Image
    _Image2: Laya.Image
    _Label1: Laya.Label
    _Image3: Laya.Image
    task_target2: Laya.Label
    task_target: Laya.HTMLDivElement
    time_label: Laya.Label
    reward_con: Laya.Box
    _Image6: Laya.Image
    _Label3: Laya.Label
    _Scroller1: Laya.Panel
    Content: Laya.HBox
    finishBtn: Laya.Box
    _Image5: Laya.Image
    finishBtnLabel: Laya.Label
    public GetComponents() {
        [
            this.bg,
            this.image2,
            this.finifsh_effect,
            this.closeBtn,
            this._Image1,
            this.content,
            this.image3,
            this.image4,
            this._Label2,
            this.icon_tag,
            this._Image2,
            this._Label1,
            this._Image3,
            this.task_target2,
            this.task_target,
            this.time_label,
            this.reward_con,
            this._Image6,
            this._Label3,
            this._Scroller1,
            this.Content,
            this.finishBtn,
            this._Image5,
            this.finishBtnLabel,
        ]
            = this.GetChildrenByNames([

                "bg",
                "image2",
                "finifsh_effect",
                "closeBtn",
                "_Image1",
                "content",
                "image3",
                "image4",
                "_Label2",
                "icon_tag",
                "_Image2",
                "_Label1",
                "_Image3",
                "task_target2",
                "task_target",
                "time_label",
                "reward_con",
                "_Image6",
                "_Label3",
                "_Scroller1",
                "Content",
                "finishBtn",
                "_Image5",
                "finishBtnLabel",
            ])
    }
}
window["TaskFinishView"] = TaskFinishView