    //获取配置项 有些可能需要加上默认值
    public static GetConfigVo(config_name: string, key: number | string, is_client_config = false, config_obj: any = null) {
        let cache_cfg = this.GetConfigFormOwnCache(config_name, key);
        if (cache_cfg) {
            return cache_cfg;
        }
        let cfg;
        if (config_obj == null) {
            if (is_client_config) {
                cfg = Config.PRELOAD_CLIENT_CONFIG[config_name];
                if (!cfg)
                    cfg = Config.PRELOAD_CLIENT_CONFIG[config_name];
            }
            else {
                cfg = Config.PRELOAD_SERVER_CONFIG[config_name];
                if (!cfg)
                    cfg = Config.PRELOAD_SERVER_CONFIG[config_name];
            }
        }
        else {
            cfg = config_obj;
        }
        if (cfg) {
            if (!this._cache_cfg_dic) {
                this._cache_cfg_dic = {};
            }
            if (!this._cache_cfg_dic[config_name]) {
                this._cache_cfg_dic[config_name] = {};
            }
            let vo = cfg[key], default_vo = Config.ConfigHasDefaultValue[config_name];
            this._cache_cfg_dic[config_name][key] = vo;
            if (!default_vo)
                return vo;
            let config_type = default_vo.config_type;
            if (config_type == Config_Type.Nothing) {
                return vo;
            }
            if (vo && vo.has_set_default_value == null) {
                default_vo = Config.GetConfigDefaultVo(config_name, is_client_config);
                if (default_vo) {
                    if (config_type == Config_Type.FilterAndMapped) {
                        let d_vo;
                        let new_vo = {};
                        for (let i = default_vo.length - 1; i >= 0; i--) {
                            d_vo = default_vo[i];
                            if (vo[i] == null) {
                                new_vo[d_vo.key] = d_vo.value;
                            }
                            else {
                                new_vo[d_vo.key] = vo[i];
                            }
                        }
                        vo = cfg[key] = new_vo;
                    }
                    else if (config_type == Config_Type.NoFilterButMapped) {
                        let new_vo = {};
                        for (let i = default_vo.length - 1; i >= 0; i--) {
                            new_vo[default_vo[i]] = vo[i];
                        }
                        vo = cfg[key] = new_vo;
                    }
                    else if (config_type == Config_Type.FilterButNoMapped) {
                        for (let key in default_vo) {
                            if (vo[key] == null) {
                                vo[key] = default_vo[key];
                            }
                        }
                    }
                }
                vo.has_set_default_value = true;
                this._cache_cfg_dic[config_name][key] = vo;
            }
            return vo;
        }
    }
    public static GetConfigKeyName(config_name: string, key: string | number) {
        let default_cfg = Config.PRELOAD_SERVER_CONFIG.config_table_default[config_name];
        let key_name = default_cfg[key];
        if (typeof key_name == "string") {
            return default_cfg;
        }
        else {
            return default_cfg.key;
        }
    }
    public static GetConfigIndex(config_name: string, key_name: string) {
        let vo = Config.ConfigHasDefaultValue[config_name];
        if (vo) {
            let config_type = vo.config_type;
            if (config_type == Config_Type.NoFilterButMapped) {
                let default_cfg: Array<string> = Config.PRELOAD_SERVER_CONFIG.config_table_default[config_name];
                return default_cfg.indexOf(key_name);
            }
            else {
                let default_cfg: Array<any> = Config.PRELOAD_SERVER_CONFIG.config_table_default[config_name];
                for (let i = 0; i < default_cfg.length; i++) {
                    if (key_name == default_cfg[i].key) {
                        return i;
                    }
                }
            }
        }
    }
    public static GetConfigDefaultVo(config_name: string, is_client_config = false) {
        let default_cfg;
        if (is_client_config) {
            default_cfg = Config.PRELOAD_CLIENT_CONFIG.ClientConfigDefaultVo[config_name];
        }
        else {
            default_cfg = Config.PRELOAD_SERVER_CONFIG.config_table_default[config_name];
        }
        return default_cfg;
    }
    private static _cache_cfg_dic;
    public static GetConfigFormOwnCache(cfg_name, key) {
        return this._cache_cfg_dic && this._cache_cfg_dic[cfg_name] && this._cache_cfg_dic[cfg_name][key];
    }
