import { BaseItem1 } from "../common/BaseItem1"
import { Vector2 } from "../util/Vector2"
import { Enum_UILayer } from "../common/LayerManager"
import { ResManager } from "../common/ResManager"

export class GuardActivateItem extends BaseItem1 {
	guard_model
	guard_type

	public constructor(parent?) {
		super(parent)
		this.base_file = "guard"
		this.layout_file = "GuardActivateItem"

		this.load_callback = () => {
		}
	}

	public InitView() {
		this.lb_desc.text = (this.guard_type == 1 && ("经验副本，挂机必备") || ("战力成吨提升!打架必备守护!"))
		let source = (this.guard_type == 1 && ("uimfz_027") || ("uimfz_025"))
		ResManager.GetInstance().SetImageSprite(this, this.img_attrName, "guard", source, true)
		source = (this.guard_type == 1 && ("uimfz_50") || ("uimfz_15"))
		ResManager.GetInstance().SetImageSprite(this, this.img_num, "guard", source, true)
		//this.ShowModel()
	}

	public ShowModel() {
		this.ClearModel()
		let cfg_kv = ResManager.GetInstance().GetGameConfigFromCache(this, "Magiccirclekeyvalue", false)
		if (cfg_kv) {
			let id = (this.guard_type == 1 && (cfg_kv.high_magic_circle_id.value) || (cfg_kv.low_magic_circle_id.value))
			let y = (this.guard_type == 1 && (-233) || (-130))
			let data = {
				res_id: id,
				clothe_res_id: id,
				type: 1,
				can_rotate: true,
				layer_value: Enum_UILayer.Activity,
				//scale = pos_cfg.scale,
				position: new Vector2(14, y),
				//rotate = pos_cfg.rotate,
				texture_size: new Vector2(160, 147),
				//action_name_list = action_list,
			}
			ResManager.GetInstance().SetRoleModel(this, this.gp_model, data)
			/*
			let curr_sorting_order = this.AddCurrLayerSortingOrder(this.layer_value)
			this.CoverMode(this._lb_dec, Enum_UILayer.Activity, curr_sorting_order)
			this.CoverMode(this._img_attr_name, Enum_UILayer.Activity, curr_sorting_order)
			*/
		}
	}

	public ClearModel() {
		if (this.guard_model) {
			this.guard_model.DeleteMe()
			this.guard_model = null
		}
	}

	public SetData(type?) {
		this.guard_type = type
		this.InitView()
	}

	public DeleteMe() {
		this.ClearModel()
	}

	lb_desc: Laya.Label
	img_attrName: Laya.Image
	img_num: Laya.Image
	gp_model: Laya.Box
	img_arr: Laya.Image
	public GetComponents() {
		[
			this.lb_desc,
			this.img_attrName,
			this.img_num,
			this.gp_model,
			this.img_arr,
		]
			= this.GetChildrenByNames([
				"lb_desc",
				"img_attrName",
				"img_num",
				"gp_model",
				"img_arr",
			])
	}
}
window["GuardActivateItem"] = GuardActivateItem