import { SceneRoleBeHitedFont, SceneNormalFont, SceneCritFont, SceneSpecialFont, ScenePartnerFont, SceneHpChangeFont, SuckBloodFont, RevertDamageFont, WorldArtFont } from "./WorldArtFont";
import { Config } from "../../common/Config";
export enum SceneFontType {
	DAMAGE_MAINROLE,
	DAMAGE_OTHER,

	BAOJI_MAINROLE,
	BAOJI_OTHER,

	HUI_XIN,
	EXC,

	SHAN_BI,
	SHAN_BI_MAINROLE,

	PARTNER_DAMAGE,

	HP_CHANGE,
	SUCK_BLOOD,

	REVERT_DAMAGE,
}
window["SceneFontType"] = SceneFontType

export class WorldArtFontManager {
	public SceneFontCfg: {
		[x: string]: {
			name: string;
			class: any;
			cache_count: number;
		};
	} = {

		// SCENE_ADD_MAINROLE,
		// SCENE_BAOJI_MAINROLE,
		// SCENE_BAOJI_OTHER,
		// SCENE_DAMAGE_MAINROLE,
		// DAMAGE_OTHER,
		// SCENE_TALISMAN
		// SCENE_PET,
		// SCENE_BABY,

		// SCENE_EXP,

			[SceneFontType.DAMAGE_MAINROLE]: { name: "scene_damage_mainrole", class:SceneNormalFont , cache_count: 5 },
			[SceneFontType.DAMAGE_OTHER]: { name: "scene_damage_other", class: SceneRoleBeHitedFont, cache_count: 15 },

			[SceneFontType.BAOJI_MAINROLE]: { name: "scene_baoji_mainrole", class: SceneCritFont, cache_count: 5 },
			[SceneFontType.BAOJI_OTHER]: { name: "scene_baoji_other", class: SceneCritFont, cache_count: 5 },

			[SceneFontType.SHAN_BI_MAINROLE]: { name: "scene_damage_mainrole", class: SceneNormalFont, cache_count: 5 },
			[SceneFontType.SHAN_BI]: { name: "scene_damage_other", class: SceneSpecialFont, cache_count: 5 },
			

			[SceneFontType.HUI_XIN]: { name: "scene_baby", class: SceneSpecialFont, cache_count: 5 },
			[SceneFontType.EXC]: { name: "scene_talisman", class: SceneSpecialFont, cache_count: 5 },

			[SceneFontType.REVERT_DAMAGE]: { name: "scene_damage_other", class: RevertDamageFont, cache_count: 5 },
			
			[SceneFontType.PARTNER_DAMAGE]: { name: "scene_pet", class: ScenePartnerFont, cache_count: 5 },
			
			[SceneFontType.SUCK_BLOOD]: { name: "scene_add", class: SuckBloodFont, cache_count: 5 },
			[SceneFontType.HP_CHANGE]: { name: "scene_add", class: SceneHpChangeFont, cache_count: 5 },
		};
	private static _instance: WorldArtFontManager;
	private _world_font_dic: {
		[key: string]: Array<WorldArtFont>;
	} = {};
	private now_show_font_dic = {};
	damage_info;
	crit_info;
	baoji_info;
	constructor() {
		this.damage_info = Config.PRELOAD_CLIENT_CONFIG.ConfigOtherFightInfo.damage_info;
		this.crit_info = Config.PRELOAD_CLIENT_CONFIG.ConfigOtherFightInfo.crit_info;
		this.baoji_info = Config.PRELOAD_CLIENT_CONFIG.ConfigOtherFightInfo.baoji_info;
		this.InitCacheDic();
		this.InitCacheNowShowDic();
	}
	public static GetInstance() {
		if (!WorldArtFontManager._instance) {
			WorldArtFontManager._instance = new WorldArtFontManager();
		}
		return WorldArtFontManager._instance;
	}
	private InitCacheDic = () => {
		for (let key in this.SceneFontCfg) {
			this._world_font_dic[this.SceneFontCfg[key].name] = [];
		}
	};
	private InitCacheNowShowDic = () => {
		for (let key in this.SceneFontCfg) {
			this.now_show_font_dic[this.SceneFontCfg[key].name] = {};
		}
	};
	public ClearNowShowFontDic = () => {
		for (let key in this.now_show_font_dic) {
			for (let hash_code in this.now_show_font_dic[key]) {
				this.now_show_font_dic[key][hash_code].DeleteMe();
			}
			this.now_show_font_dic[key] = {};
		}
	};
	//清理多余的文字缓存
	public ClearFontCache = () => {
		for (let key in this.SceneFontCfg) {
			let cache_count = this.SceneFontCfg[key].cache_count;
			let list = this._world_font_dic[this.SceneFontCfg[key].name];
			if (list && list.length > cache_count) {
				let count = list.length - cache_count;
				while (count > 0) {
					let font = list.pop();
					if (font) {
						font.DeleteMe();
					}
					count--;
				}
			}
		}
	};
	public ShowFont = (type: SceneFontType, str: string, x, y, dir?) => {
		if (this.SceneFontCfg[type] == undefined) {
			return;
		}
		let font_name = this.SceneFontCfg[type].name;
		let list = this._world_font_dic[font_name];
		let font = list.shift();
		if (!font || font.TextObjIsNull()) {
			let sub_class = this.SceneFontCfg[type].class;
			font = new sub_class(type);
		}
		else {
			font.SetVisible(true);
		}
		font.ShowText(str, x, y, dir);
		this.now_show_font_dic[font_name][font.hashCode] = font;
	};
	public PushFont = (font: WorldArtFont) => {
		let font_name = font.GetFontName();
		let list = this._world_font_dic[font_name];
		if (!font.TextObjIsNull()) {
			font.Reset();
			list.push(font);
		}
		delete this.now_show_font_dic[font_name][font.hashCode];
	};
}
window["WorldArtFontManager"] = WorldArtFontManager