import { Config } from "../common/Config"
import { EventName } from "../common/EventName"
import { ResManager } from "../common/ResManager"
import { table } from "../common/table"
import { RoleManager } from "../role/RoleManager"
import { GlobalEventSystem } from "../util/DeclareGlobalVar"
import { ErlangParser } from "../util/ErlangParser"
import { EventDispatcher } from "../util/EventDispatcher"
import { Util, LoadLuaConfigAB } from "../util/Util"
import { GoodsModel } from "./GoodsModel"
import { MainFunc } from "./MainUIModel"

export class FashionModel extends EventDispatcher {
	CreateACtiveCallBack
	GetColorCfg
	GetColorRed
	GetDefultOrder
	GetFashionInfo
	GetGoodNumFormBag
	GetOneGoodNum
	IsActive
	IsFullLevel
	IsPosShowRed
	LoadFashionConfig
	RefColorRed
	ResetFunc
	UpdateActiveList
	UpdateCurrentUserModelList
	UpdateRedList
	color_red_dic
	fashion_activate_list
	fashion_att_config_list
	fashion_config_list
	fashion_current_user_model_dic
	fashion_grade_num_dic
	fashion_info_list
	fashion_model_list
	fashion_order_num_dic
	fashion_pos_config_list
	fashion_red_list
	fashion_wear_list
	isRed
	isShowRed
	is_request
	type_to_tab_index_
	config_fashion
	config_fashion_model
	config_fashion_pos
	config_fashion_color
	public static SCMD_REQUEST = "SCMD_REQUEST";
	public static GETACTIVATEFASHION = "GETACTIVATEFASHION";
	public static UPDATEVIEW = "UPDATEVIEW";
	public static UPDATELEVEL = "UPDATELEVEL";
	public static SUCCESSOPERATE = "SUCCESSOPERATE";
	public static SELECTADD = "SELECTADD";
	public static SELECTCOLOR = "SELECTCOLOR"
	public static ClothesType = 1;
	public static WeaponType = 2;
	public static HeadType = 3;
	static Instance
	public constructor() {
		super()

		if (FashionModel.Instance) {
			return
		}
		this.is_request = [];
		this.fashion_model_list = [];
		this.fashion_config_list = [];
		this.fashion_att_config_list = [];
		this.fashion_pos_config_list = [];
		this.fashion_current_user_model_dic = {};
		this.fashion_grade_num_dic = {};
		this.fashion_order_num_dic = {};
		this.fashion_info_list = [];
		this.fashion_activate_list = [];
		this.fashion_wear_list = [];
		this.fashion_red_list = [];
		let local_Erlang = ErlangParser.GetInstance()
		let local_GlobalEventSystem = GlobalEventSystem
		let local_EventName = EventName
		let local_FashionModel = FashionModel
		let goods_model = GoodsModel.GetInstance()
		let config_preload_server = Config
		let fashion_grade_dic_ = {}
		let fashion_order_dic_ = {}
		this.type_to_tab_index_ = {1:0,3:1}
		let fashion_type_list_ = [1, 2, 3]
		ResManager.GetInstance().LoadGameConfig(this, "config_fashion", false, null, (cfg) => {
			this.config_fashion = cfg
			this.LoadFashionConfig()
			ResManager.GetInstance().DestoryGameConfig(this, "config_fashion")
		})
		ResManager.GetInstance().LoadGameConfig(this, "config_fashion_model", false, null, (cfg) => {
			this.config_fashion_model = cfg
			ResManager.GetInstance().DestoryGameConfig(this, "config_fashion_model")
		})
		ResManager.GetInstance().LoadGameConfig(this, "config_fashion_pos", false, null, (cfg) => {
			this.config_fashion_pos = cfg
			this.LoadFashionConfig()
			ResManager.GetInstance().DestoryGameConfig(this, "config_fashion_pos")
		})
		ResManager.GetInstance().LoadGameConfig(this, "config_fashion_color", false, null, (cfg) => {
			this.config_fashion_color = cfg
			ResManager.GetInstance().DestoryGameConfig(this, "config_fashion_color")
		})

		this.ResetFunc = () => {
			fashion_grade_dic_ = []
			fashion_order_dic_ = []
			this.is_request = [];
			this.fashion_model_list = [];
			this.fashion_config_list = [];
			this.fashion_att_config_list = [];
			this.fashion_pos_config_list = [];
			this.fashion_current_user_model_dic = [];
			this.fashion_grade_num_dic = {};
			this.fashion_order_num_dic = {};
			this.fashion_info_list = [];
			this.fashion_activate_list = {};
			this.fashion_wear_list = [];
			this.fashion_red_list = [];
		}

		this.CreateACtiveCallBack = (_list?) => {
			if (_list) {
				this.fashion_info_list[_list.pos_id] = _list

				if (this.fashion_info_list[_list.pos_id]["fashion_list"]) {
					if (!this.fashion_activate_list[_list.pos_id]) {
						this.fashion_activate_list[_list.pos_id] = {}
					}

					for (let _tmpi in this.fashion_info_list[_list.pos_id]["fashion_list"]) {
						var vo = this.fashion_info_list[_list.pos_id]["fashion_list"][_tmpi]

						this.fashion_activate_list[_list.pos_id][vo["fashion_id"]] = vo
					}
				}
				this.UpdateActiveList(_list.pos_id)
			}
		}

		this.UpdateActiveList = (pos_id?) => {
			ResManager.GetInstance().LoadGameConfig(this,"config_fashion",false,null,(cfg)=>{
				let active_list = this.fashion_activate_list[pos_id]
				if (!this.fashion_order_num_dic[pos_id]) {
					this.fashion_order_num_dic[pos_id] = {}
				}
				if (!this.fashion_grade_num_dic[pos_id]) {
					this.fashion_grade_num_dic[pos_id] = {}
				}
				if (!fashion_grade_dic_[pos_id]) {
					fashion_grade_dic_[pos_id] = {}
				}
				if (!Util.IsTableEmpty(active_list)) {
					for (let _index in active_list) {
	
						let _act = active_list[_index]
						let _order = this.GetDefultOrder(_act)
						let index = pos_id + "@" + _index + "@" + (_order + 1)
						if (cfg[index]) {
	
						} else {
							fashion_grade_dic_[pos_id][_index] = 0
							let v = this.fashion_order_num_dic[pos_id][_index]
							if (v && v > 0 && pos_id != 3) {	// 发饰部分暂无升级
								this.fashion_grade_num_dic[pos_id][_index] = v
								fashion_order_dic_[pos_id][_index] = null
								this.fashion_order_num_dic[pos_id][_index] = null
							} else {
								if (fashion_order_dic_[pos_id]) {
									fashion_order_dic_[pos_id][_index] = null
								}
								if (this.fashion_order_num_dic[pos_id]) {
									this.fashion_order_num_dic[pos_id][_index] = null
								}
							}
						}
					}
					this.RefColorRed(pos_id)
					this.UpdateRedList(pos_id)
				}
			})
			
		}

		this.IsFullLevel = (pos?) => {
			if (Util.IsTableEmpty(this.fashion_grade_num_dic[pos])) {
				return
			}
			if (this.fashion_info_list[pos] && !this.fashion_pos_config_list[pos + "@" + (this.fashion_info_list[pos]["pos_lv"] + 1)]) {
				this.fashion_grade_num_dic[pos] = []
			}
		}

		this.UpdateRedList = (pos_id?) => {
			this.fashion_red_list[pos_id] = []
			let order_num_dic = this.fashion_order_num_dic[pos_id]
			if (order_num_dic) {
				for (let _index in order_num_dic) {

					let _order = null
					let index = null
					let _cost = null
					if (this.fashion_activate_list[pos_id] && this.fashion_activate_list[pos_id][_index]) {
						_order = this.GetDefultOrder(this.fashion_activate_list[pos_id][_index])
						index = pos_id + "@" + _index + "@" + (_order + 1)
						if (this.fashion_config_list[index] && this.fashion_config_list[index].star_cost) {
							_cost = JSON.parse(this.fashion_config_list[index].star_cost)
						}
					} else {
						_order = 0
						index = pos_id + "@" + _index + "@" + (_order + 1)
						if (this.fashion_config_list[index] && this.fashion_config_list[index].active_cost) {
							_cost = JSON.parse(this.fashion_config_list[index].active_cost)
						}
					}

					if ((_cost && _cost[0]) && Number(_cost[0][2]) <= order_num_dic[_index]) {
						this.fashion_red_list[pos_id][_index] = 1
					}
				}
				if (this.IsPosShowRed(pos_id)) {
					local_GlobalEventSystem.Fire(local_EventName.UPDATE_BASE_WINDOWS_COMPONENT_RED_STATE, "FashionBaseView", this.type_to_tab_index_[pos_id], true)
				} else {
					local_GlobalEventSystem.Fire(local_EventName.UPDATE_BASE_WINDOWS_COMPONENT_RED_STATE, "FashionBaseView", this.type_to_tab_index_[pos_id], false)
				}
				this.Fire(local_FashionModel.UPDATEVIEW, pos_id)
				local_GlobalEventSystem.Fire(local_EventName.REFRESH_FUNCTION_ICON_RED_DOT, MainFunc.Role)
			}
			this.Fire(local_FashionModel.UPDATELEVEL, pos_id)
		}

		this.isShowRed = () => {
			for (let _tmpi in fashion_type_list_) {
				var vo = fashion_type_list_[_tmpi]
				if (this.IsPosShowRed(vo)) {
					return true
				}
			}
			return false
		}

		this.IsPosShowRed = (pos_id?) => {
			this.IsFullLevel(pos_id)
			if (Util.IsTableEmpty(this.fashion_red_list[pos_id]) && Util.IsTableEmpty(this.fashion_grade_num_dic[pos_id]) && !this.GetColorRed(pos_id)) {
				return false
			} else {
				return true
			}
		}

		this.GetOneGoodNum = (goods_list?) => {
			if (!goods_list) {
				return
			}
			for (let _tmpi in fashion_type_list_) {
				var pos_id = fashion_type_list_[_tmpi]
				for (let _tmpi in goods_list) {
					var info = goods_list[_tmpi]
					if (fashion_order_dic_[pos_id] && fashion_order_dic_[pos_id][info.type_id] != null) {
						if (this.fashion_order_num_dic[pos_id]) {
							let _num = goods_model.GetTypeGoodsNum(info.type_id)
							if (_num > 0) {
								this.fashion_order_num_dic[pos_id][info.type_id] = _num
							} else {
								delete this.fashion_order_num_dic[pos_id][info.type_id]
							}
						}
					} else if (pos_id != 3 && fashion_grade_dic_[pos_id] && fashion_grade_dic_[pos_id][info.type_id] != null) { // 发饰部位暂无升级
						if (this.fashion_grade_num_dic[pos_id]) {
							let _num = goods_model.GetTypeGoodsNum(info.type_id)
							if (_num > 0) {
								this.fashion_grade_num_dic[pos_id][info.type_id] = _num
							} else {
								delete this.fashion_grade_num_dic[pos_id][info.type_id]
							}
						}
					}
				}
				this.RefColorRed(pos_id)
				this.UpdateRedList(pos_id)
			}
		}

		this.GetGoodNumFormBag = (pos_id?) => {
			let fashion_order_dic = fashion_order_dic_[pos_id]
			if (fashion_order_dic) {
				for (let _id in fashion_order_dic) {

					let _num = goods_model.GetTypeGoodsNum(_id)
					if (_num > 0) {
						this.fashion_order_num_dic[pos_id][_id] = _num
					}
				}
			}
			let fashion_grade_dic = fashion_grade_dic_[pos_id]
			if (fashion_grade_dic && pos_id != 3) { // 发饰部位暂无升级
				for (let _id in fashion_grade_dic) {

					let _num = goods_model.GetTypeGoodsNum(_id)
					if (_num > 0) {
						if (!this.fashion_grade_num_dic[pos_id]) {
							this.fashion_grade_num_dic[pos_id] = {}
						}
						this.fashion_grade_num_dic[pos_id][_id] = _num
					}
				}
			}
			this.UpdateRedList(pos_id)
		}

		this.UpdateCurrentUserModelList = (_career?, _sex?) => {
			this.fashion_current_user_model_dic = {}
			fashion_order_dic_ = []
			this.fashion_wear_list = []
			ResManager.GetInstance().LoadGameConfig(this, "config_fashion_model", false, null,(fashion_model_list?) => {
				for (let fashion in fashion_model_list) {

					let _fashion = fashion_model_list[fashion]
					if (_fashion["career"] == _career && _fashion["sex"] == _sex && _fashion.color_id == 0) {
						this.fashion_current_user_model_dic[fashion] = _fashion
						if (!fashion_order_dic_[_fashion.pos_id]) {
							fashion_order_dic_[_fashion.pos_id] = {}
						}
						fashion_order_dic_[_fashion.pos_id][_fashion["fashion_id"]] = 0
						let waer = [_fashion["fashion_id"], 0, _fashion["pos_id"]]
						if (!this.fashion_wear_list[_fashion.pos_id]) {
							this.fashion_wear_list[_fashion.pos_id] = []
						}
						table.insert(this.fashion_wear_list[_fashion.pos_id], waer)
					}
				}
				let sort_func = (a?, b?) => {
					return Number(a[0]) < Number(b[0])
				}
			
				for (let k in this.fashion_wear_list) {
					var v = this.fashion_wear_list[k]
					table.sort(v, sort_func)
				}
				ResManager.GetInstance().DestoryGameConfig(this, "config_fashion_model", false);
			})
		}
	
		this.LoadFashionConfig = () => {
			this.fashion_config_list = this.config_fashion// config_preload_server.Fashion
			this.fashion_pos_config_list = this.config_fashion_pos//config_preload_server.Fashionpos
		}

		this.IsActive = (pos_id?, fashion_id?) => {
			let list = this.fashion_activate_list && this.fashion_activate_list[pos_id]
			if (list && Util.TableSize(list) > 0) {
				for (let k in list) {
					var v = list[k]
					if (v.fashion_id == fashion_id) {
						return true
					}
				}
			}
			return false
		}

		//not_color:不判断染色的红点
		this.isRed = (pos_id?, fashion_id?, not_color?) => {
			if (!not_color) {
				let bool = this.GetColorRed(pos_id, fashion_id)
				if (bool) { return bool }
			}
			let list = this.fashion_red_list && this.fashion_red_list[pos_id]
			if (list && Util.TableSize(list) > 0) {
				for (let k in list) {
					var v = list[k]
					if (k == fashion_id) {
						if (v > 0) {
							return true
						} else {
							return false
						}
					}
				}
			}
			return false
		}

		//时装颜色相关配置
		this.GetColorCfg = (pos_id?, fashion_id?, color_id?, star_lv?) => {
			if (!this.config_fashion_model){
				return
			}
			// let sort_fun=(a?,b?)=>{
			// 	return Number(a["fashion_id"]) <  Number(b["fashion_id"])
			// }
			// table.sort(this.config_fashion_model,sort_fun)
			if (!pos_id || !fashion_id || fashion_id == 0) { return }
			let cfgs = []
			if (star_lv) { // 指定配置
				return this.config_fashion_color[pos_id + "@" + fashion_id + "@" + color_id + "@" + star_lv]// Config.Fashioncolor[pos_id + "@" + fashion_id + "@" + color_id + "@" + star_lv]
			} else if (color_id) { // 指定颜色下的所有配置
				for (let lv = 1; lv <= 1; lv++) {
					let key = pos_id + "@" + fashion_id + "@" + color_id + "@" + lv
					let cfg = this.config_fashion_color[key]//Config.Fashioncolor[key]
					if (!cfg) {
						break
					}
					cfgs[key] = cfg
				}
				return cfgs
			} else { // 指定时装颜色的种类p
				let career = RoleManager.GetInstance().GetMainRoleCareer()
				let sex = RoleManager.GetInstance().GetMainRoleSex()

				for (let color_id = 1; color_id <= 10; color_id += 1) {
					let lv = 1
					let key = pos_id + "@" + fashion_id + "@" + career + "@" + sex + "@" + color_id
					let cfg = this.config_fashion_model[key]//Config.Fashioncolor[key]
					if (!cfg) {
						return color_id - 1
					}
				}
			}
		}
		
		//单一时装界面信息(已激活)
		this.GetFashionInfo = (pos_id?, fashion_id?) => {
			if (pos_id && fashion_id) {
				return this.fashion_activate_list[pos_id] && this.fashion_activate_list[pos_id][fashion_id]
			}
		}

		//时装颜色红点(只有已激活的时装需要考虑红点)
		this.color_red_dic = {}
		this.RefColorRed = (pos_id?) => {
			// LoadLuaConfigAB("Fashioncolor", () => {
				ResManager.GetInstance().LoadGameConfig(this, "config_fashion_color", false, null, (cfg) => {
					this.config_fashion_color = cfg
					this.color_red_dic[pos_id] = {}
					ResManager.GetInstance().DestoryGameConfig(this, "config_fashion_color")

					let list = this.fashion_activate_list[pos_id]
					if (list) {
						for (let k in list) {
							var v = list[k]
							let id = v.fashion_id
							this.color_red_dic[pos_id][id] = {}
							let color_type = this.GetColorCfg(pos_id, id)

							for (let i = 1; i <= color_type; i += 1) {
								let lv = 0
								for (let k1 in v.color_list) {
									var v1 = v.color_list[k1]
									if (v1.color_id == i) {
										lv = v1.fashion_star_lv
									}
								}
								let key = pos_id + "@" + id + "@" + i+"@" + (lv + 1)
								let cfg = this.config_fashion_color[key]//Config.Fashioncolor[key]
								if (cfg) {
									let cost
									if (lv == 0) {
										cost =local_Erlang.Parse(cfg.active_cost)
									} else {
										cost = local_Erlang.Parse(cfg.star_cost)
									}
									let have_num = GoodsModel.GetInstance().GetTypeGoodsNum(cost[0][1])
									let need_num = Number(cost[0][2])
									this.color_red_dic[pos_id][id][i] = (have_num >= need_num && (true) || (null))
								} else {
									this.color_red_dic[pos_id][id][i] = null
								}
							}
						}
					}
				})


				
			// })
		}
		this.GetColorRed = (pos_id?, fashion_id?, color?) => {
			if (fashion_id == null) {
				if (this.color_red_dic[pos_id]) {
					for (let k in this.color_red_dic[pos_id]) {
						var v = this.color_red_dic[pos_id][k]
						for (let k1 in v) {
							var v1 = v[k1]
							if(v1){
								return true
							}
						}
					}
				}
				return false
			}
			if (this.color_red_dic && this.color_red_dic[pos_id] && this.color_red_dic[pos_id][fashion_id]) {
				for (let k in this.color_red_dic[pos_id][fashion_id]) {
					var v = this.color_red_dic[pos_id][fashion_id][k]
					if (color && k == color) {
						return v
					} else if (color == null && v) {
						return v
					}
				}
			}
			return false
		}

		//获取默认颜色的阶数
		this.GetDefultOrder = (info?) => {
			if (info && info.color_list) {
				for (let k in info.color_list) {
					var v = info.color_list[k]
					if (v.color_id == 0) {
						return v.fashion_star_lv
					}
				}
			}
		}

	}

	public static GetInstance() {

		if (!FashionModel.Instance) {
			FashionModel.Instance = new FashionModel()
		}
		return FashionModel.Instance
	}
}

window["FashionModel"] = FashionModel