import { GlobalEventSystem } from "../util/DeclareGlobalVar";
import { Util, Split } from "../util/Util"
import { BaseItem1 } from "./BaseItem1";
import { EventName } from "./EventName";
import { OpenFun } from "./OpenFun"

export class MaterialsItem extends BaseItem1 {
	public _Image11: Laya.Image;
	public targetName: Laya.Label;
	public btn: Laya.Box;
	public _Image1: Laya.Image;
	public labelDisplay: Laya.Label; 
	public _Image2: Laya.Image;

	private data;


	// public static width = 500
	// public static height = 86

	public constructor(parent) {
		
		super(parent)
		this.base_file = "common"
		this.layout_file = "MaterialsItem"
		this.is_delay_callback = false
		this.load_callback=()=>{
			this.InitEvent()
			this.dataChanged()
		}
	}


	public InitEvent() {
		Util.AddClickEvent(this.btn, () => {
			if (this.data[2] == "38070001") {
			} else {
				OpenFun.OpenFun(this.data[0], this.data[1], this.data[2])
			}
			GlobalEventSystem.Fire(EventName.MATERIAL_VIEW_CLOSE)
		}, this, true)
	}

	public dataChanged() {
		if(this.data){
			let title = OpenFun.OpenName(this.data[0])
			this.targetName.text = title
			//if (this.data[1] == 26 && FunctionOpenModel.GetInstance().IsInShowingStory(FuncOpenId.MonBook) ) {
			//FunctionOpenModel:GetInstance():ShowFuncOpenArrow(FuncOpenId.MonBook, this.btn)
			//}
			let list = Split(String(this.data[0]), "_")
			let bool = false
			if (list.length >= 2 && list[0] == 331) {
				bool = true
			}
			this.btn.visible = Number(this.data[0]) < 10000 || bool
		}
	}

	public SetData(data?){
		this.data=data;
	}

	public GetComponents() {
		[this._Image11,
			this.targetName,
			this.btn,
			this._Image1,
			this.labelDisplay,
			this._Image2] =
			this.GetChildrenByNames(["_Image11",
				"targetName",
				"btn",
				"_Image1",
				"labelDisplay",
				"_Image2"])
    }


}

window["MaterialsItem"] = MaterialsItem