import { BaseItem1 } from "../common/BaseItem1"
import { BaseItemRenderer } from "../common/BaseItemRenderer"
import { ResManager } from "../common/ResManager"
import { GuildActivityModel } from "../commonModel/GuildActivityModel"
import { ColorUtil } from "../util/ColorUtil"

export class EveningIntroItem extends BaseItemRenderer {
	model
	name_outline

	public WIDTH = 170
	public HEIGT = 120

	is_set
	public constructor(parent) {
		super()
		this.is_set = false
		this.base_file = "evening"
		this.layout_file = "EveningIntroItem"
		this.model = GuildActivityModel.GetInstance()
		this.load_callback = () => {
			//this.name_outline = this.GetChild("_lb_name").GetComponent("Outline")

			if (!this.is_set) {
				this.is_set = true
			}
		}

		this.Load()
	}


	public dataChanged() {

		if (! super.dataChanged()) {
			return
		}
		if (this.is_loaded) {
			this.SetDate()
			this.is_set = true
		} else {
			this.is_set = false
		}

	}

	SetDate() {
		if (!this.data) return
		this._lb_name.text = this.data.name

		if (this.selected) {
			ResManager.GetInstance().SetImageSprite(this, this._img_select, "evening_asset", "uighgha_011", true)
			ResManager.GetInstance().SetImageSprite(this, this._img_icon, "evening_asset", this.data.icon, true)
			this._lb_name.color = ColorUtil.TryParseHtmlString("#ffffff")
			//this.name_outline.effectColor = ColorUtil.TryParseHtmlString("#e4792a")
		} else {
			ResManager.GetInstance().SetImageSprite(this, this._img_select, "evening_asset", "uighgha_012", true)
			ResManager.GetInstance().SetImageSprite(this, this._img_icon, "evening_asset", this.data.icon, true)
			this._lb_name.color = ColorUtil.TryParseHtmlString("#89592B")
			//this.name_outline.effectColor = ColorUtil.TryParseHtmlString("#ffffff")
		}
	}

	_img_select: Laya.Image
	_img_icon: Laya.Image
	_lb_name: Laya.Label
	public GetComponents() {
		[
			this._img_select,
			this._img_icon,
			this._lb_name,
		]
			= this.GetChildrenByNames([

				"_img_select",
				"_img_icon",
				"_lb_name",
			])
	}
}

window["EveningIntroItem"] = EveningIntroItem