	public LoadSuccess() {
		this._lb_name.text = ""

		this.hp_bar = new ProgressBar2(this._gp_hp_bar, 100, 100, false, false, "uiComponent", "ui_4", "ui_5")
		this.hp_bar.Load()
		this.hp_bar.SetPosition(0, 0)

		this.InitParentVisible()
		this.InitConVisible()
		this.UpdateParentLayout()
		this.UpdateConLayout()
		this.InitEvent()
	}


