	public DeleteMe() {

		if (this.hp_bar) {
			this.hp_bar.DeleteMe()
			this.hp_bar = null
		}
		if (this.shield_bar) {
			this.shield_bar.DeleteMe()
			this.shield_bar = null
		}

		this.name_board_mgr.RemoveNameBoard(this.hashCode)

		this.attach_target = false
		super.DeleteMe()
	}

