	public ShowMedal(medal_id?) {
		if (medal_id > 0) {
			ResManager.GetInstance().LoadGameConfig(this, "config_medal", false, undefined, (cfgs) => {
				let medal_Cfg = MedalModel.GetInstance().medalConfig(cfgs)
				if (medal_Cfg && medal_Cfg.title > 0) {
					ResManager.GetInstance().SetTexture(this, this._img_medal, GameResPath.GetIcon("mainUI", "tx_" + medal_Cfg.title),()=>{
						this.TryUpdateConLayout()
					},this, true)
					SetLocalScale(this._img_medal, 0.8, 0.8, 0.8)
					this._img_medal.visible = true
				} else {
					this._img_medal.visible = false
				}
			})
		} else {
			this._img_medal.visible = false
		}
		this.TryUpdateConLayout()
	}

