import { BaseView1 } from "../common/BaseView1"
import { Enum_UILayer } from "../common/LayerManager"
import { LoopScrowViewMgr } from "../common/LoopScrowViewMgr"
import { ResManager } from "../common/ResManager"
import { LuaSoundManager } from "../common/SoundManager"
import { GuildActivityModel } from "../commonModel/GuildActivityModel"
import { Util } from "../util/Util"
import { EveningRewardItem } from "./EveningRewardItem"

export class EveningRewardView extends BaseView1 {
	_ac_item
	_ac_rank
	back_login_toClose
	click_bg_toClose
	destroy_callback
	is_center
	model
	preload_server_config
	show_open_movie
	use_background


	public constructor() {
		super()

		this.model = GuildActivityModel.GetInstance();
		this.base_file = "evening"
		this.layout_file = "EveningRewardView"
		this.layer_value = Enum_UILayer.Activity
		this.is_center = true
		this.use_background = true
		this.click_bg_toClose = true
		this.show_open_movie = true
		this.back_login_toClose = true
		this.preload_server_config = { "Guildfeastdragon": false }
		this.load_callback = () => {

			this.LoadSuccess()
			this.InitEvent()
		}

		this.destroy_callback = () => {
			this.Clear()
		}
	}

	// function EveningRewardView.Close()
	// 	super.Close()
	// }

	public Clear() {

		if (this._ac_rank) {
			this._ac_rank.DeleteMe()
			this._ac_rank = null
		}
	}

	public LoadSuccess() {

		this.InitView()
	}

	public InitView() {

		let _guild_feast_dragon_cfg = ResManager.GetInstance().GetGameConfigFromCache(this, "Guildfeastdragon", false)
		let list = null
		// this._ac_item = eui. new ArrayCollection(list)
		// this._list_item.dataProvider = this._ac_item
		// this._list_item.itemRenderer = EveningRewardItem

		this._ac_rank = new LoopScrowViewMgr()
		this._ac_rank.SetData(this.Content, EveningRewardItem, list, this._Scroller1)
	}

	public InitEvent() {

		Util.AddClickEvent(this._btn_close, () => {
			this.Close()
		}
			, this, true, null, null, null, null, LuaSoundManager.SOUND_UI.CLOSE)
	}


	public DeleteMe() {
		super.DeleteMe()
	}

	_Image1: Laya.Image
	_Image2: Laya.Image
	_Image3: Laya.Image
	_Image4: Laya.Image
	_Group1: Laya.HBox
	_Image5: Laya.Image
	_Label1: Laya.Label
	_Image6: Laya.Image
	_Scroller1: Laya.Panel
	Content: Laya.Box
	_btn_close: Laya.Box
	_Image11: Laya.Image
	labelDisplay: Laya.Label
	_Image7: Laya.Image
	_Label2: Laya.Label
	_Label3: Laya.Label
	_Label4: Laya.Label
	public GetComponents() {
		[
			this._Image1,
			this._Image2,
			this._Image3,
			this._Image4,
			this._Group1,
			this._Image5,
			this._Label1,
			this._Image6,
			this._Scroller1,
			this.Content,
			this._btn_close,
			this._Image11,
			this.labelDisplay,
			this._Image7,
			this._Label2,
			this._Label3,
			this._Label4,
		]
			= this.GetChildrenByNames([

				"_Image1",
				"_Image2",
				"_Image3",
				"_Image4",
				"_Group1",
				"_Image5",
				"_Label1",
				"_Image6",
				"_Scroller1",
				"Content",
				"_btn_close",
				"_Image11",
				"labelDisplay",
				"_Image7",
				"_Label2",
				"_Label3",
				"_Label4",
			])
	}
}
window["EveningRewardView"]=EveningRewardView