import { EventDispatcher } from "../util/EventDispatcher";
import { SceneBaseType } from "../scene/SceneConfig";
import { PoseState } from "../util/StateMachineManager";
import { RoleManager } from "../role/RoleManager";


// TypeScript file
export class DemonVo extends EventDispatcher {
    vo_type = SceneBaseType.Demon;
    pos_x = 0; //X像素坐标(int16)
    pos_y = 0; //Y像素坐标(int16)
    hp = 100; //当前hp(int32)
    maxHp = 100; //最大hp(int32)
    name = "使魔"; //名字(string)
    move_speed = 160; //速度(int16)
    ghost_mode = 0;
    hide_flag = 0; //是否不可见(int8)
    warGroup = 0; //战斗分组(int8)
    demon_id = 0; //使魔id
    model_id = 0; //模型id
    texture_res = 0; //贴图
    poseState = PoseState.STAND;
    birth_angle = 270; //出生角度  水平向右为0 逆时针一圈为360度
    owner_id = 0; //所属玩家id
    owner_vo;
    team_id;
    public constructor() {
        super();
    }
    public ReadFromProtocal() {
    }
    public SetVo(owner_vo) {
        this.owner_vo = owner_vo
        if(this.owner_vo){
            this.warGroup = this.owner_vo.warGroup
            this.team_id = this.owner_vo.team_id
            this.name = owner_vo.name + "的使魔"
            this.demon_id = owner_vo.demon_id
        }
    }
    public GetTextureId() {
        return this.demon_id
    }
}

window["DemonVo"] = DemonVo