		this.FindElement = (findVo?, isAgain?) => {
			if (!this.main_role || !this.scene_data_loaded) {
				return
			}
			// if (this.main_role.IsFishingState() ) {
			// 	Message.show("钓鱼中~，请先退出钓鱼状态")
			// 	return
			// }

			isAgain = isAgain || false
			if (findVo == null || findVo.type == null || findVo.sceneId == null || findVo.id == null) {
				return
			}
			// // 判断目标场景是否开启
			// if (findVo.sceneId != scene_mgr.GetSceneId() ) {
			// 	let vo
			// 	vo = {}
			// 	vo.scene_id = findVo.sceneId
			// 	let hasOpen = MapModel.GetInstance().CanEnterScene(vo)
			// 	if (hasOpen != true ) {
			// 		Message.show("无法进入目标场景")
			// 		return
			// 	}
			// }
			this.clearGoToData()
			GlobalEventSystem.Fire(EventName.FINDWAY_STARTED)

			// 寻路NPC要重新计算距离
			if (findVo.type == FindVo.NPC) {
				let npc = scene_mgr.GetNpcVo(findVo.id)
				if (npc) {
					findVo.x = npc.logic_x
					findVo.y = npc.logic_y
				}
			}

			//跳完后 继续寻路
			// OperateManager.Instance.jump_end_not_continue = false

			////////////////-设置飞鞋坐标////////////////-
			var callback = () => {
				GlobalEventSystem.Fire(EventName.FIND, findVo)
			}
			AutoFightManager.GetInstance().SetFlyData(findVo.sceneId, findVo.x * SceneObj.GetLogicRealRatio().x, findVo.y * SceneObj.GetLogicRealRatio().y, callback)

			////////////////-是否处于处于CanMove状态//////////////////
			this.CancelWaitQuest()
			if (this.main_role && !this.main_role.CanMove()) {
				let timer_func = () => {
					if (this.main_role && this.main_role.CanMove()) {
						this.FindElement(findVo)
						return
					}
				}
				this.timer = GlobalTimerQuest.AddPeriodQuest(timer_func, 0.1)
				return
			}

			this.find_vo_cache = findVo
			let myx = mainrole_vo.pos_x / SceneObj.GetLogicRealRatio().x
			let myy = mainrole_vo.pos_y / SceneObj.GetLogicRealRatio().y
			if (SceneManager.Instance.showHorseScene()) {
				if (findVo.sceneId == scene_mgr.GetSceneId()) {
					if (((myx - findVo.x) * (myx - findVo.x) + (myy - findVo.y) * (myy - findVo.y)) > 400) {
						GlobalEventSystem.Fire(EventName.CHANGE_FIGHTING_STATE, false)		////寻路自动上坐骑
					}
				} else {
					if (!findVo.force_change_scene) {
						GlobalEventSystem.Fire(EventName.CHANGE_FIGHTING_STATE, false)		////寻路自动上坐骑
					}
				}
			}
			if (findVo.sceneId != scene_mgr.GetSceneId()) {  //跨场景
				// let scene_path = SceneConnectMap.Instance.FindPath(this.scene_mgr.GetSceneId(), findVo.sceneId)
				// if (findVo.force_change_scene || List.Empty(scene_path) ) {
				// 	findVo.force_change_scene = false
				// 	this.scene_mgr.find_nextvo = findVo
				// 	this.find_isAgain = isAgain
				// 	GlobalEventSystem.Fire(SceneEventType.REQUEST_CHANGE_SCENE, findVo.sceneId, findVo.call_type)
				// }else{
				var change_scene_callback = () => {
					this.clearGoToData()
					if (scene_mgr.GetSceneId() == findVo.sceneId) {
						OperateManager.Instance.ClearSrcOper()  //停止继续寻路
						this.FindElement(findVo)
						return true
					}
				}
				OperateManager.Instance.StartCrossSceneAction(findVo.sceneId, { "x": findVo.x, "y": findVo.y }, change_scene_callback, undefined)
				// }
				return
			}
			if (findVo.type == FindVo.SCENE) {
				this.ClearFindNextScene()
				GlobalEventSystem.Fire(EventName.FINDWAY_ENDED)
				return
			} else if (findVo.type == FindVo.NPC) {
				if (!SceneManager.Instance.IsHomeBuildScene()) {
					this.MainRoleToNpc(findVo.id)
				} else {
					let lx, ly = this.main_role.GetLogicPos()
					if (GameMath.GetDistance(lx, ly, findVo.x, findVo.y) <= 1) {
						this.main_role.DoStand()
						let onDelay = () => {
							if (this.delay_timer_id) {
								GlobalTimerQuest.CancelQuest(this.delay_timer_id)
								this.delay_timer_id = null
							}
							GlobalEventSystem.Fire(EventName.FINDWAY_ENDED)
						}
						this.delay_timer_id = GlobalTimerQuest.AddDelayQuest(onDelay, 0.5)
						if (findVo.call_back) {
							findVo.call_back()
						}
					} else {
						this.MainRoleMoveAndCancel(new Vector2(findVo.x, findVo.y), 0, findVo.call_back)
					}
				}
			} else if (findVo.type == FindVo.MONSTER) {
				let lx, ly = this.main_role.GetLogicPos()
				if ((findVo.x > 0 || findVo.y > 0) && GameMath.GetDistance(lx, ly, findVo.x, findVo.y) > 20) {
					if (isAgain == false) {
						var findAgain = () => {
							if (this.CanSelectMonster(true)) {
								let mon = this.FindNearestMonsters(findVo.id)
								if (mon) {
									this.MainRoleAttackMonster(mon)
								}
							}
						}
						this.MainRoleMoveAndCancel(new Vector2(findVo.x, findVo.y), findVo.range || 0, findAgain)
						if (findVo.call_back) {
							findVo.call_back()
						}
					}
				} else if (scene_mgr.GetMonsterVoByTypeId(findVo.id) != null) {
					if (isAgain == false) {
						if (this.CanSelectMonster(true)) {
							let mon = this.FindNearestMonsters(findVo.id)
							if (mon) {
								this.MainRoleAttackMonster(mon)
								GlobalEventSystem.Fire(EventName.FINDWAY_ENDED)
							}
							if (findVo.call_back) {
								findVo.call_back()
							}
						}
					}
				} else {
					GlobalEventSystem.Fire(EventName.FINDWAY_ENDED)
				}
			} else if (findVo.type == FindVo.PLAYER) {
				let player = this.GetRole(findVo.id)
				GlobalEventSystem.Fire(EventName.FINDWAY_ENDED)
				if (player != null) {
					this.MainRoleAttackRole(player)
				}
			} else if (findVo.type == FindVo.POINT) {
				let lx, ly = this.main_role.GetLogicPos()
				if (GameMath.GetDistance(lx, ly, findVo.x, findVo.y) <= 1) {
					this.main_role.DoStand()
					let onDelay = () => {
						if (this.delay_timer_id) {
							GlobalTimerQuest.CancelQuest(this.delay_timer_id)
							this.delay_timer_id = null
						}
						GlobalEventSystem.Fire(EventName.FINDWAY_ENDED)
					}
					this.delay_timer_id = GlobalTimerQuest.AddDelayQuest(onDelay, 0.5)
					if (findVo.call_back) {
						findVo.call_back()
					}
				} else {
					this.MainRoleMoveAndCancel(new Vector2(findVo.x, findVo.y), 0, findVo.call_back)
				}

			} else if (findVo.type == FindVo.Fishing) {
				let lx, ly = this.main_role.GetLogicPos()
				if (GameMath.GetDistance(lx, ly, findVo.x, findVo.y) <= 1) {
					this.main_role.DoStand()
					let onDelay = () => {
						if (this.delay_timer_id) {
							GlobalTimerQuest.CancelQuest(this.delay_timer_id)
							this.delay_timer_id = null
						}
						GlobalEventSystem.Fire(EventName.FINDWAY_ENDED)
					}
					this.delay_timer_id = GlobalTimerQuest.AddDelayQuest(onDelay, 0.5)
					if (findVo.call_back) {
						findVo.call_back()
					}
				} else {
					this.MainRoleMoveAndCancel(new Vector2(findVo.x, findVo.y), 0, findVo.call_back)
				}
			} else if (findVo.type == FindVo.Figure) {
			} else if (findVo.type == FindVo.Thinking) {
			}
		}

