import { BaseItem1 } from "../common/BaseItem1"
import { BaseItemRenderer } from "../common/BaseItemRenderer"
import { UIToolTipMgr } from "../common/UIToolTipMgr"
import { GoodsModel } from "../commonModel/GoodsModel"
import { GuildModel } from "../commonModel/GuildModel"
import { Enum_ColorUtil_Light, ColorUtil, Enum_ColorUtil_Dark } from "../util/ColorUtil"
import { TimeUtil } from "../util/TimeUtil"
import { HtmlColorTxt, SetAnchoredPosition, AddUnderLineAndClick, Util } from "../util/Util"

export class GuildDepotRecordItem extends BaseItemRenderer {
	_model

	public WIDTH  = 665
	public HEIGT = 30
	is_set=false
	public constructor(parent) {
		super()
		this._model = GuildModel.GetInstance()
		this.base_file = "guild"
		this.layout_file = "GuildDepotRecordItem"
		this.is_set=false
		this.load_callback=()=>{
				// this._lb_content.addEventListener(Laya.TextEvent.LINK, this.ClickFunc, this)
	            // AddClickEvent(this.euqip,)
			if(!this.is_set){
				this.is_set=true
				this.SetData()
			}
		}
		this.Load()
	}


	PreSetHtml = () => {

		this._lb_content.width = 310
		this._lb_content.style.fontSize = 20
		this._lb_content.style.color = "#663915"
		//this._lb_content.style.wordWrap = true
		this._lb_content.style.leading = 4


		this.euqip.width = 310
		this.euqip.style.fontSize = 20
		this.euqip.style.color = "#663915"
		//this.euqip.style.wordWrap = true
		this.euqip.style.leading = 4

	}


	public dataChanged() {
		if(!super.dataChanged())return
		if(this.is_loaded){
			this.is_set=true
			this.SetData()
		}else{
			this.is_set=false
		}
	}


	public SetData(){
		if(!this.data)return
		this.PreSetHtml()
		let info = this.data
		this.euqip.style.color =ColorUtil.GetReplaceChar(ColorUtil.GetColorDark(info.color)) 
		this._lb_content.innerHTML = "[" + TimeUtil.timeConversion(info.time, "mm-dd hh.MM") + "]" + HtmlColorTxt(info.role_name, Enum_ColorUtil_Dark.GREEN) + this.GetRecordTypeTxt(info.exchange_type)

		this.euqip.innerHTML =  GoodsModel.GetGoodsName(info.type_id) +""
		this.euqip.x=this._lb_content.contextWidth+2
		//SetAnchoredPosition(this.euqip, this._lb_content.width, 0)
		AddUnderLineAndClick(this, this.euqip, () => {
			if (this.data) {
				this.ClickFunc(this.data.id)
			}
		})
		// this.ReplaceUIShader(this.euqip)
	}

	public DeleteMe() {
		//if (this._lb_content ) {
		//this._lb_content.removeEventListener(Laya.TextEvent.LINK, this.ClickFunc, this)
		//}
		super.DeleteMe()
	}

	public ClickFunc(id?) {
		let info = this.GetRecordById(id)
		if (info) {
			this.RecordClickCallBack(info)
		}
	}

	public GetRecordById(id?) {
		let depot_info = this._model.GetDepotInfo()
		if (!depot_info) {
			return
		}
		for (let _tmpi in depot_info.exchange_records) {
			var info = depot_info.exchange_records[_tmpi]
			if (info.id == id) {
				return info
			}
		}
	}

	public RecordClickCallBack(info?) {

		if (info.type == 10) {
			UIToolTipMgr.GetInstance().AppendEquipTips(info.type_id, null, null, info)
		} else {
			UIToolTipMgr.GetInstance().AppendGoodsTips(info.type_id)
		}
	}

	public GetRecordTypeTxt(type?) {
		if (type == 1) {
			return "捐献"
		} else if (type == 2) {
			return "兑换"
		} else if (type == 3) {
			return "销毁"
		}
	}
	_lb_content: Laya.HTMLDivElement
	euqip: Laya.HTMLDivElement
	public GetComponents() {
		[
			this._lb_content,
			this.euqip,
		]
			= this.GetChildrenByNames([

				"_lb_content",
				"euqip",
			])
	}
}
window["GuildDepotRecordItem"] = GuildDepotRecordItem