		let local_MainFunc = MainFunc
		let local_CommonManager_Instance = CommonManager.GetInstance()

		let mainui_loaded_flag_ = {
			MainUITopViewSkin: false,
			MainUIActivityViewSkin: false,
			MainUISecondaryViewSkin: false,
			MainUIChatViewExml: false,
			MainUIDownViewSkin: false
		}
		let _loaded_mainui_callback_ = null

		let main_ui_view_ref_dic_ = []

		//////////////////-SetMainuiLoadedFlag//////////////////-
		this.SetMainuiLoadedFlag = (layout_name?, value?, ref_tar?) => {
			main_ui_view_ref_dic_[layout_name] = ref_tar
			for (let name in mainui_loaded_flag_) {

				if (mainui_loaded_flag_[name] == false) {
					return
				}
			}
			if (_loaded_mainui_callback_) {
				_loaded_mainui_callback_()
				this.has_loaded_mainui_callback = true
				_loaded_mainui_callback_ = null
			}
		}

		//////////////////-SetLoadedMainUICallback//////////////////-
		this.SetLoadedMainUICallback = (func?) => {
			if (_loaded_mainui_callback_) {
				return
			}
			GlobalEventSystem.Fire(EventName.INIT_MAINUI_EVENT)
			_loaded_mainui_callback_ = func
			this.SetMainuiLoadedFlag(null, true)
			setTimeout(() => {
				if (_loaded_mainui_callback_) {
					_loaded_mainui_callback_()
					this.has_loaded_mainui_callback = true
					_loaded_mainui_callback_ = null
				}
			},
				5
			)
		}

		this.GetMainFuncOpenCond = (main_func?) => {
			let bool = false
			if (main_func == local_MainFunc.Role) {
				bool = true
			} else if (main_func == local_MainFunc.Bag) {
				bool = true
			} else if (main_func == local_MainFunc.Pet) {
				bool = local_CommonManager_Instance.CheckFuncOpenState("MountPetView", true)
			} else if (main_func == local_MainFunc.Equip) {
				bool = local_CommonManager_Instance.CheckFuncOpenState("EquipView", true)
			} else if (main_func == local_MainFunc.Treasure) {
				bool = local_CommonManager_Instance.CheckFuncOpenState("SecretTreasureMainView", true)
			} else if (main_func == local_MainFunc.Red) {
				bool = local_CommonManager_Instance.CheckFuncOpenState("RedEnterView", true)
			} else if (main_func == local_MainFunc.Love) {
				bool = local_CommonManager_Instance.CheckFuncOpenState("MarriageBaseView", true)
			} else if (main_func == local_MainFunc.Guild) {
				bool = local_CommonManager_Instance.CheckFuncOpenState("GuildJoinBaseView", true)
			} else if (main_func == local_MainFunc.Composite) {
				bool = local_CommonManager_Instance.CheckFuncOpenState("CompositeView", true)
			} else if (main_func == local_MainFunc.Help) {
				bool = local_CommonManager_Instance.CheckFuncOpenState("GodBefallMainView", true)
			}
			return bool
		}

		this.SwitchView = (func?, index?) => {
			if (func == MainFunc.Role) {
				local_GlobalEventSystem.Fire(RoleModel.OPEN_CHOSE_ROLE_VIEW, index)
			} else if (func == MainFunc.Bag) {
				OpenFun.OpenFun(105)
			} else if (func == MainFunc.Pet) {
				local_GlobalEventSystem.Fire(local_EventName.SWITCH_MOUNT_PET_VIEW, index)
			} else if (func == MainFunc.Equip) {
				EquipModel.GetInstance().Fire(EquipEvent.OPEN_VIEW, "EquipView", index)
			} else if (func == MainFunc.Red) {
				// CompositeModel.GetInstance().Fire(CompositeEvent.OPEN_RED_VIEW, index)
			} else if (func == MainFunc.Treasure) {
				local_GlobalEventSystem.Fire(local_EventName.OPEN_VIEW, "SecretTreasureMainView", index)
			} else if (func == MainFunc.Love) {
				if (CommonManager.GetInstance().CheckFuncOpenState("BabyMainView", true)) {
					let open_state = ViewManager.GetInstance().GetViewOpenState("MainUIIconBoxView")
					if (open_state) {
						local_GlobalEventSystem.Fire(local_EventName.CLOSE_VIEW, "MainUIIconBoxView")
					} else {
						let position = this.GetIconPosInMainUIView(2, MainFunc.Love, { x: 0, y: 0 }, { x: 0, y: 1 })
						if (position) {
							local_GlobalEventSystem.Fire(local_EventName.OPEN_VIEW, "MainUIIconBoxView", "172", position, { x: -38, y: 145 }, 2)
						}
					}
				} else {
					local_GlobalEventSystem.Fire(local_EventName.OPEN_VIEW, "MarriageBaseView")
				}
			} else if (func == MainFunc.Guild) {
				GuildModel.GetInstance().OpenGuildView(0)
			} else if (func == MainFunc.Composite) {
				// CompositeModel.GetInstance().Fire(CompositeModel.OPEN_COMPOSITE_VIEW, index)
			} else if (func == MainFunc.Help) {
				local_GlobalEventSystem.Fire(local_EventName.OPEN_VIEW, "StarEquipMainView")
				// starEquipModel.GetInstance().Fire(starEquipModel.OPEN_VIEW, "StarEquipMainView")
			}
		}


