    public SwitchView(type?) {

        let isholyboss = SceneManager.GetInstance().IsHolyBossScene()
        if (this.nowType == type && !isholyboss) {
            if (type == MainUITaskTeamView.SwitchType.Task) {
                this.task_model.Fire(TaskModel.TASK_OPEN_VIEW, TaskView)	//打开界面
            }
            // return
        }

        this.nowType = type
        this.task_group.visible = this.nowType == MainUITaskTeamView.SwitchType.Task && !isholyboss
        this.team_group.visible = this.nowType == MainUITaskTeamView.SwitchType.Team && !isholyboss
        this.non_team_group.visible = this.nowType == MainUITaskTeamView.SwitchType.Team && !isholyboss

        if (type == MainUITaskTeamView.SwitchType.Task) {
            if (this.boss_scene) {
                MainUIManager.GetInstance().AddMoveComponent(this, this.task_group, true, MainUIManager.MOVE_TYPE.Stay)
                let source = this.mainui_act_state && "uirwl_004b1" || "uirwl_004d2"
                ResManager.GetInstance().SetImageSprite(this, this._task_icon, "mainUI_asset", source)
            } else {
                ResManager.GetInstance().SetImageSprite(this, this._task_icon, "mainUI_asset", "uirwl_004b1")
            }
            ResManager.GetInstance().SetImageSprite(this, this._task_bg, "mainUI_asset", "uirwl_004a")

            ResManager.GetInstance().SetImageSprite(this, this._team_bg, "mainUI_asset", "UIrwl_004")
            ResManager.GetInstance().SetImageSprite(this, this._team_icon, "mainUI_asset", "uirwl_004c1")

            this._team_desc.color = MainUITaskTeamView.DarkColor
            this._task_desc.color = MainUITaskTeamView.LightColor
            this._team_desc_en.color = MainUITaskTeamView.DarkColor
            this._task_desc_en.color = MainUITaskTeamView.LightColor

            //if (! this.task_init ) {
            //this.task_init = true
            this.ShowTaskContent()
            //}
        } else {
            ResManager.GetInstance().SetImageSprite(this, this._task_bg, "mainUI_asset", "UIrwl_004")
            if (this.boss_scene) {
                MainUIManager.GetInstance().RemoveMoveOneComponent(this, this.task_group)
                let source = this.mainui_act_state && "uirwl_004b" || "uirwl_004d1"
                ResManager.GetInstance().SetImageSprite(this, this._task_icon, "mainUI_asset", source)
            } else {
                ResManager.GetInstance().SetImageSprite(this, this._task_icon, "mainUI_asset", "uirwl_004b")
            }


            ResManager.GetInstance().SetImageSprite(this, this._team_bg, "mainUI_asset", "uirwl_004a")
            ResManager.GetInstance().SetImageSprite(this, this._team_icon, "mainUI_asset", "uirwl_004c")

            this._team_desc.color = MainUITaskTeamView.LightColor
            this._task_desc.color = MainUITaskTeamView.DarkColor
            this._team_desc_en.color = MainUITaskTeamView.LightColor
            this._task_desc_en.color = MainUITaskTeamView.DarkColor
            if (isholyboss) {
                // BossModel.GetInstance().Fire(BossModel.FORCE_SHOW_TASK)
                return
            }
            this.UpdateTeamData()

        }
    }

