    public ShowFinger() {

        let main_line_task_vo = this.task_model.GetMainLineTaskVo()
        if (SceneManager.GetInstance().IsFieldScene() && Util.IsTableEmpty(BaseWindowComponent.CURR_OPEN_VIEW)
            && main_line_task_vo && !this.task_model.IsFirstTask() && !this.task_model.NotShowFinger(main_line_task_vo)) {
            if (this.delay_timer_id_) {
                clearTimeout(this.delay_timer_id_)
                this.delay_timer_id_ = null
            }
            let need_show_one = true
            if (!this.task_model.DoTask(null, false)) {
                //console.log("33333333333333333")
                let [has_lv, lv_task_vo, daily_task_vo] = this.task_model.HasNotFinishLvTask()
                if (has_lv && daily_task_vo) { //日常任务特殊处理
                    //console.log("ShowFinger////-333333333////", this.task_model.has_show_daily_task_finger)
                    if (!this.task_model.has_show_daily_task_finger) {
                        let step_cfg = { direction: 4, text: "<font color='0xFFFF00'>日常任务</font> \n加速升级~" }
                        this.ShowMainLineTaskArrow(step_cfg, true)
                    } else {
                        //console.log("ShowFinger////-333333333////", this.task_model.has_show_daily_task_finger)
                        need_show_one = false
                        this.HideMainLineTaskArrow()
                    }
                } else {
                    if (main_line_task_vo.task_tips_type == TaskTipType.LV) {
                        if ((this.task_model.click_lv_arrow_time && TimeUtil.getServerTime() - this.task_model.click_lv_arrow_time < TaskModel.lV_ARROW_TIME_LEN) || this.task_model.show_lv_times > 2) {
                            return
                        }
                        this.task_model.show_lv_times = this.task_model.show_lv_times + 1
                    }
                    //console.log("ShowFinger////-3333333333333333//////")
                    this.ShowMainLineTaskArrow()
                }
            }
            //console.log("ShowFinger////-44444444444444444//////")
            if (need_show_one) {
                this.NeedShowOneFinger()
            }
        } else {
            this.HideMainLineTaskArrow()
        }
    }

    public NeedShowOneFinger() {

        let main_line_task_vo = this.task_model.GetMainLineTaskVo()
        //console.log("ShowFinger////-5555555555555555555//////：", ! this.story_model.HasMainUiFinger())
        if (!this.story_model.HasMainUiFinger() && main_line_task_vo && main_line_task_vo.task_tips_type != TaskTipType.DressEquip) {
            //if (! this.story_model.HasMainUiFinger() && main_line_task_vo && main_line_task_vo.main_line_order <= 41 && main_line_task_vo.task_tips_type != TaskTipType.DressEquip ) {
            let force = false
            let step_cfg = this.task_model.GetNowGuideCfg(true)
            if (!this.task_model.IsFindNpcTask(main_line_task_vo.task_tips_type) && main_line_task_vo.task_tips_type != TaskTipType.Kill
                && main_line_task_vo.task_tips_type != TaskTipType.Collect) {
                force = true
            }
            if (!step_cfg || !step_cfg.text) {
                if (this.task_model.IsCurrMainTaskHasFinish()) {
                    step_cfg = { direction: 4, text: "任务完成 \n快领取奖励吧~" }
                } else if (main_line_task_vo.task_tips_type != TaskTipType.Kill) {
                    step_cfg = { direction: 4, text: "继续主线任务 \n 加油成长吧~" }
                }
            } else {
                let copy = step_cfg
                copy.direction = 4
                step_cfg = copy
            }
            if (this.delay_timer_id_) {
                clearTimeout(this.delay_timer_id_)
                this.delay_timer_id_ = null
            }
            let delay_fun = () => {
                //console.log("ShowFinger////-6666666666666666//////：", force)
                this.ShowMainLineTaskArrow(step_cfg, force)
            }

            this.delay_timer_id_ = setTimeout(delay_fun, 0.1)
        }
    }

