    public SetMainLineTask(task_vo?) {
        let main_line_task_vo = this.task_model.GetMainLineTaskVo()
        let receive_task_list = this.task_model.GetHasReceiveTaskList()
        if (receive_task_list && Util.TableSize(receive_task_list) > 0 && (task_vo || main_line_task_vo)) {
            if (!this.main_line_item_) {
                this.main_line_item_ = new MainUITaskMainLineItem(this.main_line_con)
                this.main_line_item_.Load()
            }
            this.main_line_item_.SetVisible(true)
            let task_id = 0
            let task = null
            task = []
            if (task_vo) {
                task_id = task_vo.task_id
            } else {
                task_id = main_line_task_vo.task_id
            }
            task.task_id = task_id
            task.sort_index = 0
            task.sort_sub_index = 0
            task.tips_list = receive_task_list[task.task_id]
            this.main_line_item_.SetData(task)
            //初始化完设一遍引导箭头
            this.ShowFinger()
        } else {
            if (this.main_line_item_) {
                this.main_line_item_.SetVisible(false)
            }
        }
    }

    public SetTaskConSize() {
        if (!this.main_line_con.visible) {
            this.Content1.y = this.main_line_con.y
            this.Content1.height = 179
        } else {
            this.Content1.y = 135
            this.Content1.height = 120
        }
    }

    public SetNowTaskPos() {

        if (!this.is_loaded) {
            return
        }
        let index = 0
        if ((this.task_list_ && this.task_model.now_select_task_id)) {
            let vo = null

            let i = 0
            let length = this.task_list_.length
            do {
                vo = this.task_list_[i]
                if (vo) {
                    if (vo.task_id == this.task_model.now_select_task_id) {
                        index = i
                        break
                    }
                }
                i = i + 1
            } while ((i < length)
            )
            let gap = index * 70
        }
        // this.task_loop_mgr.CenterOnChild(index)
    }

