import { BaseItemRenderer } from "../common/BaseItemRenderer"
import { ResManager } from "../common/ResManager"
import { MedalModel } from "../commonModel/MedalModel"
import { ShopModel } from "../commonModel/ShopModel"
import { ColorType, Enum_ColorUtil_Dark, Enum_ColorUtil_Light } from "../util/ColorUtil"
import { SetSizeDelta, Util } from "../util/Util"

export class ShopSeriesTab extends BaseItemRenderer {
	_Image1
	labelDisplay
	linelabelDisplay
	model
	group: Laya.Box
	redDisplay: Laya.Image
	public WIDTH = 120
	public HEIGT = 47

	public constructor(parent) {
		super()

		this.model = ShopModel.GetInstance()
		this.base_file = "shop"
		this.layout_file = "ShopSeriesTab"
		this.Load()
		// this.skinName= "resource/game/shop/exml/ShopSeriesTabExml.exml"

		// this.load_callback = () => {

		// }

	}

	public createChildren() {
		super.createChildren()
	}

	public dataChanged() {

		//顯示數據中的 label 值
		// if (this.is_loaded ) 
		if (super.dataChanged()) {
			let data = this.data
			this.labelDisplay.text = data.desc

			let img_width = null
			let img_height = null
			let text_color = null
			let line_color = null
			let url = null
			if (this.selected) {
				img_width = 115.87
				img_height = 46.76
				//text_color = ColorUtilValue.WHITE
				text_color = "#ffffff"
				// line_color = Color(225/255,116/255,58/255,1) e1743a
				line_color = Enum_ColorUtil_Light.ORANGE
				url = "uiscv2_007"
			} else {
				img_width = 107
				img_height = 43.17
				// text_color = Color(232/255,217/255,211/255,1) e8d9d3
				text_color = "#9c9c9c"
				// line_color = Color(179/255,130/255,112/255,1) b38270 brown
				line_color = Enum_ColorUtil_Dark.GRAY
				url = "uiscv2_008"
			}

			ResManager.GetInstance().SetImageSprite(this, this._Image1, "shop_asset", url)
			SetSizeDelta(this._Image1, img_width, img_height)
			this.labelDisplay.color = text_color
			// this.linelabelDisplay.effectColor = line_color
		}
	}


	public GetComponents() {
		[
			this._Image1,
			this.group,
			this.redDisplay,
			this.labelDisplay,
		]
			= this.GetChildrenByNames([

				"_Image1",
				"group",
				"redDisplay",
				"labelDisplay",
			])
	}
}
window["ShopSeriesTab"] = ShopSeriesTab