import { BaseItem1 } from "../common/BaseItem1"
import { EventName } from "../common/EventName"
import { OpenFun } from "../common/OpenFun"
import { ResManager } from "../common/ResManager"
import { WordManager } from "../common/WordManager"
import { TaskModel, TaskType, TaskTipType, TaskTypeColor } from "../commonModel/TaskModel"
import { RoleManager } from "../role/RoleManager"
import { Scene } from "../scene/Scene"
import { SceneManager } from "../scene/SceneManager"
import { Message } from "../sysinfo/SysInfoController"
import { GlobalEventSystem } from "../util/DeclareGlobalVar"
import { PoseState } from "../util/StateMachineManager"
import { Status } from "../util/Status"
import { TimeUtil } from "../util/TimeUtil"
import { Util, SetLocalScale, Trim, SetAnchoredPositionX } from "../util/Util"

export class MainUITaskMainLineItem extends BaseItem1 {
	Empclick_group
	Empfinger_con
	data
	finger_cache
	first_pos_x
	force
	init_pos_y
	is_delay_callback
	name_pos_y
	needRefresh
	select_cache
	step_cfg
	task
	task_model

	public constructor(parent?) {
		super(parent)

		this.base_file = "mainUI"
		this.layout_file = "MainUITaskItem"
		this.task_model = TaskModel.GetInstance()
		this.init_pos_y = 0;
		this.name_pos_y = 0;
		this.is_delay_callback = false
		this.first_pos_x = 186
		this.load_callback = () => {
			this.InitEvents()
			// this.first_pos_x = this.right_tag.x
			this.first_pos_x = 186

		}
	}

	public DeleteMe() {

		this.ClearUIEffect(this.finish_effect)
		this.ClearUIEffect(this.select_effect)
		super.DeleteMe()
	}

	public InitEvents() {

		let click_fun = () => {
			if (!this.task_model.last_click_main_ui_task_time || Status.NowTime - this.task_model.last_click_main_ui_task_time > 0.8) {
				if (this.task) {
					let main_role = Scene.GetInstance().GetMainRole()
					if (main_role && main_role.IsInState(PoseState.FLY_SHOE_EFFECT)) {
						return
					}
					this.HideMainLineArrow()
					if (this.task.task_type == TaskType.DAILY) {
						this.task_model.has_show_daily_task_finger = true
					} else {
						this.task_model.has_show_daily_task_finger = false
					}

					this.task_model.Fire(TaskModel.CLICK_DO_TASK, this.task.task_id, this.task.task_type)
					let finish = this.task_model.IsAllStepFinish(this.task.task_id)
					if (finish && !this.task_model.IsFindNpcTask(this.task.task_tips_type)) {
						if (this.task_model.ThisTaskTypeCanShowView(this.task)) {
							this.task_model.Fire(TaskModel.TASK_OPEN_VIEW, "TaskFinishView", this.task)
							// } else if (this.task.task_type == TaskType.REINCARNATION && ReincarnationModel.GetInstance().IsFinishStageTask() ) {
							// 	OpenFun.OpenFun(18)
							// } else if (this.task.task_tips_type == TaskTipType.FinDunType && this.task.id == DUN_TYPE.Exp && SceneManager.GetInstance().IsExpDungeon() ) { 
							// 	Message.show("副本还在继续哦~")
							// 	return
						} else {
							TaskModel.GetInstance().Fire(TaskModel.REQUEST_CCMD_EVENT, 30004, this.task.task_id)
						}
					} else {
						this.task_model.DoTask(this.task, null, null, true, true)
					}
					if (this.task_model.IsMainTask(this.task.task_id) && this.task.task_tips_type == TaskTipType.LV) {
						this.task_model.click_lv_arrow_time = TimeUtil.getServerTime()
					}


				}
				this.task_model.last_click_main_ui_task_time = Status.NowTime
			}
		}

		Util.AddClickEvent(this.click_group, click_fun, this, true)

		let click_do_task = (task_id?, task_type?) => {
			if ((this.task && task_type) && task_id) {
				let bool = this.task.task_id == task_id || (task_type == this.task.task_type && (task_type == TaskType.GUILD || task_type == TaskType.DAILY))
				this.SetSelect(bool)
			}
		}

		this.BindEvent(this.task_model, TaskModel.CLICK_DO_TASK, click_do_task)

		let UpdateCircleTaskProgress = (scmd?) => {
			if (this.task && scmd) {
				if (this.task.task_type == scmd.task_type) {
					this.SetTipsMsg(this.task)
				}
			}
		}

		this.BindEvent(this.task_model, TaskModel.UPDATE_CIRCLE_TASK_PROGRESS, (scmd?) => {
			UpdateCircleTaskProgress(scmd)
		}
		)
		let update_fun = (task_id?, task_tips_list?) => {
			if (!this.task_model.IsAllStepFinish(task_id)) {
				if (((this.data && this.task) && this.task.task_id == task_id) && task_tips_list) {
					this.data.tips_list = task_tips_list
					if (this.data.tips_list[0]) {
						this.task = this.FindUnFinishTask(this.data.tips_list)
						this.SetTipsMsg(this.task)
					}
				}
			}
		}

		this.BindEvent(this.task_model, TaskModel.UPDATE_ONE_TASK, update_fun)

		let lvUpFunc = () => {
			if ((this.data && this.task) && this.task.task_type == TaskType.REINCARNATION) {
				this.SetTipsMsg(this.data)
			}
		}

		this.BindVar(RoleManager.GetInstance().GetMainRoleVo(), EventName.CHANGE_LEVEL, lvUpFunc)

		let task_success_fun = (task_id?) => {
			if (this.task && this.task.task_id == task_id && this.click_group) {
				SetLocalScale(this.click_group, 1)
			}
		}
		this.BindEvent(this.task_model, TaskModel.FINISH_TASK, task_success_fun)

		if (this.needRefresh) {
			this.SetData(this.data)
			this.needRefresh = false
		}
	}

	public SetData(data?) {

		this.data = data
		if (this.is_loaded && this.data.tips_list) {
			let task = this.FindUnFinishTask(this.data.tips_list)
			if (task) {
				this.task = task
				this.SetTaskData(task)
				if (this.finger_cache) {
					this.ShowMainLineArrow(this.step_cfg, this.force)
					this.finger_cache = false
				}
			}
		} else {
			this.needRefresh = true
		}
	}

	public FindUnFinishTask(tips_list?) {

		if (tips_list) {
			let task = tips_list[0]
			for (let _tmpi in tips_list) {
				var vo = tips_list[_tmpi]
				if (vo.has_finish != 1) {
					task = vo
					break
				}
			}
			return task
		}
	}

	public SetTaskData(task?) {

		if (task) {
			this.SetTitle(task)
			this.SetTipsMsg(task)
		}
	}

	public SetTitle(task?) {

		if (task) {
			//let task_name = TaskTypeTitle[task.task_type] + task.task_name
			//if (! task_name ) {
			//task_name = this.task_model.GetTaskNameTitle(task.task_id)
			//}
			let icon_sour = this.task_model.GetTaskTagIconSour(task.task_type)
			ResManager.GetInstance().SetImageSprite(this, this.task_tag, "mainUI_asset", icon_sour, true)
			let task_name = "<font color=" + TaskTypeColor[task.task_type] + ">" + task.task_name + "</font>"

			if (task.task_type == TaskType.GUILD || task.task_type == TaskType.DAILY) {
				let [finish_num, all_num] = this.task_model.GetCicleTaskProgressByTaskType(task.task_type)
				if (task.task_type == TaskType.GUILD) {
					all_num = 10
					if (finish_num == null) {
						finish_num = 0
					}
					finish_num = (finish_num % 10 == 0 && (10) || (finish_num % 10))
				}
				if (finish_num != null && all_num != null) {
					let color_str = (all_num == finish_num && ("'#b3ff48'") || ("'#ffffff'"))
					task_name = task_name + "<font color=" + color_str + ">(" + finish_num + "/" + all_num + ")</font>"
				}
			} else if (task.task_type == TaskType.MAIN_LINE) {
				if (task.task_id > 100640) {
					task_name = task_name
				} else {
					task_name = task_name + "<font color=" + TaskTypeColor[task.task_type] + ">" + "" + task.main_line_order + "</font>"
				}
			}
			this.task_name.style.fontSize = 16
			this.task_name.style.color = "#54d5ff"
			this.task_name.width = 187
			this.task_name.innerHTML = Util.StrToHTML(Trim(task_name))
		}
	}

	public SetTipsMsg(task?) {

		let tip_str = ""
		let task_tips_msg = this.task_model.GetTaskTipsMsg(task, true)
		let res_name = null
		let finish = this.task_model.IsAllStepFinish(task.task_id)
		let reinSpeTips = null
		if (task.task_type == TaskType.REINCARNATION) {
			if (Number(task.now_num) >= Number(task.need_num)) {
				finish = true
				reinSpeTips = true
			}
			// let lv = ReincarnationModel.GetInstance().needStageList[task.task_id]
			// if ((finish && lv) && RoleManager.GetInstance().GetMainRoleVo().level < lv ) {
			// 	finish = false
			// 	reinSpeTips = lv
			// }else{
			// reinSpeTips = false
			// }
		}
		if (finish) {
			if (this.task_model.IsFindNpcTask(task.task_tips_type)) {
				tip_str = Trim(task_tips_msg)
			} else {
				tip_str = Trim(task_tips_msg) + " <font color='#b3ff48'>(完成)</font>"
			}
			res_name = "ui_taskbar_glow"
		} else {
			res_name = "ui_taskbar_glow1"
			if (task.show_num > 0) {
				let now_str = WordManager.FormatNumber(task.show_num)
				tip_str = Trim(task_tips_msg) + " <font color='#ffef67'>(0/" + now_str + ")</font>"
			} else {
				let now_str = WordManager.FormatNumber(task.now_num)
				let need_str = WordManager.FormatNumber(task.need_num)
				let color_str = (task.need_num == task.now_num && ("'#b3ff48'") || ("'#ffef67'"))
				if (reinSpeTips) {
					tip_str = "人物达到" + reinSpeTips + "级<font color='#ffef67'>(0/1)</font>"
				} else {
					tip_str = Trim(task_tips_msg) + " <font color=" + color_str + ">(" + now_str + "/" + need_str + ")</font>"
				}
			}
		}
		this.task_tips.style.fontSize = 16
		this.task_tips.style.color = "#ffffff"
		this.task_tips.style.leading = 8
		this.task_tips.width = 200
		this.task_tips.innerHTML = Util.StrToHTML(Trim(tip_str))
		this.task_tips.height = this.task_tips.contextHeight + 10
		this.task_tips.style.padding = [(this.task_tips.height - this.task_tips.contextHeight) / 2, 0, 0, 0]
		let pos_x = this.first_pos_x
		if (this.task_name.contextWidth > 145) {
			pos_x = pos_x + (this.task_name.contextWidth - 145)
		}
		SetAnchoredPositionX(this.right_tag, pos_x)
		this.right_tag.visible = finish
		if (finish) {
			// this.AddUIEffect2("ui_taskbar_framework1", this.finish_effect, null, null, true)
		} else {
			this.ClearUIEffect(this.finish_effect)
		}
		let bool = this.task.task_id == this.task_model.now_select_task_id || (this.task_model.now_do_task_type == this.task.task_type && (this.task_model.now_do_task_type == TaskType.GUILD || this.task_model.now_do_task_type == TaskType.DAILY))
		this.SetSelect(bool)
		this.task_model.SendProtoToFinsh(task)
	}

	public ShowMainLineArrow(step_cfg?, force?) {

		if (this.is_loaded) {
			let main_line_task_vo = this.task_model.GetMainLineTaskVo()
			let step_cfg = null
			if (main_line_task_vo) { 		//保持任务栏的箭头是4的方向
				let cfg = this.task_model.GetNowGuideCfg(true)
				if (cfg) {
					step_cfg = cfg
					step_cfg.direction = 4
				}
			}
			GlobalEventSystem.Fire(EventName.SHOW_FINGER, this, this.finger_con, "Main", null, null, true, null, step_cfg, force)
		} else {
			this.finger_cache = true
			this.step_cfg = step_cfg
			this.force = force
		}
	}

	public HideMainLineArrow() {

		GlobalEventSystem.Fire(EventName.HIDE_FINGER, this, this.finger_con)
	}

	public SetSelect(bool?) {

		if (this.is_loaded) {
			this.select_bg.visible = bool
			//}else{
			//this.select_cache = bool
		}
	}

	click_group: Laya.Box
	bg: Laya.Image
	task_tag: Laya.Image
	task_name: Laya.HTMLDivElement
	right_tag: Laya.Image
	task_tips: Laya.HTMLDivElement
	num_txt: Laya.HTMLDivElement
	finish_effect: Laya.Box
	select_effect: Laya.Box
	select_bg: Laya.Image
	finger_con: Laya.Box
	public GetComponents() {
		[
			this.click_group,
			this.bg,
			this.task_tag,
			this.task_name,
			this.right_tag,
			this.task_tips,
			this.num_txt,
			this.finish_effect,
			this.select_effect,
			this.select_bg,
			this.finger_con,
		]
			= this.GetChildrenByNames([

				"click_group",
				"bg",
				"task_tag",
				"task_name",
				"right_tag",
				"task_tips",
				"num_txt",
				"finish_effect",
				"select_effect",
				"select_bg",
				"finger_con",
			])
	}


}

window["MainUITaskMainLineItem"] = MainUITaskMainLineItem