    public constructor() {
        // Runner.GetInstance().AddRunObj(this)
        let local_Math = Math;
        this.readStream = (buffer: Laya.Byte, type) => {
            let value = null, func_name = this.ReadFmt2Func[type];
            if (func_name) {
                value = buffer[func_name]();
            }
            else if (type == "l") {
                let hight_value: number = buffer.readUint32(), low_value: number = buffer.readUint32();
                value = hight_value * local_Math.pow(2, 32) + low_value;
            }
            else if (type == "L") {
                let hight_value: number = buffer.readInt32(), low_value: number = buffer.readInt32();
                value = hight_value * local_Math.pow(2, 32) + low_value;
            }
            // if (type == "c") {
            //     value = buffer.readUnsignedByte()
            // }
            // else if (type == "C") {
            //     value = buffer.readByte()
            // }
            // else if (type == "i") {
            //     value = buffer.readUint32()
            // }
            // else if (type == "I") {
            //     value = buffer.readInt32()
            // }
            // else if (type == "h") {
            //     value = buffer.readUint16()
            // }
            // else if (type == "H") {
            //     value = buffer.readShort()
            // }
            // else if (type == "s") {
            //     value = buffer.readUTF()
            // }
            // else if (type == "B") {
            //     // value = buffer:ReadBytes()
            // }
            // console.log("receive message = " + value)
            return value;
        };
        this.writeStream = (buffer: Laya.Byte, type, value) => {
            // console.log("send Message = "+ type+"_"+(value))
            if (value == null) {
                if (type == "s") {
                    value = "";
                }
                else {
                    value = 0;
                }
            }
            let func_name = this.WriteFmt2Func[type];
            if (func_name) {
                buffer[func_name](value);
            }
            else if (type == "l") {
                let hight_value: number = local_Math.floor(value / local_Math.pow(2, 32)), low_value: number = value % local_Math.pow(2, 32);
                buffer.writeUint32(hight_value);
                buffer.writeUint32(low_value);
            }
            else if (type == "L") {
                let hight_value: number = local_Math.floor(value / local_Math.pow(2, 32)), low_value: number = value % local_Math.pow(2, 32);
                buffer.writeInt32(hight_value);
                buffer.writeInt32(low_value);
            }
            // if (type == "c") {
            //     buffer.writeByte(value)
            // }
            // else if (type == "i") {
            //     buffer.writeUint32(value)
            // }
            // else if (type == "I") {
            //     buffer.writeInt32(value)
            // }
            // else if (type == "h") {
            //     buffer.writeUnsignedShort(value)
            // }
            // else if (type == "H") {
            //     buffer.writeShort(value)
            // }
            // else if (type == "s") {
            //     buffer.writeUTF(value)
            // }
            // else if (type == "B") {
            //     buffer.writeBytes(value)
            // }
        };
        // this.InitSocket();
    }
    public InitSocket = () => {
        if (!this.socket){
            this.receive_byteBuff.endian = Laya.Byte.BIG_ENDIAN
            this.socket = new Laya.Socket();
            //设置数据格式为二进制，默认为字符串
            this.socket.endian = Laya.Byte.BIG_ENDIAN
            //添加收到数据侦听，收到数据会调用此方法
            this.socket.on(Laya.Event.MESSAGE, this, this.onReceiveMessage);
            //添加链接打开侦听，连接成功会调用此方法
            this.socket.on(Laya.Event.OPEN, this, this.onSocketOpen);
            //添加链接关闭侦听，手动关闭或者服务器关闭连接会调用此方法
            this.socket.on(Laya.Event.CLOSE, this, this.onSocketClose);
            //添加异常侦听，出现异常会调用此方法
            this.socket.on(Laya.Event.ERROR, this,  this.onSocketError);
        }
    };
