import { BaseItemRenderer } from "../common/BaseItemRenderer"
import { Enum_UILayer } from "../common/LayerManager"
import { CustomActivityModel } from "../commonModel/CustomActivityModel"
import { ResManager } from "../common/ResManager"
import { GameResPath } from "../util/GameResPath"
import { Enum_ColorUtil_Light } from "../util/ColorUtil"
import { HtmlColorTxt, Util } from "../util/Util"
import { CustomActivityDefine } from "../commonModel/CustomActivityDefine"
import { OpenFun } from "../common/OpenFun"
import { EquipmentItem } from "../common/EquipmentItem"
import { GoodsModel } from "../commonModel/GoodsModel"


export class AccumRechargeItem extends BaseItemRenderer {
	_img_bg: Laya.Image
	_Image111: Laya.Image
	_img_over: Laya.Image
	_lb_title: Laya.HTMLDivElement
	_btn_recharge: Laya.Box
	_Image11: Laya.Image
	labelDisplay: Laya.Label
	_btn_get: Laya.Box
	_Image1: Laya.Image
	_reddot: Laya.Image
	labelDisplay1: Laya.Label
	_Scroller1: Laya.Panel
	_gp_reward: Laya.HBox
	VHS_Scroller1
	_Viewport1
	_canGet
	_enough
	_item_list
	_model
	parent_wnd
	WIDTH = 698
	HEIGT = 163
	public static width = 698
	public static height = 163

	public constructor(parent) {
		super()


		this._item_list = []
		this._enough = false
		this._canGet = false
		this.base_file = "activity"
		this.layout_file = "AccumRechargeItem"

		this._model = CustomActivityModel.GetInstance()
		
		this.load_callback = () => {

			this.LoadSuccess()
		}
		this.Load()
	}

	public LoadSuccess() {
		this._Scroller1.hScrollBar.visible = false
		this.InitEvent()

		//this.RegisterMask(this._Viewport1, 2)
		ResManager.GetInstance().SetOutsideImageSprite(this, this._img_bg, GameResPath.GetIcon("activity", "cjgh_002"))
	}

	public DeleteMe() {

		for (let _tmpi in this._item_list) {
			var item = this._item_list[_tmpi]
			item.DeleteMe()
		}
		this._item_list = null
		super.DeleteMe()
	}

	public dataChanged() {
		if (super.dataChanged()) {
			let data = this.data
			let cond = CustomActivityModel.GetInstance().GetActCondition(data.base_type, data.sub_type, "data", data.grade)
			let is_today = cond.type && Number(cond.type) == 1
			let total = null
			if (is_today) {
				total = this._model.GetActRechargeDay()
			} else {
				total = this._model.GetActRecharge(data.base_type, data.sub_type)
			}
			total = total == null && 0 || total
			let target = is_today && Number(cond.today_gold) || Number(cond.gold)
			target = target == null && 0 || target
			let enough = total >= target
			let canGet = data.status != 2

			let color = "'#fff36b'"
			let str = HtmlColorTxt(total + "/" + target, color)
			let day_ref = is_today && "<font color='b3ff48'>(每天重置)</font>" || ""
			this._lb_title.style.fontSize = 26
			this._lb_title.style.valign = "center"
			this._lb_title.style.color = "#ffffff"
			this._lb_title.width = 500
			this._lb_title.innerHTML = Util.StrToHTML("累计充值" + str + "勾玉" + day_ref)
			//this._lb_title.textFlow = Util.StrToHTML("累计充值" + str + "钻石" + day_ref)
			this._reddot.visible = canGet && enough
			this._btn_get.visible = canGet && enough
			this._btn_recharge.visible = canGet && !enough
			this._img_over.visible = !canGet

			this._enough = enough
			this._canGet = canGet
			let rewards = this._model.GetActReward(data.base_type, data.sub_type, data.form_type, data.reward)
			this.UpdateItems(rewards)
		}
	}

	public InitEvent() {

		Util.AddClickEvent(this._btn_get, () => {
			let data = this.data
			if (this._canGet || (this._enough && data.status == 0)) {
				this._model.Fire(CustomActivityDefine.EVENT.SCMD_REQUEST, 33105, data.base_type, data.sub_type, data.grade)
			}
		}, this, true)

		Util.AddClickEvent(this._btn_recharge, () => {
			OpenFun.OpenFun(21)
		}, this, true)
	}

	public UpdateItems(list?) {

		for (let i = 0; i < list.length; i++) {
			let info = list[i]
			let item = this._item_list[i]
			if (!item) {
				item = new EquipmentItem(this._gp_reward, null, "UI")
				item.SetItemSize(87, 87)
				//item.SetMaskId(2)
				//item.SetMaskRect(this.data.parent_mask)
				//item.SetMaskItemMaterial(this.mask_item_mat)
				item.Load()
				this._item_list[i] = item
			}
			let [type_id, _] = GoodsModel.GetInstance().GetMappingTypeId(info[0], info[1])
			let goods_vo = GoodsModel.GetInstance().GetGoodsBasicByTypeId(type_id)
			item.SetData(type_id, info[2])
			item.SetVisible(true)
		}

		for (let i = list.length; i < this._item_list.length; i++) {
			this._item_list[i].SetVisible(false)
		}

		// if (list.length <= 5) {
		// 	this._Viewport1.raycastTarget = false
		// } else {
		// 	this._Viewport1.raycastTarget = true
		// }
	}



	public GetComponents() {
		[
			this._img_bg,
			this._Image111,
			this._img_over,
			this._lb_title,
			this._btn_recharge,
			this._Image11,
			this.labelDisplay,
			this._btn_get,
			this._Image1,
			this._reddot,
			this.labelDisplay1,
			this._Scroller1,
			this._gp_reward,
		]
			= this.GetChildrenByNames([

				"_img_bg",
				"_Image111",
				"_img_over",
				"_lb_title",
				"_btn_recharge",
				"_Image11",
				"labelDisplay",
				"_btn_get",
				"_Image1",
				"_reddot",
				"labelDisplay1",
				"_Scroller1",
				"_gp_reward",
			])
	}
}

window["AccumRechargeItem"] = AccumRechargeItem