import { GameMath } from "../../util/GameMath";
import { Status } from "../../util/Status";
import { Character } from "./Character";
import { SceneBaseType } from "../SceneConfig";
import { PoseState } from "../../util/StateMachineManager";
import { Vector2 } from "../../util/Vector2";
import { SceneObj } from "./SceneObj";
import { Scene } from "../Scene";
import { SceneManager } from "../SceneManager";
import { SourceOperateMove } from "../../operation/SourceOperateMove";
import { Config } from "../../common/Config";

export class Partner extends Character {
	name
	update_index
	is_to_dead
	owner_name_id
	find_way_offset
	vo
	id
	follow_dis
	last_find_time
	is_dead
	is_can_update
	curr_follow_tar_pos
	owner
	_type
	compress_id
	move_speed             
	has_drop_pick

	public constructor(){		
	super() 
		
		this._type = SceneBaseType.Partner
		this.update_index = 0
		this.follow_dis = 200
		this.last_find_time = 0
		this.find_way_offset = 0 
		this.curr_follow_tar_pos = {x : 0,y : 0}
	}

	public PartnerTextureChange(){ 
		
		this.CreateClotheSprite(this.vo.GetTextureId())
	}

	public CanUpdate(){ 
		if (! this.is_can_update ) {
			return false
		} 
		let can_update = super.CanUpdate()
		if (! can_update ) {
			if (this.owner && this.owner.IsInState(PoseState.MOVE) ) {
				return true
			} else if (this.owner && this.owner.IsInState(PoseState.JUMP) && this.ignore_update_index > 8 ) {
				return true
			} else if (this.IsInState(PoseState.STAND) && ! this.all_rotate_off && this.ignore_update_index > 10 ) {
				return true
			}
		}
		return can_update
	}

	public Update(now_time?, elapse_time?){ 
		
		if (this.vo == null || this.owner == null ) {
			return
		}
		this.update_index = this.update_index + 1
		if (this.update_index % 7 == 0 ) { 
			let dist = GameMath.GetDistance(this.real_pos.x, this.real_pos.y, this.owner.real_pos.x, this.owner.real_pos.y, true)
			if (dist >= this.follow_dis && ! this.has_drop_pick ) {
				if (Status.NowTime - this.last_find_time > this.find_way_offset ) {
					this.last_find_time = Status.NowTime
					let end_pos = this.GetFollowPos()
					this.move_speed = this.owner.GetMoveSpeed(this.owner.direction) * (1 + (dist - 350) / 600)
					let is_straight_line = this.FindPathAndMove(end_pos)
					if (is_straight_line ) {
						this.find_way_offset = 0 
					}else{
						this.find_way_offset = 0.15
					}
					this.update_index = 1
				}
			}
		} else if (this.update_index % 3 == 0 ) {
			if (this.owner.HasModelHideFlag() && ! this.HasModelHideFlag(SceneObj.ModelHideFlag.IndependenRole) ) {
				this.SetModelHideFlag(SceneObj.ModelHideFlag.IndependenRole, true)
			} else if (! this.owner.HasModelHideFlag() && this.HasModelHideFlag(SceneObj.ModelHideFlag.IndependenRole) ) {
				this.SetModelHideFlag(SceneObj.ModelHideFlag.IndependenRole, false)
			}
		}
		super.Update(now_time, elapse_time)
	}

	public Revived(){ 
		
		super.Revived()
	}



	public DeleteMe(){ 
		
		this.ReleaseObj()
	}
	public ClearPartner(){ 
		
		if (this.vo ) {
			this.vo.UnBindAll()
			this.vo.DeleteMe()	
			this.vo = null
		}

		if (this.owner && this.owner.GetVo() && this.owner_name_id ) {
			this.owner.GetVo().UnBind(this.owner_name_id)
		}
		this.owner_name_id = null
	}
	public ReleaseObj(){ 
		
		this.ReleaseCharacter()
		this.ClearPartner()

		this.is_dead = true
		this.is_to_dead = true
	}

	public ResetObj(){ 
		
		this.ResetCharacter()
	}

	public InitPartnerVo(owner?, partner_vo?){ 
		
		this.vo = partner_vo
		this.id = partner_vo.partner_id
		this.owner = owner
		this.name = this.vo.name
		this.compress_id = Scene.GetInstance().CompressObjId(SceneBaseType.Partner, owner.id)
		this.is_can_update = true
		if (this.name_board ) {
			this.name_board.SetHp(this.vo.hp, this.vo.maxHp)
		}
		if (this.vo.hide_flag == 1 ) {
			this.SetModelHideFlag(SceneObj.ModelHideFlag.ServerHide, true)
		}
		this.SetHideNameBord(false)
		this.UpdateName()
		this.BindVoEvents()
		
	}

	public LoadInfoFromVo(  ){ 
		
		this.SetMoveSpeed(this.vo.move_speed)
		this.PartnerTextureChange()
		this.SetShowPosition()
	}

	public BindVoEvents(){ 
		
		

		//刷新名字
		let name_func = (oldVar1?, value?) => {
			this.vo.name = value + "的伙伴"
			this.UpdateName()
		}
		this.owner_name_id = this.owner.GetVo().BindOne("name", name_func)
	}

	public UpdateName(){ 
		
		if (this.vo && this.name_board ) {
			this.name_board.SetHpVisible(false)
			let color = "#5be2ff"

			let name = this.owner.InMaskState() && "蒙面人的伙伴" || this.vo.name
			this.name_board.SetName(name, color)
		}
	}

	public UpdateModel( model_name ?){ 
		
		this.CreateClotheSprite(model_name)
		this.UpdateName()
	}

	public GetFollowPos(){ 
		
		let owner_pos = this.owner.real_pos
		let owner_height = this.owner.GetBodyHeight()
		
		this.curr_follow_tar_pos.x = owner_pos.x + this.owner.direction.x * - 200
		this.curr_follow_tar_pos.y = owner_pos.y  + owner_height * 0.3
		
		if (Math.abs(this.owner.direction.x) <= 0.1 ) {
			this.curr_follow_tar_pos.x = owner_pos.x + (this.owner.direction.x > 0 && 1 || -1) * - 40 -100
		} else if (Math.abs(this.owner.direction.x) <= 0.2 ) {
			this.curr_follow_tar_pos.x = owner_pos.x + this.owner.direction.x * - 200 - 100
		}
		
		let grid_x = this.curr_follow_tar_pos.x / SceneObj.GetLogicRealRatio().x,grid_y = this.curr_follow_tar_pos.y / SceneObj.GetLogicRealRatio().y
		if (this.scene_mgr.IsBlockXY(grid_x,grid_y) ) {
			let [x,y] = SourceOperateMove.FindNearestPos(new Vector2(owner_pos.x,owner_pos.y),new Vector2(this.curr_follow_tar_pos.x,this.curr_follow_tar_pos.y)) 
			this.curr_follow_tar_pos.x = x - 100
			this.curr_follow_tar_pos.y = y
		}
		return this.curr_follow_tar_pos
	}


	public SetShowPosition(flag?){ 
		
		if (! this.vo || ! this.owner ) { return }
		let end_pos = this.GetFollowPos()
		let grid_x = end_pos.x / SceneObj.GetLogicRealRatio().x,grid_y = end_pos.y / SceneObj.GetLogicRealRatio().y
		if (this.scene_mgr.IsBlockXY(grid_x, grid_y) ) {
			end_pos = SourceOperateMove.FindNoBlockPos(new Vector2(grid_x, grid_y))
			if (end_pos != null ) {
				end_pos.x = end_pos.x * SceneObj.GetLogicRealRatio().x
				end_pos.y = end_pos.y * SceneObj.GetLogicRealRatio().y
			}else{
				end_pos = this.GetFollowPos()
				end_pos.x = end_pos.x + 0.5
				end_pos.y = end_pos.y + 0.5
			}
		}
		this.SetRealPos(end_pos.x, end_pos.y, true)
		this.SetDirection(this.owner.direction, null, null, true)
		this.DoStand()
	}

	public EnterStateAttack(state_name?){ 
		
		super.EnterStateAttack(state_name)
		
		let cfg = this.movie_cfg
		let t = this.s_attack_state
		let anim_name = ""
		let anim_time = t.last_time
		if (cfg == null || cfg.anim == null ) {
			return
		}
		anim_name = cfg.anim
		this.PlayAction(anim_name)
	}

	public LoadClotheResComplete(){ 
		
		let cfg = Config.PRELOAD_CLIENT_CONFIG.ClientSceneModeCfg
		let scale = cfg && cfg[this.id] && cfg[this.id].size || 1
		this.SetScale(scale)
		super.LoadClotheResComplete()
		
	}

	public SetCanUpdateState(flag?){ 
		
		this.is_can_update = flag
	}

	//设置施法僵直的时间秒数,结束时间
	public SetSkillRigidity(time_len?){ 
		
		this.skill_mgr.SetSkillRigidity(this, time_len)
	}

	//判断角色是否在施法僵直的过程中
	public isInRigidity(){ 
		
		return this.skill_mgr.isInRigidity(this)
	}

	public resetRigidityTime(){ 
		
		this.skill_mgr.resetRigidityTime(this)
	}
}

window["Partner"] = Partner