import { BaseView1 } from "../common/BaseView1"
import { Enum_UILayer, LayerManager } from "../common/LayerManager"
import { GlobalTimerQuest, Util } from "../util/Util"
import { GlobalEventSystem, ClientConfig } from "../util/DeclareGlobalVar"
import { LoginModel } from "./LoginModel"
import { ResManager } from "../common/ResManager"
import { PlatformManager } from "../PlatformManager"
import { LoginStateEvent } from "../common/EventName"
import { LoginManager } from "./LoginManager"
import { SoundManager } from "../common/SoundManager"
export class LoginBgView extends BaseView1 {
    public _img_bg: Laya.Image
    public _bg_group: Laya.Box
    public _gp_effect: Laya.Box
    public _lb_version: Laya.Label
    public down_txt: Laya.Label
    public copy_right: Laya.Label
    public _img_bg1:Laya.Image
    public black_bg:Laya.Image

    InitEvent
    ChangeRoleStatus
    SetCopyRight
    SetData
    public constructor() {
        super()
        this.base_file = "login"
        this.layout_file = "LoginBgView"
        this.layer_value = Enum_UILayer.Top
        this.destroy_imm = true
        this.need_loading_view = false
        this.background_alpha = 0
        this.not_close_by_android_back_key = true
        this.use_background = true
        let local_Util = Util, 
            local_GlobalEventSystem = GlobalEventSystem, 
            login_model = LoginModel.GetInstance(), 
            local_LoginModel = LoginModel, 
            res_mgr = ResManager.GetInstance(), 
            local_plat_mgr = PlatformManager.GetInstance(), 
            local_LoginStateEvent = LoginStateEvent, 
            local_LoginManager_ins = LoginManager.GetInstance()

        this.load_callback = () => {

            this._img_bg = this.GetChildByName("_img_bg")
            this._bg_group = this.GetChildByName("_bg_group")
            this._gp_effect = this.GetChildByName("_gp_effect")
            this._lb_version = this.GetChildByName("_lb_version")
            this.down_txt = this.GetChildByName("down_txt")
            this.copy_right = this.GetChildByName("copy_right")
            this._img_bg1 = this.GetChildByName("_img_bg1")
            this.black_bg = this.GetChildByName("black_bg")

            if (local_Util.IsMiniGame()) {
                let version_text = window["version_text"]
                if (version_text) {
                    Laya.stage.setChildIndex(version_text, Laya.stage.numChildren + 1)
                }
            }

            SoundManager.GetInstance().PlaySoundEffect("2_dianji", true, 0)
            this.black_bg.width = LayerManager.GetInstance().stageWidth
            this.black_bg.height = LayerManager.GetInstance().stageHeight

            this.InitEvent()
        }


        let bg_had_load = false
        let protocal_had_load = false
        this.open_callback = function () {
            bg_had_load = false
            protocal_had_load = false
            this.SetData()
        }

        this.destroy_callback = function () {
            local_Util.RemoveVersionText()
            if (local_Util.IsWXGame() || local_Util.IsDouYinGame() || local_Util.IsMeiTuanGame() || local_Util.IsBiLiBiLiGame() || local_Util.IsQQGame() || local_Util.IsBaiduGame()) {
                Laya.loader.clearRes("assets/denglu_bg.jpg")
            }
        }

        this.InitEvent = () => {
            if (PlatformManager.IsEyouEnPlatform()) {
                this.down_txt.visible = false
            }
            // this.copy_right.centerY = 536
            let bg_fun = () => {
                let sdk_name = local_plat_mgr.sdk_name
                if (sdk_name && window[sdk_name] && local_plat_mgr.sdk_login_had_callback == false && ClientConfig.click_bg_can_login_sdk) {
                    local_plat_mgr.LoginBySdkCallbak()
                }
            }
            Util.AddClickEvent(this._img_bg, bg_fun, this)

            Util.AddClickEvent(this._img_bg1, ()=>{
            }, this)

            
            // if (local_Util.GetDeviceOS() == DEVICE_OS.IOS || local_Util.GetDeviceOS() == DEVICE_OS.IOS_APP) {
            //     SoundManager.GetInstance().PlaySceneSound(2001, 0)
            // }
            // let close_func = () => {
            // 	this.Close()
            // }
            // this.BindEvent(local_GlobalEventSystem, EventName.GAME_START, close_func)
            this.BindEvent(LoginManager.GetInstance(), local_LoginStateEvent.OPEN_VIEW, (view_name) => {
                if (view_name == "LoginCreateRoleView" || view_name == "LoginSelectRoleView") {
                    this.ChangeRoleStatus()
                }
            })
            this.BindEvent(LoginManager.GetInstance(), local_LoginStateEvent.OPEN_VIEW, (view_name) => {
                if (view_name == "LoginEnterView" || view_name == "AccountView") {
                    this.SetData()
                }
            })
            // this.copy_right.visible = PlatformManager.IsAiFengGamePlatform()
            this.SetCopyRight()
        }

        this.ChangeRoleStatus = () => {
            this.copy_right.visible = false
            let bg_url = "resource/game/login/texture/ui_Login_bg2.jpg"
            this._img_bg.visible = true
            this._bg_group.visible = false
            res_mgr.SetTexture(this, this._img_bg, bg_url, (texture) => {
                if (texture) {
                    Util.SetLargeScreenImageSize(this._img_bg, texture.textureWidth, texture.textureHeight)
                }
            }, this, true)
        }
        this.SetCopyRight = () => {
            if (ClientConfig && ClientConfig.copy_right && String(ClientConfig.copy_right).trim() != "") {
                this.copy_right.visible = true
                this.copy_right.text = ClientConfig.copy_right
            }
            else {
                this.copy_right.visible = false
            }
        }
        this.SetData = () => {
            let begin_login = () => {
                if (!bg_had_load) {
                    local_Util.RemoveGameStartLoading()
                    bg_had_load = true
                    local_LoginManager_ins.Fire(local_LoginStateEvent.START_LOGIN_MODULE)
                    // if (!protocal_had_load) {
                    res_mgr.LoadProtocalConfigZip()
                    // 	protocal_had_load = true
                    // }
                }
            }
            GlobalTimerQuest.AddDelayQuest(() => {
                if (!this.use_delete_method) {
                    begin_login()
                }
            }, 10)
            let onLoadCallback = async (texture?) => {
                if (local_Util.IsOPPOFastGame()) {
                    window["qg"].loadingComplete({})
                }
                // if (!protocal_had_load) {
                // 	res_mgr.LoadProtocalConfigZip()
                // 	protocal_had_load = true
                // }
                if (texture) {
                    Util.SetLargeScreenImageSize(this._img_bg, texture.textureWidth, texture.textureHeight)
                }
                PlatformManager.GetInstance().NativeLogigBgSuccess()
                begin_login()
            }
            // GlobalTimerQuest.AddDelayQuest(() => {
            // 	if (!protocal_had_load) {
            // 		res_mgr.LoadProtocalConfigZip()
            // 		protocal_had_load = true
            // 	}
            // }, 50)
            if (ClientConfig && ClientConfig.login_bg) {
                this._img_bg.visible = true
                this._bg_group.visible = false
                let bg_url = PlatformManager.GetInstance().GetLoginBgPath()
                res_mgr.SetTexture(this, this._img_bg, bg_url, onLoadCallback, this, true)
            }
            else {
                if (local_Util.IsCanvasRenderMode()) {
                    this._img_bg.visible = true
                    this._bg_group.visible = false
                    let bg_url = "resource/game/scene/dragonBones/denglu/denglu_bg.jpg?v=7"
                    if (PlatformManager.IsEyouEnPlatform()) {
                        if (Util.IsLargeScreenDevice()) {
                            bg_url = "resource/game/scene/dragonBones/denglu/denglu_bg_en.jpg"
                        }
                        else {
                            bg_url = "resource/game/scene/dragonBones/denglu/denglu_bg_en_small.jpg"
                        }
                    }
                    else if (PlatformManager.IsSuyouNativePlatform()) {
                        bg_url = "resource/game/scene/dragonBones/denglu/loading_bg_suyou_ys.jpg"
                    }
                    res_mgr.SetTexture(this, this._img_bg, bg_url, onLoadCallback, this, true)
                }
                else {
                    this._bg_group.visible = true
                    this._img_bg.visible = true
                    if ((local_Util.IsWXGame() || local_Util.IsDouYinGame() || local_Util.IsMeiTuanGame() || local_Util.IsBiLiBiLiGame() || local_Util.IsQQGame() || local_Util.IsBaiduGame()) && window["login_bg"]) {
                        this._img_bg.texture = window["login_bg"].texture
                        onLoadCallback()
                    }
                    else {
                        let bg_url = "resource/game/scene/dragonBones/denglu/denglu_bg.jpg?v=7"
                        if (PlatformManager.IsEyouEnPlatform()) {
                            if (Util.IsLargeScreenDevice()) {
                                bg_url = "resource/game/scene/dragonBones/denglu/denglu_bg_en.jpg"
                            }
                            else {
                                bg_url = "resource/game/scene/dragonBones/denglu/denglu_bg_en_small.jpg"
                            }
                        }
                        else if (PlatformManager.IsSuyouNativePlatform()) {
                            bg_url = "resource/game/scene/dragonBones/denglu/loading_bg_suyou_ys.jpg"
                        }
                        res_mgr.SetTexture(this, this._img_bg, bg_url, onLoadCallback, this, true)
                    }
                    // if (!this._bg_movie) {
                    // 	this._bg_movie = new UIDragonBonesModelClass(this._bg_group, "denglu", { x: 550, y: 1250 }, { scale_x: 1, scale_y: 1 })
                    // }
                }
            }
        }
    }
}
window["LoginBgView"] = LoginBgView