import { GameResPath } from "../util/GameResPath";
import { AtlasUrl, Util } from "../util/Util";
import { BaseItem1 } from "./BaseItem1";
import { BaseItemRenderer } from "./BaseItemRenderer";
import { InstructionSmallItem } from "./InstructionSmallItem";
import { ResManager } from "./ResManager";

export class InstructionItem extends BaseItem1 {
	private _item_list = [];
	data
	parent
	Hight
	constructor(parent) {
		super(parent);
		this.parent=parent
		this.base_file = "common"
		this.layout_file = "InstructionItem"

		this.load_callback = () => {
			// this._title_lb.style.fontSize = 24
			this._title_lb.style.fontSize=22
			this._title_lb.style.color="#763320"
			this._title_lb.style.stroke=2
			this._title_lb.style.strokeColor="#dfd1cd"
			this._title_lb.style.bold=true
			this.display_obj.height=50
			// ResManager.GetInstance().SetOutsideImageSprite(this, this._Image1, GameResPath.GetIcon("common2", "ui_task_08"), true)
			this.dataChanged()

		}

		// this.skinName = "resource/game/common/exml/InstructionItemExml.exml"\
		// this.Load()
	}

	public createChildren() {
		super.createChildren()
	}

	protected dataChanged(): void {

		// if () {
			let list = this.data;
			this._title_gp.visible = list.item_title != undefined;
			this._title_gp.visible = list.item_title != undefined;
			if (this._title_gp.visible)
				this._title_lb.width = 150
			this._title_lb.innerHTML = Util.StrToHTML(list.item_title);
			let item: InstructionSmallItem;
			let info;
			let index = 0;
			for (let i: number = 0; i < list.item_content.length; i++) {
				item = this._item_list[i];
				info = list.item_content[i];
				if (!item) {
					item = new InstructionSmallItem(this._content_gp);
					item.SetInstructionitem(this)
					item.Load();
					this._item_list.push(item);
				}
				item.SetVisible(true);
				// item.includeInLayout = true;
				item.setData(info);
				index++;
				// item.ExcuteCallback(()=>{
				// 	this.display_obj.height+=this._content_gp.space+item._lb_desc.contextHeight
				// 	this.parent.refresh()
				// })
			}
			if (this._item_list.length > index) {
				for (let i: number = index; i < this._item_list.length; i++) {
					item = this._item_list[i];
					item.SetVisible(false)
					// item.visible = false;
					// item.includeInLayout = false;
				}
			}
		// }
	}
	//刷新高度，以及父物体布局	
	public Refresh_height(html_obj?){
		if(!html_obj.contextHeight) return	
		this.display_obj.height+=this._content_gp.space+html_obj.contextHeight
		this.parent.refresh()
	}
	public SetData(info?){
		this.data=info
	}
	public DeleteMe(): void {
		let item: InstructionSmallItem;
		for (let key in this._item_list) {
			item = this._item_list[key];
			item.DeleteMe()
		}
		this._item_list = [];
		this.parent=null
		// ResManager.getInstance().DestroyAllReferenceRes(this.hashCode);
		super.DeleteMe();
	}

	_Group1: Laya.VBox
	_title_gp: Laya.Box	
	_Image1: Laya.Image
	_Image2: Laya.Image
	_title_lb: Laya.HTMLDivElement
	_content_gp: Laya.VBox
	public GetComponents() {
		[
			this._Group1,
			this._title_gp,
			this._Image1,
			this._Image2,
			this._title_lb,
			this._content_gp,
		]
			= this.GetChildrenByNames([

				"_Group1",
				"_title_gp",
				"_Image1",
				"_Image2",
				"_title_lb",
				"_content_gp",
			])

	}
}
window["InstructionItem"] = InstructionItem