// TypeScript file
export class RoleManager extends EventDispatcher {
    public static Instance: RoleManager;
    mainRoleInfo:MainRoleVo;
    change_career_time = 0;
    GetMainRoleVo;
    GetMainRoleId;
    GetMainRoleLevel
    SetHeadImgList;
    UpdateHeadImgList;
    HaveActiviteThisHead;
    IsActiviteByTypeId;
    GetMainRoleSex
    GetMainRoleCareer
    role_platform_times_data = {};
    public constructor() {
        super();
        this.mainRoleInfo = new MainRoleVo();
        let local_GlobalEventSystem = GlobalEventSystem, UPDATE_ROLE_HEAD_ICON = EventName.UPDATE_ROLE_HEAD_ICON, head_img_list_, config_picture_;
        this.GetMainRoleVo = (): MainRoleVo => {
            return this.mainRoleInfo;
            
        };
        this.GetMainRoleId = () => {
            return this.mainRoleInfo.role_id;
        };
        //主角头像列表
        this.SetHeadImgList = (list) => {
            head_img_list_ = list;
            local_GlobalEventSystem.Fire(UPDATE_ROLE_HEAD_ICON);
        };
        //主角头像列表
        this.UpdateHeadImgList = (img_id) => {
            if (!head_img_list_) {
                head_img_list_ = [];
            }
            let find = false;
            for (let vo of head_img_list_) {
                if (vo == img_id) {
                    find = true;
                    break;
                }
            }
            if (!find) {
                head_img_list_.push(img_id);
            }
            local_GlobalEventSystem.Fire(UPDATE_ROLE_HEAD_ICON);
        };
        //该头像是否激活
        this.HaveActiviteThisHead = (id) => {
            let activite = 0;
            if (head_img_list_) {
                for (let vo of head_img_list_) {
                    if (vo == id) {
                        activite = 1;
                        break;
                    }
                }
            }
            if (id == 1 || id == 3) {
                activite = 1;
            }
            return activite;
        };
        this.IsActiviteByTypeId = (type_id) => {
            let is_active = false;
            config_picture_ = Config.PRELOAD_SERVER_CONFIG.config_picture;
            if (config_picture_) {
                let cfg;
                let list;
                let id;
                for (let key in config_picture_) {
                    cfg = config_picture_[key];
                    list = JSON.parse(cfg.cost);
                    if (list && list.length > 0) {
                        for (let vo of list) {
                            if (vo[0] == "goods" && vo[1] && vo[1][0]) {
                                if (vo[1][0][1] == type_id) {
                                    id = key;
                                    break;
                                }
                            }
                        }
                    }
                }
                if (id) {
                    is_active = this.HaveActiviteThisHead(id) == 1 ? true : false;
                }
            }
            return is_active;
        };
        this.GetMainRoleSex = () =>{
            return this.mainRoleInfo.sex
        }
        this.GetMainRoleLevel = () =>{
            return this.mainRoleInfo.level
        }
        this.GetMainRoleCareer = () =>{
            return this.mainRoleInfo.career
        }
    }
    public static GetInstance() {
        if (!RoleManager.Instance) {
            RoleManager.Instance = new RoleManager();
        }
        return RoleManager.Instance;
    }
}
window["RoleManager"] = RoleManager