	public SetAlpha(num) {
		this.gp_award.alpha = num
	}
	public DeleteMe() {
		if (this.gp_award)
			Laya.Tween.clearAll(this.gp_award)
		if (this.award_item) {
			this.award_item.DeleteMe()
		}
		this.award_item = null
		super.DeleteMe()
	}

