		this.GetExploreLayerReward = (layer?, config_guild_dun_level_reward?) => {
			let cfg = config_guild_dun_level_reward
			if (!cfg) {
				return {}
			}
			let list = []
			for (let key in cfg) {

				// [ts2lua]cfg下标访问可能不正确
				if (cfg[key].level != layer) {
					break
				}
				// [ts2lua]cfg下标访问可能不正确
				table.insert(list, cfg[key])
			}
			//list:sort((a?, b?) => {
			//return a.world_lv - b.world_lv
			//}
			//)
			table.sort(list, (a?, b?) => {
				return a.world_lv - b.world_lv
			})
			let world_lv = role_mgr.GetMainRoleVo().worldLv
			for (let _tmpi in list) {
				var info = list[_tmpi]
				if (world_lv < info.world_lv) {
					return local_Erlang.Parse(info.preview_reward)
				}
			}
			return {}
		}

		this.GetExploreGiftData = (dun_score?, config_guild_dun_score_reward?) => {
			let cfg = config_guild_dun_score_reward
			if (!cfg) {
				return [0, 0, 0]
			}
			let data = null
			let index = 0
			for (let key in cfg) {

				// [ts2lua]cfg下标访问可能不正确
				let info = cfg[key]
				let over = info.score > dun_score
				if (over) {
					// [ts2lua]lua中0和空字符串也是true，此处data需要确认
					return [(data && (data.score) || (0)), info.score, index]
				}
				data = info
				index = index + 1
			}
			return [data.score, data.score + 1, index]
		}

