	public constructor(parent?, career?, sex?, clothe_res_id?, weapon_res_id?, weapon_clothe_id?, type?, rotate?, action_name_list?, can_rotate?, scale?, position?, fashion_model_id?, texture_id?, action_delta?, free_param?, ignore_param?, skill_id?, load_call_back?, wing_id?, image_id?, head_wear_id?, head_clothe_id?, footmark_id?,show_gray?,particle_scale?,hair_id?,hallows_id?, mask_id?,skin_renderQueue?, custom_sorting_order?, camera_rt_data?){
		super() 
		this.parent = parent
		this.particle_list = []
		this.pos_x = 0
		this.playIndex = 0
		this.custom_speed = 1
		this.force_add = true
		// this.rotateX = -SceneRotateX
		this.SetData(parent, career, sex, clothe_res_id, weapon_res_id, weapon_clothe_id, type, rotate, action_name_list, can_rotate, scale, position, fashion_model_id, texture_id, action_delta, free_param, ignore_param, skill_id, load_call_back, wing_id, image_id, head_wear_id, head_clothe_id, footmark_id,show_gray,particle_scale,hair_id,hallows_id, mask_id,skin_renderQueue, custom_sorting_order, camera_rt_data)
		this.AddEvents()
	}
	public DeleteMe(){ 
		
		this.ClearActionTimerList()
		this.RemoveAllParticle()
		if (this.clothe ) {
			this.clothe.DeleteMe()
			this.clothe = null
		}
		if (this.head_clothe ) {
			this.head_clothe.DeleteMe()
			this.head_clothe = null
		}
		if (! Util.IsNull(this.default_headWear_go) && this.default_headWear_abName ) {
			// ResManager.GetInstance().AddObjToPool(this, this.default_headWear_abName, this.default_headWear_abName, this.default_headWear_go)
			this.default_headWear_go = null
			this.default_headWear_abName = null
		}
		if (this.head_wear ) {
			this.head_wear.DeleteMe()
			this.head_wear = null
		}
		if (this.weapon_clothe_obj ) {
			this.weapon_clothe_obj.DeleteMe()
			this.weapon_clothe_obj = null
			this.weapon_clothe_id = null
		}

		if (this.hair_clothe ) {
			this.hair_clothe.DeleteMe()
			this.hair_clothe = null
		}

		
		if (this.horse_gameObject ) {
			this.horse_gameObject.destroy()
		} else if (this.gameObject ) {
			this.gameObject.destroy()
		}

		this.horse_gameObject = null
		this.horse_transform = null
		this.gameObject = null
		this.form = null

		if(this.cameraObject)
		{
			if (this.renderTexture ) {
				// this.camera.targetTexture = null
				this.renderTexture.destroy()
				// destroy(this.renderTexture)
				// destroy(this.cameraObj)
				// this.cameraObj = null
				this.renderTexture = null
			}
	
			this.cameraObject.destroy()
			this.cameraObject = null
		}

		if (this.weapon_event_id ) {
			GlobalEventSystem.UnBind(this.weapon_event_id)
			this.weapon_event_id = null
		}
		if (this.fahion_event_id ) {
			GlobalEventSystem.UnBind(this.fahion_event_id)
			this.fahion_event_id = null
		}
		if (this.cloth_event_id ) {
			GlobalEventSystem.UnBind(this.cloth_event_id)
			this.cloth_event_id = null
		}
		// if (this.foot_move_id ) {
		// 	GlobalTimerQuest.CancelQuest(this.foot_move_id)
		// 	this.foot_move_id = null
		// }
		if (this.talk_board ) {
			this.talk_board.DeleteMe()
			this.talk_board = null
		}
		this.ClearTimer()
		super.DeleteMe()
	}

