	public CheckAllLoadCallback(){ 
		if (Util.TableSize(this.is_loading_flag, true) <= 0 ) {
			if (this.load_call_back ) {
				let local_load_call_back = this.load_call_back
				this.load_call_back = null
				let delaycallback = () => {
					if (this.use_delete_method ) { return }
					local_load_call_back(this.gameObject)
				}
				this.timer = setTimeout(delaycallback, 0.01) //延迟一下 避免回调后设置overrideSorting 失效
			}
		}
	}

	public CheckIsLoading(){ 
		
		if (Util.TableSize(this.is_loading_flag) > 0 ) {
			return true
		}
	}

