	//创建武器
	public async CreateWeapon(_type?, weapon_res_id?, career?, weapon_clothe?){ 
		
		if (weapon_res_id ) {
			let[abName, weapon_attach_list, weapon_res_list] = GameResPath.GetWeaponRes(_type, weapon_res_id , career, true)
			var load_call_back =(objs)=> {
				if (this.form ) {
					if (this.use_delete_method) {
						if (objs) {
							for (let i = 0; i < objs.length; i++) {
								var obj = objs[i]
								obj.destroy()
							}
						}
						return
					}
					if (weapon_attach_list && objs ) {
						let bone_go = null
						for (let k = 0; k < weapon_attach_list.length; k++) {
							var boneName = weapon_attach_list[k]
							bone_go = Util.FindBone(this.form.owner, boneName)
							if (bone_go ) {
								if (!objs[k]) {
									console.warn("!!!!!!!!!!!!can ! load weapon resName = ", weapon_res_list[k])
									return
								}
								let go = objs[k]
								// go.setParent(bone_go)
								bone_go.addChild(go)
							}
						}
					}
				}
			}
			if (this.form && abName && weapon_res_list ) {
				let objs = []
				let length = weapon_res_list.length
				let call_back = (obj) =>{
					objs.push(obj)
					if(length == objs.length){
						load_call_back(objs)
					}
				}
				for (let i in weapon_res_list) {
					let full_url = GameResPath.GetObjectPath("weapon", weapon_res_list[i])
					// var entity = await window["EngineFactory"].createPrefab(full_url)
					// call_back(entity)
					ResManager.GetInstance().CreatePrefab(this.hashCode, full_url, call_back)
				}
			}
		}
	}

