	public AddEvents(){ 
		
		if (this.can_rotate ) {

			var touch_begin =(e: Laya.Event)=> {
				this.pos_x = e.stageX
				Laya.stage.on(Laya.Event.MOUSE_MOVE, this, draging)
				Laya.stage.on(Laya.Event.MOUSE_UP, this, touch_end)
				Laya.stage.on(Laya.Event.MOUSE_OUT, this, touch_end)
			}
			var draging =(e: Laya.Event)=> {
				this.OnDragging(e.stageX)
			}
			var touch_end =(e: Laya.Event)=> {
				Laya.stage.off(Laya.Event.MOUSE_MOVE, this, draging)
				Laya.stage.off(Laya.Event.MOUSE_UP, this, touch_end)
				Laya.stage.off(Laya.Event.MOUSE_OUT, this, touch_end)
			}
			this.parent.on(Laya.Event.MOUSE_DOWN, this, touch_begin)
		}

	}

	public OnDragging(pos_x?){ 
		
		if (pos_x && this.pos_x ) {
			let delta_x = pos_x - this.pos_x
			if (this.form) {
				if (delta_x > 0 ) {
					this.rotate += 5
				}else{
					this.rotate -= 5
				}
				if (this.horse_transform ) {
					this.horse_transform.localRotationEulerY = this.rotate
				}else{
					this.form.localRotationEulerY = this.rotate
				}
				this.pos_x = pos_x
			}
		}else{
			console.log("//-UIModelClass3d//OnDragging-pos_x-:", pos_x)
		}
	}

