import { Util } from "../util/Util";
import { BaseItem1 } from "./BaseItem1";

export class InstructionSmallItem extends BaseItem1 {
    public _lb_desc: Laya.HTMLDivElement
    private _content: string;
    instruction_item  //
    constructor(parent) {
        super(parent);
        this.base_file = "common";
        this.layout_file = "InstructionSmallItem";
        this.is_load_res = false
        this.load_callback = () => {
            this._lb_desc.style.fontSize = 22
            this._lb_desc.style.color = "#80372C"
            this._lb_desc.style.valign = "top"
            this._lb_desc.style.width = 500
            this.initView()
        }

    }

    public setData(content): void {
        this._content = content;
        this.initView();
    }

    private initView(): void {
        if(!this._lb_desc){
            return 
        }   
        this._lb_desc.innerHTML = Util.StrToHTML(this._content);
        this.instruction_item.Refresh_height(this._lb_desc)
    }

    public SetInstructionitem(item?){
        this.instruction_item=item
    }
    public DeleteMe(){
        if(this.instruction_item){
            this.instruction_item=null
        }
        super.DeleteMe()
    }
    public GetComponents() {
        [
            this._lb_desc,
        ]
            = this.GetChildrenByNames([

                "_lb_desc",
            ])
    }
}
window["InstructionSmallItem"] = InstructionSmallItem