import { BaseView1 } from "../common/BaseView1"
import { EventName } from "../common/EventName"
import { Enum_UILayer } from "../common/LayerManager"
import { ResManager } from "../common/ResManager"
import { LuaSoundManager } from "../common/SoundManager"
import { CheatModel } from "../commonModel/CheatModel"
import { GoodsModel } from "../commonModel/GoodsModel"
import { GuildModel, GuildEvent, GuildDefine } from "../commonModel/GuildModel"
import { PlatformManager } from "../PlatformManager"
import { RoleManager } from "../role/RoleManager"
import { Message } from "../sysinfo/SysInfoController"
import { ColorUtil, Enum_ColorUtil_Dark } from "../util/ColorUtil"
import { ErlangParser } from "../util/ErlangParser"
import { Util, HtmlColorTxt, NotEnougnDiamond } from "../util/Util"

export class GuildBuildView extends BaseView1 {
	CheckBindCond
	CheckDiamond
	CheckInput
	Clear
	InitEvent
	InptextDisplay
	LoadSuccess
	UpdateCostData
	UpdateCostDataBind
	UpdateLvData
	CheckInputTip
	LayoutGroup2

	click_bg_toClose
	destroy_callback
	destroy_imm
	is_center
	show_open_movie
	use_background


	public constructor() {
		super()


		this.base_file = "guild"
		this.layout_file = "GuildBuildView"
		this.layer_value = Enum_UILayer.Activity
		this.is_center = true
		this.use_background = true
		this.click_bg_toClose = true
		this.show_open_movie = true
		this.destroy_imm = true
		let model = GuildModel.GetInstance()
		let _bind_enough = false
		let _diamond_enough = false
		let local_GuildEvent = GuildEvent
		let local_PlatformManager = PlatformManager.GetInstance()
		let local_RoleManager = RoleManager.GetInstance()
		let local_GoodsModel = GoodsModel.GetInstance()
		let local_ResManager = ResManager.GetInstance()
		let local_Message = Message
		this.load_callback = () => {

			this.LoadSuccess()
			this.InitEvent()
		}

		this.destroy_callback = () => {
			this.Clear()
		}

		this.Clear = () => {

		}

		this.LoadSuccess = () => {
			this.UpdateCostData()
			this.UpdateCostDataBind()
			this.UpdateLvData()


			this.LayoutGroup2(this._Group2)
			this.CheckInputTip()
		}

		this.InitEvent = () => {
			Util.AddClickEvent(this._btn_diamond, () => {
				if (!this.CheckInput() || !this.CheckDiamond()) {
					return
				}
				let create_func = () => {
					// var callback = () => {
					model.Fire(local_GuildEvent.REQUEST_PROTO, 40004, "ls", 1, this.textDisplay.text)
					// }
					// HttpMaskWord(this.textDisplay.text,callback,true)
				}

				if (Util.IsQQGame() && local_PlatformManager.is_wx_alpha) {
					local_PlatformManager.MsgSecCheck(this.textDisplay.text, create_func)
				} else {
					create_func()
				}
				this.Close()
			}
				, this, true)
			Util.AddClickEvent(this._btn_bind, () => {
				if (!this.CheckInput() || !this.CheckBindCond()) {
					return
				}
				model.Fire(local_GuildEvent.REQUEST_PROTO, 40004, "ls", 2, this.textDisplay.text)
				this.Close()
			}
				, this, true)
			Util.AddClickEvent(this._btn_close, () => {
				this.Close()
			}
				, this, true, null, null, null, null, LuaSoundManager.SOUND_UI.CLOSE)

			this.textDisplay.on(Laya.Event.INPUT, this, (text?) => {
				if (this.textDisplay.text.length > 6) {
					Message.show("公会名不能超过6个字")
				}

				this.CheckInputTip()
			})

			this.BindVar(local_RoleManager.GetMainRoleVo(), "jin", () => {
				this.UpdateCostData()
			}
			)
			this.BindVar(local_RoleManager.GetMainRoleVo(), "jinLock", () => {
				this.UpdateCostDataBind()
			}
			)
			this.BindEvent(local_RoleManager.GetMainRoleVo(), EventName.CHANGE_LEVEL, () => {
				this.UpdateLvData()
			}
			)
		}

		this.UpdateLvData = () => {
			let role_lv = local_RoleManager.GetMainRoleVo().level
			// [ts2lua]lua中0和空字符串也是true，此处role_lv < GuildDefine.GUILD_BUILD_LV需要确认
			let color = (role_lv < GuildDefine.GUILD_BUILD_LV && (Enum_ColorUtil_Dark.RED) || (Enum_ColorUtil_Dark.ORANGE))
			// if (PlatformMgr.GetInstance().IsEyouThPlatform() ) {
			// 	this._lb_level.text = HtmlColorTxt("(Lv." + GuildDefine.GUILD_BUILD_LV + ")", color)
			// }else{
			this._lb_level.color = ColorUtil.GetReplaceChar(color)
			this._lb_level.text = `（${GuildDefine.GUILD_BUILD_LV}级）`  //Util.StrToHTML(HtmlColorTxt("(" + GuildDefine.GUILD_BUILD_LV + "级)", color))""
			// }
		}

		this.UpdateCostData = () => {
			if (this.use_delete_method) {
				return
			}
			let cdata = model.GetGuildKVCfg(13)
			cdata = JSON.parse(cdata)[0]
			this._lb_cost.text = cdata[2]
			let own = local_GoodsModel.GetRoleSpecGoodsNum(cdata[0], cdata[1])
			_diamond_enough = own >= Number(cdata[2])
			let type_id = local_GoodsModel.GetMappingTypeId(cdata[0], cdata[1])
			local_ResManager.SetOutsideImageSprite(this, this._img_cost, GoodsModel.GetGoodsPath(type_id[0]))
		}

		this.UpdateCostDataBind = () => {
			if (this.use_delete_method) {
				return
			}
			let ndata = model.GetGuildKVCfg(12)
			ndata = JSON.parse(ndata)[0]
			this._lb_cost_bind.text = ndata[2]
			let own = local_GoodsModel.GetRoleSpecGoodsNum(ndata[0], ndata[1])
			_bind_enough = own >= Number(ndata[2])
			let bind_type_id = local_GoodsModel.GetMappingTypeId(ndata[0], ndata[1])
			local_ResManager.SetOutsideImageSprite(this, this._img_cost_bind, GoodsModel.GetGoodsPath(bind_type_id[0]))
		}

		this.CheckDiamond = () => {
			if (!_diamond_enough) {
				NotEnougnDiamond()
				return false
			}
			return true
		}

		this.CheckBindCond = () => {
			if (local_RoleManager.GetMainRoleVo().level < GuildDefine.GUILD_BUILD_LV) {
				local_Message.show("等级不足")
				return false
			}
			if (!_bind_enough) {
				local_Message.show("绑钻不足")
				return false
			}
			return true
		}

		this.CheckInput = () => {
			let input = this.textDisplay.text
			if (this.textDisplay.text.length > 6) {
				local_Message.show("公会名不能超过6个字")
				return false
			}
			if (this.textDisplay.text.length < 1) {
				local_Message.show("公会名不能为空")
				return false
			}
			return true
		}


		this.CheckInputTip = () => {
			this.Placeholder.visible = this.textDisplay.text.length == 0;
		}

		this.LayoutGroup2 = (groups) => {
			let len = groups.numChildren
			let init_y = this._Label2.y
			let contentWidth: number = 0
			let i, child

			for (i = 0; i < len; i++) {
				child = groups.getChildAt(i)
				if (child) {
					child.y = init_y
					contentWidth += child.width;
				}
			}

			let start_x = (groups.width - contentWidth) / 2
			for (i = 0; i < len; i++) {
				child = groups.getChildAt(i)
				if (child) {
					child.x = start_x
					start_x += child.width
				}
			}
		}


	}


	_Image11111: Laya.Image
	_Image2: Laya.Image
	_Image3: Laya.Image
	_lb_win_name: Laya.Label
	_text_input: Laya.Box
	_image1: Laya.Image
	Placeholder: Laya.Label
	textDisplay: Laya.TextInput
	_btn_bind: Laya.Box
	_Image111: Laya.Image
	labelDisplay1: Laya.Label
	_btn_diamond: Laya.Box
	_Image11: Laya.Image
	labelDisplay: Laya.Label
	_btn_close: Laya.Box
	_Image1111: Laya.Image
	_Group2: Laya.Box
	_Label2: Laya.Label
	_lb_cost: Laya.Label
	_img_cost: Laya.Image
	_Label3: Laya.Label
	_lb_cost_bind: Laya.Label
	_img_cost_bind: Laya.Image
	_lb_level: Laya.Label
	public GetComponents() {
		[
			this._Image11111,
			this._Image2,
			this._Image3,
			this._lb_win_name,
			this._text_input,
			this._image1,
			this.Placeholder,
			this.textDisplay,
			this._btn_bind,
			this._Image111,
			this.labelDisplay1,
			this._btn_diamond,
			this._Image11,
			this.labelDisplay,
			this._btn_close,
			this._Image1111,
			this._Group2,
			this._Label2,
			this._lb_cost,
			this._img_cost,
			this._Label3,
			this._lb_cost_bind,
			this._img_cost_bind,
			this._lb_level,
		]
			= this.GetChildrenByNames([

				"_Image11111",
				"_Image2",
				"_Image3",
				"_lb_win_name",
				"_text_input",
				"_image1",
				"Placeholder",
				"textDisplay",
				"_btn_bind",
				"_Image111",
				"labelDisplay1",
				"_btn_diamond",
				"_Image11",
				"labelDisplay",
				"_btn_close",
				"_Image1111",
				"_Group2",
				"_Label2",
				"_lb_cost",
				"_img_cost",
				"_Label3",
				"_lb_cost_bind",
				"_img_cost_bind",
				"_lb_level",
			])
	}
}
window["GuildBuildView"]=GuildBuildView