import { BaseClass } from "../../common/BaseClass";
import { WorldArtFontManager, SceneFontType } from "./WorldArtFontManager";
import { LayerManager, Enum_UILayer } from "../../common/LayerManager";
import { ResManager } from "../../common/ResManager";
import { Config } from "../../common/Config";
import { Scene } from "../Scene";
import { Vector2 } from "../../util/Vector2";
import { GameMath } from "../../util/GameMath";
export abstract class WorldArtFont extends BaseClass {
	private _parent: Laya.Box;
	protected fontMgr: WorldArtFontManager;
	protected bitmapText: Laya.Label;
	protected is_tween: boolean = false;
	protected font_name: string;
	protected time_id_list
	protected tw:Laya.Tween
	constructor(protected type: SceneFontType) {
		super();
		let self = this;
		self._parent = LayerManager.GetInstance().GetUILayer(Enum_UILayer.NameBoard);
		self.fontMgr = WorldArtFontManager.GetInstance();
		self.font_name = self.fontMgr.SceneFontCfg[self.type].name;
		self.bitmapText = new Laya.Label()
		ResManager.GetInstance().LoadFont(this, self.font_name, self.bitmapText, 14)
		self._parent.addChild(self.bitmapText);
		self.time_id_list = []
		self.Reset();
	}
	public GetType(): SceneFontType {
		return this.type;
	}
	public GetFontName(): string {
		return this.font_name;
	}
	public Reset() {
		if(this.time_id_list.length > 0){
			for(let id of this.time_id_list){
				clearTimeout(id)
			}
			this.time_id_list.length = 0
		}
		if(this.bitmapText){
			Laya.Tween.clearAll(this.bitmapText)
		}

		this.SetVisible(false);
	}
	public TextObjIsNull() {
		return this.bitmapText == null;
	}
	public SetVisible(visible: boolean) {
		if (this.bitmapText) {
			this.bitmapText.alpha = visible ? 1 : 0;
			this.bitmapText.visible = visible;
		}
		// if(visible)
		// {
		//	 if(!this.bitmapText.parent)
		//	 {
		//		 this._parent.addChild(this.bitmapText)
		//	 }
		// }else
		// {
		//	 if(this.bitmapText.parent)
		//	 {
		//		 this.bitmapText.parent.removeChild(this.bitmapText)
		//	 }
		// }
		// this.bitmapText.visible = visible;
	}
	public GetActionStatus() {
		return this.is_tween;
	}
	public DeleteMe() {
		super.DeleteMe();
		this.Reset();
		if(this.bitmapText)
			this.bitmapText.destroy()
		this.bitmapText = null;
	}
	/**
	 * [现仅限于tween参数固定,没有额外计算]
	 * @param start_pos 初始位置
	 */
	public PublicAction(x?, y?) {
		let self = this
		self.is_tween = true
		self.bitmapText.x = x || 0
		self.bitmapText.y = y || 0
		
		let cfg = Config.PRELOAD_CLIENT_CONFIG.ConfigOtherFightInfo.scene_fnt_cfg[self.font_name]
		let total_count = cfg.length

		let compolete_func = () =>{
			self.is_tween = false
			self.fontMgr.PushFont(self)
		}

		let laya_tween:any = Laya.Tween
		for (let v of cfg) {
			let parms = {}
			for (let key in v.parms) {
				parms[key] = key != "x" && key != "y" ? v.parms[key] : v.parms[key] + self.bitmapText[key]
			}
			if(Number(v) == total_count - 1)
			{
				laya_tween = laya_tween.to(self.bitmapText, parms, v.time, Laya.Ease.linearNone, Laya.Handler.create(this, compolete_func))
			}
			else{
				laya_tween = laya_tween.to(self.bitmapText, parms, v.time, Laya.Ease.linearNone)
			}
		}
	}
	protected abstract StartAction(x?, y?);
	abstract ShowText(str: string, x?, y?, dir_num?);
}

//通用飘字
export class SceneNormalFont extends WorldArtFont {
	private _move_dir = new Vector2();
	protected StartAction(x?, y?, dir?) {
		let self = this;
		self.is_tween = true;
		// let role = Scene.GetInstance().GetMainRole();
		// if (!role) return;
		// let dir_num = role.GetDirectionNumber()
		self._move_dir = dir//GameMath.DirNumToVector(dir, self._move_dir);
		self.bitmapText.x = x;
		self.bitmapText.y = y;
		let cfg = WorldArtFontManager.GetInstance().damage_info;
		self.bitmapText.alpha = cfg[0];
		self.bitmapText.scaleX = cfg[1];
		self.bitmapText.scaleY = cfg[1];
		y += self._move_dir.y * cfg[2];
		x += self._move_dir.x * cfg[2];
		
		// let tw = Laya.Pool.getItemByClass("tween", Laya.Tween)
		// tw.to(self.bitmapText, { y: y, x: x, scaleX: 0.8, scaleY: 0.8, alpha: 1 }, cfg[3], Laya.Ease.linearNone, Laya.Handler.create(this, ()=>{
		// 	let time_id = setTimeout(() => {
		// 		console.warn("%%%%3333", this.hashCode, this.bitmapText["$_GID"])
		// 		tw.to(self.bitmapText,{ x: x - self._move_dir.x * cfg[5], alpha: 0 }, cfg[6], Laya.Ease.linearNone, Laya.Handler.create(this, ()=>{
		// 			self.is_tween = false;
		// 			self.fontMgr.PushFont(self);
		// 			console.warn("%%%%4444", this.hashCode, this.bitmapText["$_GID"])
		// 		}))
		// 	}, cfg[4]);
		// 	console.warn("%%%%2222", this.hashCode, this.bitmapText["$_GID"])
		// 	this.time_id_list.push(time_id)
		// }))
		Laya.Tween.to(self.bitmapText, { y: y, x: x, scaleX: 0.8, scaleY: 0.8, alpha: 1 }, cfg[3], Laya.Ease.linearNone, Laya.Handler.create(this, ()=>{
			Laya.Tween.to(self.bitmapText,{ x: x - self._move_dir.x * cfg[5], alpha: 0 }, cfg[6], Laya.Ease.linearNone, Laya.Handler.create(this, ()=>{
				self.is_tween = false;
				self.fontMgr.PushFont(self);
			}), cfg[4])
		}))
	}
	public ShowText(str: string, x?, y?, dir?) {
		let self = this;
		self.bitmapText.text = str;
		self.bitmapText.anchorX = self.bitmapText.anchorY = 0.5;
		self.StartAction(x, y, dir);
	}
}

