import { BaseView1 } from "../common/BaseView1"
import { Enum_UILayer } from "../common/LayerManager"
import { LoopScrowViewMgr } from "../common/LoopScrowViewMgr"
import { ResManager } from "../common/ResManager"
import { GuildActivityModel } from "../commonModel/GuildActivityModel"
import { GameResPath } from "../util/GameResPath"
import { TimeUtil } from "../util/TimeUtil"
import { SetSizeDeltaX, SetLocalPositionY, Util, GlobalTimerQuest } from "../util/Util"

export class EveningResultView extends BaseView1 {
	Content
	_btn_right
	_gp_fly
	_gp_reward_con
	_gp_tip_1
	_gp_victory
	_img_reward_bg
	_lb_left_time
	_sc_reward
	back_login_toClose
	background_alpha
	click_bg_toClose
	destroy_callback
	destroy_imm
	end_time
	is_center
	model
	percentHeight
	percentWidth
	reward_arr
	time_id
	use_background


	public constructor() {
		super()

		this.model = GuildActivityModel.GetInstance();
		this.base_file = "evening"
		this.layout_file = "EveningResultView"
		// this.dependent_res = ["dungeonCommon"]
		this.layer_value = Enum_UILayer.Activity
		this.is_center = true
		this.use_background = true
		this.background_alpha = 1
		this.click_bg_toClose = true
		this.destroy_imm = true
		this.back_login_toClose = true
		this.percentWidth = 100
		this.percentHeight = 100
		this.load_callback = () => {

			this.LoadSuccess()
		}

		this.destroy_callback = () => {
			this.Clear()
		}
	}

	public LoadSuccess() {

		this.InitView()
		this.InitEvent()
	}

	public Clear() {

		this.CancelTime()
		this.model.SetResultInfo(null)
		if (this.reward_arr) {
			this.reward_arr.DeleteMe()
			this.reward_arr = null
		}
	}

	public InitView() {

		ResManager.GetInstance().SetOutsideImageSprite(this, this._img_reward_bg, GameResPath.GetIcon("common4", "uijs_038"))
		// this.AddUIEffect2("ui_victory_glow", this._gp_fly, null, {x=1.25, y=1.25}, false, null, null, null, true)
		// this.AddUIEffect2("ui_victory_glow1", this._gp_victory, null, {x=1.4, y=1.4}, true, false, false, false, false, true)
		let data = this.model.GetResultInfo()
		if (!data) {
			return
		}
		// this.reward_arr = eui. new ArrayCollection()
		// this._dgp_reward.dataProvider = this.reward_arr
		// this._dgp_reward.itemRenderer = AwardItemRenderer
		// this._dgp_reward.itemRendererSkinName = AwardItemRendererSkin

		this.reward_arr = new LoopScrowViewMgr()
		//this.reward_arr.SetData(this.Content, AwardItemRenderer, {}, this._sc_reward)

		if ((data && data.reward_list) && data.reward_list.length > 0) {
			let len = data.reward_list.length
			let index = Math.ceil(len / 4)
			if (index > 3) {
				index = 3
			}
			if (index == 0) {
				index = 1
			}
			let layout = null
			if (index == 1) {
				// layout = eui. new HorizontalLayout()
				// layout.gap = 15
				// layout.horizontalAlign = Laya.HorizontalAlign.CENTER
				// this._sc_reward.width = 108 * len + len - 1 * 15
				SetSizeDeltaX(this._sc_reward, 108 * len + len - 1 * 15)
			} else {
				// layout = eui. new TileLayout()
				// layout.verticalGap = 15
				// layout.horizontalGap = 15
				// layout.horizontalAlign = Laya.HorizontalAlign.LEFT
				// layout.verticalAlign = Laya.VerticalAlign.TOP
			}
			// this._dgp_reward.layout = layout
			// this._gp_reward_con.height = index * 108 + index - 1 * 13 + 32 + 20
			SetSizeDeltaX(this._gp_reward_con, index * 108 + index - 1 * 13 + 32 + 20)
			// this.validateNow()
			// this._gp_fly.y = this._gp_reward_con.y - 80
			// this._gp_victory.y = this._gp_reward_con.y - 80
			// this._gp_tip_1.y = this._gp_reward_con.y - 30

			SetLocalPositionY(this._gp_fly, this._gp_reward_con.localPosition.y - 80)
			SetLocalPositionY(this._gp_victory, this._gp_reward_con.localPosition.y - 80)
			SetLocalPositionY(this._gp_tip_1, this._gp_reward_con.localPosition.y - 30)

			this.reward_arr.replaceAll(data.reward_list)
		}
		this.end_time = TimeUtil.getServerTime() + 10
		this.StartTime()
	}

	public InitEvent() {

		Util.AddClickEvent(this._btn_right, () => {
			this.Close()
		}
			, this, true)
	}

	public StartTime() {

		this.CancelTime()
		// this.time_id = Laya. new Timer(1000, 0)
		// this.time_id.addEventListener(Laya.TimerEvent.TIMER, this.UpadteTime, this)
		// this.time_id.start()
		// this.UpadteTime()

		this.time_id = GlobalTimerQuest.AddPeriodQuest(() => {
			this.UpadteTime()
		}, 1, -1)
		this.UpadteTime()
	}

	public CancelTime() {

		if (this.time_id) {
			// this.time_id.stop()
			// this.time_id.removeEventListener(Laya.TimerEvent.TIMER, this.UpadteTime, this)
			GlobalTimerQuest.CancelQuest(this.time_id)
			this.time_id = null
		}
	}

	public UpadteTime() {

		let left_time = this.end_time - TimeUtil.getServerTime()
		if (left_time < 0) {
			this.Close()
			return
		}
		this._lb_left_time.text = left_time + "秒后自动关闭"
	}

	public DeleteMe(){
		super.DeleteMe()
	}

}
window["EveningResultView"]=EveningResultView
