
/*
@description:对话模块
*/

import { BaseController } from "../common/BaseController"
import { Config } from "../common/Config"
import { EventName, SceneEventType } from "../common/EventName"
import { UserMsgAdapter } from "../common/UserMsgAdapter"
import { DialogueModel, DialogueTypeConst } from "../commonModel/DialogueModel"
import { TaskModel } from "../commonModel/TaskModel"
import { DialogueView } from "../dialogue/DialogueView"
import { RoleManager } from "../role/RoleManager"
import { Message } from "../sysinfo/SysInfoController"
import { GlobalEventSystem } from "../util/DeclareGlobalVar"
import { ErlangParser } from "../util/ErlangParser"
import { Util } from "../util/Util"


export class DialogueController extends BaseController {
	dialogueView
	dialogueModel
	taskModel
	preload_dialogue_view
	user_msg_adapter
	static Instance: any

	registerAllProtocals
	showDialg
	CloseDialoueView
	addAllEvents
	showTask
	response12101
	selectTask
	response12102
	acceptTask
	response30003
	finishTask
	talkToNPC
	showNpcFunctionSelectTalk
	showNpcTalk
	clickAnswerHandler
	public constructor() {
		super()

		DialogueController.Instance = this
		let user_msg_adapter = UserMsgAdapter.GetInstance()
		this.dialogueView = null
		this.dialogueModel = DialogueModel.GetInstance()
		this.taskModel = TaskModel.GetInstance()
		this.dialogueModel.autoIntoCopy = 0

		this.registerAllProtocals = () => {
			this.RegisterProtocal(12101, "response12101") //npc关联任务
			this.RegisterProtocal(12102, "response12102") //获取任务对话
		}

		this.showDialg = (npcDialogVo?) => {
			if (this.dialogueView == null) {
				this.dialogueView = new DialogueView()
			}
			if (npcDialogVo && npcDialogVo.dialogList) {
				// if (this.dialogueView.transform) {
				// 	this.dialogueView.transform.SetAsLastSibling()
				// }
				this.dialogueView.Open(npcDialogVo)
			} else {
				if (this.dialogueView.HasOpen() == true) {
					this.dialogueView.Close()
				}
			}
		}

		this.CloseDialoueView = () => {
			if (this.dialogueView && this.dialogueView.HasOpen() == true) {
				this.dialogueView.Close()
			}
		}

		this.addAllEvents = () => {
			var onRequestHandler = (...new_args) => {
				let args_list = new_args
				if (args_list[1] == 30009) {
					this.SendFmtToGame(args_list[1], "c", args_list[2])
				} else if (args_list[1] == 30010) {
					this.SendFmtToGame(args_list[1], "c", args_list[2])
				} else if (args_list[1] == 30015) {
					this.SendFmtToGame(args_list[1], "cl", args_list[2], args_list[3])
				} else if (args_list[1] == 30011) {
					this.SendFmtToGame(args_list[1], "i", args_list[2])
				} else {
					this.SendFmtToGame(args_list[1])
				}
			}
			this.dialogueModel.Bind(DialogueModel.REQUEST_CCMD_EVENT, onRequestHandler)

			var taskFun = (npcId, taskId, state) => {
				this.selectTask(npcId, taskId, state)
			}
			this.Bind(DialogueModel.SELECT_TASK, taskFun)

			var answer_fun = (dialogueVo, dialogueNodeVo, selected, double) => {
				this.clickAnswerHandler(dialogueVo, dialogueNodeVo, selected, double)
			}
			this.Bind(DialogueModel.CLICK_ANSWER, answer_fun)

			var showTask1 = (id) => {
				let level = RoleManager.Instance.mainRoleInfo.level
				// if (id == GuildModel.FEAST_NPC) {

				// } else {
					this.dialogueModel.changeSceneClose = false
					this.dialogueModel.isAuto = false   //发事件过来的要重置一下auto状态
					this.showTask(id)
				// }
			}
			this.Bind(SceneEventType.SHOW_TASK, showTask1)

			var acceptTask1 = (id) => {
				this.dialogueModel.changeSceneClose = false
				this.acceptTask(id)
			}
			this.Bind(EventName.SEND_TASK_ACCEPT, acceptTask1)

			var finishTask1 = (id, arr) => {
				this.dialogueModel.changeSceneClose = false
				this.finishTask(id, arr)
			}
			this.Bind(EventName.SEND_TASK_FINISH, finishTask1)

			// 超级强硬的关闭对话框
			var OutCloseDialog = () => {
				this.CloseDialoueView()
				this.dialogueModel.changeSceneClose = true
			}
			GlobalEventSystem.Bind(SceneEventType.SCENE_CHANGED, OutCloseDialog)

			let close_fun = () => {
				this.CloseDialoueView()
			}
			GlobalEventSystem.Bind(SceneEventType.CLOSE_DIALOGUE_VIEW, close_fun)
		}

		this.showTask = (id?) => {
			this.taskModel.scmd12101Send = true
			this.SendFmtToGame(12101, "i", id)
		}

		this.response12101 = () => {
			if (!this.taskModel.scmd12101Send) {
				return
			}
			this.taskModel.scmd12101Send = false
			let scmd12101 = user_msg_adapter.GetSCMD("12101")
			scmd12101.task_id = 0
			this.dialogueModel.npcDialogVo = scmd12101
			let dialogid = this.dialogueModel.GetDialogueId(scmd12101.npc_id)
			let npc_config = this.dialogueModel.GetNpcCfg(scmd12101.npc_id)
			//现在没有配置功能性Npc
			// if (npc_config && npc_config.action && npc_config.action.length > 0) {
			// 	//this:showNpcFunctionSelectTalk(dialogid,scmd12101.task_list.length)
			// } else {
				this.showNpcTalk(dialogid, scmd12101.task_list.length)
			// }

			//如果没有任务，则播放声音
			//if (scmd12101.task_list.length == 0 ) {
			// TaskSoundManager.GetInstance().PlayNpcSound(scmd12101.npc_id)
			//}
		}

		/*
		* 显示对话
		* @param npcId NPCID
		* @param taskId 任务ID
		* @param state 任务状态
		*
		*/
		this.selectTask = (npcId?, taskId?, state?) => {
			this.SendFmtToGame(12102, "ii", npcId, taskId)
			this.dialogueModel.isAuto = false
		}

		this.response12102 = () => {
			if (this.dialogueModel.changeSceneClose == true) {
				// 过滤掉延时的返回
				return
			}
			let scmd12102 = user_msg_adapter.GetSCMD("12102")
			this.dialogueModel.npcDialogVo = scmd12102
			console.log("response12102:", this.dialogueModel.npcDialogVo.npc_id, this.dialogueModel.npcDialogVo.task_id, this.dialogueModel.npcDialogVo.talk_id)
			let dialog = this.dialogueModel.GetTalkCfg(this.dialogueModel.npcDialogVo.talk_id)
			if(dialog){
				dialog = Util.DeepCopy(dialog)
				this.dialogueModel.npcDialogVo.dialogList = dialog
				this.dialogueModel.npcDialogVo.dialogList.content = JSON.parse(dialog.content)
			}
			
			this.dialogueModel.npcDialogVo.task_list = []
			//奖励这里获取
			this.dialogueModel.npcDialogVo.award = null
			if (!this.dialogueModel.npcDialogVo.dialogList) {
				Message.show("对话配置为空 id：" + this.dialogueModel.npcDialogVo.talk_id)
			}
			let temp = TaskModel.Instance.GetAllTaskList(this.dialogueModel.npcDialogVo.task_id)
			if (temp && temp[0]) {
				let award_list = []
				if (temp[0].special_goods_list) {
					let list = ErlangParser.GetInstance().Parse(temp[0].special_goods_list)
					if (list) {
						for (let _tmpi in list) {
							var vo = list[_tmpi]
							if (Number(vo[0]) == RoleManager.GetInstance().mainRoleInfo.career) {
								let obj = null
								obj = []
								obj[0] = 0
								obj[1] = Number(vo[2])
								obj[2] = Number(vo[3])
								award_list.push(obj)
							}
						}
					}
				}
				let list2 = ErlangParser.GetInstance().Parse(temp[0].award_list)
				if (list2) {
					for (let _tmpi in list2) {
						var vo = list2[_tmpi]
						award_list.push(vo)
					}
				}
				this.dialogueModel.npcDialogVo.award = award_list
			}
			if (this.dialogueModel.npcDialogVo.dialogList && this.dialogueModel.npcDialogVo.dialogList.content) {
				for (let k = 0; k < this.dialogueModel.npcDialogVo.dialogList.content.length; k++) {
					var v = this.dialogueModel.npcDialogVo.dialogList.content[k]
					for (let _ = 0; _ < v.list.length; _++) {
						var vo = v.list[_]
						if (vo.type == 0 && (vo.text).trim() == "") {
							//对话内容为空字符串，直接接受任务或者完成任务
							let data = this.taskModel.GetHasReceiveTaskList(scmd12102.task_id)
							if (data && data[0]) {
								if (data[0].acceptType == 0) {
									this.finishTask(scmd12102.task_id)
								} else if (data[0].acceptType == 1) {
									this.acceptTask(scmd12102.task_id)
								}
							}
							return
						}
					}
				}
			}
			this.showDialg(this.dialogueModel.npcDialogVo)
			//TaskSoundManager:GetInstance():PlayTaskAcceptSound(scmd12102.task_id)
		}

		// 接受任务
		this.acceptTask = (id?) => {
			id = Number(id)
			this.taskModel.Fire(TaskModel.REQUEST_CCMD_EVENT, 30003, id)
			this.dialogueModel.isAuto = true
		}

		this.response30003 = () => {
			this.taskModel.wait_30003 = false
			let flag, msg = this.ReadFmt("ii")
			if (flag == 0) {
				Util.ErrorCodeShow(msg)
			} else {
				this.taskModel.now_select_task_id = flag
				Message.show("<font color='0x93e725'>成功接受任务</font>")
				// lua_soundM.PlayTaskSound(flag)
			}
		}
		//double: 0是默认 1是双倍
		this.finishTask = (id?, arr?, double?) => {
			this.dialogueModel.isAuto = true
			this.taskModel.Fire(TaskModel.REQUEST_CCMD_EVENT, 30004, id)
		}

		/*
		* 任务对话事件
		* @param npcId NPCID
		* @param taskId 任务ID
		*
		*/
		this.talkToNPC = (npcId?, taskId?) => {
			this.taskModel.Fire(TaskModel.REQUEST_CCMD_EVENT, 30007, npcId)
			this.dialogueModel.isAuto = true;
		}



		//选择npc功能对话框
		this.showNpcFunctionSelectTalk = (talkid?, taskCount?) => {
			let dialogid = talkid
			let npcDialogVo = this.dialogueModel.npcDialogVo
			npcDialogVo.dialogId = dialogid
			let dialog = this.dialogueModel.GetTalkCfg(dialogid)
			if (dialog){
				dialog = Util.DeepCopy(dialog)
				npcDialogVo.dialogList = dialog
				npcDialogVo.dialogList.content = JSON.parse(dialog.content)
			}
			
			if (npcDialogVo.dialogList == null) {
				npcDialogVo.dialogList = DialogueModel.DEFAULT_TALK
				if (npcDialogVo.dialogList.content[1]) {
					npcDialogVo.dialogList.content[1].id = npcDialogVo.npc_id
				}
			}
			// 跳过空对话
			if (this.dialogueModel.isAuto == true && taskCount == 0) {
				this.dialogueModel.isAuto = false
				return
			}
			this.showDialg(npcDialogVo)
		}

		this.showNpcTalk = (talkid?, taskCount?) => {
			let dialogid = talkid
			let npcDialogVo = this.dialogueModel.npcDialogVo
			let is_default_talk = false
			/*
			同个npc下面可能同时会有主线和支线任务，12101协议任务数据可能会有2条，
			这样客户端就不知道应该选择哪个任务来触发相关操作， 所以在开始任务前，客户端先记下当前任务id，
			这里判断12101协议里面的任务数据是不是存在当前客户端保存的当前任务id，存在的话就把非当前任务的数据删掉
			*/

			if (this.taskModel.now_select_task_id && this.dialogueModel.npcDialogVo && this.dialogueModel.npcDialogVo.task_list.length > 1) {
				let find = false
				for (let i = 0; i < this.dialogueModel.npcDialogVo.task_list.length; i++) {
					var v = this.dialogueModel.npcDialogVo.task_list[i]
					if (v.task_id == this.taskModel.now_select_task_id) {
						find = true
						break
					}
				}
				if (find) {
					let delete_index = []
					for (let i = 0; i < this.dialogueModel.npcDialogVo.task_list.length; i++) {
						var v = this.dialogueModel.npcDialogVo.task_list[i]
						if (v.task_id != this.taskModel.now_select_task_id) {
							delete_index.push(i)
						}
					}
					let del_num = 0
					for (let i = 0; i < delete_index.length; i++) {
						var v = delete_index[i]
						let index = v - del_num
						this.dialogueModel.npcDialogVo.task_list.push(this.dialogueModel.npcDialogVo.task_list, index)
						del_num = del_num + 1
					}
					taskCount = 1
				}
			}
			npcDialogVo.dialogId = dialogid
			let dialog = this.dialogueModel.GetTalkCfg(dialogid)
			if (dialog){
				dialog = Util.DeepCopy(dialog)
				npcDialogVo.dialogList = dialog
				npcDialogVo.dialogList.content = JSON.parse(dialog.content)
			}
			
			// if (npcDialogVo.dialogList && npcDialogVo.dialogList.content){
			// 	npcDialogVo.dialogList.content = JSON.parse(npcDialogVo.dialogList.content)
			// }

			if (npcDialogVo.dialogList == null) {
				console.log("~~~~~db里面找不到该对话id, 显示默认对话:", dialogid)
				npcDialogVo.dialogList = DialogueModel.DEFAULT_TALK
				is_default_talk = true
				if (npcDialogVo.dialogList.content[1]) {
					npcDialogVo.dialogList.content[1].id = npcDialogVo.npc_id
				}
			}

			// 跳过空对话
			if (this.dialogueModel.isAuto == true && taskCount == 0) {
				this.dialogueModel.isAuto = false
				return
			}
			////(task_state  0.无 1.有可接任务 2.有未完成的任务 3.有可提交的任务 4.有任务对话)
			// console.log("对话内容状态",npcDialogVo.dialogList.total_content, npcDialogVo.dialogList.content[1].total_list, taskCount)
			if (npcDialogVo.dialogList.total_content == 1 && npcDialogVo.dialogList.content[1].total_list == 1
				//and taskCount == 1 && npcDialogVo.task_list[1].task_state~=2 ) {
				&& taskCount == 1) {
				this.selectTask(npcDialogVo.npc_id, npcDialogVo.task_list[0].task_id, npcDialogVo.task_list[0].task_state)
			} else {
				if (npcDialogVo.npc_id == 0 && is_default_talk) { //当npc_id 是0 ，而且是默认对话的时候，对话框就不显示出来了
					return
				}
				if (this.dialogueModel.isAuto == false) {
					this.showDialg(npcDialogVo)
				} else if (npcDialogVo.task_list.length > 0) {
					let isShow = false
					for (let _ in npcDialogVo.task_list) {
						var taskNodeVo = npcDialogVo.task_list[_]
						if (taskNodeVo.task_state != 2) {
							isShow = true
						}
					}
					if (isShow == true && npcDialogVo.dialogId && npcDialogVo.dialogId != 0) {
						this.showDialg(npcDialogVo)
					}
				}
			}
			this.dialogueModel.isAuto = false
		}

		/*
		* 点击NPC对话框确定按钮
		* @param e
		*
		*/
		this.clickAnswerHandler = (dialogueVo?, dialogueNodeVo?, selected?, double?) => {
			selected = selected || false
			let typeId = 0
			if (dialogueNodeVo.type == DialogueTypeConst.FINISH_AND_TRIGGER) {
				this.finishTask(dialogueVo.task_id, false, double);
			} else if (dialogueNodeVo.type == DialogueTypeConst.TRIGGER) {
				//let vo = TaskModel.GetInstance().GetCanTaskById(dialogueVo.task_id)
				this.acceptTask(dialogueVo.task_id);
			} else if (dialogueNodeVo.type == DialogueTypeConst.FINISH) {
				this.finishTask(dialogueVo.task_id, false, double);
			} else if (dialogueNodeVo.type == DialogueTypeConst.TRIGGER_AND_FINISH) {

			} else if (dialogueNodeVo.type == DialogueTypeConst.TALK_EVENT) {
				this.talkToNPC(dialogueVo.npc_id, dialogueVo.task_id)
			}
		}



		this.registerAllProtocals()
		this.addAllEvents()
	}
}



window["DialogueController"] = DialogueController