import { CommonManager } from "../common/CommonManager"
import { Config } from "../common/Config"
import { EventName } from "../common/EventName"
import { TaskModel } from "../commonModel/TaskModel"
import { RoleManager } from "../role/RoleManager"
import { ServerTimeModel } from "../serverTime/ServerTimeModel"
import { GlobalEventSystem, ClientConfig } from "../util/DeclareGlobalVar"
import { EventDispatcher } from "../util/EventDispatcher"
import { Status } from "../util/Status"

export class ActivityIconManager extends EventDispatcher {
	CheckBoxOpenState
	getIconInfo
	RestoreIconFromBox
	GetIconRedDot
	LevelChangeCheckIconOpen
	FunIsOpenByIconType
	DeleteIconAndIntoBox
	deleteIcon
	SetIconRedDot
	addIcon
	NeedInputBox
	icon_info_list
	getBoxIconInfo
	DeleteAllIcon
	AddEvents


	public static UPDATE_SINGLE_ICON = "UPDATE_SINGLE_ICON"
	public static ADD_TOP_ICON = "ADD_TOP_ICON"
	public static ADD_LEFT_ICON = "ADD_LEFT_ICON"
	public static ADD_RIGHT_ICON = "ADD_RIGHT_ICON"
	public static DELETE_ICON = "DELETE_ICON"
	public static UPDATE_ALL_ICON = "UPDATE_ALL_ICON"
	public static SET_ICON_TEXT = "SET_ICON_TEXT"
	public static UPDATE_EFFECT = "UPDATE_EFFECT"
	public static ADD_RECHARGE_ICON = "ADD_RECHARGE_ICON"
	static Instance: any

	public constructor() {
		super()

		if (ActivityIconManager.Instance) {
			return
		}
		ActivityIconManager.Instance = this

		let local_RoleManager_Instance = RoleManager.GetInstance()
		let local_GlobalEventSystem = GlobalEventSystem
		let local_ServerTimeModel = ServerTimeModel
		let local_ServerTimeModel_Instance = ServerTimeModel.GetInstance()
		let local_EventName = EventName
		let local_CommonManager_Instance = CommonManager.GetInstance()
		// let local_PlatformManager_Instance = PlatformManager.GetInstance()
		let local_TaskModel_Instance = TaskModel.GetInstance()
		let local_Config = Config

		let icon_box_info_list_ = []
		let icon_red_dot_ = []

		this.icon_info_list = []

		this.AddEvents = () => {
			let delay_timer_id = null
			let level_change = (lv?) => {
				if (delay_timer_id) {
					clearTimeout(delay_timer_id)
					delay_timer_id = null
				}
				if (!delay_timer_id) {
					delay_timer_id =
						setTimeout(() => {
							this.LevelChangeCheckIconOpen()
						},
							0.06
						)
				}
			}

			local_RoleManager_Instance.GetMainRoleVo().Bind(local_EventName.CHANGE_LEVEL, level_change)
			// local_TaskModel_Instance.Bind(TaskModel.UPDATE_NEWEST_TASK_ID, level_change)
			local_GlobalEventSystem.Bind(local_ServerTimeModel.REFRESH_SERVER_TIME, level_change)

			local_GlobalEventSystem.Bind(
				local_EventName.GAME_START, () => {
					this.LevelChangeCheckIconOpen()
				}
			)
			let box_fun = (iconType?, bool?) => {
				let force = false
				let box_icon_cfg = local_CommonManager_Instance.GetBoxIconCfg(iconType)
				if (bool != null) {
					this.SetIconRedDot(iconType, bool)
				}
				if (box_icon_cfg) {
					local_GlobalEventSystem.Fire(local_EventName.REFRESH_ACTIVITY_ICON_RED_DOT, box_icon_cfg.attach_icon_type)
				}
			}

			local_GlobalEventSystem.Bind(local_EventName.REFRESH_ACTIVITY_ICON_RED_DOT, box_fun)
			let alpha_state_change = () => {
				this.DeleteAllIcon()
				this.LevelChangeCheckIconOpen()
			}

			local_GlobalEventSystem.Bind(local_EventName.ALPHA_STATE_CHANGE, alpha_state_change)
		}

		this.SetIconRedDot = (iconType?, bool?) => {
			icon_red_dot_[String(iconType)] = bool
		}

		this.GetIconRedDot = (iconType?) => {
			return icon_red_dot_[String(iconType)]
		}

		this.getIconInfo = (iconType?) => {
			return this.icon_info_list[String(iconType)]
		}

		this.getBoxIconInfo = (iconType?) => {
			return icon_box_info_list_[String(iconType)]
		}

		this.addIcon = (iconType?, time?, iconInfo?, icon_txt?, icon_img?) => {
			iconType = String(iconType)
			// if (iconType == "283" && ! HolyTerritoryModel.GetInstance().RealTimeOpen()  ) {
			// 	this.deleteIcon(iconType)
			// 	return
			// }
			let roleVo = local_RoleManager_Instance.GetMainRoleVo()
			if (!roleVo) {
				return
			}
			let cfg = local_CommonManager_Instance.GetFunctionIconCfg(iconType)
			if (cfg) {
				if (ClientConfig.alpha_mode && cfg.need_hide_in_alpha) {	//审核服下，图标不显示
					return
				}
				let openDay = local_ServerTimeModel_Instance.GetOpenServerDay()

				if ((iconType == "2820" && openDay > 15)) {
					if (roleVo.level < 160) {
						this.deleteIcon(cfg.icon_type)
						return
					}
				} else {
					if ((roleVo.level < cfg.open_lv
						|| openDay < cfg.open_day
						|| ((cfg.max_open_day && cfg.max_open_day != 0) && openDay > cfg.max_open_day)
						|| (cfg.open_task_id && local_TaskModel_Instance.newest_finish_task_id < cfg.open_task_id))
						//and (iconType == "2820" && openDay > 15 && roleVo.level < 160)
					) {

						this.deleteIcon(cfg.icon_type)
						return
					}
				}
			} else {
				return
			}

			let count_down_time = time
			let vo = this.getIconInfo(iconType)
			let box_icon_cfg = local_CommonManager_Instance.GetBoxIconCfg(iconType)
			if (box_icon_cfg) {
				if (!this.CheckBoxOpenState(box_icon_cfg.attach_icon_type)) {
					this.RestoreIconFromBox()
				} else if (this.NeedInputBox(box_icon_cfg)) {
					this.deleteIcon(cfg.icon_type)
					let info = null
					info = []
					info.id = iconType
					info.time = count_down_time
					info.add_time = Status.NowTime
					info.icon_txt = icon_txt || ""
					info.icon_img = icon_img
					info.data = iconInfo || local_CommonManager_Instance.GetFunctionIconCfg(iconType)
					icon_box_info_list_[iconType] = info
					if (!this.getIconInfo(box_icon_cfg.attach_icon_type)) {
						this.addIcon(box_icon_cfg.attach_icon_type)
					}
					return
				}
			}
			if (vo) {
				if (count_down_time != null) {
					vo.time = count_down_time
				}
				vo.icon_img = icon_img
				local_GlobalEventSystem.Fire(ActivityIconManager.UPDATE_SINGLE_ICON, iconType)
			} else {
				if (this.FunIsOpenByIconType(iconType)) {
					let info = null
					info = []
					info.id = iconType
					info.time = count_down_time || 0
					info.add_time = Status.NowTime
					info.icon_txt = icon_txt || ""
					info.data = iconInfo || local_CommonManager_Instance.GetFunctionIconCfg(iconType)
					info.icon_img = icon_img
					this.icon_info_list[iconType] = info
					if (info.data) {
						if (((info.data.location_type == 1 || info.data.location_type == 2) || info.data.location_type == 3) ||
							info.data.location_type == 6
						) {
							local_GlobalEventSystem.Fire(ActivityIconManager.ADD_TOP_ICON, iconType)
						} else if (info.data.location_type == 4) {
							local_GlobalEventSystem.Fire(ActivityIconManager.ADD_LEFT_ICON, iconType)
						} else if (info.data.location_type == 5) {
							local_GlobalEventSystem.Fire(ActivityIconManager.ADD_RIGHT_ICON, iconType)
						} else if (info.data.location_type == 7) {
							local_GlobalEventSystem.Fire(ActivityIconManager.ADD_RECHARGE_ICON, iconType)
						}
					}
				}
			}
			if (cfg.is_box) {
				this.DeleteIconAndIntoBox(iconType)
			}
		}

		this.deleteIcon = (iconType?) => {
			iconType = String(iconType)
			if (this.icon_info_list[iconType] || icon_box_info_list_[iconType]) {
				local_GlobalEventSystem.Fire(ActivityIconManager.DELETE_ICON, iconType)
				this.icon_info_list[iconType] = null
				icon_box_info_list_[iconType] = null
			}
		}

		this.DeleteAllIcon = () => {
			for (let iconType in this.icon_info_list) {

				this.deleteIcon(iconType)
			}
			for (let iconType in icon_box_info_list_) {

				this.deleteIcon(iconType)
			}
		}

		this.LevelChangeCheckIconOpen = () => {
			let roleVo = local_RoleManager_Instance.GetMainRoleVo()
			if (!roleVo || roleVo.role_id == 0) {
				return
			}
			let openDay = local_ServerTimeModel_Instance.GetOpenServerDay()
			let cfg = null
			let sub_cfg = null
			for (let area in local_Config.PRELOAD_CLIENT_CONFIG.ConfigFunctionIcon) {

				cfg = local_Config.PRELOAD_CLIENT_CONFIG.ConfigFunctionIcon[area]
				if (cfg) {
					for (let key in cfg) {

						if (key == "33216") {
							sub_cfg = cfg[key]
						}
						sub_cfg = cfg[key]
						if (sub_cfg) {
							if (!sub_cfg.controll_by_own_fun) {
								this.addIcon(sub_cfg.icon_type)
							}
						}
					}
				}
			}
		}

		this.FunIsOpenByIconType = (icon_type?) => {
			let open = true
			if (icon_type == 10) {
			} else if (icon_type == 11) {
			}
			return open
		}

		this.CheckBoxOpenState = (iconType?) => {
			let cfg = local_CommonManager_Instance.GetFunctionIconCfg(iconType)
			let roleVo = local_RoleManager_Instance.GetMainRoleVo()
			if (((cfg && cfg.is_box) && roleVo) && !cfg.controll_by_own_fun) {
				let openDay = local_ServerTimeModel_Instance.GetOpenServerDay()
				if (roleVo.level < cfg.open_lv || openDay < cfg.open_day || (cfg.max_open_day != 0 && openDay > cfg.max_open_day)
					|| cfg.open_task_id && local_TaskModel_Instance.newest_finish_task_id < cfg.open_task_id
				) {
					return false
				}
			}
			return true
		}

		this.NeedInputBox = (icon_cfg?) => {
			if (icon_cfg) {
				let openDay = local_ServerTimeModel_Instance.GetOpenServerDay()
				let roleVo = local_RoleManager_Instance.GetMainRoleVo()
				// if (icon_cfg.icon_type == "1112" && KaifuActivityModel && ! KaifuActivityModel.GetInstance().canShowIcon() ) {
				// 	return false
				// }
				// if (icon_cfg.icon_type == "424" || icon_cfg.icon_type == "424@1" ) {
				// 	let type = local_Config.ConfigCustomActivity.SPECIAL_ID["BOOKOFCONTRACT"]
				// 	return CustomActivityModel.GetInstance().GetSpecialOpenState(type)
				// }
				if (((roleVo.level < icon_cfg.attach_open_lv || openDay < icon_cfg.attach_open_day) ||
					icon_cfg.attach_max_open_day != 0 && openDay > icon_cfg.attach_max_open_day)
					|| icon_cfg.attach_open_task_id && local_TaskModel_Instance.newest_finish_task_id < icon_cfg.attach_open_task_id
				) {
					return false
				}
				return true
			}
		}

		this.RestoreIconFromBox = () => {
			let box_icon_cfg = null
			let icon_info = null
			for (let icon_type in icon_box_info_list_) {

				box_icon_cfg = local_CommonManager_Instance.GetBoxIconCfg(icon_type)
				icon_info = icon_box_info_list_[icon_type]
				if ((icon_info && box_icon_cfg) && !this.CheckBoxOpenState(box_icon_cfg.attach_icon_type)) {
					let box_icon = box_icon_cfg.attach_icon_type
					icon_box_info_list_[icon_type] = null
					let is_delete = true
					for (let _type in icon_box_info_list_) {

						let box_cfg = local_CommonManager_Instance.GetBoxIconCfg(_type)
						if (box_cfg.attach_icon_type == box_icon) {
							is_delete = false
						}
					}
					if (is_delete && this.getBoxIconInfo(box_icon)) {
						this.deleteIcon(box_icon)
					}
					this.addIcon(icon_type, icon_info.time, null, icon_info.icon_txt, icon_info.icon_img)
				}
			}
		}

		this.DeleteIconAndIntoBox = (iconType?) => {
			let cfg = null
			let info = null
			for (let key in local_Config.PRELOAD_CLIENT_CONFIG.ConfigBoxIcon) {

				cfg = local_Config.PRELOAD_CLIENT_CONFIG.ConfigBoxIcon[key]
				if (cfg.attach_icon_type == iconType) {
					info = this.getIconInfo(cfg.icon_type)
					if (info) {
						this.addIcon(cfg.icon_type, info.time, null, info.icon_txt, info.icon_img)
					}
				}
			}
		}

		this.AddEvents()
		this.LevelChangeCheckIconOpen()
	}

	public static GetInstance() {

		if (!ActivityIconManager.Instance) {
			new ActivityIconManager()
		}
		return ActivityIconManager.Instance
	}
}
window["ActivityIconManager"] = ActivityIconManager