export class DungeonMaterialEnterItem extends BaseItem1 {
	_img_bg: Laya.Image
	_Image1: Laya.Image
	_lb_dungeon_name: Laya.Label
	_Label1: Laya.Label
	_lb_fight_count: Laya.HTMLDivElement
	_btn_add: Laya.Image
	_Label2: Laya.Label
	_scroll_reward: Laya.Panel
	Content: Laya.HBox
	_Image2: Laya.Image
	_img_difficulty: Laya.Image
	_img_lock: Laya.Image
	_lb_unlock: Laya.Label
	_btn_left: Laya.Image
	_btn_right: Laya.Image
	_Image4: Laya.Image
	_lb_difficulty: Laya.Label
	_btn_challenge: Laya.Box
	_Image5: Laya.Image
	labelDisplay: Laya.Label
	_gp_sweeping: Laya.Box
	_Image3: Laya.Image
	_Label3: Laya.Label
	_point_icon: Laya.Image
	_img_challenge_red: Laya.Image
	_gp_effect: Laya.Box
	_Group1: Laya.HBox
	_img_sweep_icon: Laya.Image
	_lb_sweep_count: Laya.Label


	CheckBuyTimeEffect
	GetImgSource
	GetMaxIndex
	InitEvent
	LoadSuccess
	SelectView
	SetData
	UpdateSweepingCount
	UpdateView
	parent_mask_corners
	reward_item_list_
	story_obj_list
	updatePoint


	public constructor(parent?) {
		super(parent)

		let role_mgr = RoleManager.GetInstance()
		let findun_type = TaskTipType.FinDunType
		let local_Message = Message
		let dungeon_model = BaseDungeonModel.GetInstance()
		let local_BaseDungeonModel = BaseDungeonModel
		let goods_model = GoodsModel.GetInstance()
		let local_GlobalEventSystem = GlobalEventSystem
		let OPEN_VIEW = EventName.OPEN_VIEW
		let vip_model = VipModel.GetInstance()
		this.layer_value = Enum_UILayer.UI

		let data_ = null
		let default_index_ = 0
		let now_index_ = null
		let max_index_ = null
		this.reward_item_list_ = null
		let dun_type_ = null
		let left_count_ = null
		let role_level_ = null
		this.base_file = "dungeonMaterial"
		this.layout_file = "DungeonMaterialEnterItem"
		// this.dependent_res = ["dungeonCommon"]
		role_level_ = role_mgr.GetMainRoleVo().level || 0

		this.load_callback = () => {
			this._scroll_reward.hScrollBar.visible = false
			this.LoadSuccess()
		}

		this.createChildren = () => {
			this.story_obj_list = []
			// [ts2lua]this.story_obj_list下标访问可能不正确
			this.story_obj_list[findun_type] = []
			// [ts2lua]this.story_obj_list下标访问可能不正确
			// [ts2lua]this.story_obj_list[findun_type]下标访问可能不正确
			this.story_obj_list[findun_type][dun_type_] = [this._btn_challenge]
			super.createChildren()
		}

		this.InitEvent = () => {
			let left_func = () => {
				let index = now_index_ - 1
				// if (index >= 0 ) {
				if (index >= 0) {
					this.SelectView(index)
				} else {
					local_Message.show("已到达最低")
				}
			}

			let right_func = () => {
				let index = now_index_ + 1
				if (index < max_index_) {
					this.SelectView(index)
				} else {
					local_Message.show("已到达最高")
				}
			}

			let challenge_func = () => {
				if (data_) {
					let open = dungeon_model.DungeonOpenCondition(dun_type_)
					if (!open) {
						return
					}
					// [ts2lua]data_下标访问可能不正确
					dungeon_model.Fire(local_BaseDungeonModel.SCMD_REQUEST, 61001, data_[now_index_].dun_id)
				}
			}

			let sweeping_func = () => {
				let dun_model = dungeon_model
				let open = dun_model.DungeonOpenCondition(dun_type_)
				if (!open) {
					return
				}
				// [ts2lua]data_下标访问可能不正确
				let dun_data = data_[now_index_]
				if (!dun_data || Number(dun_data.level) > role_level_) {
					local_Message.show("关卡未开启~")
					return
				}
				if (dun_data && Number(dun_data.sweep_lv) > role_level_) {
					local_Message.show(dun_data && dun_data.sweep_lv + "级开启扫荡~")
					return
				}
				if (!dun_data.is_sweep) {
					local_Message.show("需要通关副本才能扫荡")
					return
				}
				if (!left_count_) {
					local_Message.show("剩余副本次数不足")
					return
				}
				if (goods_model.GetTypeGoodsNum(local_BaseDungeonModel.SWEEPING_GOODS_ID) == 0 && !dun_model.material_auto_buy_state) {
					local_GlobalEventSystem.Fire(OPEN_VIEW, "DungeonMaterialAlertView", dun_type_, dun_data.dun_id)
					return
				}
				dun_model.Fire(local_BaseDungeonModel.SCMD_REQUEST, 61022, dun_data.dun_id, 1)
			}

			let add_func = () => {
				if (data_) {
					// [ts2lua]data_下标访问可能不正确
					local_GlobalEventSystem.Fire(OPEN_VIEW, "DungeonBuyTimeView", data_[now_index_].dun_id)
				}
			}

			Util.AddClickEvent(this._btn_add, add_func, this, true)
			Util.AddClickEvent(this._gp_sweeping, sweeping_func, this, true)
			Util.AddClickEvent(this._btn_challenge, challenge_func, this, true)
			Util.AddClickEvent(this._btn_left, left_func, this, false)
			Util.AddClickEvent(this._btn_right, right_func, this, false)
			let update_view_func_1 = (dun_id?) => {
				// [ts2lua]data_下标访问可能不正确
				// [ts2lua]data_下标访问可能不正确
				if ((data_ && data_[now_index_]) && data_[now_index_].dun_id == dun_id) {
					this.UpdateView()
				}
			}

			this.BindEvent(dungeon_model, local_BaseDungeonModel.UPDATE_DUNGEON_TIME, update_view_func_1)
			let update_view_func_2 = (dun_type?) => {
				// [ts2lua]data_下标访问可能不正确
				// [ts2lua]data_下标访问可能不正确
				if ((data_ && data_[now_index_]) && data_[now_index_].type == dun_type) {
					this.UpdateView()
				}
			}

			this.BindEvent(dungeon_model, local_BaseDungeonModel.UPDATE_DUNGEON_TYPE_VIEW, update_view_func_2)
			this.BindEvent(dungeon_model, local_BaseDungeonModel.UPDATE_ACTIVITY, (base_type?, sub_type?) => {
				if (base_type && base_type == local_BaseDungeonModel.MORE_ACTIVITY || !base_type) {
					this.updatePoint()
				}
			}
			)
			this.BindVar(role_mgr.GetMainRoleVo(), "vip_flag", (event_name?, value?, old_value?) => {
				this.UpdateView()
			}
			)
			this.BindEvent(vip_model, VipModel.UPDATE_NOBLE_STATE, () => {
				this.UpdateView()
			}
			)
			this.BindEvent(goods_model, GoodsModel.UPDATE_GOODS_NUM, (goods_list?) => {
				if (this.use_delete_method) {
					return
				}
				for (let _tmpi in goods_list) {
					var vo = goods_list[_tmpi]
					if (vo.type_id == local_BaseDungeonModel.SWEEPING_GOODS_ID) {
						this.UpdateSweepingCount()
						break
					}
				}
			}
			)
		}

		this.LoadSuccess = () => {
			// if (PlatformMgr.GetInstance().IsEyouEnPlatform() ) {
			// 	this.labelDisplay.size  = 20
			// 	this._Label3.size  = 20
			// 	this._lb_unlock.size  = 18
			// }
			// ResManager.GetInstance().SetOutsideImageSprite(this, this._img_bg, GameResPath.GetIcon("dungeonMaterial","uifb_002_jiugong700x286"))
			//ResManager.GetInstance().SetImageSprite(this, this._img_bg, "dungeonmaterial_asset", "uitc_007")
			ResManager.GetInstance().SetOutsideImageSprite(this, this._img_sweep_icon, GameResPath.GetGoodsIconPath(String(local_BaseDungeonModel.SWEEPING_GOODS_ID)))
			ResManager.GetInstance().SetOutsideImageSprite(this, this._Image1, GameResPath.GetIcon("dungeonMaterial", "uifb_004"))
			ResManager.GetInstance().SetOutsideImageSprite(this, this._Image4, GameResPath.GetIcon("dungeonMaterial", "uifb_nd"))

			// let scrollRect = this.parent_wnd.GetComponentInParent(typeof(UnityEngine.UI.ScrollRect))
			// if (! IsNull(scrollRect) ) {
			// 	let content = scrollRect.transform.Find("_gp_content")
			// 	if (content ) {
			// 		this.parent_mask_corners = GetWorldCorners(content)
			// 		let mask = this.GetChild("_scroll_reward/Viewport").GetComponent("Image")
			// 		this.RegisterMask(mask, 2)
			// 	}
			// }
			this.UpdateSweepingCount()
			this.InitEvent()
			this.SelectView(this.GetMaxIndex())
			//LayoutRebuilder(this._Group1)

		}

		this.SetData = (dun_type?) => {
			dun_type_ = dun_type
			if (this.is_loaded) {
				this.UpdateView()
			}
		}

		this.SelectView = (index?) => {
			if (index == now_index_) {
				return
			}
			now_index_ = index
			this.UpdateView()
		}

		this.UpdateView = () => {
			let index = now_index_
			let cfg1 = ResManager.GetInstance().GetGameConfigFromCache(this, "config_num_by_vip", false)
			let cfg2 = ResManager.GetInstance().GetGameConfigFromCache(this, "config_num_by_vip_info", false)
			data_ = dungeon_model.GetDungeonInfo(dun_type_)
			// [ts2lua]修改数组长度需要手动处理。
			max_index_ = data_.length
			if (data_) {
				// [ts2lua]data_下标访问可能不正确
				let data = data_[index]
				if (data) {
					let role_lv = role_mgr.GetMainRoleVo().level
					let name: string = data.name
					//let a = name.indexOf(")")
					this._lb_dungeon_name.text = name.substr(0, name.indexOf("("))
					this._lb_difficulty.text = name.substr(name.indexOf("(") + 1, 2)
					ResManager.GetInstance().SetOutsideImageSprite(this, this._img_difficulty, GameResPath.GetIcon("dungeonMaterial", this.GetImgSource(index)), true)
					let vip_card = vip_model.GetNobleCardState()
					let vip_flag = role_mgr.GetMainRoleVo().vip_flag
					if (vip_flag >= 1) {
						vip_card = 99
					}
					let vip_default_count = vip_model.GetVipPrivilegeValue(local_BaseDungeonModel.MODULE_ID, local_BaseDungeonModel.VIP_COUNT_PARAMETER + Number(dun_type_), vip_card, vip_flag)
					let daily_default_count = Number(data.count_cond) + vip_default_count
					let total_count = data.add_count + data.vip_count + daily_default_count
					let left_times = total_count - data.daily_count
					left_count_ = left_times
					let vip_max = vip_model.GetVipPrivilegeValue(local_BaseDungeonModel.MODULE_ID, local_BaseDungeonModel.VIP_PARAMETER + Number(dun_type_), vip_card, vip_flag)
					if (vip_max != data.vip_count) {
						// this.AddUIEffect2("ui_plussign_glow", this._gp_effect, null, {x=1, y=1}, true)
					} else {
						// this.ClearUIEffect(this._gp_effect)
					}
					if (CommonManager.GetInstance().CheckFuncOpenState(DungeonEnterView) && role_lv >= Number(data.level)) {
						this._img_challenge_red.visible = left_times != 0
					} else {
						this._img_challenge_red.visible = false
					}
					// [ts2lua]lua中0和空字符串也是true，此处left_times == 0需要确认
					let str = (left_times == 0 && ("<font color='#ff0000'>" + left_times + "</font>") || (left_times))
					// this._lb_fight_count.text = (Laya. new HtmlTextParser()).parser(str + "/" + total_count)
					this._lb_fight_count.style.fontSize = 22
					this._lb_fight_count.style.valign = "center"
					this._lb_fight_count.style.color = "#0a953e"
					this._lb_fight_count.width = 100
					this._lb_fight_count.innerHTML = Util.StrToHTML(str + "/" + total_count)

					let reward_list = []
					if (data.reward) {
						reward_list = JSON.parse(data.reward)
					}
					if (!this.reward_item_list_) {
						this.reward_item_list_ = []
					}

					for (let i = reward_list.length - 1; i < this.reward_item_list_.length; i++) {
						this.reward_item_list_[i].SetVisible(false)
					}

					for (let key in reward_list) {

						let vo = reward_list[key]
						let item = this.reward_item_list_[key]
						if (!item) {
							item = new BaseAwardItem(this.Content)
							this.reward_item_list_[key] = item
							item.SetItemSize(96, 96)
							// item.SetMaskId(2)
							// item.SetMaskRect(this.parent_mask_corners)
							item.Load()
						}
						let [type_id, lock] = goods_model.GetMappingTypeId(vo[0], vo[1])
						let goods_vo = goods_model.GetGoodsBasicByTypeId(type_id)
						if (goods_vo) {
							item.SetData(goods_vo.type_id, vo[2], lock)
							item.SetVisible(true)
						}
					}
					this.updatePoint()
					this.CheckBuyTimeEffect()
				}
			}
		}

		this.updatePoint = () => {
			let point = dungeon_model.getPoint(dun_type_)
			// this._point_icon.visible = point > 0
			this._point_icon.visible = point > 0
			if (this._point_icon.visible) {
				// [ts2lua]lua中0和空字符串也是true，此处point == 2需要确认
				let img = (point == 2 && ("uifb_027.png") || ("uifb_028.png"))
				ResManager.GetInstance().SetImageSprite(this, this._point_icon, "dungeoncommon_asset", img)
			}
		}

		this.GetMaxIndex = () => {
			if (!data_) {
				data_ = dungeon_model.GetDungeonInfo(dun_type_)
			}
			table.sort(data_, (a?, b?) => {
				return Number(a.level) < Number(b.level)
			})
			for (let key in data_) {

				// [ts2lua]data_下标访问可能不正确
				let v = data_[key]
				if (Number(v.level) > role_level_) {
					return Number(key) - 1
				}
				if (Number(key) == data_.length - 1) {
					return Number(key)
				}
			}
			// return 0
			return 0
		}

		this.GetImgSource = (index?) => {
			// [ts2lua]data_下标访问可能不正确
			let data = data_[index]
			if (data) {
				let lv = Number(data.level)
				if (role_level_ >= lv) {
					Util.SetImageGray(this._img_difficulty, false)
					this._lb_unlock.visible = false
					this._img_lock.visible = false
				} else {
					Util.SetImageGray(this._img_difficulty, true)
					this._lb_unlock.visible = true
					this._img_lock.visible = true
					// [ts2lua]lua中0和空字符串也是true，此处data.level > 370需要确认
					let level = (lv > 370 && ("神创" + (lv - 370)) || (lv))
					// if (PlatformMgr.GetInstance().IsEyouEnPlatform() ) {
					// 	this._lb_unlock.text = "Lv." + level + " to unlock"
					// }else{
					this._lb_unlock.text = level + "级解锁"
					//}
				}
				// return "resource/game/dungeonMaterial/texture/material_level_" + (index + 1) + ".png"
				return "material_level_0" + (index + 1) + ""
			}
		}

		this.UpdateSweepingCount = () => {
			this._lb_sweep_count.text = "x" + goods_model.GetTypeGoodsNum(local_BaseDungeonModel.SWEEPING_GOODS_ID)
		}

		this.CheckBuyTimeEffect = () => {
			let left_times
			let dun_id = data_[now_index_].dun_id
			let dun_cfg = Config.GetConfigVo(Config.ConfigHasDefaultValue.config_dungeon.name, dun_id, false)
			let dun_list = dungeon_model.GetDungeonInfo(dun_type_)
			let vip_card = vip_model.GetNobleCardState()
			let vip_flag = role_mgr.GetMainRoleVo().vip_flag
			let value = VipModel.GetInstance().GetVipPrivilegeValue(local_BaseDungeonModel.MODULE_ID, local_BaseDungeonModel.VIP_PARAMETER + dun_type_, vip_card, vip_flag)
			for (let _tmpi in dun_list) {
				var v = dun_list[_tmpi]
				if (v.dun_id == dun_id) {
					left_times = Math.max(0, value - v.vip_count)
				}
			}
			if (left_times > 0) {
				this.AddUIEffect("UI_2102", this.layer_value, this._btn_add, null, null, true)
			} else {
				this.ClearUIEffect(this._btn_add)
			}
		}
	}

	public DeleteMe() {

		if (this.reward_item_list_) {
			for (let _tmpi in this.reward_item_list_) {
				var v = this.reward_item_list_[_tmpi]
				v.DeleteMe()
			}
		}
		this.reward_item_list_ = []
		super.DeleteMe()
	}


	public GetComponents() {
		[
			this._img_bg,
			this._Image1,
			this._lb_dungeon_name,
			this._Label1,
			this._lb_fight_count,
			this._btn_add,
			this._Label2,
			this._scroll_reward,
			this.Content,
			this._Image2,
			this._img_difficulty,
			this._img_lock,
			this._lb_unlock,
			this._btn_left,
			this._btn_right,
			this._Image4,
			this._lb_difficulty,
			this._btn_challenge,
			this._Image5,
			this.labelDisplay,
			this._gp_sweeping,
			this._Image3,
			this._Label3,
			this._point_icon,
			this._img_challenge_red,
			this._gp_effect,
			this._Group1,
			this._img_sweep_icon,
			this._lb_sweep_count,
		]
			= this.GetChildrenByNames([

				"_img_bg",
				"_Image1",
				"_lb_dungeon_name",
				"_Label1",
				"_lb_fight_count",
				"_btn_add",
				"_Label2",
				"_scroll_reward",
				"Content",
				"_Image2",
				"_img_difficulty",
				"_img_lock",
				"_lb_unlock",
				"_btn_left",
				"_btn_right",
				"_Image4",
				"_lb_difficulty",
				"_btn_challenge",
				"_Image5",
				"labelDisplay",
				"_gp_sweeping",
				"_Image3",
				"_Label3",
				"_point_icon",
				"_img_challenge_red",
				"_gp_effect",
				"_Group1",
				"_img_sweep_icon",
				"_lb_sweep_count",
			])
	}
}
window["DungeonMaterialEnterItem"] = DungeonMaterialEnterItem