		this.UnLockRedDot = (not_fire?) => {
			let show = false
			if (unlock_cfg_ && _has_receive_task_list && not_fire && curr_unlock_type) {
				let vo = null
				let task = null
				let stone_task = null
				let child_task = null
				for (let type in unlock_cfg_) {

					vo = unlock_cfg_[type]
					task = _has_receive_task_list[vo.active_task_id]
					if (task) {
						show = true
						for (let _tmpi in task) {
							var obj = task[_tmpi]
							if (obj.has_finish != 1) {
								show = false
								break
							}
						}
						if (show == false) {
							let i = 0
							do {
								stone_task = _has_receive_task_list[vo.stone_task_id_list[i].stone_task_id]
								if (stone_task) {
									show = true
									let [can_do, need_num] = this.CanDoThisTask(vo.stone_task_id_list[i].open_task_id)
									for (let _tmpi in stone_task) {
										var obj = stone_task[_tmpi]
										if (obj.has_finish != 1 || !can_do) {
											show = false
											break
										}
									}
								}
								if (show) {
									break
								}
								i = i + 1
							} while ((i < vo.stone_task_id_list.length))
						}
					}
					if (show) {
						break
					}
				}
			}
			if (!not_fire) {
				this.Fire(local_TaskModel.UPDATE_UNLOCK_RED_DOT)
			}
			return show
		}

