		this.GetNowShowLvRewardCfg = () => {
			if (!config_rush_giftbag_) {
				return [null, null, null]
			}
			if (!lv_reward_cfg_list_ || lv_reward_cfg_list_.length <= 0) {
				lv_reward_cfg_list_ = []

				for (let key in config_rush_giftbag_) {

					let cfg = config_rush_giftbag_[key]
					lv_reward_cfg_list_.push(cfg)
				}

				let sort_fun = (a?, b?) => {
					return a.bag_lv - b.bag_lv
				}

				lv_reward_cfg_list_.sort(sort_fun)
			}

			let show_lv = (lv_reward_cfg_list_[1] && (lv_reward_cfg_list_[1].bag_lv) || (0))
			// let data = WelfareModel.GetInstance().GetLevelRewardInfo()
			let data = null
			let can_receive = false
			if (data) {
				for (let _tmpi in data.giftbag_state) {
					var vo = data.giftbag_state[_tmpi]
					if (vo.received == 0 || vo.received == 1) {
						show_lv = vo.lv
						can_receive = vo.received == 1
						break
					}
				}
				let draw_over = true
				let list = data.giftbag_state
				for (let i in list) {
					var v = list[i]
					if (v.received != 2) {
						draw_over = false
						break
					}
				}
				if (draw_over) {
					show_lv = 0
				}
			}
			let lv = role_mgr.mainRoleInfo.level
			let cfg = null
			let last_cfg = null
			let now_cfg = null
			let i = 0
			do {
				cfg = lv_reward_cfg_list_[i]
				if (show_lv == Number(cfg.bag_lv)) {
					now_cfg = cfg
					last_cfg = lv_reward_cfg_list_[i - 1]
					break
				}
				i = i + 1
			} while ((i < lv_reward_cfg_list_.length))
			return [last_cfg, now_cfg, can_receive]
		}

		this.FindIndex = (task_id?, task_type?, is_finish?) => {
			let index = null
			let sub_index = null
			if (task_id && task_type) {
				let lv = role_mgr.mainRoleInfo.level
				let order_list = TypeSortOrder
				if (lv >= TaskModel.SortOrer2Level) {
					order_list = TypeSortOrder2
				}
				if (is_finish) {
					index = order_list["finish"]
					sub_index = order_list[task_type]
				} else {
					index = order_list[task_id]
					if (!index) {
						index = order_list[task_type]
						sub_index = order_list[task_type]
					}
				}
			}
			if (!index) {
				index = 99
			}
			if (!sub_index) {
				sub_index = 99
			}
			return [index, sub_index]
		}

