		this.PauseAutoDoTask = (bool?) => {

			//console.log("now_select_task_id////////////:", now_select_task_id)
			if (RoleManager.Instance.mainRoleInfo.level > TaskModel.GuideLevel) {
				console.log("暂停为false////////////-")
				pause_to_do_task = false
				return
			}
			if (now_select_task_id) {
				let task = this.GetHasReceiveTaskList(now_select_task_id)
				if (task && task[1]) {
					let task_vo = task[1]
					if (task_vo) {
						if (delay_id) {
							clearTimeout(delay_id)
							delay_id = null
						}
						// console.log("暂停为bool////////////-：", bool)
						pause_to_do_task = bool
						if (bool) {
							OperateManager.GetInstance().StopMove(true)  //先清掉当前场景的操作包，避免继续移动寻路
						} else {
							if (task_vo) {
								let delay_fun = () => {
									if (!StoryModel.GetInstance().HasFingerIsShowing() && this.GetAutoTaskSetting()) {
										this.DoTask(task_vo)
									}
								}
								delay_id = setTimeout(delay_fun, 0.4)
							}
						}
					}
				}
			}
		}

