import { BaseView1 } from "../common/BaseView1"
import { Config } from "../common/Config"
import { DownDropBtn } from "../common/DownDropBtn"
import { Enum_UILayer } from "../common/LayerManager"
import { ResManager } from "../common/ResManager"
import { LuaSoundManager } from "../common/SoundManager"
import { table } from "../common/table"
import { EquipModel } from "../commonModel/EquipModel"
import { GuildModel, GuildEvent } from "../commonModel/GuildModel"
import { Message } from "../sysinfo/SysInfoController"
import { Util } from "../util/Util"

export class GuildCleanView extends BaseView1 {
	Clear
	ClickDownDropColor
	ClickDownDropStage
	ClickDownDropStar
	FireEvent
	GetSelectEquips
	InitEvent
	LoadSuccess
	click_bg_toClose
	color_btn
	destroy_callback
	destroy_imm
	is_center
	show_open_movie
	stage_btn
	star_btn
	use_background

	public constructor() {
		super()


		this.base_file = "guild"
		this.layout_file = "GuildCleanView"
		this.layer_value = Enum_UILayer.UI
		this.layer_value = Enum_UILayer.Activity
		this.use_background = true
		this.click_bg_toClose = true
		this.is_center = true
		this.destroy_imm = true
		this.show_open_movie = true
		this.load_callback = () => {

			this.LoadSuccess()
		}

		this.destroy_callback = () => {
			this.Clear()
		}

		let model = GuildModel.GetInstance()
		let _set_stage = -1
		let _set_color = -1
		let _set_star = -1
		let stage_cfg = null
		let color_cfg = null
		let star_cfg = null
		let cfg_finish = null
		let local_GuildEvent = GuildEvent
		let local_ResManager = ResManager.GetInstance()
		let local_Message = Message
		this.preload_client_config = {
			"ConfigGuild": false
		}
		this.LoadSuccess = () => {
			let cfg = ResManager.GetInstance().GetGameConfigFromCache(this, "ConfigGuild", true)
			let list = []
			for (let _ in cfg.down_drop_apply_set_stage) {
				var v = cfg.down_drop_apply_set_stage[_]
				table.insert(list, v)
			}
			table.sort(list, (a?, b?) => {
				return a.cond < b.cond
			})

			this.stage_btn = new DownDropBtn(this._dd_stage)
			this.stage_btn.Init(list, this.ClickDownDropStage, "品阶选择", "content", this.layer_value, 5)
			this.stage_btn.Load()

			list = []
			for (let _ in cfg.down_drop_apply_set_color) {
				var v = cfg.down_drop_apply_set_color[_]
				table.insert(list, v)
			}
			table.sort(list, (a?, b?) => {
				return a.cond < b.cond
			})

			this.color_btn = new DownDropBtn(this._dd_color)
			this.color_btn.Init(list, this.ClickDownDropColor, "品质选择", "content", this.layer_value, 5)
			this.color_btn.Load()

			list = []
			for (let _ in cfg.down_drop_apply_set_star) {
				var v = cfg.down_drop_apply_set_star[_]
				table.insert(list, v)
			}
			table.sort(list, (a?, b?) => {
				return a.cond < b.cond
			})

			this.star_btn = new DownDropBtn(this._dd_star)
			this.star_btn.Init(list, this.ClickDownDropStar, "星数选择", "content", this.layer_value, 5)
			this.star_btn.Load()


			this.InitEvent()
			this.FireEvent()
		}

		this.Clear = () => {
			_set_stage = -1
			_set_color = -1
			_set_star = -1
			if (this.stage_btn) {
				this.stage_btn.DeleteMe()
				this.stage_btn = null
			}
			if (this.color_btn) {
				this.color_btn.DeleteMe()
				this.color_btn = null
			}
			if (this.star_btn) {
				this.star_btn.DeleteMe()
				this.star_btn = null
			}
		}

		this.FireEvent = () => {

		}

		this.InitEvent = () => {
			Util.AddClickEvent(this._btn_close, () => {
				this.Close()
			}
				, this, true, null, null, null, null, LuaSoundManager.SOUND_UI.CLOSE)
			Util.AddClickEvent(this._btn_cancel, () => {
				this.Close()
			}
				, this, true)
			Util.AddClickEvent(this._btn_go, () => {
				if (_set_stage < 0) {
					local_Message.show("还没选择品阶")
					return
				}
				if (_set_color < 0) {
					local_Message.show("还没选择品质")
					return
				}
				if (_set_star < 0) {
					local_Message.show("还没选择星数")
					return
				}
				let list = this.GetSelectEquips()
				if (list.length < 1) {
					local_Message.show("操作成功，共销毁0件装备")
				} else {
					model.Fire(local_GuildEvent.REQUEST_CLEAN, list)
				}
			}
				, this, true)
		}

		this.ClickDownDropStage = (index?, data?) => {
			_set_stage = data.cond
		}

		this.ClickDownDropColor = (index?, data?) => {
			_set_color = data.cond
		}

		this.ClickDownDropStar = (index?, data?) => {
			_set_star = data.cond
		}

		this.GetSelectEquips = () => {
			let equips = []
			let depot_info = model.GetDepotInfo()
			if (!depot_info) {
				return equips
			}
			let emodel = EquipModel.GetInstance()
			for (let _tmpi in depot_info.depot_goods) {
				var info = depot_info.depot_goods[_tmpi]
				if (info.color > _set_color) {
				} else {
					let equip_attr_cfg = local_ResManager.GetGameConfigFromCache(this, "Equipattr", false)
					if (emodel.GetStageByTypeId(info.type_id, equip_attr_cfg) > _set_stage) {
					} else {
						if (emodel.GetStarByTypeId(info.type_id, equip_attr_cfg) > _set_star) {
						} else {
							table.insert(equips, info.goods_id)
						}
					}
				}
			}
			return equips
		}


	}


	public DeleteMe() {

		super.DeleteMe()
	}



	_Image11: Laya.Image
	_Image3: Laya.Image
	_Image2: Laya.Image
	_lb_win_name: Laya.Label
	_btn_go: Laya.Box
	_Image1111: Laya.Image
	labelDisplay1: Laya.Label
	_btn_cancel: Laya.Box
	_Image1: Laya.Image
	labelDisplay: Laya.Label
	_btn_close: Laya.Box
	_Image111: Laya.Image
	labelDisplay11: Laya.Label
	_Label2: Laya.Label
	_dd_star: Laya.Box
	_dd_stage: Laya.Box
	_dd_color: Laya.Box
	public GetComponents() {
		[
			this._Image11,
			this._Image3,
			this._Image2,
			this._lb_win_name,
			this._btn_go,
			this._Image1111,
			this.labelDisplay1,
			this._btn_cancel,
			this._Image1,
			this.labelDisplay,
			this._btn_close,
			this._Image111,
			this.labelDisplay11,
			this._Label2,
			this._dd_star,
			this._dd_stage,
			this._dd_color,
		]
			= this.GetChildrenByNames([

				"_Image11",
				"_Image3",
				"_Image2",
				"_lb_win_name",
				"_btn_go",
				"_Image1111",
				"labelDisplay1",
				"_btn_cancel",
				"_Image1",
				"labelDisplay",
				"_btn_close",
				"_Image111",
				"labelDisplay11",
				"_Label2",
				"_dd_star",
				"_dd_stage",
				"_dd_color",
			])
	}
}
window["GuildCleanView"] = GuildCleanView