import { SetSizeDeltaX } from "../util/Util"
import { EveningMainConItem } from "./EveningMainConItem"

export class EveningIntroTextItem extends EveningMainConItem {
	_lb_content:Laya.Label
	data
	needRefreshData
	public static width = 400
	public static height = 20
	public constructor(parent) {
		super(parent)

		this.base_file = "evening"
		this.layout_file = "EveningMainConItem"
		this.load_callback=()=>{
			this._lb_content.x=20
			SetSizeDeltaX(this.display_obj, EveningIntroTextItem.width)
			SetSizeDeltaX(this._lb_content, EveningIntroTextItem.width-20)
			if (this.needRefreshData) {
				this.SetData(this.data)
				this.needRefreshData = false
			}
		}
	}



	public SetData(data?) {


		this.data = data || this.data

		if (this.is_loaded) {

			this._lb_content.text = this.data
			
			this.display_obj.height=this._lb_content.textField.textHeight+5
		} else {
			this.needRefreshData = true

		}

	}



}

window["EveningIntroTextItem"] = EveningIntroTextItem