import { BaseItem1 } from "../common/BaseItem1"
import { BaseItemRenderer } from "../common/BaseItemRenderer"
import { ResManager } from "../common/ResManager"
import { FashionModel } from "../commonModel/FashionModel"
import { GoodsModel } from "../commonModel/GoodsModel"
import { GameResPath } from "../util/GameResPath"
import { SetHtmlCenter, Util } from "../util/Util"

export class FashionItem extends BaseItemRenderer {
	fashion_group: Laya.Box
	fashion_icon_group: Laya.Box
	fashion_plate_image: Laya.Image
	_Group1: Laya.Box
	fashion_icon_image: Laya.Image
	select: Laya.Image
	fashion_red_image: Laya.Image
	fashion_waer_image: Laya.Image
	Image: Laya.Image
	name_box:Laya.Box
	fashion_name_label: Laya.HTMLDivElement
	cache_bool
	pos_id


	public static width = 143
	public static height = 189
	public constructor(parent) {
		super()
		this.HEIGT=143
		this.WIDTH=189

		this.base_file = "fashion"
		this.layout_file = "FashionItem"
		// this.load_callback = () => {
		// this.skinName = "resource/game/fashion/exml/FashionItemExml.exml"
		// 	// if (PlatformMgr.GetInstance().IsEyouEnPlatform() ) {

		// 	// }
		// }
		this.Load()

	}

	public load_callback(){
		this.display_obj.scale(0.8,0.8)
	}

	public dataChanged() {
		if(super.dataChanged()){
			if (this.data) {
				this.pos_id = this.data[2]
			}
			this.select.visible = this.selected
			this.SetItemShow()
		}
		
	}

	public SetItemShow() {


		if (!this.data || !this.data[0]) {
			return
		}
		this.fashion_name_label.width=100
		let goodinfo = GoodsModel.GetInstance().GetGoodsBasicByTypeId(this.data[0])
		if (!goodinfo) { return }
		if (goodinfo) {
			this.fashion_name_label.innerHTML = Util.StrToHTML(GoodsModel.GetGoodsNameWithColorDark(this.data[0]))
		}
		//this.fashion_plate_image.source = "common_asset.com_goods_plate_" + goodinfo.color
		ResManager.GetInstance().SetImageSprite(this, this.fashion_plate_image, "common_asset", "com_goods_plate_" + goodinfo.color)
		ResManager.GetInstance().SetOutsideImageSprite(this, this.fashion_icon_image, GameResPath.GetGoodsIconPath(goodinfo.goods_icon))
		let infoList = FashionModel.GetInstance().fashion_info_list[this.pos_id]
		if (!infoList) { return }
		let id = infoList["wear_fashion_id"]
		let id1 = this.data[0]
		if (infoList && id == id1) {
			this.fashion_waer_image.visible = true
		} else {
			this.fashion_waer_image.visible = false
		}
		let bool = FashionModel.GetInstance().isRed(this.pos_id, this.data[0])
		this.fashion_red_image.visible = bool
		//let redList = FashionModel.GetInstance().fashion_red_list[this.pos_id]
		//if (redList && redList[this.data[0*/ ) {

		//}else{
		//this.fashion_red_image.visible = false  
		//}
		let activeList = FashionModel.GetInstance().fashion_activate_list[this.pos_id]
		if (activeList && activeList[this.data[0]]) {
			if (this.cache_bool != false) {
				this.cache_bool = false
				Util.SetImageGray(this.fashion_icon_image, false)
				Util.SetImageGray(this.fashion_plate_image, false)
			}
		} else {
			if (this.cache_bool != true) {
				this.cache_bool = true
				Util.SetImageGray(this.fashion_icon_image, true)
				Util.SetImageGray(this.fashion_plate_image, true)
			}
			// this.fashion_name_label.innerHTML = Util.StrToHTML("<font color='#9c9c9c'>" + goodinfo.goods_name + "</font>")
		}
		this.SetHtmlCenterX(this.fashion_name_label,this.name_box.width)

	}
	public SetHtmlCenterX(html_obj?, w?) {
		if (!html_obj) {
			return
		}
		// html_obj.width = w
		html_obj.x = w / 2 - html_obj.contextWidth / 2
	}

	public GetComponents() {
		[
			this.fashion_group,
			this.fashion_icon_group,
			this.fashion_plate_image,
			this._Group1,
			this.fashion_icon_image,
			this.select,
			this.fashion_red_image,
			this.fashion_waer_image,
			this.Image,
			this.fashion_name_label,
			this.name_box
		]
			= this.GetChildrenByNames([

				"fashion_group",
				"fashion_icon_group",
				"fashion_plate_image",
				"_Group1",
				"fashion_icon_image",
				"select",
				"fashion_red_image",
				"fashion_waer_image",
				"Image",
				"fashion_name_label",
				"name_box"
			])
			this.fashion_name_label.style.fontSize=22
			this.fashion_name_label.style.color="#9c9c9c"
	}
}
window["FashionItem"] = FashionItem