import { LayerManager } from "../common/LayerManager"
import { table } from "../common/table"
import { MainUIModel } from "../commonModel/MainUIModel"
import { SYTweenFunc } from "../util/SYTweenFunc"
import { SYTweenLite } from "../util/SYTweenLite"


export class EveningResetPosVo {

    is_show //是否展示主界面
    pos_x           //再次出现的位置
    hide_p       //隐藏点

    //数据保存
    obj_save = {}
    is_destroy = false

    tween_ids
    count:number=0

    public constructor() {
        this.is_destroy = false
        this.tween_ids = []
    }

    public Remove() {
        this.count=0
        this.StopAnimate()
        this.obj_save={}
        this.is_destroy = true
    }


    public StopAnimate() {

        if (this.tween_ids) {
            for (let _ in this.tween_ids) {
                var key = this.tween_ids[_]
                SYTweenLite.Stop(key)
            }
            this.tween_ids = []
        }
    }

    public PushComp(key: string, comp, offset_x?) {
        if (this.is_destroy) return
        this.count++
        let arr = [comp, offset_x]
        this.obj_save[key] = arr
    }

    public UpdatePos = (is_show?) => {
        if (this.is_destroy) return

        this.hide_p = (LayerManager.GetInstance().stageWidth / 2 - 720 / 2)
        this.is_show = is_show

        let key, arr
        let is_w_over: boolean = LayerManager.GetInstance().stageWidth > 720

        if (this.is_show) {
            this.pos_x = -this.hide_p
            for (key in this.obj_save) {
                arr = this.obj_save[key]
                if (arr[0]) {
                    arr[0].x = is_w_over ? this.pos_x + arr[1] : arr[1]
                }
            }
            return
        }

        
        this.pos_x = is_w_over ? -this.hide_p : 0
        if (!is_w_over) this.hide_p = 0

      
        for (key in this.obj_save) {
            arr = this.obj_save[key]
            if (arr[0]) {
                arr[0].x = is_w_over ? this.pos_x + arr[1] : arr[1]
            }
        }
    }

    public SwitchMain(is_show?) {
        this.StopAnimate()
        this.is_show = is_show
        this.hide_p = -(LayerManager.GetInstance().stageWidth / 2 - 720 / 2)

        let key, arr
        let ct:number=0

        if(!is_show)this.SetVisible(true)
        for (key in this.obj_save) {
            arr = this.obj_save[key]
            if (arr[0]) {

                if (is_show) {
                    table.insert(this.tween_ids, SYTweenLite.to(this, arr[0], SYTweenLite.UiAnimationType.ANCHORED_POSX,
                        this.hide_p - arr[0].width - arr[1], MainUIModel.Move_Time_Interval, () => {
                            ct++
                            if(ct>=this.count){
                                this.SetVisible(false)
                            }
                        }, SYTweenFunc.linear, false))

                } else {
                    table.insert(this.tween_ids, SYTweenLite.to(this, arr[0], SYTweenLite.UiAnimationType.ANCHORED_POSX,
                        this.pos_x + arr[1], MainUIModel.Move_Time_Interval, () => {
                            ct++
                            if(ct>=this.count){
                            }
                        }, SYTweenFunc.linear, false))
                }

            }
        }


    }


    SetVisible(boo?){
        let key, arr
        for (key in this.obj_save) {
            arr = this.obj_save[key]
            if (arr[0]) {
                arr[0].visible=boo
            }
        }

    }


}
window["EveningResetPosVo"] = EveningResetPosVo