import { BaseItem1 } from "../common/BaseItem1"
import { BaseItemRenderer } from "../common/BaseItemRenderer"
import { ResManager } from "../common/ResManager"
import { GoodsModel } from "../commonModel/GoodsModel"
import { GameResPath } from "../util/GameResPath"
import { TimeUtil } from "../util/TimeUtil"
import { GlobalTimerQuest, Util } from "../util/Util"
export class MainUIBuffItem extends BaseItemRenderer {

	timer_id

	public constructor() {
		super()
		this.base_file = "mainUI"
		this.layout_file = "MainUIBuffItem"

		this.load_callback = () => {
			this.LoadSuccess()
		}
		this.Load()
	}

	LoadSuccess() {
		this.InitEvent()
	}

	public dataChanged() {
		if (!super.dataChanged()) {
			return
		}
		ResManager.GetInstance().SetOutsideImageSprite(this.base_item, this._img_buff, GameResPath.GetIcon("bufficon", this.data.cfg.icon))
		this._lb_name.text = this.data.cfg.name
		if (this.data.time != 0 && this.data.time != null) {
			if (typeof (this.data.time) == "string") {
				this._lb_time.text = this.data.time
			} else {
				if (!this.timer_id) {
					this.timer_id = GlobalTimerQuest.AddPeriodQuest(() => {
						if (this.data && this._lb_time) {
							if(this.data.end_time == undefined)
								this.data.end_time = TimeUtil.getServerTime() + this.data.time
							if (this.data.end_time && this.data.end_time >= TimeUtil.getServerTime()) {
								//this.data.time=this.data.time-1
								this._lb_time.text = TimeUtil.convertTimeColor(this.data.end_time - TimeUtil.getServerTime())
							} else {
								this.CancelTimer()
								GoodsModel.GetInstance().Fire(GoodsModel.GET_GOODS_BUFF_LIST)
							}
						}
					}, 0.5)
				}
				this.data.end_time = TimeUtil.getServerTime() + this.data.time
				this._lb_time.text = TimeUtil.convertTimeColor(this.data.end_time - TimeUtil.getServerTime())
			}
		} else {
			this._lb_time.text = ""
		}
		if (this.data.show_des || this.data.des) {
			this._html_desc.style.color = "#7b5250"
			this._html_desc.style.fontSize = 16
			this._html_desc.style.width = 224
			this._html_desc.style.leading = 8
			this._html_desc.innerHTML = this.data.show_des || this.data.des
		}
		let show_btn = this.data.key == "mengmr"
		this._gp_info.visible = show_btn
		this._img_help.visible = show_btn
	}

	public SetData(data?) {

		this.data = data
		if (typeof (this.data.time) == "string") {
			this.data.end_time = 0
		} else {
			this.data.end_time = TimeUtil.getServerTime() + this.data.time
		}

		if (this.is_loaded) {

		}
	}

	public CancelTimer() {
		if (this.timer_id) {
			GlobalTimerQuest.CancelQuest(this.timer_id)
			this.timer_id = false
		}
	}

	public InitEvent() {

	}

	public DeleteMe() {
		this.CancelTimer()
		super.DeleteMe()
	}

	_Group1: Laya.Box
	_Image1: Laya.Image
	_img_buff: Laya.Image
	_img_help: Laya.Image
	_lb_name: Laya.Label
	_lb_time: Laya.Label
	_gp_info: Laya.Box
	_Image2: Laya.Image
	_Label1: Laya.Label
	_lb_desc: Laya.Label
	_html_desc: Laya.HTMLDivElement
	public GetComponents() {
		[
			this._Group1,
			this._Image1,
			this._img_buff,
			this._img_help,
			this._lb_name,
			this._lb_time,
			this._gp_info,
			this._Image2,
			this._Label1,
			this._lb_desc,
			this._html_desc,
		]
			= this.GetChildrenByNames([

				"_Group1",
				"_Image1",
				"_img_buff",
				"_img_help",
				"_lb_name",
				"_lb_time",
				"_gp_info",
				"_Image2",
				"_Label1",
				"_lb_desc",
				"_html_desc",
			])
	}
}
window["MainUIBuffItem"] = MainUIBuffItem