import { BaseView1 } from "../common/BaseView1"
import { Config } from "../common/Config"
import { EquipmentItem } from "../common/EquipmentItem"
import { Enum_UILayer } from "../common/LayerManager"
import { ResManager } from "../common/ResManager"
import { LuaSoundManager } from "../common/SoundManager"
import { GoodsModel } from "../commonModel/GoodsModel"
import { GuildModel, GuildEvent } from "../commonModel/GuildModel"
import { Enum_ColorUtil_Dark } from "../util/ColorUtil"
import { ErlangParser } from "../util/ErlangParser"
import { Util, HtmlColorTxt } from "../util/Util"

export class GuildHelpTipsView extends BaseView1 {
    Clear
    Emp_btn_cancel
    Emp_btn_go
    InitEvent
    LoadSuccess
    OutlabelDisplay
    OutlabelDisplay1
    Scr_Scroller1
    _btn_cancel
    _btn_close
    _btn_go
    _data
    _gp_item
    _item_list
    _lb_tips
    _model
    brightSea_model
    destroy_callback
    destroy_imm
    is_center
    use_background

    public constructor() {
        super()

        this.base_file = "guild"
        this.layout_file = "GuildHelpTipsViewExml"
        this.layer_value = Enum_UILayer.Activity
        this.destroy_imm = true
        this.use_background = true
        this.is_center = true
        this._model = GuildModel.GetInstance()
        // this.brightSea_model = BrightSeaModel.GetInstance()
        this.load_callback = () => {

            this.InitEvent()
            this.LoadSuccess()
        }

        this.destroy_callback = () => {
            this.Clear()
        }

        this.Clear = () => {
            if (this._item_list) {
                for (let _tmpi in this._item_list) {
                    var item = this._item_list[_tmpi]
                    item.DeleteMe()
                }
                this._item_list = null
            }
        }

        this.InitEvent = () => {
            Util.AddClickEvent(
                this._btn_close, () => {
                    this.Close()
                },
                this,
                true,
                null,
                null,
                null,
                null,
                LuaSoundManager.SOUND_UI.CLOSE
            )
            Util.AddClickEvent(
                this._btn_cancel, () => {
                    this.Close()
                },
                this,
                true
            )
            Util.AddClickEvent(
                this._btn_go, () => {
                    if (this._data.extra && this._data.extra.length > 0) {
                        let extra = this._data.extra[1]
                        this.brightSea_model.enemy_fight = extra.rober_power
                    }
                    this._model.Fire(GuildEvent.REQUEST_PROTO, 40402, "lc", this._data.assist_id, this._data.type)
                },
                this,
                true
            )
        }

        this.LoadSuccess = () => {
            let data = this._data
            let nameStr = HtmlColorTxt(data.name, Enum_ColorUtil_Dark.GREEN)
            let str = "是否开始进行对" + nameStr + "的协助\n协助完成后将获得以下奖励："
            this._lb_tips.textFlow = Util.StrToHTML(str)

            if (data.type == 3) {
                // 璀璨之海
                let extra = data.extra[1]
                let reward
                if (extra) {
                    reward = extra.rober_reward
                }
                if (reward) {
                    this._item_list = this._item_list || {}
                    let index = 1
                    let reward_tb = GoodsModel.RewardKeyToNumber(reward)
                    for (let key in reward_tb) {

                        let vo = reward_tb[key]
                        let ret = this.brightSea_model.LoadAndRefreshAwardItem(vo, this._gp_item, this._item_list, index, this.layer_value, 75)
                        if (ret) {
                            index = index + 1
                        }
                    }
                }
            } else {
                ResManager.GetInstance().LoadGameConfig(this, "config_guild_assist", false, null, (guild_assist) => {
                    let cfg = guild_assist
                    cfg = cfg[data.type + "@" + data.sub_type]
                    let gmodel = GoodsModel.GetInstance()
                    this._item_list = []
                    let list = cfg && ErlangParser.GetInstance().Parse(cfg.rewards) || {}
                    for (let i = 1; i <= list.length; i++) {
                        let vo = list[i]
                        let item = new EquipmentItem(this._gp_item, null, "Activity")
                        item.Load()
                        item.SetItemSize(96, 96)
                        let type_id, lock = gmodel.GetMappingTypeId(vo[1], vo[2])
                        item.SetData(type_id, vo[3], lock)
                        this._item_list[i] = item
                    }
                    ResManager.GetInstance().DestoryGameConfig(this, "config_guild_assist")
                })

            }
        }
    }

    public Open(parms?) {

        this._data = parms
        super.Open()
    }

}

window["GuildHelpTipsView"] = GuildHelpTipsView