import { BaseItem1 } from "../common/BaseItem1"
import { ResManager } from "../common/ResManager"
import { table } from "../common/table"
import { GuildActivityModel, GuildActEvent } from "../commonModel/GuildActivityModel"
import { Enum_ColorUtil_Light } from "../util/ColorUtil"
import { TimeUtil } from "../util/TimeUtil"
import { Split, Util } from "../util/Util"

export class EveningFireView extends BaseItem1 {
    _fire_info
    _timer_id
    fire_item_list
    max_wave
    model
    percentHeight
    percentWidth
    preload_client_config
    preload_server_config


    InitView
    InitEvent
    FireEvent
    public constructor(parent?) {
        super(parent)

        this.model = GuildActivityModel.GetInstance();
        this.max_wave = 0;
        this.base_file = "evening"
        this.layout_file = "EveningFireView"
        this.percentWidth = 100
        this.percentHeight = 100
        // this.preload_client_config = [ConfigGuildAct=false]
        // this.preload_server_config = [Gfeast=false]


        this.InitView = () => {
            this.fire_item_list = []
        }

        this.InitEvent = () => {
            // Util.AddClickEvent(this._btn_exit, () => {
            //     this.model.Fire(GuildActEvent.REQUEST_PROTO, 40218)
            // }
            //     , this, true)
            this.BindVar(this.model, "fire_info", (event_name?, value?, old_value?) => {
                this._fire_info = value
                this.SetTimer(value)
            }
            )
            this.BindEvent(this.model, GuildActEvent.UPDATE_EXP, (info?) => {
                this.UpdateExp(info)
            }
            )
        }

        this.FireEvent = () => {
            this.model.Fire(GuildActEvent.REQUEST_PROTO, 40255, "c", 1)
            this.model.Fire(GuildActEvent.REQUEST_PROTO, 40256)
        }


        this.load_callback = () => {
            this.max_wave = Number(ResManager.GetInstance().GetGameConfigFromCache(this, "Gfeast", false)[36]["value"])
            this.InitView()
            this.InitEvent()
            this.FireEvent()
        }
    }



    public DeleteMe() {
        this.Clear()
        super.DeleteMe()
    }

    public Clear() {
        this.ClearTimer()
        this.fire_item_list = []
    }



    UpdateFireItemsAfterPick(info) {
        let fire_info = info || this.model.GetFireInfo()
        if (!fire_info) {
            return
        }
        if (fire_info.fire_list.length < 1) {
            return
        }
        for (let key in this.fire_item_list) {

            // [ts2lua]this.fire_item_list下标访问可能不正确
            this.fire_item_list[key].visible = false
        }
        let i = 0
        do {
            do {
                let info = fire_info.fire_list[i]
                // [ts2lua]this.fire_item_list下标访问可能不正确
                let fire_group = this.fire_item_list[info.fire_id]
                if (!fire_group) {
                    break
                }
                fire_group.visible = true
            } while (true
            )
            i = i + 1
        } while ((i < fire_info.fire_list.length)
        )
    }

    UpdateFireItems(info) {
        let fire_info = info || this.model.GetFireInfo()
        if (!fire_info) {
            return
        }
        if (fire_info.fire_list.length < 1) {
            return
        }
        // [ts2lua]lua_resM:GetGameConfigFromCache(this, "ConfigGuildAct", true)下标访问可能不正确
        let fire_cfg = ResManager.GetInstance().GetGameConfigFromCache(this, "ConfigGuildAct", true)["fire_cfg"]
        // [ts2lua]lua_resM:GetGameConfigFromCache(this, "ConfigGuildAct", true)下标访问可能不正确
        let pos_list = ResManager.GetInstance().GetGameConfigFromCache(this, "ConfigGuildAct", true)["fire_pos_cfg"]
        // let clone_list = pos_list.slice(0)
        let clone_list = table.remove(pos_list, 1)
        let i = 0
        do {
            let info = fire_info.fire_list[i]
            // [ts2lua]this.fire_item_list下标访问可能不正确
            let fire_group = this.fire_item_list[info.fire_id]
            if (!fire_group) {
                // fire_group = eui. new Group()
                // fire_group.width = 70
                // fire_group.height = 70
                // this._group_fire.addChild(fire_group)
               // fire_group = NewImage(this, this._group_fire, Vector2(70, 70), "UI")
                // [ts2lua]this.fire_item_list下标访问可能不正确
                this.fire_item_list[info.fire_id] = fire_group
                Util.AddClickEvent(fire_group, () => {
                    this.model.Fire(GuildActEvent.REQUEST_PROTO, 40257, "i", info.fire_id)
                }
                    , this, true)
            }
            // this.ClearUIEffect(fire_group)
            // [ts2lua]fire_cfg下标访问可能不正确
            // this.AddUIEffect2(fire_cfg[info.color].effect, fire_group, {x=30, y=30}, 1.5, true)
            // fire_group.touchEnabled = true
            let rand = Math.floor(Math.random()* clone_list.length)
            // [ts2lua]clone_list下标访问可能不正确
            let pos = clone_list[rand]
            fire_group.x = pos[0]
            fire_group.y = pos[1]
            clone_list.slice(rand, 1)
            i = i + 1
        } while ((i < fire_info.fire_list.length)
        )
    }

    SetTimer(info) {
        this.ClearTimer()
        let wave = info.wave + 1
        let etime = info.next_time
        if (etime <= 0) {
            this._lb_tips.text = "【篝火阶段】即将结束"
            return
        }
        this.SetTimeText(etime - TimeUtil.getServerTime(), wave)
        // this._timer_id = Laya.new Timer(1000, 0)
        // this._timer_id.addEventListener(Laya.TimerEvent.TIMER, this.UpdateTimer, this)
        // this._timer_id.start()
    }

    UpdateTimer() {
        let rtime = this._fire_info.next_time - TimeUtil.getServerTime()
        if (rtime < 0) {
            this.ClearTimer()
        } else {
            this.SetTimeText(rtime, this._fire_info.wave + 1)
        }
    }

    SetTimeText(rtime, wave) {
        let str1 = Util.HtmlColorTxt(rtime, Enum_ColorUtil_Light.GREEN)
        let str2 = Util.HtmlColorTxt(wave + "/" + this.max_wave, Enum_ColorUtil_Light.GREEN)
        this._lb_tips.text =`${str1}秒后出现第${str2}波火苗` //Util.StrToHTML(str1 + "秒后出现第" + str2 + "波火苗")
    }

    ClearTimer() {
        // if (this._timer_id) {
        //     this._timer_id.stop()
        //     this._timer_id.removeEventListener(Laya.TimerEvent.TIMER, this.UpdateTimer, this)
        //     this._timer_id = null
        // }
    }

    UpdateExp(info) {
        this._lb_exp.text = "+" + info.exp
    }

    _group_fire: Laya.Box
    _Group2: Laya.Box
    _Image1: Laya.Image
    _Label1: Laya.Label
    _lb_tips: Laya.Label
    _Group1: Laya.HBox
    _Label2: Laya.Label
    _Image2: Laya.Image
    _lb_exp: Laya.Label
    public GetComponents() {
        [
            this._group_fire,
            this._Group2,
            this._Image1,
            this._Label1,
            this._lb_tips,
            this._Group1,
            this._Label2,
            this._Image2,
            this._lb_exp,
        ]
            = this.GetChildrenByNames([

                "_group_fire",
                "_Group2",
                "_Image1",
                "_Label1",
                "_lb_tips",
                "_Group1",
                "_Label2",
                "_Image2",
                "_lb_exp",
            ])
    }
}

window["EveningFireView"]=EveningFireView


