import { BaseItem1 } from "../common/BaseItem1"
import { EventName } from "../common/EventName"
import { LoopScrCon, LoopScrowViewMgr } from "../common/LoopScrowViewMgr"
import { ResManager } from "../common/ResManager"
import { GuildModel, GuildEvent } from "../commonModel/GuildModel"
import { MainFunc } from "../commonModel/MainUIModel"
import { TaskModel, TaskTipType } from "../commonModel/TaskModel"
import { RoleManager } from "../role/RoleManager"
import { Message } from "../sysinfo/SysInfoController"
import { GlobalEventSystem } from "../util/DeclareGlobalVar"
import { Util } from "../util/Util"
import { GuildJoinItem } from "./GuildJoinItem"

export class GuildJoinView extends BaseItem1 {

	FireEvent
	InitEvent
	LoadSuccess
	UpdateRedDot
	UpdateView
	loop_mgr
	model
	story_obj_list

	public constructor(parent?) {
		super(parent)


		this.model = GuildModel.GetInstance();
		this.base_file = "guild"
		this.layout_file = "GuildJoinView"
		let data_list = null
		let local_GuildEvent = GuildEvent
		let local_Util = Util
		let local_ResManager = ResManager.GetInstance()
		this.load_callback = () => {

			this.LoadSuccess()
			//GlobalEventSystem:Fire(EventName.SELECT_STORY_TARGET, StoryModel.StoryTargetName.GuildIcon, false)
		}

		this.LoadSuccess = () => {
			if (this.task_model.MainTaskIsJoinGuildTaskType()) {
				let main_line_vo = this.task_model.GetMainLineTaskVo()
				if (main_line_vo && !this.task_model.IsAllStepFinish(main_line_vo.task_id)) {
					this.task_model.Fire(TaskModel.REQUEST_CCMD_EVENT, 30008)
				}
			}

			this.InitEvent()
			this.FireEvent()
		}

		this.FireEvent = () => {
			this.model.Fire(local_GuildEvent.REQUEST_PROTO, 40001, "shh", "", 999, 1)
		}

		this.InitEvent = () => {
			Util.AddClickEvent(this._btn_build, () => {
				if (GuildModel.IsHasGuild()) {
					Message.show("您当前已有所属公会")
					return
				}
				this.model.Fire(local_GuildEvent.OPEN_VIEW, "GuildBuildView")
			}
				, this, true)
			Util.AddClickEvent(this._btn_apply, () => {
				if (GuildModel.IsHasGuild()) {
					Message.show("您当前已有所属公会")
					return
				}
				if (!data_list || data_list.length < 1) {
					Message.show("暂无公会")
					return
				}
				this.model.Fire(local_GuildEvent.REQUEST_PROTO, 40003)
			}
				, this, true)
			Util.AddClickEvent(this._btn_tips, () => {
				if (GuildModel.IsHasGuild()) {
					Message.show("您当前已有所属公会")
					return
				}
				this.model.Fire(local_GuildEvent.OPEN_VIEW, "GuildBuildView")
			}
				, this, true)
			this.BindEvent(this.model, local_GuildEvent.UPDATE_JION_LIST, (list?) => {
				data_list = list
				this.UpdateView(list)
			}
			)
			this.BindEvent(this.model, local_GuildEvent.APPLY_APPROVE, (guild_id?) => {
				if (!data_list) {
					return
				}
				for (let _tmpi in data_list) {
					var info = data_list[_tmpi]
					if (info.guild_id == guild_id) {
						info.is_apply = 1
						break
					}
				}
				this.UpdateView(data_list)
			}
			)
			this.BindVar(RoleManager.GetInstance().GetMainRoleVo(), "guild_id", (type?, value?, old_value?) => {
				if (old_value == 0) {
					this._reddot.visible = false
					this.create_reddot.visible = false
					this.model.apply_red_mark = true
				}
			}
			)
		}

		this.UpdateView = (list?) => {

			//let next_collect = eui. new ArrayCollection(list)
			//this._group_data.dataProvider = next_collect
			//this._group_data.itemRenderer = GuildJoinItem

			if (!this.loop_mgr) {
				this.loop_mgr = new LoopScrowViewMgr()
				this.loop_mgr.SetData(this._list_items, GuildJoinItem, list, LoopScrCon.Vertical)
			} else {
				this.loop_mgr.replaceAll(list)
			}

			this._group_empty.visible = list.length < 1
			if (!this.model.apply_red_mark) {
				this.UpdateRedDot(list)
			}
		}

		this.UpdateRedDot = (list?) => {
			let can_join = false
			if (list && list.length > 0) {
				for (let _tmpi in list) {
					var vo = list[_tmpi]
					if (vo.member_capacity > vo.member_num) {
						can_join = true
						break
					}
				}
			}
			this._reddot.visible = can_join
			this.create_reddot.visible = !can_join
		}


	}

	public createChildren() {

		this.story_obj_list = this.story_obj_list || {}
		// [ts2lua]this.story_obj_list下标访问可能不正确
		this.story_obj_list[TaskTipType.JoinGuild] = [this._btn_apply]
		super.createChildren()
	}

	public DeleteMe() {

		if (this.loop_mgr) {
			this.loop_mgr.DeleteMe()
			this.loop_mgr = null
		}
		this.model.apply_red_mark = true
		this.model.Fire(GuildEvent.UPDATE_BASE_RED_STATUS)
		GlobalEventSystem.Fire(EventName.REFRESH_FUNCTION_ICON_RED_DOT, MainFunc.Guild)
		super.DeleteMe()
	}



	_bg: Laya.Image
	_Image111: Laya.Image
	_btn_build: Laya.Box
	_Image1111: Laya.Image
	labelDisplay11: Laya.Label
	_btn_apply: Laya.Box
	_Image11: Laya.Image
	labelDisplay1: Laya.Label
	_reddot: Laya.Image
	create_reddot: Laya.Image
	_list_items: Laya.List
	_group_empty: Laya.Box
	_Image2: Laya.Image
	_Label1: Laya.Label
	_btn_tips: Laya.Box
	_Image1: Laya.Image
	labelDisplay: Laya.Label
	public GetComponents() {
		[
			this._bg,
			this._Image111,
			this._btn_build,
			this._Image1111,
			this.labelDisplay11,
			this._btn_apply,
			this._Image11,
			this.labelDisplay1,
			this._reddot,
			this.create_reddot,
			this._list_items,
			this._group_empty,
			this._Image2,
			this._Label1,
			this._btn_tips,
			this._Image1,
			this.labelDisplay,
		]
			= this.GetChildrenByNames([

				"_bg",
				"_Image111",
				"_btn_build",
				"_Image1111",
				"labelDisplay11",
				"_btn_apply",
				"_Image11",
				"labelDisplay1",
				"_reddot",
				"create_reddot",
				"_list_items",
				"_group_empty",
				"_Image2",
				"_Label1",
				"_btn_tips",
				"_Image1",
				"labelDisplay",
			])
	}
}
window["GuildJoinView"] = GuildJoinView