export class GuildMainView extends BaseItem1 {
	CheckGuildMaster
	FireEvent
	GetUpgradeMoney
	InitConfig
	InitEvent
	InitItems
	InitView
	SetMoney
	UpdateView


	horizontalCenter
	//item_list
	y
	loop_mgr


	public constructor(parent?) {
		super(parent)


		//this.item_list = [];
		this.base_file = "guild"
		this.layout_file = "GuildMainView"
		this.horizontalCenter = 0
		this.y = 10
		let model = GuildModel.GetInstance()
		let cfg = null
		let cfg_finish = false
		let can_board = false
		let board_mark = null
		let local_Util = Util
		let local_ResManager = ResManager.GetInstance()
		let local_GuildEvent = GuildEvent
		let local_Message = Message
		this.preload_client_config = {
			"ConfigGuild": false
		}
		this.preload_server_config = {
			"config_guild_lv": false
		}
		this.load_callback = () => {
			this.InitConfig()
			this.InitView()
			this.InitItems()
			this.InitEvent()
			this.FireEvent()


			ResManager.GetInstance().SetOutsideImageSprite(this, this._img_jiejie_b, GameResPath.GetIcon("guild", "com_title_bg_4"), true)

		}

		//this.preload_server_config = [Guildlv=false]

		this.InitConfig = () => {
			cfg = ResManager.GetInstance().GetGameConfigFromCache(this, "ConfigGuild", true)
			// cfg = this.preload_client_config["ConfigGuild"]
			//if (this.use_delete_method ) {
			//lua_resM:DestroyAllReferenceRes(this.hashCode)
			//return
			//}
			cfg_finish = true
			if (this.is_loaded) {
				this.InitItems()
			}
		}

		this.InitView = () => {

		}

		this.FireEvent = () => {
			model.Fire(local_GuildEvent.REQUEST_PROTO, 40005)
		}

		this.InitEvent = () => {
			Util.AddClickEvent(this._image_5, () => {
				local_Message.show("尊贵的会长，拥有至高无上的“拳腻”")
			}
				, this, true)
			Util.AddClickEvent(this._image_6, () => {
				local_Message.show("公会等级越高，可容纳成员上限越高")
				
			}
				, this, true)
			Util.AddClickEvent(this._image_7, () => {
				local_Message.show("公会等级提升的必要资源")
			}
				, this, true)
			Util.AddClickEvent(this._image_8, () => {
				local_Message.show("公会成员的总战力！")
			}
				, this, true)
			let board_func = () => {
				let data = model.GetGuildInfo()
				if (!data) {
					return
				}
				if (!can_board) {
					local_Message.show("没有修改权限")
					return
				}
				model.Fire(local_GuildEvent.OPEN_VIEW, "GuildBoardView", data.announce)
			}

			Util.AddClickEvent(this._lb_board, () => {
				board_func()
			}
				, this)
			Util.AddClickEvent(this._btn_up_guild, () => {
				Message.show("升级公会")
			}, this, true)

			this.BindVar(model, "guild_info", () => {
				this.UpdateView()
			}
			)


			Util.AddClickEvent(this._btn_board, () => {
				board_func()
			}, this, true)


			this.BindVar(model, "gfunds", () => {
				this._lb_money.innerHTML = String(model.GetFunds())
			}
			)
		}

		this.UpdateView = () => {
			let data = model.GetGuildInfo()
			if (!data) {
				return
			}
			this._lb_guildname.text = data.guild_name
			this._lb_board.text = data.announce
			this._lb_level.text = "Lv." + data.guild_lv
			this._lb_power.text = data.combat_power
			this._lb_member.text = data.member_num + "/" + data.member_capacity
			let master_figure = model.GetTopMemberVo(1)
			// [ts2lua]lua中0和空字符串也是true，此处master_figure需要确认
			this._lb_mastername.text = (master_figure && (master_figure.name) || ("暂无"))
			can_board = model.HasPermission(GuildPermission.MODIFY_TENET_AND_ANNOUNCE)
			this.SetMoney(data.gfunds, this.GetUpgradeMoney())
		}

		this.InitItems = () => {
			if (!cfg_finish) {
				return
			}
			if (!cfg) {
				return
			}
			let list = []
			for (let _ in cfg.main_func) {
				var v = cfg.main_func[_]
				table.insert(list, v)
			}
			table.sort(list, (a?, b?) => {
				return a.index < b.index
			})

			// let result = true
			// for (let _tmpi in list) {
			// 	var info = list[_tmpi]
			// 	let con
			// 	let item = this.item_list[info.id]
			// 	if (!item) {
			// 		if (Number(info.id) == 8) {
			// 			result = this.CheckGuildMaster()
			// 		} else if (Number(info.id) == 11) {
			// 			result = model.GuildIdolIsOpen()
			// 		}
			// 		if (!result) {
			// 			result = true
			// 			con = true
			// 		} else {
			// 			item = new GuildMainItem(this._group_item)
			// 			item.Load()
			// 			// [ts2lua]this.item_list下标访问可能不正确
			// 			this.item_list[info.id] = item

			// 		}
			// 	}
			// 	if (!con && item) {
			// 		item.ExcuteCallback(() => {
			// 			item.SetData(info)
			// 		}
			// 		)
			// 	}
			// }

			let is_open = true
			let list_infos = []
			for (let _tmpi in list) {
				var info = list[_tmpi]
				let con
				is_open = true

				if (Number(info.id) == 8) {
					is_open = this.CheckGuildMaster()
				} else if (Number(info.id) == 11) {
					is_open = model.GuildIdolIsOpen()
				}
				if (is_open) {
					list_infos.push(info)
				}
			}

			if (!this.loop_mgr) {
				this.loop_mgr = new LoopScrowViewMgr()
				this.loop_mgr.SetData(this._group_item, GuildMainItem, list_infos, LoopScrCon.Vertical)
			} else {
				this.loop_mgr.replaceAll(list_infos)
			}

			this._group_item.scrollBar.touchScrollEnable = false
		}



		this.CheckGuildMaster = () => {
			return GuildModel.IsGuildMaster()
		}

		this.SetMoney = (gfunds?, need?) => {
			let str = HtmlColorTxt(gfunds, Enum_ColorUtil_Dark.GREEN)
			this._lb_money.style.fontSize = 18;
			this._lb_money.style.size(100, 24)
			this._lb_money.innerHTML = Util.StrToHTML(` ${str}/${need}`)
		}

		this.GetUpgradeMoney = () => {
			let guild_info = model.GetGuildInfo()
			if (!guild_info) {
				return "-"
			}
			let Guildlv = local_ResManager.GetGameConfigFromCache(this, "config_guild_lv", false)
			// [ts2lua]Guildlv下标访问可能不正确
			let cfg = Guildlv && Guildlv[guild_info.guild_lv]
			if (!cfg || !cfg.growth_val_limit) {
				return "已满级"
			}
			return cfg.growth_val_limit
		}

		// this.InitConfig()
	}


	public DeleteMe() {

		// for (let key in this.item_list) {

		// 	// [ts2lua]this.item_list下标访问可能不正确
		// 	this.item_list[key].DeleteMe()
		// }
		// this.item_list = []

		if (this.loop_mgr) {
			this.loop_mgr.DeleteMe()
			this.loop_mgr = null
		}

		super.DeleteMe()
	}



	_img_jiejie_bg: Laya.Image
	_img_jiejie_b: Laya.Image
	_Image2: Laya.Image
	_image_1: Laya.Image
	_image_2: Laya.Image
	_image_3: Laya.Image
	_image_4: Laya.Image
	_image_5: Laya.Image
	_image_6: Laya.Image
	_image_7: Laya.Image
	_image_8: Laya.Image
	_img_title_bg: Laya.Image
	_lb_mastername: Laya.Label
	_lb_member: Laya.Label
	_lb_money: Laya.HTMLDivElement
	_lb_power: Laya.Label
	_lb_level: Laya.Label
	_lb_guildname: Laya.Label
	_lb_board: Laya.Label
	_group_item: Laya.List
	_btn_board: Laya.Image
	_btn_up_guild: Laya.Box
	_btn_up_img: Laya.Image
	public GetComponents() {
		[
			this._img_jiejie_bg,
			this._img_jiejie_b,
			this._Image2,
			this._image_1,
			this._image_2,
			this._image_3,
			this._image_4,
			this._image_5,
			this._image_6,
			this._image_7,
			this._image_8,
			this._img_title_bg,
			this._lb_mastername,
			this._lb_member,
			this._lb_money,
			this._lb_power,
			this._lb_level,
			this._lb_guildname,
			this._lb_board,
			this._group_item,
			this._btn_board,
			this._btn_up_guild,
			this._btn_up_img,
		]
			= this.GetChildrenByNames([

				"_img_jiejie_bg",
				"_img_jiejie_b",
				"_Image2",
				"_image_1",
				"_image_2",
				"_image_3",
				"_image_4",
				"_image_5",
				"_image_6",
				"_image_7",
				"_image_8",
				"_img_title_bg",
				"_lb_mastername",
				"_lb_member",
				"_lb_money",
				"_lb_power",
				"_lb_level",
				"_lb_guildname",
				"_lb_board",
				"_group_item",
				"_btn_board",
				"_btn_up_guild",
				"_btn_up_img",
			])
	}
}
window["GuildMainView"]=GuildMainView