import { BaseItem1 } from "../common/BaseItem1"

export class CheckBox extends BaseItem1 {
	//public

    public  checkImg:Laya.Image
    public  checkLabel 
    public  selected
    private call_back
    private check_text
	public constructor(parent,call_back?,check_text?) {
		super(parent)
		this.base_file = "alert"
		this.layout_file = "TheCheckBox"
        this.selected=false;
        this.call_back=call_back
        this.check_text=check_text
        this.load_callback=()=>{
            this.LoadSuccess()
            this.InitEvent()
        }
	}

	public LoadSuccess() {
		// [this.checkImg,this.checkLabel]=this.GetChildrenByNames(["checkImg","checkLabel"])
        this.checkLabel.text= this.check_text ? this.check_text : "本次登录不再提示"

	}

    public InitEvent(){
        this.checkImg.on(Laya.Event.CLICK,this,()=>{
            if(this.checkImg.skin.indexOf("gx1")==-1){
                this.checkImg.skin="resource/game/alert/texture/com_ui_gx1.png"
                this.selected=true
                if (this.call_back) {
                    this.call_back(this.selected)
                }
            }else{
                this.checkImg.skin="resource/game/alert/texture/com_ui_gx.png"
                this.selected=false
                if (this.call_back) {
                    this.call_back(this.selected)
                }

            }
        })

    }

    public GetComponents(){
        [this.checkImg,
            this.checkLabel,] =
            this.GetChildrenByNames(
                ["checkImg"
                , "checkLabel",])
    }
}
window["CheckBox"] = CheckBox