export class FightingShowSmallItem extends BaseItem1 {
    public _gp_fire_effect: Laya.Box;
    public _Group1: Laya.Box;
    public _img: Laya.Image;
    public _lb_fighting: Laya.Label;
    public _lb_fighting2: Laya.Text;

    LoadSuccess

    UpdateView

    Updatefighting
    Font_name: string = "fighting_font"
    bitmapFont: Laya.BitmapFont
    onLoaded
    is_center_x
    is_center_y

    public constructor(parent) {
        super(parent)

        let _fire_effect_index_ = null
        let _fighting = null
        let _load_state = false
        let _need_refresh = false
        this.base_file = "common"
        this.layout_file = "FightingShowSmallItem"
        // this.skinName = "resource/game/common/exml/FightingShowSmallSkin.exml";
        this.load_callback = () => {
        //    this.GetComponents()
            // this._Group1 = this.GetChild("_Group1")
            // this._gp_fire_effect = this.GetChild("_gp_fire_effect").gameObject
            // this._img = this.GetChild("_Group1/_Image1").GetComponent("Image")
            // this._lb_fighting = this.GetChild("_Group1/_lb_fighting").GetComponent("Text")
            this.LoadSuccess()
            ResManager.GetInstance().LoadFont(this, "fighting_font", this._lb_fighting, null, false)
        }

        this.LoadSuccess = () => {
            _load_state = true
            // this.form.pivot = Vector2(0.5, 1)
            // this.form.anchorMin = Vector2(0.5, 1)
            // this.form.anchorMax = Vector2(0.5, 1)
            if (_need_refresh) {
                this.UpdateView()
            }
            this.SetCenter()
        }   

        this.Updatefighting = (fighting?) => {
            _fighting = fighting
            if (_load_state) {
                this.UpdateView()
            } else {
                _need_refresh = true
            }
        }


        this.UpdateView = () => {
            if (!_load_state) {
                return
            }
            let fighting = _fighting

            this._lb_fighting.text = String(fighting)
            // this._lb_fighting.font=this.Font_name
            let len = fighting.length
            let index = 10
            let width = 290
            if (len < 6) {
                index = 6
                width = 230
            } else if (len > 5 && len < 8) {
                index = 8
                width = 260
            } else if (len > 7) {
                index = 10
                width = 290
            }
            //if (index != _fire_effect_index_ ) {
            //let pos = Vector2(-(width - this.width) / 2, 0)
            //if (this._gp_fire_effect ) {
            //lua_resM:ClearUIEffect(this._gp_fire_effect)
            let layer = this.layer_value || "UI"
            // ResManager.GetInstance().SetUIEffect(this,"UI_1104", layer, this._gp_fire_effect.transform, null, null, true)

            // let curr_sorting_order = this.AddCurrLayerSortingOrder(layer)
            // this.CoverEffect(this._Group1, layer, curr_sorting_order)
            //}
            //}
            _fire_effect_index_ = index
            // SetSizeDeltaX(this, 64 + this._lb_fighting.preferredWidth) //GetSizeDeltaX(this._lb_fighting.transform)
            // UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(this._Group1)
        }

    }

    // public DeleteMe(){ 

    //if (this._gp_fire_effect ) {
    //lua_resM:ClearUIEffect(this._gp_fire_effect)
    //}
    // }

    public IsCenter(centerx?,centery?){
        if(centerx){
            this.is_center_x=true
        }
        if(centery){
            this.is_center_y=true
        }
        this.SetCenter()
    }
    public SetCenter(){
        if(!this.display_obj){
            return 
        }
        if (this.is_center_x)
        {
            if(this._lb_fighting.width>109){
                this.display_obj.width=this._img.width+this._lb_fighting.width-109
            }
            this.display_obj.centerX=0
        }   
        if(this.is_center_y){
            this.display_obj.centerY=0
        }
    }
    public GetComponents() {
        [
            this._gp_fire_effect,
            this._Group1,
            this._img,
            this._lb_fighting,
        ]
            = this.GetChildrenByNames([

                "_gp_fire_effect",
                "_Group1",
                "_img",
                "_lb_fighting",
            ])
    }
}
window["FightingShowSmallItem"] = FightingShowSmallItem