import { BaseComponent } from "./BaseComponent";
import { BaseClass } from "./BaseClass";
import { LOAD_QUEUE } from "../util/DeclareGlobalVar";
import { UIModelClass3D } from "./UIModelClass3D";
import { ResManager } from "./ResManager";
import { GameResPath } from "../util/GameResPath";
import { GetTargetHashcode } from "../util/Util";
import { LayerManager } from "./LayerManager";
export class UIEffect extends BaseComponent {
    private gameObject_dic = null
    private cameraObject_dic = null
    private renderTexture_dic = null
    public constructor() {
        super();
    }
    public ClearUIEffect = (parent_con: Laya.Sprite, destroy_go = true) => {
        if (parent_con) {
            parent_con.removeChildren();
            let p_hashcode = GetTargetHashcode(parent_con)
            if(destroy_go && this.gameObject_dic)
            {
                let gameObject_list = this.gameObject_dic[p_hashcode]
                if(gameObject_list)
                {
                    for(let i = 0; i < gameObject_list.length; i ++)
                    {
                        let gameObject = gameObject_list[i]
                        if(gameObject)
                        {
                            gameObject.destroy()
                        }
                    }
                    delete this.gameObject_dic[p_hashcode]
                }
            }
            if(this.cameraObject_dic)
            {
                let camera = this.cameraObject_dic[p_hashcode]
                if(camera)
                {
                    camera.destroy()
                    delete this.cameraObject_dic[p_hashcode]
                }
            }
            if(this.renderTexture_dic)
            {
                let renderTexture = this.renderTexture_dic[p_hashcode]
                if(renderTexture)
                {
                    renderTexture.destroy()
                    delete this.renderTexture_dic[p_hashcode]
                }
            }
        }
    };
    public DeleteMe()
    {
        if(this.gameObject_dic)
        {
            for(let has_code in this.gameObject_dic)
            {
                let gameObject_list = this.gameObject_dic[has_code]
                if(gameObject_list)
                {
                    for(let i = 0; i < gameObject_list.length; i ++)
                    {
                        let gameObject = gameObject_list[i]
                        if(gameObject)
                        {
                            gameObject.destroy()
                        }
                    }
                }
            }
            this.gameObject_dic = null
        }
        if(this.cameraObject_dic)
        {
            for(let has_code in this.cameraObject_dic)
            {
                let camera = this.cameraObject_dic[has_code]
                if(camera)
                {
                    camera.destroy()
                }
            }
            this.cameraObject_dic = null
        }
        if(this.renderTexture_dic)
        {
            for(let has_code in this.renderTexture_dic)
            {
                let renderTexture = this.renderTexture_dic[has_code]
                if(renderTexture)
                {
                    renderTexture.destroy()
                }
            }
            this.renderTexture_dic = null
        }
        super.DeleteMe()
    }
       /**
     * 添加ui粒子特效
     * @param res_name 特效名字
     * @param parent 父容器 注意设置好位置和大小
     * @param position 位置，修改的是粒子特效的位置而不是父容器的位置
     * @param scale 粒子特效的缩放大小
     * @param is_loop 是否循环
     * @param last_time 持续时间，播放多久时间后销毁掉 单位秒
     * @param playend_call_back_func 播放last_time的时间后回调
     * @param load_finish_func 加载完粒子特效回调
     * @param hash_target 资源持有对象，一般在不销毁的类中播放特效时，手动创建一个BaseClass对象传进来，然后自己控制销毁
     * @param multi_children 是否支持同时显示多个子特效 默认一个父容器同时只能播放一个粒子特效
     * @param rotation 粒子特效旋转值
     * @param load_queue 加载队列，一般无视
     * @language zh_CN
     */
    public AddUIEffect = (res_name, parent: Laya.Sprite, position?, scale?, is_loop?, last_time?, playend_call_back_func?, load_finish_func?, hash_target?: BaseClass, multi_children ?, rotation?, load_queue: LOAD_QUEUE = LOAD_QUEUE.LOW) => {
        if (res_name && parent && parent instanceof Laya.Sprite) {
            let p_hashcode = GetTargetHashcode(parent)
            let curr_pos_index = UIModelClass3D.CURR_POS_INDEX;
            let scene:Laya.Scene3D = LayerManager.GetInstance().Scene3D
            if(multi_children)
            {
                if(parent["childEffect_pos_index"])
                {
                    curr_pos_index = parent["childEffect_pos_index"]
                }else
                {
                    parent["childEffect_pos_index"] = curr_pos_index
                    UIModelClass3D.CURR_POS_INDEX ++;
                }
            }else
            {
                if(this.gameObject_dic)
                {
                    let gameObject_list = this.gameObject_dic[p_hashcode]
                    if(gameObject_list)
                    {
                        for(let i = 0; i < gameObject_list.length; i ++)
                        {
                            let gameObject = gameObject_list[i]
                            if(gameObject)
                            {
                                gameObject.destroy()
                            }
                        }
                        delete this.gameObject_dic[p_hashcode]
                    }
                }
                UIModelClass3D.CURR_POS_INDEX ++;
            }
            var load_call_back = (obj:Laya.Sprite3D)=> {
                if (!obj) {
                    console.warn("!!!!!!!!!!!!!!!!!!!!ParticleEffect 找不到特效资源" + res_name)
                    return
                }
                if (this.use_delete_method) {
                    obj.destroy()
                    return
                }
                this.gameObject_dic = this.gameObject_dic || {}
                this.gameObject_dic[p_hashcode] = this.gameObject_dic[p_hashcode] || []

                this.gameObject_dic[p_hashcode].push(obj)
                scene.addChild(obj)
                let curr_obj_index = this.gameObject_dic[p_hashcode].length
                let pos_x = curr_pos_index * UIModelClass3D.POS_STEP_VALUE;
			    let pos_y = curr_pos_index * UIModelClass3D.POS_STEP_VALUE;
                if (position)
				{
					pos_x += position.x
					pos_y += position.y
				}
                let transform = obj.transform
                transform.localPosition = new Laya.Vector3(pos_x, pos_y, 0);
                transform.localRotationEuler = new Laya.Vector3(0, rotation || 0, 0)
                scale = scale || 1
                transform.localScale = new Laya.Vector3(1 * scale, 1 * scale, 1 * scale)
                is_loop = is_loop || false
                // let particles = obj.getComponentsInChildren(window["ParticleComponent"], true);
                // let len = particles.length;
                // let particle;
                // for (let i = 0; i < len; i++)
                // {
                //     particle = particles[i];
                //     particle.main.loop = is_loop;
                // }
                if (last_time && last_time > 0) {
                    let onDelay = () => {
                        if (!this.use_delete_method) {

                            obj.destroy()
                            if(this.gameObject_dic)
                            {
                                let gameObject_list = this.gameObject_dic[p_hashcode]
                                if(gameObject_list)
                                {
                                    gameObject_list.splice(curr_obj_index, 1)
                                }
                            }
                            if (playend_call_back_func) {
                                playend_call_back_func();
                            }
                        }
                    };
                    setTimeout(onDelay, last_time * 1000);
                }
                if (load_finish_func)
                    load_finish_func(obj);
            }
            let hashCode = hash_target && hash_target.hashCode || this.hashCode
            // ResManager.GetInstance().CreatePrefab(hashCode, GameResPath.GetUIEffectPath(res_name), load_call_back, load_queue)
            Laya.Sprite3D.load(ResManager.GetInstance().cdn_res_path + GameResPath.GetUIEffectPath(res_name), Laya.Handler.create(null, (sp:Laya.Sprite3D) =>{
                if(sp&&load_call_back)
                {
                    load_call_back(sp.clone() as Laya.Sprite3D)
                }
            }));
            if(multi_children && this.cameraObject_dic && this.cameraObject_dic[p_hashcode])
            {
                return
            }
            this.ClearUIEffect(parent, false)
           
            let camera:Laya.Camera = scene.addChild(new Laya.Camera(0, 0.3, 1000)) as Laya.Camera
            this.cameraObject_dic = this.cameraObject_dic || {}
            this.cameraObject_dic[p_hashcode] = camera
            camera.transform.localPosition = new Laya.Vector3(curr_pos_index * UIModelClass3D.POS_STEP_VALUE, curr_pos_index * UIModelClass3D.POS_STEP_VALUE, -10);
            camera.transform.localRotationEuler = new Laya.Vector3(0, 180, 0)
            camera.transform.localScale = new Laya.Vector3(1, 1, 1)
            //清除摄像机的标记
            // camera.clearFlag = Laya.CameraClearFlags.DepthOnly;
            camera.clearFlag = Laya.CameraClearFlags.SolidColor;
            camera.clearColor = new Laya.Vector4(0.0, 0.0, 0.0, 0.0);
            camera.enableHDR = false
            camera.orthographic = true
            camera.fieldOfView = 60
            camera.orthographicVerticalSize = 12.8;
            let renderTexture = Laya.RenderTexture.createFromPool(parent.width * 1, parent.height * 1,Laya.RenderTextureFormat.R8G8B8A8, Laya.RenderTextureDepthFormat.DEPTH_16)
            camera.renderTarget = renderTexture
            this.renderTexture_dic = this.renderTexture_dic || {}
            this.renderTexture_dic[p_hashcode] = renderTexture
            var img = new Laya.Image();
            img.source = new Laya.Texture(renderTexture)
            parent.addChild(img);
        }
    };
}

window["UIEffect"] = UIEffect