import { EventDispatcher } from "../util/EventDispatcher";
import { GlobalEventSystem } from "../util/DeclareGlobalVar";
import { EventName } from "./EventName";
// import { BaseWindowComponent } from "./BaseWindowComponent";
// TypeScript file
export enum Enum_UILayer {
    Scene,
    Shadow,
    SceneObj,
    NameBoard,
    UIRoot,
    Main,
    UI,
    Activity,
    Top,
    Message,
    FightingUp,
    AwySvip,
    ClickEffect
}
window["Enum_UILayer"] = Enum_UILayer;
export class LayerManager extends EventDispatcher {
    public gpu_size_label;
    private static _instance: LayerManager;
    private _stage: Laya.Stage;
    private _scene3d:Laya.Scene3D
    private _stageWidth: number = 0;
    private _stageHeight: number = 0;
    public srcStageWidth: number = 1; //最开始的舞台宽度
    public srcStageHeight: number = 1; //最开始的舞台高度
    public camera_base_size:number = 12.8;
    private _last_renderTexture
    SetFrameRate;
    InitUILayer;
    GetUILayer;
    UpdateUILayer;
    public constructor() {
        super();
        let local_laya = Laya, local_Enum_UILayer = Enum_UILayer, _ui_layer_list_: Array<Laya.Box> = [], 
        //每层对应的名字 用来调试的时候看的更清晰
        _layer_name_ = ["scene", "Shadow", "sceneObj", "NameBoard", "UIRoot", "Main", "UI", "Activity", "Top", "Message", "FightUp", "AwySvip", "ClickEffect"], _gp_message_con_, _gp_fighting_con_;
        this.SetFrameRate = (frameRate) => {
            this._stage.frameRate = frameRate;
            window["render_time"] = 1000 / frameRate;
        };
        this.InitUILayer = () => {
            let layer: Laya.Box;
            let ui_root;
            for (let i = 0; i < _layer_name_.length; i++) {
                layer = new Laya.Box();
                if (i <= local_Enum_UILayer.NameBoard) {
                    layer.width = 100;
                    layer.height = 100;
                    if (i == local_Enum_UILayer.Scene) {
                        this._stage.addChild(layer);
                    }
                    else {
                        _ui_layer_list_[local_Enum_UILayer.Scene].addChild(layer);
                    }
                }
                else {
                    layer.width = this._stage.width;
                    layer.height = this._stage.height;
                    if (i == local_Enum_UILayer.UIRoot) {
                        this._stage.addChild(layer);
                        ui_root = layer;
                    }
                    else {
                        ui_root.addChild(layer);
                    }
                }
                // layer.includeInLayout = false
                if (i == local_Enum_UILayer.UIRoot) {
                    layer.mouseEnabled = true;
                }
                else {
                    if (layer)
                    {
                        layer.mouseThrough = true;
                    }
                    layer.mouseEnabled = true;
                }
                layer.name = _layer_name_[i];
                _ui_layer_list_[i] = layer;
            }
            let onClickHandler = () => {
                GlobalEventSystem.Fire(EventName.STAGE_CLICK_EVENT);
            };
            this._stage.on(local_laya.Event.CLICK, this, onClickHandler);
        };
        this.GetUILayer = (layer_value: number) => {
            let layer = _ui_layer_list_[layer_value];
            if (layer) {
                return layer;
            }
            else {
                console.error("can not get uilayer name is = ", layer_value);
            }
        };
        
        this.UpdateUILayer = (need_refresh_screen:boolean = false) => {
            // let BaseWindowComponent = window["BaseWindowComponent"]
            // BaseWindowComponent.is_full_screen = null;
            for (let layer_value in _ui_layer_list_) {
                if (Number(layer_value) > local_Enum_UILayer.NameBoard) {
                    let layer = _ui_layer_list_[layer_value];
                    if (layer) {
                        layer.width = this._stage.width;
                        layer.height = this._stage.height;
                    }
                }
            }
        };
    }
    public static GetInstance() {
        if (!LayerManager._instance) {
            LayerManager._instance = new LayerManager();
        }
        return LayerManager._instance;
    }
    public set stage(value: Laya.Stage) {
        this._stage = value;
    }
    public get stage() {
        return this._stage;
    }
    public set stageWidth(value: number) {
        this._stageWidth = value;
    }
    public get stageWidth() {
        return this._stageWidth;
    }
    public set stageHeight(value: number) {
        this._stageHeight = value;
    }
    public get stageHeight() {
        return this._stageHeight;
    }
    public set Scene3D(value:Laya.Scene3D)
    {
        this._scene3d = value
    }
    public get Scene3D()
    {
        return this._scene3d
    }
}
window["LayerManager"] = LayerManager