import { BaseItem1 } from "../common/BaseItem1"
import { BaseView1 } from "../common/BaseView1"
import { LoopScrCon, LoopScrowViewMgr } from "../common/LoopScrowViewMgr"
import { GuildEvent, GuildModel, GuildPermission } from "../commonModel/GuildModel"
import { Message } from "../sysinfo/SysInfoController"
import { TimeUtil } from "../util/TimeUtil"
import { Util } from "../util/Util"
import { GuildMemberItem } from "./GuildMemberItem"

export class GuildMemberView extends BaseItem1 {
	FireEvent
	InitEvent
	StartScroll
	UpdateView
	loop_mgr
	preload_server_config

	public constructor(parent?) {
		super(parent)
		this.layer_value = "UI"
		this.base_file = "guild"
		this.layout_file = "GuildMemberView"
		this.dependent_res = ["mainUI", "guild"]
		this.preload_server_config = {"config_guild_prestige":true}
		let local_GuildEvent = GuildEvent
		let model = GuildModel.GetInstance()
		let apply_click_time = 0
		let permission_set = false
		let permission_email = false
		let permission_apply = false
		let local_Util = Util
		let local_TimeUtil = TimeUtil
		let local_GuildPermission = GuildPermission
		this.load_callback = () => {
			
			this.UpdateView()
			this.InitEvent()
			this.FireEvent()
		}

		this.FireEvent = () => {
			model.Fire(local_GuildEvent.REQUEST_PROTO, 40006)
		}

		this.InitEvent = () => {
			Util.AddClickEvent(this._btn_set, () => {
				if (!model.HasPermission(local_GuildPermission.APPROVE_SETTING)) {
					Message.show("您没有操作权限")
					return
				}
				model.Fire(local_GuildEvent.OPEN_VIEW, "GuildApplySetView")
			}
				, this, true)
			Util.AddClickEvent(this._btn_apply, () => {
				if (!model.HasPermission(local_GuildPermission.APPROVE_APPLY)) {
					Message.show("您没有操作权限")
					return
				}
				if (model.apply_request_mark) {
					return
				}
				let time = local_TimeUtil.getServerTime()
				let c = apply_click_time
				if (local_TimeUtil.getServerTime() - apply_click_time > 5) {
					model.apply_request_mark = true
					apply_click_time = local_TimeUtil.getServerTime()
					model.Fire(local_GuildEvent.REQUEST_PROTO, 40008)
				} else {
					let apply_info = model.GetApplyInfo()
					if (apply_info && apply_info.apply_list.length > 0) {
						model.Fire(local_GuildEvent.OPEN_VIEW, "GuildApplyLookView")
					}
				}
			}
				, this, true)

			
			this.BindVar(model, "member_info", () => {
				this.UpdateView()
			}
			)
			this.red.visible = model.apply_red
			

			this.BindVar(model, "apply_red", () => {
				this.red.visible = model.apply_red
			})

			//this._scroller.addEventListener(Laya.UIEvent.CHANGE_START, this.StartScroll, this)

		}

		this.StartScroll = () => {
			//model:Fire(local_GuildEvent.CLOSE_ROLE_MENU_VIEW)
		}

		this.UpdateView = () => {
			let member_info = model.GetMemberInfo()
			if (!member_info) {
				return
			}

			// let list = member_info.member_list
			// let arr_1=[]
			// for(let i=0;i<20;i++){
			// 	arr_1.push(list[0])
			// }

			if (!this.loop_mgr) {
				this.loop_mgr = new LoopScrowViewMgr()
				this.loop_mgr.SetData(this._list_menber, GuildMemberItem, member_info.member_list, LoopScrCon.Vertical)
			} else {
				this.loop_mgr.replaceAll(member_info.member_list)
			}
		}

	}

	public DeleteMe() {

		
		//if (this._scroller ) {
		//this._scroller.addEventListener(Laya.UIEvent.CHANGE_START, this.StartScroll, this)
		//}
		if (this.loop_mgr) {
			this.loop_mgr.DeleteMe()
			this.loop_mgr = null
		}
		super.DeleteMe()
	}


	_Image3: Laya.Image
	_list_menber: Laya.List
	_Group2: Laya.Box
	_btn_set: Laya.Box
	_Image1: Laya.Image
	labelDisplay1: Laya.Label
	_btn_apply: Laya.Box
	_Image11: Laya.Image
	labelDisplay: Laya.Label
	red: Laya.Image
	public GetComponents() {
		[
			this._Image3,
			this._list_menber,
			this._Group2,
			this._btn_set,
			this._Image1,
			this.labelDisplay1,
			this._btn_apply,
			this._Image11,
			this.labelDisplay,
			this.red,
		]
			= this.GetChildrenByNames([

				"_Image3",
				"_list_menber",
				"_Group2",
				"_btn_set",
				"_Image1",
				"labelDisplay1",
				"_btn_apply",
				"_Image11",
				"labelDisplay",
				"red",
			])
	}
}

window["GuildMemberView"]=GuildMemberView