import { BaseView1 } from "../common/BaseView1"
import { EquipmentItem } from "../common/EquipmentItem";
import { Enum_UILayer } from "../common/LayerManager";
import { GoodsModel } from "../commonModel/GoodsModel";
import { TaskModel, TaskType } from "../commonModel/TaskModel";
import { ErlangParser } from "../util/ErlangParser";
import { GlobalTimerQuest, Util } from "../util/Util";

export class TaskGuildFinishView extends BaseView1 {

    SetTaskReward
    InitEvent
    _Local_Open
    CancelTime
    LoadSuccess
    StartTime
    OnTime
    InitView

    public constructor() {
        super()


        this.base_file = "task"
        this.layout_file = "TaskGuildFinishView"
        this.layer_value = Enum_UILayer.Activity
        this.destroy_imm = true
        this.use_background = true
        this.click_bg_toClose = false
        this.show_open_movie = true
        this.is_delay_callback = false
        this.not_show_main_msg = true
        this.is_center = true
        let model = TaskModel.GetInstance()
        let local_Util = Util
        let local_laya = Laya
        let task_vo_ = null
        let item_list_ = null
        let close_time_ = 5
        let time_event_id_ = null
        let all_num_ = null
        let finish_num_ = null
        this.load_callback = () => {
            this.LoadSuccess()
            this.InitEvent()
        }

        this.open_callback = () => {
            this.InitView()
        }

        this.destroy_callback = () => {
            this.CancelTime()
            if (item_list_) {
                for (let _tmpi in item_list_) {
                    var item = item_list_[_tmpi]
                    item.DeleteMe()
                    item = null
                }
                item_list_ = null
            }
        }

        this.LoadSuccess = () => {
            item_list_ = []
            close_time_ = 5
        }

        this.InitEvent = () => {
            let close_fun = () => {
                this.Close()
            }
            local_Util.AddClickEvent(this.closeBtn, close_fun, this, true, null, null, null, null)
            local_Util.AddClickEvent(this.finishBtn, close_fun, this, true)
        }

        this._Local_Open = (...new_args) => {
            let param = new_args
            task_vo_ = param[0], all_num_ = param[1], finish_num_ = param[2]
            super.Open()
        }

        this.InitView = () => {
            this.SetTaskReward()
            this.StartTime()
        }

        this.SetTaskReward = () => {
            if (!task_vo_) {
                return
            }
            let award_list = []
            if (task_vo_.task_type == TaskType.GUILD) {
                if (task_vo_.circle_task_normal_reward) {
                    let format_fun = (list?) => {
                        for (let _tmpi in list) {
                            var vo = list[_tmpi]
                            let obj = []
                            obj[0] = vo.type
                            obj[1] = vo.type_id
                            obj[2] = vo.count
                            award_list.push(obj)
                        }
                    }
                    format_fun(task_vo_.circle_task_normal_reward)
                    format_fun(task_vo_.circle_task_extra_reward)
                }
            } else {
                award_list = ErlangParser.GetInstance().Parse(task_vo_.award_list)
            }
            if (item_list_) {
                for (let _tmpi in item_list_) {
                    var item = item_list_[_tmpi]
                    item.visisble = false
                }
            }
            if (award_list && award_list.length > 0) {
                let item = null
                let vo = null
                let i = 0
                do {
                    item = item_list_[i]
                    vo = award_list[i]
                    if (!item) {
                        item = new EquipmentItem(this.Content)
                        item_list_[i] = item
                        item.Load()
                        item.SetScale(0.6)
                    }
                    let [type_id, lock] = GoodsModel.GetInstance().GetMappingTypeId(vo[0], vo[1])
                    item.SetData(type_id, vo[2])
                    i = i + 1
                } while ((i < award_list.length))
            }
        }

        this.StartTime = () => {
            this.CancelTime()
            if (!this.task_model.GetAutoTaskSetting()) {
                if (this.finishBtnLabel) {
                    this.finishBtnLabel.text = "Confirm"
                }
                return
            }
            var peorid_func = () => {
                if (!this.use_delete_method) {
                    this.OnTime()
                }
            }
            time_event_id_ = GlobalTimerQuest.AddPeriodQuest(peorid_func, 1, -1)
            this.OnTime()
        }

        this.OnTime = () => {
            close_time_ = close_time_ - 1
            if (close_time_ <= 0) {
                this.finishBtnLabel.text = "确定"
                this.CancelTime()
                this.Close()
                return
            }
            this.finishBtnLabel.text = "确定(" + close_time_ + ")"
        }

        this.CancelTime = () => {
            if (time_event_id_) {
                GlobalTimerQuest.CancelQuest(time_event_id_)
                time_event_id_ = null
            }
        }
    }

    public Open(...new_args) {
        this._Local_Open(...new_args)
    }
    _Image2: Laya.Image
    _Image3: Laya.Image
    bg: Laya.Image
    closeBtn: Laya.Image
    _Image5: Laya.Image
    _Image6: Laya.Image
    _Image7: Laya.Image
    first_line: Laya.Label
    sec_line: Laya.Label
    tips: Laya.Label
    _Scroller1: Laya.Panel
    Content: Laya.HBox
    finishBtn: Laya.Box
    _Image8: Laya.Image
    finishBtnLabel: Laya.Label
    public GetComponents() {
        [
            this._Image2,
            this._Image3,
            this.bg,
            this.closeBtn,
            this._Image5,
            this._Image6,
            this._Image7,
            this.first_line,
            this.sec_line,
            this.tips,
            this._Scroller1,
            this.Content,
            this.finishBtn,
            this._Image8,
            this.finishBtnLabel,
        ]
            = this.GetChildrenByNames([

                "_Image2",
                "_Image3",
                "bg",
                "closeBtn",
                "_Image5",
                "_Image6",
                "_Image7",
                "first_line",
                "sec_line",
                "tips",
                "_Scroller1",
                "Content",
                "finishBtn",
                "_Image8",
                "finishBtnLabel",
            ])
    }
}
window["TaskGuildFinishView"] = TaskGuildFinishView