	public UnBindVo(){ 
		
		if (this.vo ) {
			this.vo.ResetData()
			if (this.vo_bind_handlers ) {
				for (let _ in this.vo_bind_handlers) {
					var handler = this.vo_bind_handlers.pop()
					this.vo.UnBind(handler)
				}
				this.vo_bind_handlers = []
			}
			if (this.vo_ext_bind_handlers ) {
				for (let _ in this.vo_ext_bind_handlers) {
					var handler = this.vo_ext_bind_handlers.pop()
					this.vo.UnBind(handler)
				}
				this.vo_ext_bind_handlers = []
			}
			if (this.GetType() != SceneBaseType.MainRole ) {
				this.vo.UnBindAll()
			}
		}
	}
	
	public ClearRole(){ 
		
		this.DeleteSprite()
		this.DeleteEvil()
		this.DeleteGoddess()
		this.DeletePet()
		this.DeleteBaby()
		this.DeleteStarSoul()
		this.DeleteAssisitStarSoul()
		this.DeleteGuard()
		this.DeletePartner()
		this.DeleteDemon()
		this.DeleteShengqi()
		this.RemoveAllParticle()
		this.SetShieldForceCreateEffect(false)
		this.UnBindVo()
		if (this.GetType() != SceneBaseType.MainRole ) {
			this.scene_mgr.AddRoleVoPool(this.vo)
		}
		this.vo = false
		this.next_frame_funcs = null
	}
	
	public RemoveAllParticle(){ 
		
		if (this.speed_effect_id ) {
			this.particle_mgr.DelEffect(this.speed_effect_id)
			this.speed_effect_id = false
		}
		// if (this.jump_after_image_id ) {
		//	 afterImageMgr.DeleteAfterImage(this.jump_after_image_id)
		//	 this.jump_after_image_id = false
		// }
		if (this.bone_fire_partical_id ) {
			this.particle_mgr.DelEffect(this.bone_fire_partical_id)
			this.bone_fire_partical_id = false
		}
		if (this.escort_partical_id ) {
			this.particle_mgr.DelEffect(this.escort_partical_id)
			this.escort_partical_id = false
		}
		if (this.offline_partical_id ) {
			this.particle_mgr.DelEffect(this.offline_partical_id)
			this.offline_partical_id = false
		}
		if (this.bumo_effect_id ) {
			this.particle_mgr.DelEffect(this.bumo_effect_id)
			this.bumo_effect_id = false
		}
		if (this.weapon_effect_id ) {
			this.particle_mgr.DelEffect(this.weapon_effect_id)
			this.weapon_effect_id = false
		}
	
		if (this.shield_info ) {
			if (this.shield_info.shield_effect_id ) {
				this.particle_mgr.DelEffect(this.shield_info.shield_effect_id)
				this.shield_info.shield_effect_id = false
			}
	
			if (this.shield_info.shield_fade_effect_id ) {
				this.particle_mgr.DelEffect(this.shield_info.shield_fade_effect_id)
				this.shield_info.shield_fade_effect_id = false
			}
			this.shield_info.is_show_effect = false
			this.shield_info.curr_shield_id = 0
			this.shield_info.curr_shield_quality = 0
		}
	
	
	
		super.RemoveAllParticle()
	}
	
	public ReleaseObj(){ 
		
		this.DeleteFootmark()
		this.DoStand()
		this.ClearSwingEffect()
		this.ClearProtectEffectTimer()
		this.ClearShieldEffectTimer()
		this.RemoveLivenessImage()
		this.RemoveWing()
		this.RemoveBrick()
		this.RemoveHeadWear()
		this.ReleaseCharacter()
		this.ClearRole()
		this.wing_abName = false
		this.wing_resName = false
		this.headWear_abName = false
		this.headWear_resName = false
		this.is_dead = true
		this.is_to_dead = true
		super.ReleaseObj()
	}
	
	public ResetObj(){ 
		
		this.ResetCharacter()
	
		this.last_check_swim_pos.x = 0
		this.last_check_swim_pos.y = 0
	}
	
	public InitRoleVo(vo?){ 
		
		this.vo = vo
		this.id = vo.role_id
	
		this.name = this.vo.name
		if (this.vo.is_fake_role ) {
			this.compress_id = Scene.GetInstance().CompressObjId(SceneBaseType.Fake_Role, this.id)
		}else{
			this.compress_id = Scene.GetInstance().CompressObjId(SceneBaseType.Role, this.id)
		}
		if (this.vo.is_virtual_friend ) {
			this.SetHideNameBord(true)
		}else{
			this.SetHideNameBord(false)
		}
		if (this.name_board ) {
			this.name_board.SetHp(this.vo.hp, this.vo.maxHp)
		}
		this.UpdateName()
		this.ChangeModeHide()
		this.ChangeGhostMode()
		this.UpdateMarriage()
		this.UpdateGuildInfo()
		this.UpdateDsgt()
		this.UpdateFlagState()
		this.UpdateWarGroup()
		this.BindVoEvents()
		this.UpdateGrade()
		this.UpdateVip()
		this.UpdateSuperVip()
		this.UpdateServerName()
		this.UpdateBossFlag()
		this.AddSafetyEffect()
		this.UpdateMedal()
	}
	
