	public ChangeBrickId(oldVar1?, value?, old_value?){ 
		
		value = value || this.vo.brick_id
		// if (this.GetType() == SceneBaseType.MainRole ) {
		//	 SeaHegemonyModel.GetInstance().Fire(SeaHegemonyModel.ASSERT_BRICK_ID_CHANGE)
		// }
	
		if (this.IsDead() ) {
			return
		}
	
		if (value > 0 ) {
			this.HideAllWeapon()
			this.HideWing()
			this.RemoveLivenessImage()
	
			this.ShowHeadWear(true)
	
			//if ((! this.brick_gameObject || value != this.last_brick_id) && ! this.loading_brick ) {
			//	this.LoadBrickRes()
			//}
	
			if (this.GetHorseId() > 0 && this.IsOnHorse() ) {
				this.DownHorse()
			}
			if (this.IsInState(PoseState.SIT) ) {
				this.DoStand()
			}
			if (this.name_board ) {
				// this.name_board.SetBrickVisible(true, value)
			}
		}else{
			this.RemoveBrick()
			this.ShowAllWeapon()
			this.ShowWing()
	
			if (old_value && old_value > 0 ) {
				GlobalEventSystem.Fire(EventName.CHANGE_FIGHTING_STATE, false)
			}
			if (this.name_board ) {
				// this.name_board.SetBrickVisible(false)
			}
		}
		SkillManager.Instance.setCurrentSkillId()
		// SkillManager.Instance.ClearCachedSkill()
	
		//下马可能之前存在标志，导致模型透明
		if (this.alpha_flag_value_list ) {
			this.alpha_flag_value_list[Character.AlphaFlag.HorseUp] = null
			this.alpha_flag_value_list[Character.AlphaFlag.HorseDown] = null
		}
	
		this.RoleClothChange()
	}
	
	public ChangeGodId(oldVar1?, value?, old_value?){ 
		console.log("changegodid", this.vo)
		if (! this.vo ) {
			return
		}
		value = value || this.vo.god_id
		if (value > 0 && old_value && old_value <= 0 && this.GetType() == SceneBaseType.MainRole ) {
			this.play_change_god_action = true
		}else{
			this.play_change_god_action = false
		}
		let god_model_scale = 1//this.vo.GetGodModelScale() || 1
		if (this.GetType() == SceneBaseType.MainRole ) {
			if (value > 0 ) {
				if (this.GetHorseId() > 0 ) {
					GlobalEventSystem.Fire(EventName.CHANGE_FIGHTING_STATE, true)
				}
				if (this.IsInState(PoseState.SIT) ) {
					this.DoStand()
				}
				if (this.scene.GetMainRole() ) {
					this.scene.GetMainRole().EnterFightingState(6)
				}
			}
			//可能之前在打怪,用的不是降神技能，所以需要重新选择技能
			SkillManager.Instance.setCurrentSkillId()
			// SkillManager.Instance.ClearCachedSkill()
			this.scene.UpdateAutoFight()
	
	
		}
	
		//下马可能之前存在标志，导致模型透明
		if (this.alpha_flag_value_list ) {
			this.alpha_flag_value_list[Character.AlphaFlag.HorseUp] = null
			this.alpha_flag_value_list[Character.AlphaFlag.HorseDown] = null
		}
	
		this.SetScale(god_model_scale)
		this.RoleClothChange()
		this.DeleteFootmark()
	}
	
