	public DoBeAttacked(dir?, pos?, force_hited?, movie_cfg?, attacker?, skill_id?){ 
		
		let can_be_attacked = super.DoBeAttacked(dir, pos, force_hited, movie_cfg, attacker, skill_id)
		if (can_be_attacked && (pos != null || this.is_need_hit_height) ) {
			if (this.ChangeState(PoseState.HITED) ) {
				let t = {start_time : Status.NowTime,
					total_time : null,
					stop_time : null,
					start_pos : null,
					end_pos : null,
				}
	
				t.total_time = (this.is_need_hit_height) && this.hitHeightSkill_info.complete_time || this.normal_hited_totalTime
				t.stop_time = Status.NowTime + t.total_time
				t.start_pos = new Vector2(this.real_pos.x, this.real_pos.y)
				t.end_pos = pos
				this.s_hited_info = t
			}
		} else if (this.IsInState(PoseState.SIT) ) { //如果在打坐 则打断打坐状态
			this.DoStand()
		}else{
			if (this.GetType() == SceneBaseType.MainRole ) {
				if (this.scene_mgr.IsCSPvP() || this.scene_mgr.IsServerBossScene() ) { //3v3打断采集
					GlobalEventSystem.Fire(EventName.CANCEL_TO_COLLECT)
					//} else if (this.scene_mgr.IsEscortScene() && EscortGoddessModel.GetInstance().IsHuSong() ) {
					//if (attacker.GetType() == SceneBaseType.Role ) {
					//GlobalEventSystem:Fire(EventName.STARTAUTOFIGHT)
					//}
				}
			}
		}
		return can_be_attacked
	}
	
