	public UpdateFlyWithDir(dir?, elapse_time?){ 
		
		if (dir ) {
			let dist = this.GetMoveSpeed(dir) * elapse_time
			let x = this.real_pos.x + dir.x * dist
			let y = this.real_pos.y + dir.y * dist
			this.SetDirection(this.real_pos, new Vector2(x, y), true)
			this.SetRealPos(x, y)
			GlobalEventSystem.Fire(SceneEventType.MAIN_ROLE_FLYING, dir, dist)
			this.fly_distance = (this.fly_distance || 0) + dist
			if (this.fly_distance >= 120 ) {
				GlobalEventSystem.Fire(SceneEventType.MOVEREQUEST, x, y, MOVE_TYPE.BLINK)
				this.fly_distance = 0
			}
		}
	}
	
