	//坐骑改变
	public HorseChange(){ 
		if (this.scene_mgr.HideOnlyRoleScene() ) {
			return
		}
	
		if (this.IsDead() ) {
			return
		}
		if (this.vo && this.vo.brick_id > 0 ) {
			return
		}

		let is_ride = this.vo.GetFigureRideState(FigureProtoVo.FigureType.Horse)
		if (is_ride == 0 || this.scene_mgr.HideOnlyRoleScene() ) {
			if (this.GetHorseId() == 0 ) {
				this.DownHorse()
			}
			if (this.GetType() == SceneBaseType.MainRole ) {
				GlobalEventSystem.Fire(EventName.HIDE_HORSE_SUCCESS, true)
			}
		}else{
			// 如果当前在跳跃状态，则不能马上上马，跳跃完再上马
			if (this.IsInState(PoseState.JUMP) ) {
				this.show_horse_after_jump = true
			}else{
				if (this.GetType() == SceneBaseType.MainRole ) {
					//可能先变身 然后马上收到上马协议
					if (this.vo.CheckIsGod && this.vo.CheckIsGod() ) {
						GlobalEventSystem.Fire(EventName.CHANGE_FIGHTING_STATE, true)
						return
					}
				}
				this.RideHorse(true)
				if (this.GetType() == SceneBaseType.MainRole ) {
					GlobalEventSystem.Fire(EventName.RIDE_HORSE_SUCCESS)
				}
			}
	
		}
		this.ChangeSpeedBuffEffect()
	}
	
	
	public DownHorse(force_down?){ 
		
		super.DownHorse(force_down)
		this.SetShieldEffectOffset()
		if (this.IsInState(PoseState.MOVE) ) {
			this.CreateFootmark()
		}
	}
	
	public RideHorse(force_change?){ 
		
		super.RideHorse(force_change)
		this.SetShieldEffectOffset()
		this.DeleteFootmark()
	}
	
	
