	//角色状态改变展示(0.无 1.补魔 2.被补魔 3.自我补魔)
	public StateChange(state_type?){ 
		
		this.state_type = state_type
		if (state_type == 1 || state_type == 2 || state_type == 3 ) {
			if (this.IsInState(PoseState.MAGIC) ) {
				this.DoStand()
			}else{
				this.DoMagic(state_type)
			}
		} else if (state_type == 0 ) {
			this.DoStand()
		}
		this.ChangeMageicEffect(state_type)
	}
	
	public ChangeMageicEffect(state_type?){ 
		
		if (state_type == 1 ) {
			if (! this.bumo_effect_id ) {
				this.bumo_effect_id = this.particle_mgr.AddTargetEffect("other_effect_bumo1", this.compress_id, true, null, null, 7)
			}
		} else if (state_type == 2 || state_type == 3 ) {
			if (! this.bumo_effect_id ) {
				this.bumo_effect_id = this.particle_mgr.AddTargetEffect("other_effect_bumo2", this.compress_id, true, null, null, 7)
			}
		}else{
			if (this.bumo_effect_id ) {
				this.particle_mgr.DelEffect(this.bumo_effect_id)
				this.bumo_effect_id = false
			}
		}
	}
	
