	public CheckSwingState(){ 
		
		if (this.swing_into_state ) {
			//游泳状态下加载模型完成播放跳跃动作
			this.SetShadowVisible(false)
			this.SWingJump()
		}
	
		//加载其他角色模型后检测是否在游泳区
		this.CheckSWingArea()
	
		if (this.IsInState(PoseState.MOVE) ) {
			this.IntoSWimmingState()
		} else if (this.IsInState(PoseState.STAND) ) {
			this.IntoSWingIdleState()
		}
		if (this.scene_mgr.IsKFGuildWarFightScene() ) { //跨服公会战
			SkillManager.Instance.Fire(SkillManager.UPDATE_SKILL_LIST)
		}
	}
	
