	////////////////////////-守护天使////////////////////////
	
	public ChangeGuard(){ 
		
		if (this.vo.fazhen_id != 0 && (this.IsMainRole() || ! this.HasBlockSetting("guard")) ) {
			this.CreateGuard()
		}else{
			if (this.guard ) {
				this.DeleteGuard()
			}
		}
	}
	
	public HideGuard(flag?){ 
		
		if (this.guard ) {
			this.guard.SetModelHideFlag(flag, true)
		}
	}
	
	public ShowGuard(flag?){ 
		
		if (this.guard ) {
			this.guard.SetModelHideFlag(flag, false)
			this.guard.SetShowPosition(flag)
		}
	}
	
	public CreateGuard(){ 
		
		if (this.vo.fazhen_id != 0 ) {
			this.guard = this.scene.CreateGuard(this, this.vo)
		}
		if (this.IsSwimState() ) {
			this.HideGuard(SceneObj.ModelHideFlag.IndependentHide)
		}
	}
	
	public DeleteGuard(){ 
		
		if (this.guard ) {
			this.scene.DeleteGuard(this.id)
			this.guard = null
		}
	}
	
	////////////////////////-圣器//////////////////////-
	
	public ChangeShengqi(){ 
		
		let shengqi_id = this.vo.GetFigureId(FigureProtoVo.FigureType.Shengqi)
		if (! this.scene_mgr.HideOnlyRoleScene() && shengqi_id != 0 && (this.IsMainRole() || ! this.HasBlockSetting("shengqi")) ) {
			 this.CreateShengqi()
		}else{
			 if (this.shengqi ) {
				 this.DeleteShengqi()
			 }
		}
	}
	
	public HideShengqi(flag?){ 
		
		if (this.shengqi ) {
			this.shengqi.SetModelHideFlag(flag, true)
		}
	}
	
	public ShowShengqi(flag?){ 
		
		if (this.shengqi ) {
			this.shengqi.SetModelHideFlag(flag, false)
			//this.shengqi.SetShowPosition(flag)
		}
	}
	
	public CreateShengqi(){ 
		
		// if (this.scene.is_block_follow ) {
		// 	 return
		// }
		if (this.vo.GetFigureId(FigureProtoVo.FigureType.Shengqi) != 0 ) {
			 this.shengqi = this.scene.CreateShengqi(this, this.vo)
		}
		if (this.IsSwimState() ) {
			 this.HideShengqi(SceneObj.ModelHideFlag.IndependentHide)
		}
	}
	
	public DeleteShengqi(){ 
		
		if (this.shengqi ) {
			 this.scene.DeleteShengqi(this.id)
			 this.shengqi = null
		}
	}
	
	public UpdateMedal(medal_id?){
		//优先显示神谕头衔，无，则显示勋章
		if (this.vo && this.name_board ) {
			if (this.InMaskState() ) {
				 this.name_board.ShowMedal(0)
				 this.name_board.SetTouxian(0)
			}else{
				 if (this.vo.title_id && this.vo.title_id != 0  ) {
					 this.name_board.SetTouxian(this.vo.title_id)
					 this.name_board.ShowMedal(0)
				 }else{
					 medal_id = ! medal_id && this.vo.medal_id || medal_id
					 if (this.vo && this.name_board ) {
						 this.name_board.SetTouxian(0)
						 this.name_board.ShowMedal(medal_id)
					 }
				 }
			}
		}
	}
	
	public UpdateNameBoard(){ 
		
		this.UpdateName()
		this.UpdateDsgt()
		this.UpdateVip()
		this.UpdateSuperVip()
		this.UpdateServerName()
		this.UpdateMedal()
		this.UpdateGuildInfo()
	}
	
	public InMaskState(){ 
		
		return this.vo.mask_id > 0 && SceneManager.GetInstance().CanMaskScene()
	}
	
