import { BaseItem1 } from "../common/BaseItem1"
import { EquipmentItem } from "../common/EquipmentItem"
import { Enum_UILayer } from "../common/LayerManager"
import { ResManager } from "../common/ResManager"
import { GoodsModel } from "../commonModel/GoodsModel"
import { GameResPath } from "../util/GameResPath"
import { Util } from "../util/Util"

// To edit this template in: Data/Config/Template.lua
// To disable this template, check off menuitem: Options-Enable Template File

//-@class SelectGiftItem

export class SelectGiftItem extends BaseItem1 {
	_Group1: Laya.Box
	bg: Laya.Image
	_Image1111: Laya.Image
	item_group: Laya.Box
	num_bg: Laya.Image
	name_label: Laya.HTMLDivElement
	num_label: Laya.Label
	reduce_btn: Laya.Box
	_Image111: Laya.Image
	labelDisplay11: Laya.Label
	increase_btn: Laya.Box
	_Image11: Laya.Image
	labelDisplay1: Laya.Label
	max_btn: Laya.Box
	_Image1: Laya.Image
	labelDisplay: Laya.Label
	haveLb: Laya.Label

	num
	cfg
	award
	call_back
	index


	public constructor(parent?) {
		super(parent)


		this.base_file = "bag"
		this.layout_file = "SelectGiftItem"
		this.num = 0;
		this.load_callback = () => {
			this.name_label.width = 320
			this.name_label.style.fontSize = 26
			this.name_label.style.color = "#ff0000"

			this.LoadSuccess()
			this.InitEvent()

		}
	}

	public LoadSuccess() {

		if (this.is_loaded) {
			// ResManager.GetInstance().SetOutsideImageSprite(this, this.bg, GameResPath.GetIcon("bag", "uitc_007"))
			// ResManager.GetInstance().SetOutsideImageSprite(this, this._Image1111, GameResPath.GetIcon("bag", "uitc_010"), true)
			if (this.cfg) {
				this.InitView()
				this.SetNum(0)
			}
		}
	}

	public InitEvent() {


		Util.AddClickEvent(this.reduce_btn, () => {
			if (this.call_back && this.cfg) {
				this.call_back(this.index, -1, this)
			}
		}
			, this, true)
		Util.AddClickEvent(this.increase_btn, () => {
			if (this.call_back && this.cfg) {
				this.call_back(this.index, 1, this)
			}
		}
			, this, true)
		Util.AddClickEvent(this.max_btn, () => {
			if (this.call_back && this.cfg) {
				this.call_back(this.index, "max", this)
			}
		}
			, this, true)
		Util.AddClickEvent(this.num_bg, () => {
			if (this.call_back && this.cfg) {
				this.call_back(this.index, "zixuan", this)
			}
		}
			, this, false)
	}

	public InitView() {

		if (!this.award) {
			this.award = new EquipmentItem(this.item_group, null, Enum_UILayer.Activity)
			// this.award.SetUseMask(true)
			this.award.Load()
		}
		let [type_id, lock] = GoodsModel.GetInstance().GetMappingTypeId(this.cfg[0], this.cfg[1])
		let goods_vo = GoodsModel.GetInstance().GetGoodsBasicByTypeId(type_id)
		if (goods_vo) {
			this.award.SetData(goods_vo.type_id, this.cfg[2])
			this.name_label.innerHTML = Util.StrToHTML(GoodsModel.GetGoodsNameWithColorDark(goods_vo.type_id))
			this.name_label.width = 320
			this.haveLb.text = "拥有:" + GoodsModel.GetInstance().GetTypeGoodsNum(goods_vo.type_id)
		}
	}

	public SetNum(num?) {


		if (this.is_loaded) {
			this.num = num
			this.num_label.text = String(num)
		}
	}

	public SetData(cfg?, call_back?, index?) {


		this.cfg = cfg
		this.call_back = call_back
		this.index = index
		this.LoadSuccess()
	}

	public DeleteMe() {
		if (this.award) {
			this.award.DeleteMe()
			this.award = null
		}
		super.DeleteMe()
	}

	public GetComponents() {
		[
			this._Group1,
			this.bg,
			this._Image1111,
			this.item_group,
			this.num_bg,
			this.name_label,
			this.num_label,
			this.reduce_btn,
			this._Image111,
			this.labelDisplay11,
			this.increase_btn,
			this._Image11,
			this.labelDisplay1,
			this.max_btn,
			this._Image1,
			this.labelDisplay,
			this.haveLb,
		]
			= this.GetChildrenByNames([

				"_Group1",
				"bg",
				"_Image1111",
				"item_group",
				"num_bg",
				"name_label",
				"num_label",
				"reduce_btn",
				"_Image111",
				"labelDisplay11",
				"increase_btn",
				"_Image11",
				"labelDisplay1",
				"max_btn",
				"_Image1",
				"labelDisplay",
				"haveLb",
			])
	}
}
window["SelectGiftItem"] = SelectGiftItem