import { BaseController } from "../common/BaseController"
import { EventName } from "../common/EventName"
import { ResManager } from "../common/ResManager"
import { table } from "../common/table"
import { UserMsgAdapter } from "../common/UserMsgAdapter"
import { EquipmentViewSecond_Menu_Type } from "../commonModel/EquipModel"
import { FashionModel } from "../commonModel/FashionModel"
import { GoodsModel } from "../commonModel/GoodsModel"
import { OutWardBaseModel } from "../commonModel/OutWardBaseModel"
import { EquipmentView } from "../role/EquipmentView"
import { RoleManager } from "../role/RoleManager"
import { SceneManager } from "../scene/SceneManager"
import { GlobalEventSystem } from "../util/DeclareGlobalVar"
import { Util } from "../util/Util"
import  "../fashion/FashionBaseView"


//require("game.proto.413.Require413")
export class FashionConcroller extends BaseController {
	InitInfo

	public constructor() {
		super()


		this.InitInfo = () => {
			let fashionModel = FashionModel.GetInstance()
			let user_msg_adapter = UserMsgAdapter.GetInstance()
			let local_FashionModel = FashionModel
			let scmd_request = FashionModel.SCMD_REQUEST
			let goods_model = GoodsModel.GetInstance()
			let role_mgr = RoleManager.GetInstance()
			let local_GoodsModel = GoodsModel

			let local_GlobalEventSystem = GlobalEventSystem
			let local_EventName = EventName
			let view_dic_ = []
			let On41300 = () => {
				let scmd = user_msg_adapter.GetSCMD(41300)
				if (scmd.code == 1) {
					for (let _tmpi in scmd.pos_list) {
						var list = scmd.pos_list[_tmpi]
						fashionModel.Fire(local_FashionModel.GETACTIVATEFASHION, list)
					}
				}
			}
			let On41301 = () => {
				let scmd = user_msg_adapter.GetSCMD(41301)
				if (scmd.code == 1) {
					let _list = fashionModel.fashion_activate_list[scmd.pos_id][scmd.fashion_id]
					table.insert(_list.color_list, { color_id: scmd.color_id, fashion_star_lv: 1 })
					if (fashionModel.fashion_info_list[scmd.pos_id]) {
						fashionModel.fashion_info_list[scmd.pos_id]["wear_fashion_id"] = scmd.fashion_id
					}
					fashionModel.fashion_activate_list[scmd.pos_id][scmd.fashion_id].now_color_id = scmd.color_id
					fashionModel.fashion_activate_list[scmd.pos_id][scmd.fashion_id].fashion_star_lv = 1
					fashionModel.fashion_activate_list[scmd.pos_id][scmd.fashion_id] = _list
					fashionModel.Fire(local_FashionModel.SUCCESSOPERATE, scmd.pos_id, 1)
					fashionModel.UpdateActiveList(scmd.pos_id)
					let data = {
						_type: 413,
						sub_type: scmd.pos_id,
						id: scmd.fashion_id,
						color_id: scmd.color_id,
						type_id: 0
					}
					OutWardBaseModel.GetInstance().Fire(OutWardBaseModel.OPEN_VIEW, "OutwardChangedView", data)
				} else {
					Util.ErrorCodeShow(scmd.code)
				}
			}
			let On41302 = () => {
				let scmd = user_msg_adapter.GetSCMD(41302)
				if (scmd.code == 1) {
					if (fashionModel.fashion_info_list[scmd.pos_id]) {
						fashionModel.fashion_info_list[scmd.pos_id]["wear_fashion_id"] = scmd.fashion_id
						let _list = fashionModel.fashion_activate_list[scmd.pos_id][scmd.fashion_id]
						_list.now_color_id = scmd.color_id
						fashionModel.fashion_activate_list[scmd.pos_id][scmd.fashion_id] = _list
						fashionModel.Fire(local_FashionModel.UPDATEVIEW, scmd.pos_id, 1)
					} else {
						fashionModel.Fire(scmd_request, 41300)
					}
				} else {
					Util.ErrorCodeShow(scmd.code)
				}
			}

			let On41303 = () => {
				let scmd = user_msg_adapter.GetSCMD(41303)
				if (scmd.code == 1) {
					if (fashionModel.fashion_info_list[scmd.pos_id]) {
						fashionModel.fashion_info_list[scmd.pos_id]["wear_fashion_id"] = 0
						fashionModel.Fire(local_FashionModel.UPDATEVIEW, scmd.pos_id, 2)
					} else {
						fashionModel.Fire(scmd_request, 41300)
					}
				}
			}

			let On41304 = () => {
				let scmd = user_msg_adapter.GetSCMD(41304)
				if (scmd.code == 1) {
					if (fashionModel.fashion_info_list[scmd.pos_id]) {
						let _list = { fashion_id: scmd.fashion_id, fashion_star_lv: 1, now_color_id: 0, color_list: [{ color_id: 0, fashion_star_lv: 1 }] }
						if (fashionModel.fashion_info_list[scmd.pos_id]["pos_upgrade_num"] == 0) {
							//fashionModel:Fire(scmd_request, 41302, scmd.pos_id, scmd.fashion_id, 0)
						}
						if (fashionModel.fashion_info_list[scmd.pos_id]) {
							fashionModel.fashion_info_list[scmd.pos_id]["wear_fashion_id"] = scmd.fashion_id
						}
						fashionModel.fashion_activate_list[scmd.pos_id][scmd.fashion_id] = _list
						fashionModel.UpdateActiveList(scmd.pos_id)
						fashionModel.Fire(local_FashionModel.SUCCESSOPERATE, scmd.pos_id, 1)
						let data = {
							_type: 413,
							sub_type: scmd.pos_id,
							id: scmd.fashion_id,
							color_id: 0,
							type_id: 0
						}
						OutWardBaseModel.GetInstance().Fire(OutWardBaseModel.OPEN_VIEW, "OutwardChangedView", data)
					} else {
						fashionModel.Fire(scmd_request, 41300)
					}
				}
			}

			let On41305 = () => {
				let scmd = user_msg_adapter.GetSCMD(41305)
				if (scmd.code != 1) {
					Util.ErrorCodeShow(scmd.code)
					return
				}
				if (fashionModel.fashion_info_list[scmd.pos_id]) {
					fashionModel.fashion_info_list[scmd.pos_id]["pos_lv"] = scmd.pos_lv
					fashionModel.fashion_info_list[scmd.pos_id]["pos_upgrade_num"] = scmd.pos_upgrade_num
					fashionModel.Fire(local_FashionModel.SUCCESSOPERATE, scmd.pos_id, 2)
					fashionModel.UpdateActiveList(scmd.pos_id)
				} else {
					fashionModel.Fire(scmd_request, 41300)
				}
			}

			let On41306 = () => {
				let scmd = user_msg_adapter.GetSCMD(41306)
				if (scmd.code == 1) {
					if (fashionModel.fashion_activate_list[scmd.pos_id]) {
						let _list = fashionModel.fashion_activate_list[scmd.pos_id][scmd.fashion_id]
						if (_list.now_color_id == scmd.color_id) {
							_list.fashion_star_lv = scmd.fashion_star_lv
						}
						for (let k in _list.color_list) {
							var v = _list.color_list[k]
							if (v.color_id == scmd.color_id) {
								v.fashion_star_lv = scmd.fashion_star_lv
							}
						}
						fashionModel.fashion_activate_list[scmd.pos_id][scmd.fashion_id] = _list
						fashionModel.UpdateActiveList(scmd.pos_id)
						fashionModel.Fire(local_FashionModel.SUCCESSOPERATE, scmd.pos_id, 1)
					} else {
						fashionModel.Fire(scmd_request, 41300)
					}
				} else {
					Util.ErrorCodeShow(scmd.code)
				}
			}

			let On41311 = () => {
				let scmd = user_msg_adapter.GetSCMD(41311)
				let role_vo = SceneManager.GetInstance().GetRoleVo(scmd.role_id)
				if (role_vo) {
					role_vo.ChangeVar("fashion_model_list", scmd.fashion_equip, null, true)
				}
			}

			this.RegisterProtocal(41300, On41300)
			this.RegisterProtocal(41301, On41301)
			this.RegisterProtocal(41302, On41302)
			this.RegisterProtocal(41303, On41303)
			this.RegisterProtocal(41304, On41304)
			this.RegisterProtocal(41305, On41305)
			this.RegisterProtocal(41306, On41306)
			this.RegisterProtocal(41311, On41311)
			fashionModel.Bind(scmd_request, (cmd, ...new_args) => {
				let args = new_args
				if (41300 == cmd) {
					this.SendFmtToGame(cmd)
				} else if (41301 == cmd) {
					this.SendFmtToGame(cmd, "cicc", args[0], args[1], args[2], args[4])
				} else if (41307 == cmd) {
					this.SendFmtToGame(cmd)
				} else if (41311 == cmd) {
					this.SendFmtToGame(cmd)
				} else if (41302 == cmd) {
					this.SendFmtToGame(cmd, "cic", args[0], args[1], args[2])
				} else if (41303 == cmd) {
					this.SendFmtToGame(cmd, "ci", args[0], args[1])
				} else if (41304 == cmd) {
					this.SendFmtToGame(cmd, "ci", args[0], args[1])
				} else if (41306 == cmd) {
					this.SendFmtToGame(cmd, "cic", args[0], args[1], args[3])
				} else if (41310 == cmd) {
					this.SendFmtToGame(cmd, "ci", args[0], args[1])
				} else if (41305 == cmd) {
					this.WriteBegin(cmd)
					this.WriteFMT("c", args[0])
					this.WriteFMT("h", args[1].length)
					for (let _tmpi in args[1]) {
						var good = args[1][_tmpi]
						this.WriteFMT("l", good[0])
						this.WriteFMT("h", good[1])
					}
					this.SendToGame()
				}
			}
			)
			let JudgeGoodType = (goods_list?) => {
				fashionModel.GetOneGoodNum(goods_list)
			}

			goods_model.Bind(local_GoodsModel.CHANGE_BAG_LIST, JudgeGoodType)
			let CreateCurrentUserModelList = () => {
				fashionModel.LoadFashionConfig()
				fashionModel.UpdateCurrentUserModelList(role_mgr.GetMainRoleVo().career, role_mgr.GetMainRoleVo().sex)
				fashionModel.Fire(scmd_request, 41300)
			}

			goods_model.Bind(local_GoodsModel.CREATE_BAG_LIST_FINISH, CreateCurrentUserModelList)
			let GetActivateFashionInfo = (_list?) => {
				if (_list) {
					fashionModel.CreateACtiveCallBack(_list)
					fashionModel.GetGoodNumFormBag(_list.pos_id)
				}
			}

			fashionModel.Bind(local_FashionModel.GETACTIVATEFASHION, GetActivateFashionInfo)
			let OpenFashionView = (type_id?, parms?, backId?, backShowId?) => {
				if (type_id == EquipmentViewSecond_Menu_Type.Fashion) {
					let view = view_dic_["FashionBaseView"]
					if (!view) {
						view_dic_["FashionBaseView"] = true
						if (!window["FashionBaseView"]) {
							if (!ResManager.GetInstance().IsJsLoad("fashion")) {

							}
						}
						if (view_dic_["FashionBaseView"] == true) {
							let view_class = window["FashionBaseView"]
							view = new view_class()
							view_dic_["FashionBaseView"] = view
						}
					}
					if (view && view != true) {
						if (backId) {
							view.SetBackId(backId, backShowId)
							view.isbackId = true
						}
						if (parms) {
							let index = parms[0]!=null ? parms[0] : 0
							let career = role_mgr.GetMainRoleVo().career
							view.SetDefaultIndex(index)
							view.Open(index, parms[1] && parms[1] || parms[0], parms[2])
						} else {
							view.Open()
						}
					}
				}
			}

			local_GlobalEventSystem.Bind(local_EventName.SWITCH_ROLE_SECOND_BUTTON, OpenFashionView)
			local_GlobalEventSystem.Bind(local_EventName.GAME_START, () => {
				fashionModel.ResetFunc()
			}
			)
		}

		this.InitInfo()
	}
}

window["FashionConcroller"] = FashionConcroller