            let bool = false;
            if (privac_cfg) {
                let plat_name: string = ClientConfig.plat_name;
                if (plat_name && privac_cfg) {
                    for (let plat_tips in privac_cfg) {
                        if (plat_name.indexOf(plat_tips) != -1) {
                            bool = true;
                            break;
                        }
                    }
                }
            }
            return bool;
