	public static pos_array = [new Vector2(120, 120), new Vector2(120, -120), new Vector2(-120, -120), new Vector2(-120, 120)]
	public constructor() {
		super()

		this._type = SceneBaseType.Sprite

		this.stat_start_time = Status.NowTime
		this.random_move_interval = this.getRandomMoveInterval()
		this.pos_index = 1
		this.update_index = 0
		this.main_role_attack_time = false
		this.last_check_time = false
		this.last_attack_time = false
		this.last_find_time = 0
		this.find_way_offset = 0
		this.skill_id = Config.PRELOAD_CLIENT_CONFIG.ConfigOtherFightInfo.sprite_skill_id
		this.follow_dis = 200
		this.curr_follow_tar_pos = { x: 0, y: 0 }
		this.is_can_update = true
	}

	public SpriteTextureChange() {

		this.SetFashionModelRes(this.vo.GetTextureId())
		this.CreateClotheSprite(this.vo.GetSpriteClotheId())
	}

	public CanUpdate() {

		if (!this.is_can_update) {
			return false
		}
		let can_update = super.CanUpdate()
		if (!can_update) {
			if (this.owner && this.owner.IsInState(PoseState.MOVE)) {
				return true
			} else if (this.owner && this.owner.IsInState(PoseState.JUMP) && this.ignore_update_index > 8) {
				return true
			} else if (super.IsInState(PoseState.STAND) && this.all_rotate_off == null && this.ignore_update_index > 10) {
				return true
			}
		}
		return can_update
	}

	public SetCanUpdateState(bool?) {

		this.is_can_update = bool
	}


	public EnterStateMove(state_name?){ 
		
	}

	public CheckToUseSkill(now_time) {

		if (this.scene_mgr.IsSafePos(this.owner.real_pos.x, this.owner.real_pos.y)) {
			return
		}

		if (this.main_role_attack_time && now_time - this.main_role_attack_time <= 2.2) {
			if (GameMath.GetDistance(this.real_pos.x, this.real_pos.y, this.owner.real_pos.x, this.owner.real_pos.y, false) <= 450 * 450) {
				let nearest_defender_compress_id = null
				if (this.defender_list) {
					let nearest_dist = 100000000
					let curr_dist = 0
					for (let i in this.defender_list) {
						var defender = this.defender_list[i]
						curr_dist = GameMath.GetDistance(this.real_pos.x, this.real_pos.y, defender.real_pos.x, defender.real_pos.y, false)
						if (!defender.IsDead() && nearest_dist > curr_dist) {
							nearest_dist = curr_dist
							nearest_defender_compress_id = defender.compress_id
						}
					}
				}
				this.last_attack_time = now_time
				GlobalEventSystem.Fire(FightEvent.RELEASE_MAIN_SKILL, this, Config.PRELOAD_CLIENT_CONFIG.ConfigOtherFightInfo.sprite_skill_id, nearest_defender_compress_id)
			}
		}
	}

	public MainRoleAttack(defender_list?) {

		if (!Util.IsTableEmpty(defender_list)) {
			this.defender_list = defender_list
			this.main_role_attack_time = Status.NowTime
		}
	}

	public UpdateStateMove(state_name?, elapse_time?) {

		if (this.owner) {
			super.UpdateStateMove(state_name, this.owner.last_elapse_time || elapse_time)
		} else {
			super.UpdateStateMove(state_name, elapse_time)
		}
	}

	public Update(now_time?, elapse_time?) {
		if (this.vo == null || this.owner == null || this.owner.vo == null) {
			this.next_frame_funcs = null
			return
		}
		if (!Util.IsTableEmpty(this.next_frame_funcs)) {
			for (let i in this.next_frame_funcs) {
				var f = this.next_frame_funcs[i]
				if (f != null) {
					f()
				}
				this.next_frame_funcs[i] = null
			}
		}
		if (!this.last_check_time || now_time - this.last_check_time >= 2) {
			this.last_check_time = now_time
			//this:CheckToUseSkill()
		}
		if (this.last_attack_time && now_time - this.last_attack_time < 0.7) {
			if (this.IsInState(PoseState.MOVE)) {
				this.DoStand()
			}
			return
		}  //放技能1.5秒内不能移动

		this.update_index = this.update_index + 1
		if (this.update_index % 7 == 0) {
			let dist = GameMath.GetDistance(this.real_pos.x, this.real_pos.y, this.owner.real_pos.x, this.owner.real_pos.y, true)
			if (dist >= this.follow_dis) {
				if (Status.NowTime - this.last_find_time > this.find_way_offset) {
					this.last_find_time = Status.NowTime
					let end_pos = this.GetFollowPos()
					this.move_speed = this.owner.GetMoveSpeed(this.owner.direction) * (1 + (dist - 300) / 600)
					let is_straight_line = this.FindPathAndMove(end_pos)
					if (is_straight_line) {
						this.find_way_offset = 0
					} else {
						this.find_way_offset = 0.15
					}
					this.update_index = 1
				}
			} else if (Status.NowTime - this.stat_start_time >= this.random_move_interval && this.IsInState(PoseState.STAND)) {
				let end_pos = this.GetPosBesideOwner()
				this.move_speed = this.owner.GetMoveSpeed(this.owner.direction) * 0.8
				this.FindPathAndMove(end_pos)
				this.random_move_interval = this.getRandomMoveInterval()
				this.update_index = 1
			}
		} else if (this.update_index % 3 == 0) {
			if (this.owner.HasModelHideFlag() && !this.HasModelHideFlag(SceneObj.ModelHideFlag.IndependenRole)) {
				this.SetModelHideFlag(SceneObj.ModelHideFlag.IndependenRole, true)
			} else if (!this.owner.HasModelHideFlag() && this.HasModelHideFlag(SceneObj.ModelHideFlag.IndependenRole)) {
				this.SetModelHideFlag(SceneObj.ModelHideFlag.IndependenRole, false)
			}
		}
		super.Update(now_time, elapse_time)
	}


	public getRandomMoveInterval() {

		return Util.RandomRange(3, 8)
	}


	public GetPosBesideOwner() {

		let owner_pos = this.owner.real_pos
		let t = Math.floor(TimeUtil.getClientTimeMs() % 4)
		if (t == this.pos_index) {
			t = Math.floor((this.pos_index + 1) % 4)
		}

		this.pos_index = t
		let off_pos = Sprite.pos_array[t]
		this.curr_follow_tar_pos.x = owner_pos.x + off_pos.x
		this.curr_follow_tar_pos.y = owner_pos.y + off_pos.y
		return this.curr_follow_tar_pos
	}

	public Revived() {
		super.Revived()
	}

	public DeleteMe() {
		this.ReleaseObj()
		super.DeleteMe()
	}
	public ClearSprite() {

		if (this.vo) {
			this.vo.UnBindAll()
			this.vo.DeleteMe()
			this.vo = null
		}
		this.next_frame_funcs = null
		// if (this.sprite_renderer ) {	
		// 	this.sprite_renderer.material.shader = SceneManager.GetInstance().GetTextureShader()
		// 	this.sprite_renderer = null
		// }
	}

	public ReleaseObj() {

		this.ReleaseCharacter()
		this.ClearSprite()
		this.owner = null
		this.defender_list = null
		this.main_role_attack_time = false
		this.is_dead = true
		this.is_to_dead = true
	}

	public ResetObj() {

		this.ResetCharacter()
	}

	public InitSpriteVo(owner?, vo?) {

		this.owner = owner
		this.vo = vo
		this.id = vo.sprite_id

		this.name = this.vo.name
		this.compress_id = Scene.GetInstance().CompressObjId(SceneBaseType.Sprite, this.id)

		this.is_can_update = true

		this.SetHideNameBord(true)

		this.BindVoEvents()
	}

	public EnterStateAttack(state_name?) {

		super.EnterStateAttack(state_name)

		let cfg = this.movie_cfg
		let t = this.s_attack_state
		let anim_name = ""
		let anim_time = t.last_time
		if (cfg == null || cfg.anim == null) {
			return
		}
		anim_name = cfg.anim
		this.PlayAction(anim_name)
	}

