	//设置身体的位置  真实坐标不变
	public SetBodyXY(x?, y?) {

		super.SetBodyXY(x, y)
		// if (this.shadow_gameObject.transform ) {
		// 	this.shadow_gameObject.transform.localScale = Vector3.one * 0.5
		// }
	}


	public LoadInfoFromVo() {

		this.SetMoveSpeed(this.vo.move_speed)
		this.SetShowPosition()
		this.SpriteTextureChange()

		let owner_height = this.owner.GetBodyHeight()
		let offset = new Vector2(120, 150)
		this.follow_dis = offset.normalise() + 10
		if (this.vo.hp == 0) {
			this.DoDead()
		} else {
			this.DoStand()
		}
	}


	public GetFollowPos() {

		let owner_pos = this.owner.real_pos

		this.curr_follow_tar_pos.x = owner_pos.x + (this.owner.direction.x > 0 && -150 || 150)
		this.curr_follow_tar_pos.y = owner_pos.y + (this.owner.direction.x > 0 && 120 || -120)


		let grid_x = this.curr_follow_tar_pos.x / SceneObj.GetLogicRealRatio().x, grid_y = this.curr_follow_tar_pos.y / SceneObj.GetLogicRealRatio().y
		if (this.scene_mgr.IsBlockXY(grid_x, grid_y)) {
			let [x, y] = SourceOperateMove.FindNearestPos(new Vector2(owner_pos.x, owner_pos.y), new Vector2(this.curr_follow_tar_pos.x, this.curr_follow_tar_pos.y))
			this.curr_follow_tar_pos.x = x
			this.curr_follow_tar_pos.y = y
		}

		return this.curr_follow_tar_pos
	}



	public BindVoEvents() {

		this.next_frame_funcs = this.next_frame_funcs || {}

		let hp_change_func = (oldVar1?, value?) => {
			if (this.name_board) {
				this.name_board.SetHp(value, this.vo.maxHp)
			}
		}

		var move_speed_func = (oldVar1, value) => {
			this.SetMoveSpeed(value)
		}

		var hide_flag_func = (oldVar1, value) => {
			// this.SetModelHideFlag(SceneObj.ServerHide, (value == 1))
		}

		var birth_angle_func = (oldVar1, value) => {
			this.BirthAngleChange()
		}

		this.vo.BindOne("hp", hp_change_func)
		this.vo.BindOne("move_speed", move_speed_func)
		this.vo.BindOne("hide_flag", hide_flag_func)
		this.vo.BindOne("birth_angle", birth_angle_func)
	}

	public UpdateModel(sprite_id?) {

		if (this.vo) {
			this.vo.ChangeVar("sprite_id", sprite_id)
			this.SpriteTextureChange()
		}
	}


	public EnterStateStand(state_name?) {

		super.EnterStateStand(state_name)
		this.stat_start_time = Status.NowTime
	}

	public SetHide() {

		this.modelObj_transform.owner.active = false
	}

	public SetShowPosition(flag?) {

		if (!this.vo || !this.owner) { return }
		if (!this.scene.IsSceneLoaded()) { return }
		let end_pos = this.GetFollowPos()
		let grid_x = end_pos.x / SceneObj.GetLogicRealRatio().x, grid_y = end_pos.y / SceneObj.GetLogicRealRatio().y
		if (this.scene_mgr.IsBlockXY(grid_x, grid_y)) {
			end_pos = SourceOperateMove.FindNoBlockPos(new Vector2(grid_x, grid_y))
			if (end_pos != null) {
				end_pos.x = end_pos.x * SceneObj.GetLogicRealRatio().x
				end_pos.y = end_pos.y * SceneObj.GetLogicRealRatio().y
			} else {
				end_pos = this.GetFollowPos()
				end_pos.x = end_pos.x + 0.5
				end_pos.y = end_pos.y + 0.5
			}
		}
		this.SetRealPos(end_pos.x, end_pos.y, true)
		this.SetDirection(this.owner.direction, null, null, true)
		this.DoStand()
	}
