			local_GlobalEventSystem.Bind(local_EventName.REWARD_FLY, (goods_list?, start_pos?, end_pos?, layer?, len?, time1?, time2?, down_icon_type?) => {
				if (start_pos == null) {
					start_pos = { x: 360, y: -640 }
				}
				if (len == null) {
					len = 0
				}
				if (time1 == null) {
					time1 = 0
				}
				if (time2 == null) {
					time2 = 750
				}
				if (down_icon_type == null) {
					down_icon_type = MainFunc.Bag
				}
				if (goods_list && goods_list.length > 0) {
					layer = layer || Enum_UILayer.Top
					let timer_index = Status.NowTime
					if (!delay_timer_list) {
						delay_timer_list = []
					}
					if (delay_timer_list) {
						if (!layer_group_list) {
							layer_group_list = []
						}
						let group = layer_group_list[layer]
						if (!layer_group_list[layer]) {
							let ui_layer = LayerManager.GetInstance().GetUILayer((layer && (layer) || (Enum_UILayer.Top)))
							group = ui_layer // local_eui. new Group()
							//group.touchEnabled = false
							//ui_layer:addChild(group)
							layer_group_list[layer] = group
						}
						for (let i = 0; i < goods_list.length; i++) {
							let [type_id,lock] = GoodsModel.GetInstance().GetMappingTypeId(goods_list[i][0], goods_list[i][1])
							if (type_id == 34) {
								this.ShowDiamond(1, goods_list[i][3], start_pos, group)
							} else if (type_id == 35 || type_id == 36020001) {
								this.ShowDiamond(2, goods_list[i][3], start_pos, group)
							} else if (type_id == 31) {
								this.ShowDiamond(3, goods_list[i][3], start_pos, group)
							} else {
								let item = new Laya.Image()
								item.visible = false
								Laya.stage.addChild(item)
								let goodsinfo = goods_list[i]
								let timer_id = setTimeout(() => {
									if (!end_pos) {
										if (local_main_ui_down_view) {
											end_pos = local_main_ui_down_view.GetIconPos(down_icon_type, { x: 0, y: 1 }, { x: 0, y: 1 })
										} else {
											end_pos = { x: 550, y: -1000 }
										}
									}
									// Laya.timer.once(100*i,this,()=>{
										this.ShowItemMove(item, goodsinfo, start_pos, len, time1, end_pos, time2, timer_id, down_icon_type)
									// })
								}
									, i * 100)
								delay_timer_list[timer_id] = timer_id
							}
						}
					}
				}
			})

