export class table {
    public static insert(list: any[], vo, vo1?) {
        if (list && vo) {
            if (vo1) {
                list.splice(vo, 0, vo1)
            } else {
                list.push(vo)
            }
        }
    }

    public static find(list, vo) {
        if (list && vo && list.indexOf) {
            return list.indexOf(vo)
        } else {
            return -1
        }
    }

    public static remove(list: string[], index?) {
        if (list) {
            if (index != null) {
                return list.splice(index, 1)
            } else {
                return list.pop()
            }
        }
    }

    public static sort(list, func) {
        if (list) {
            list.sort((a, b) => {
                return func(a, b) ? -1 : 1
            })
        }
    }

    public static unshift(list, vo) {
        if (list) {
            list.unshift(vo)
        }
    }

    public static splice(list, start_index, count) {
        if (list) {
            list.splice(start_index, count)
        }
    }

    public static reverse(list) {
        if (list) {
            return list.reverse()
        }
    }

    public static shift(list) {
        if (list) {
            return list.shift()
        }
    }
}

window["table"] = table