	public Update(now_time?, elapse_time?){ 
		
		if (this.last_hited_time && now_time - this.last_hited_time >= 5 ) {
			if (this.IsHideNameBorad() ) {
				this.SetHideNameBord(true)
			}
			this.last_hited_time = false
		}
		super.Update(now_time, elapse_time)
	}
	
