	//血条状态
	public SetHpState(){ 
		  
		if (this.vo ) {
			let show = ! this.vo.is_hide_hp
			if (this.vo.type == MonsterType.TASK_COLLECT || this.vo.type == MonsterType.COLLECT
				|| this.vo.type == MonsterType.INFINITE_COLLECT || this.vo.type == MonsterType.HAVE_COUNT_NOT_DEAD_COLLECT
				|| this.vo.type == MonsterType.NOT_DEAD_COLLECT ) { 
				show = false
			} else if (this.vo.type == MonsterType.PRICE && this.vo.can_attack == 0 ) {
				show = false
			}
			if (this.name_board ) {
				this.name_board.SetHpVisible(show)
			}
		}
	}
	
	public UpdateName(){ 
		
		//if (this.IsHideNameBorad() ) {
		//return
		//}
		if (this.vo && this.name_board ) {
			
			if (this.scene_mgr.IsCanAttackByMainRole(this.vo,true,false,true) ) {
				this.name_board.SetRedBar()
			}else{
				this.name_board.SetGreenBar()
			}
			if (this.IsHideNameBorad() ) {
				this.name_board.SetName("")
			}else{
				let monster_name = this.vo.name
				let name_color
				//如果在公会战场, 显示占领方
				if (this.scene_mgr.IsGuildWarScene() ) {
					if (this.vo.warGroup==1 ) {
						name_color = "#f14041"
						monster_name = monster_name + "(红方占领)" 
					} else if (this.vo.warGroup==2 ) {
						name_color = "#60a0ff"
						monster_name = monster_name + "(蓝方占领)" 
					} else if (this.vo.warGroup==3 ) {
						name_color = "#f0b30e"
						monster_name = monster_name + "(黄方占领)"
					}

					if (RoleManager.Instance.mainRoleInfo.warGroup==this.vo.warGroup ) {
						this.name_board.SetGreenBar()
					}else{
						this.name_board.SetRedBar()
					}
				} else if (this.scene_mgr.IsEscortSeverScene() ) {
					//护送场景 协助者和护送者 看所有的船 都是绿色血条
					let mainVo = RoleManager.GetInstance().GetMainRoleVo()
					if (! mainVo ) { return }
					let flag = mainVo.GetFlagsByKey(16)	 //协助标志
					let q_flag = mainVo.GetFlagsByKey(2)	 //协助标志
					let escort_state = mainVo.escort_state 
					if (flag != 0 || escort_state != 0  ) {
						this.name_board.SetGreenBar()
					}
					
					if (q_flag != 0 ) {
						if (mainVo.server_id == this.vo.server_id ) {
							this.name_board.SetGreenBar()
						}
					}
					name_color = ColorUtil.GetColorLight(this.vo.color)
				} else if (this.scene_mgr.IsEscortMainScene() ) { 
					let mainVo = RoleManager.GetInstance().GetMainRoleVo()
					if (! mainVo ) { return }
					let flag = mainVo.GetFlagsByKey(16)	 //协助标志
					let escort_state = mainVo.escort_state 
					
					if (flag != 0 || escort_state != 0  ) {
						this.name_board.SetGreenBar()
					}else{
						this.name_board.SetRedBar()
					}
					
					name_color = ColorUtil.GetColorLight(this.vo.color)
				
				} else if (this.scene_mgr.IsPkBattleScene() ) {
					name_color = "#ffef67"
				} else if (this.scene_mgr.IsHolyBattleFightScene() ) {
					//圣灵战场
					//  let name_state = this.vo.warGroup == 0 && "中立" || HolyBattleModel.GroupName[this.vo.warGroup]
					//  monster_name = monster_name + " 【" + name_state + "】"
				}
	
				this.name_board.SetName(monster_name, name_color)
				// if (this.scene_mgr.IsBossForbiddenScene() || this.scene_mgr.IsBossTempleScene() ) {
				//	 this.name_board.SetAngerVisible(true)
				//	 this.name_board.SetAngerValue(this.cfg_data.anger)
				// }else{
				//	 this.name_board.SetAngerVisible(false)
				// }
				
				if (this.vo.classification && this.vo.classification != "" ) {
					// let color = ColorUtil.GetMonsterColor(this.vo.color)
					// this.name_board.SetGuildText("<color=ffffff.length>" + this.vo.classification + "</color>", color)
				}else{
					// this.name_board.SetGuildText("")
				}
				
			}
		}
	}
	
