	//创建武器
	public CreateWeaponSprite(){ 
		
		super.CreateWeaponSprite()
		if (this.CanShowHitFresnel(this.vo.type_id) ) {
			this.InitHitFresnel()
		}
		if (this.vo.effect_res && this.vo.effect_res != "" ) {
			if (! this.monster_effect_id ) {
				this.monster_effect_id = this.particle_mgr.AddTargetEffect(this.vo.effect_res, this.compress_id, true, 99999,null,7,null,null,this.vo && this.vo.particle_priority || null)
			}
		}		
		
		if (this.vo.foot_effect_res && this.vo.foot_effect_res != "" ) {
			if (! this.foot_effect_id ) {
				this.foot_effect_id = this.particle_mgr.AddTargetEffect(this.vo.foot_effect_res, this.compress_id, true, 99999,null,15,null,null,this.vo && this.vo.particle_priority || null, true)
			}
		}	
		if (this.vo.birth_effect_res && this.vo.birth_effect_res != "0" && this.vo.birth_effect_res != "" ) {
			if (! this.birth_effect_id ) {
				this.birth_effect_id = this.particle_mgr.AddTargetEffect(this.vo.birth_effect_res, this.compress_id)
			}
		}
		this.WarGroundChange()
		this.PkProtectEndTimeChange()
	}
	
