	public DoReborn(hp?){ 
		
		if (hp == null ) {
			hp = this.vo.maxHp
		} else if (hp <= 1 ) {
			hp = this.vo.maxHp * hp
		}
		
		this.vo.ChangeVar("hp", hp)
		this.is_dead = false
		this.is_to_dead = false
		this.has_dispatchDead_event = false
		this.SetLandInfo()
		this.DoStand()
	}
	
	
	public DoDead(dead_dir?){ 
		
		if (this.is_dead ) {
			return
		}
		this.dead_dir = dead_dir || false
		this.DispatchReallyDeadEvent()
		super.DoDead()
	}
	
	public EnterStateDead(state_name?){ 
		
		//尸体不能检选
		this.SetPickInfo(false)
		GlobalEventSystem.Fire(ObjectEventType.OBJ_DEAD, this.id, this.compress_id)
		this.dead_start_time = Status.NowTime
		// if (lua_viewM.is_lock_screen ) {
		//	 GlobalEventSystem.Fire(ObjectEventType.OBJ_DEADBODY_FADE_END, this.dead_body_id)
		// }
		//boss 走以前的逻辑
		if (! this.IsBoss() || (this.vo && this.vo.type_id && Config.PRELOAD_CLIENT_CONFIG.ConfigOtherFightInfo.NoDeadActionMonsterId[this.vo.type_id] == true) ) {
			 this.dead_dir = false
		}
		
		if (! this.dead_dir ) {
			this.dead_end_pos = false
			super.EnterStateDead(state_name)
		}else{
			this.SetDirection(new Vector2(-this.dead_dir.x, -this.dead_dir.y))
			this.PlayAction("death")
			let dist = Config.PRELOAD_CLIENT_CONFIG.ConfigOtherFightInfo.monsterAttackFly.distance
			this.dead_end_pos = new Vector2(this.real_pos.x + this.dead_dir.x * dist, this.real_pos.y + this.dead_dir.y * dist)
		}
		
		if (this == this.scene.GetClickTarget() ) {
			this.scene.CancelClickTarget(true)
		}
	}
	
	public UpdateStateDead(state_name?, elapse_time?){ 
			
		let total_pass_time = Status.NowTime - this.dead_start_time
		let fade_time =  1.8
		if (! this.dead_dir ) {
			let p = total_pass_time / fade_time
			if (p <= 1 ) {
				if (this.is_boss ) {
					this.SetAlphaFlag(Character.AlphaFlag.Death,(1-p))
				}
			}else{
				GlobalEventSystem.Fire(ObjectEventType.OBJ_DEADBODY_FADE_END, this.dead_body_id)
			}
		}else{
			//计算移动基本信息
			if (total_pass_time >= 0.3 ) {
				this.dead_start_time = Status.NowTime
				this.dead_dir = false
			} else if (this.dead_end_pos ) {
				let dir = new Vector2(this.dead_end_pos.x - this.real_pos.x, this.dead_end_pos.y - this.real_pos.y)
				let total_distance = dir.normalise()
				if (total_distance <= 100 ) {
					this.dead_start_time = Status.NowTime
					this.dead_dir = false
				}
				// let move_speed = Config.otherFightInfo.monsterAttackFly.end_speed + total_distance / 300 * Config.otherFightInfo.monsterAttackFly.start_speed
				// let dist = this.GetMoveSpeed(dir, move_speed) * elapse_time
				// let x = this.real_pos.x + dir.x * dist
				// let y = this.real_pos.y + dir.y * dist
				// this.SetRealPos(x, y)
			}
		}
	}
	
