	//检测该点是否在模型包围盒中[重写][27是nameboard里面名字文本的间距]
	public CheckInBound(point?){ 
		
		if (this.can_pick != true || ! point.x || ! point.y ) {
			return false
		}
		let a = point.x < (this.real_pos.x - this.res_size.x / 2)
		let b = point.x > (this.real_pos.x + this.res_size.x / 2)
		let c = point.y < (this.real_pos.y - 80) 
		let d = point.y > (this.real_pos.y + this.GetBodyHeight()/2 + 27)
		if (a || b
			|| c || d ) {
			return false
		}
		return true
	}
	
