import { BaseView1 } from "../common/BaseView1"
import { EventName } from "../common/EventName"
import { Enum_UILayer, LayerManager } from "../common/LayerManager"
import { ResManager } from "../common/ResManager"
import { table } from "../common/table"
import { TaskModel } from "../commonModel/TaskModel"
import { RoleManager } from "../role/RoleManager"
import { GlobalEventSystem } from "../util/DeclareGlobalVar"
import { GameResPath } from "../util/GameResPath"
import { Util } from "../util/Util"
import { MainUIModel } from "../commonModel/MainUIModel"
import { Mathf } from "../util/Mathf"
import { ViewManager } from "../common/ViewManager"
import { SYTweenFunc } from "../util/SYTweenFunc"
import { SYTweenLite } from "../util/SYTweenLite"
import { MainFuncIconItem } from "./MainFuncIconItem"

export class MainUIDownView extends BaseView1 {

	LoadSuccess
	InitEvent
	UpdateView
	PlayAnim
	TryRefreshItem
	PlayExpAnim
	ClearTween
	RefreshTimeInterval
	UpdateTurnRed
	UpdateIconItem
	GetIconPos
	DeleteMainUIDownArrow
	RefreshExpWithoutLevelUp
	UpdateTurnState
	Remove

	public static Max_Type = 1

	public constructor() {
		super()

		this.base_file = "mainUI"
		this.layout_file = "MainUIDownView"
		this.layer_value = Enum_UILayer.Activity
		this.not_tooltips_jump_close = true
		this.is_delay_callback = false
		this.not_close_by_android_back_key = true

		let local_MainUIModel_Instance = MainUIModel.GetInstance(),
			local_GlobalEventSystem = GlobalEventSystem,
			local_RoleManager_Instance = RoleManager.GetInstance(),
			local_EventName = EventName,
			local_Util = Util,
			local_MainUIModel = MainUIModel,
			local_Mathf = Mathf,
			local_LayerManager_Instance = LayerManager.GetInstance(),
			local_LuaViewManager_Instance = ViewManager.GetInstance(),
			local_TaskModel_Instance = TaskModel.GetInstance(),
			// local_CameraManager_Instance = CameraManager.GetInstance(),
			// local_Runner_Instance = Runner.GetInstance(),
			// local_ParticleManager_Instance = ParticleManager.GetInstance(),


			icon_item_list_ = null,
			icon_tween_list_ = null,
			fly_end_effect_obj_ = null,

			exp_ani_data_list_ = [],
			time_interval_ = 0.5,
			is_ani_exp_ = false,
			delay_refresh_time_id_,

			need_refresh_time_interval_ = false,
			tween_event_list_ = [],
			max_len_ = 722,
			local_level_ = 0,
			max_cache_count_ = 20,
			init_x_ = null,
			stay_init_x_ = null,
			refresh_item_id,
			icon_type_to_index

		this.load_callback = () => {
			this.LoadSuccess()
		}

		this.open_callback = () => {
			this.RefreshExpWithoutLevelUp()
		}

		this.destroy_callback = () => {
			this.Remove()
		}

		this.Remove = () => {

		}

		this.LoadSuccess = () => {

			this.display_obj.centerX = 0
			this.display_obj.bottom = 0

			local_MainUIModel_Instance.SetMainuiLoadedFlag(this.layout_file, true, this)

			init_x_ = this._gp_exp_run_effect.x
			stay_init_x_ = this._gp_exp_stay_effect.x

			// this.AddUIEffect2("ui_experience_stay", this.exp_stay_effect, null, null, true)

			ResManager.GetInstance().SetOutsideImageSprite(this, this._img_bg, GameResPath.GetIcon("mainUI", "uizjmv3_001"), true)

			this.UpdateView()
			this.InitEvent()
		}

		this.UpdateView = () => {
			this.UpdateIconItem()
			this.UpdateTurnRed()
			this.UpdateTurnState()
			local_MainUIModel_Instance.RefreshTurnRed()
		}

		this.InitEvent = () => {
			this.BindEvent(
				local_GlobalEventSystem,
				local_EventName.GAME_START, () => {
					local_MainUIModel_Instance.show_type = 0
					this.RefreshExpWithoutLevelUp()
					this.UpdateView()
				}
			)

			this.BindEvent(
				local_GlobalEventSystem,
				local_EventName.EXP_CHANGE_WITHOUT_ANIMATION, (var_type?, value?, old_value?) => {
					// if (! local_TaskModel_Instance.task_show_exp ) {
					this.RefreshExpWithoutLevelUp()
					// }
				}
			)

			this.BindEvent(
				local_GlobalEventSystem,
				local_EventName.FLY_TO_ICON, (obj?) => {
					// let beginObj = obj.beginobj
					// let iconType = obj.icontype
					// let callBack = obj.call_back
					// let scalx = obj.scalx
					// let scaly = obj.scaly
					// let duration = obj.duration
					// let index = icon_type_to_index && icon_type_to_index[iconType]
					// let icon = icon_item_list_ && icon_item_list_[index]
					// if (icon ) {
					// 	local_Util.flyTo(beginObj, icon, null, null, callBack, scalx, scaly, duration)
					// }else{
					// 	local_Util.flyTo(beginObj, this._gp_turn, null, null, callBack, scalx, scaly, duration)
					// }
				}
			)

			this.BindEvent(
				local_GlobalEventSystem,
				local_EventName.PLAY_DOWN_ICON_ANIMATION, (icontype?) => {
					if (!icon_tween_list_) {
						icon_tween_list_ = []
					}
					if (!icon_tween_list_[icontype]) {
						let index = icon_type_to_index && icon_type_to_index[icontype]
						let icon = icon_item_list_ && icon_item_list_[index]
						if (icon) {
							SYTweenLite.to(this, icon.transform, SYTweenLite.UiAnimationType.POSY, -58, 0.2, () => {
								if (icon_tween_list_) {
									icon_tween_list_[icontype] = null
								}
							}, SYTweenFunc.PINGPONG)
							// Laya.Tween.get(icon):to({y=58}, 200):to({y=28}, 200):to({y=38}, 150).call(() => {
							icon_tween_list_[icontype] = true
						}
					}
				}
			)

			this.BindEvent(
				local_RoleManager_Instance.GetMainRoleVo(),
				local_EventName.CHANGE_LEVEL, (level?) => {
					if (local_MainUIModel.Turn_Open_lv == level) {
						this.UpdateTurnState()
						this.UpdateTurnRed()
					}
				}
			)


			this.BindVar(
				local_MainUIModel_Instance,
				"turn_red_dot", () => {
					this.UpdateTurnRed()
				}
			)
			let push_view_fun = (is_out?) => {
				// this.visible = !is_out
			}
			this.BindEvent(local_LuaViewManager_Instance, ViewManager.PUSH_VIEWS_OUT_SCREEN, push_view_fun)

			let turn_btn_fun = (force_show_guide_icon_line?) => {
				if (force_show_guide_icon_line == null) {
					force_show_guide_icon_line = true
				}
				if (!local_MainUIModel_Instance.GetTurnState()) {
					return
				}
				local_MainUIModel_Instance.show_type = local_MainUIModel_Instance.show_type + 1
				if (local_MainUIModel_Instance.show_type > MainUIDownView.Max_Type) {
					local_MainUIModel_Instance.show_type = 0
				}
				this.UpdateTurnState()
				local_MainUIModel_Instance.RefreshTurnRed()
				// this.DeleteMainUIDownArrow()
				this.UpdateIconItem()
				// if (! force_show_guide_icon_line && ! StoryModel.GetInstance().HasFingerIsShowing() ) {
				// 	this.local_TaskModel_Instance.DoTask(null, false, false)
				// }
				local_GlobalEventSystem.Fire(local_EventName.CLOSE_ICON_BOX_VIEW)
			}
			Util.AddClickEvent(
				this._gp_turn, () => {
					turn_btn_fun(false)
				},
				this,
				true
			)

			this.BindEvent(local_GlobalEventSystem, local_EventName.SELECT_STORY_TARGET, (target_name?, is_add?, force_show_mainui_icon?) => {
				if (!local_MainUIModel_Instance.GetTurnState()) {
					return
				}
				let need_guide_line = local_MainUIModel_Instance.FindIconInLineNo(target_name)
				if (is_add && need_guide_line != null) {
					if (local_MainUIModel_Instance.show_type != need_guide_line) {
						if (force_show_mainui_icon) {
							turn_btn_fun()
							this.task_model.DoTask(null, false)
						} else {
							local_GlobalEventSystem.Fire(local_EventName.SELECT_STORY_TARGET, target_name, false)
						}
					}
				}
			})

			// this.BindEvent(local_TaskModel_Instance, TaskModel.UPDATE_NEWEST_TASK_ID_NOT_DELAY, (task_id?) => {
			// 	this.TryRefreshItem()
			// }
			// )

			local_GlobalEventSystem.Bind(local_EventName.ALPHA_STATE_CHANGE, () => {
				this.TryRefreshItem()
			})
		}

		this.DeleteMainUIDownArrow = () => {
			if (this.story_model.now_story_target_name) {
				local_GlobalEventSystem.Fire(local_EventName.SELECT_STORY_TARGET, this.story_model.now_story_target_name, false)
			}
		}

		this.UpdateIconItem = () => {
			if (!icon_item_list_) {
				icon_item_list_ = []
			}
			let icons_list = local_MainUIModel.Main_Func_Icons[local_MainUIModel_Instance.show_type]
			let item = null
			icon_type_to_index = []
			let index = 1

			for (let i in icons_list) {
				var vo = icons_list[i]
				if (local_MainUIModel_Instance.GetMainFuncOpenCond(vo.func)) {
					icon_type_to_index[vo.func] = index
					item = icon_item_list_[index]
					if (!item) {
						item = new MainFuncIconItem(this._gp_icon_con)
						item.SetData(vo)
						item.Load()
						icon_item_list_[index] = item
						item.SetPosition((index - 1) * 105, 0)
					} else {
						item.SetData(vo)
					}
					item.SetVisible(true)
					index = index + 1
				}
			}
			for (let i = index; i < icon_item_list_.length; i++) {
				icon_item_list_[i].SetVisible(false)
			}
		}

		this.UpdateTurnRed = () => {
			if (local_MainUIModel_Instance.GetTurnState()) {
				this._img_red.visible = local_MainUIModel_Instance.turn_red_dot
			} else {
				this._img_red.visible = false
			}
		}


		this.UpdateTurnState = () => {
			if (local_MainUIModel_Instance.GetTurnState()) {
				this._img_turn.gray = false
				ResManager.GetInstance().SetImageSprite(
					this,
					this._img_turn,
					"mainUI",
					local_MainUIModel_Instance.show_type == 0 && "uizjmv3_015" || "uizjmv3_016"
				)
			} else {
				this._img_turn.gray = true
				ResManager.GetInstance().SetImageSprite(this, this._img_turn, "mainUI", "uizjmv3_015")
			}
		}

		this.RefreshExpWithoutLevelUp = (not_delay?) => {
			let main_role_vo = local_RoleManager_Instance.GetMainRoleVo()

			if (exp_ani_data_list_.length > max_cache_count_) {
				table.remove(exp_ani_data_list_, 1)
			}

			// let gap = local_Mathf.Abs(main_role_vo.exp - last_exp_) / main_role_vo.exp_lim
			// let show_effect_run = null

			// if (main_role_vo.level > last_level_ || gap >= 0.1 ) {
			// 	show_effect_run = true
			// }

			// last_exp_ = main_role_vo.exp
			// last_level_ = main_role_vo.level

			let exp = main_role_vo.exp
			let exp_lim = main_role_vo.exp_lim
			if (exp > exp_lim) {
				exp = exp_lim
			}
			let persent
			if (exp_lim == 0) {
				persent = 0
			} else {
				let a = exp / exp_lim * 100
				persent = Math.floor(a) / 100
			}


			table.insert(
				exp_ani_data_list_,
				{
					persent: persent,
					level: main_role_vo.level,
					exp: exp,
					exp_lim: main_role_vo.exp_lim,
					// show_effect_run : show_effect_run
				}
			)

			if (is_ani_exp_) {
				need_refresh_time_interval_ = true
				return
			} else {
				//0.5秒 捕获数据 
				if (delay_refresh_time_id_) {
					return
				}

				delay_refresh_time_id_ = setTimeout(() => {
					delay_refresh_time_id_ = false
					this.RefreshTimeInterval()
					this.PlayExpAnim()
				}, 0.5)
			}
		}

		this.RefreshTimeInterval = () => {
			let len = exp_ani_data_list_.length
			time_interval_ = len > 0 && (0.5 / len) || 0
		}

		this.PlayExpAnim = () => {
			if (need_refresh_time_interval_) {
				this.RefreshTimeInterval()
				need_refresh_time_interval_ = false
			}

			let vo = table.remove(exp_ani_data_list_)
			if (vo) {
				is_ani_exp_ = true
				this.PlayAnim(vo)
			} else {
				is_ani_exp_ = false
			}
		}

		this.PlayAnim = (tb?) => {

			let endValue = max_len_ * Number(tb.persent)

			if (endValue < 0) {
				endValue = 0
			} else if (endValue > max_len_) {
				endValue = max_len_
			}

			let onComleted = () => {
				this._lb_exp.text = tb.exp + " / " + tb.exp_lim
				this.PlayExpAnim()
			}

			if (tb.level > local_level_) {
				let onComleted2 = () => {
					this._img_exp.width = 0
					if (this._img_exp.width == endValue) {
						onComleted()
					} else {
						table.insert(
							tween_event_list_,
							SYTweenLite.to(
								this,
								this._img_exp,
								SYTweenLite.UiAnimationType.WIDTH,
								endValue,
								time_interval_,
								onComleted,
								SYTweenFunc.EASE_IN_OUT
							)
						)
					}
				}
				if (this._img_exp.width == max_len_) {
					onComleted2()
				} else {
					table.insert(
						tween_event_list_,
						SYTweenLite.to(
							this,
							this._img_exp,
							SYTweenLite.UiAnimationType.WIDTH,
							max_len_,
							time_interval_,
							onComleted2,
							SYTweenFunc.EASE_IN_OUT
						)
					)
				}
			} else {
				table.insert(
					tween_event_list_,
					SYTweenLite.to(
						this,
						this._img_exp,
						SYTweenLite.UiAnimationType.WIDTH,
						endValue,
						time_interval_,
						onComleted,
						SYTweenFunc.EASE_IN_OUT
					)
				)
			}
			local_level_ = tb.level
		}

		this.ClearTween = () => {
			if (tween_event_list_) {
				for (let _ in tween_event_list_) {
					var key = tween_event_list_[_]
					SYTweenLite.Stop(key)
				}
				tween_event_list_ = []
			}
		}

		this.GetIconPos = (main_func?, centor_offset?) => {
			let index = icon_type_to_index && icon_type_to_index[main_func]
			let icon
			if (icon_item_list_ && icon_item_list_[index]) {
				icon = icon_item_list_[index]
			}
			if (!icon) {
				icon = this._gp_turn
			}
			if (icon) {
				let point
				if (centor_offset) {
					if(icon == this._gp_turn){
						point = icon.localToGlobal(new Laya.Point(centor_offset.x,centor_offset.y))
					}else{
						point = icon.localToGlobal(centor_offset.x,centor_offset.y)
					}
				} else {
					if(icon == this._gp_turn){
						point = icon.localToGlobal(new Laya.Point(icon.width / 2, 0))
					}else{
						point = icon.localToGlobal(icon.width / 2,0)
					}
				}
				return { x: point.x, y: point.y }
			}
			return false

			// let index = icon_type_to_index && icon_type_to_index[main_func]
			// let icon_trans = null
			// if (icon_item_list_ && icon_item_list_[index]) {
			// 	icon_trans = icon_item_list_[index]
			// }
			// if (!icon_trans) {
			// 	icon_trans = this._gp_turn
			// }
			// if (icon_trans) {
			// 	return { x: icon_trans.x, y: icon_trans.y } //UILocalToCanvasPoint(icon_trans, centor_offset, pivot_offset)
			// }
			// return false
		}


		this.TryRefreshItem = () => {
			if (refresh_item_id) {
				return
			}

			refresh_item_id = setTimeout(() => {
				this.UpdateIconItem()
				local_MainUIModel_Instance.RefreshTurnRed()

				refresh_item_id = false

			}, 0.5)
		}
	}
	_img_bg: Laya.Image
	_gp_icon_con: Laya.Box
	_gp_turn: Laya.Box
	_img_turn: Laya.Image
	_img_red: Laya.Image
	_Group1: Laya.Box
	_Image1: Laya.Image
	_Image2: Laya.Image
	_Image3: Laya.Image
	_Image4: Laya.Image
	_img_exp: Laya.Image
	_gp_exp_run_effect: Laya.Box
	_gp_exp_stay_effect: Laya.Box
	_gp_fly_end_effect: Laya.Box
	_lb_exp: Laya.Label
	public GetComponents() {
		[
			this._img_bg,
			this._gp_icon_con,
			this._gp_turn,
			this._img_turn,
			this._img_red,
			this._Group1,
			this._Image1,
			this._Image2,
			this._Image3,
			this._Image4,
			this._img_exp,
			this._gp_exp_run_effect,
			this._gp_exp_stay_effect,
			this._gp_fly_end_effect,
			this._lb_exp,
		]
			= this.GetChildrenByNames([

				"_img_bg",
				"_gp_icon_con",
				"_gp_turn",
				"_img_turn",
				"_img_red",
				"_Group1",
				"_Image1",
				"_Image2",
				"_Image3",
				"_Image4",
				"_img_exp",
				"_gp_exp_run_effect",
				"_gp_exp_stay_effect",
				"_gp_fly_end_effect",
				"_lb_exp",
			])
	}
}
window["MainUIDownView"] = MainUIDownView