		this.SetIconType = (icon_type?) => {
	
			this.icon_type = icon_type || this.icon_type
			if (!this.is_loaded) {
				need_refresh_data = true
				return
			}
			this.cfg = CommonManager.GetInstance().GetFunctionIconCfg(this.icon_type)
			this.icon_info = ActivityIconManager.GetInstance().getIconInfo(this.icon_type)
			if (!this.icon_info) {
				let info = ActivityIconManager.GetInstance().getBoxIconInfo(this.icon_type)
				if (info) {
					this.icon_info = info
				}
			}
			if (!this.cfg) {
				return
			}
			this.SetIconImg()
			this.SetCountTimer()
			this.SetIconEffect()
			this.ShowRedDot(dot_cache)
			if (this.icon_info && this.icon_info.icon_txt) {
				this.SetIconText(this.icon_info.icon_txt)
			}
	
			if (this.cfg && this.cfg.location_type == 1 || this.cfg.location_type == 2 || this.cfg.location_type == 3 ||
				this.cfg.location_type == 6 ||
				this.cfg.location_type == 7
			) {
				ResManager.GetInstance().SetImageSprite(this, this._img_bg, this.base_file, "uizjmhdtb_001")
			}
		}

		
	
