		this.SetCountTimer = () => {
	
			if (!Util.IsTableEmpty(icon_type_timer_dic) && icon_type_timer_dic[this.icon_type]) {
				return
			}
			if ((!this.is_loaded || !this.icon_type) || !this.icon_info) {
				return
			}
			this.CancelTimer()
			let show = false
			foreshow_ing = this.icon_info.data.foreshow_ing
			foreshow_show = this.icon_info.data.foreshow_show
			foreshow_msg = this.icon_info.data.foreshow_msg
			foreshow_icon = this.icon_info.data.foreshow_icon
			if (this.icon_info.data.count_down_time) {
				show = true
				this.StartTimer(this.icon_info.time)
			}
			if (this.icon_info.icon_txt != "") {
				show = true
			}
			this._lb_desc.visible = show
		}

		
	
		this.StartTimer = (time?) => {
	
			this.CancelTimer()
			count_time = time
			if ((!this.icon_type || time == null) || !this.cfg) {
				return
			}
			update_timer_id =
				GlobalTimerQuest.AddPeriodQuest(() => {
					this.OnTimer()
				},
					1, -1)
			this.OnTimer()
		}
	
		this.CancelTimer = () => {
	
			if (update_timer_id) {
				GlobalTimerQuest.CancelQuest(update_timer_id)
				update_timer_id = null
			}
			count_time = 0
		}

		
	
