		this.SetAlpha = (alpha?) => {
			if (this.is_loaded) {
				this.display_obj.alpha = alpha
			} else {
				alpha_cache = alpha
			}
		}

		
		this.SetIconScale = (scale?) => {
	
			if (this.is_loaded) {
				SetLocalScale(this._gp_icon, scale)
			} else {
				icon_scale_cache = scale
			}
		}
	
		this.SetAsLastSibling = (not_need_sorting_order?) => {
			if (this.is_loaded) {
				this._parent.setChildIndex(this.display_obj, this._parent.numChildren - 1)
				if (!not_need_sorting_order) {
					let finger = this.story_model.GetFinger(this, this._img_icon)
					if (finger && finger.gameObject) {
						finger.SetCoverMode()
					}
				}
			} else {
				set_first_cache = true
			}
		}
	
	
