	public GetComponents() {
		[
			this._gp_icon,
			this._gp_static,
			this._img_bg,
			this._img_icon,
			this._img_red,
			this._lb_desc,
			this._gp_effect,
		]
			= this.GetChildrenByNames([

				"_gp_icon",
				"_gp_static",
				"_img_bg",
				"_img_icon",
				"_img_red",
				"_lb_desc",
				"_gp_effect",
			])
	}
