import { BaseItem1 } from "../common/BaseItem1"

export class EveningMainConItem extends BaseItem1 {
	data
	needRefreshData

	public static width = 630
	public static height = 20


	public constructor(parent) {
		super(parent)

		this.base_file = "evening"
		this.layout_file = "EveningMainConItem"
		this.load_callback = () => {
			if (this.needRefreshData) {
				this.SetData(this.data)
				this.needRefreshData = null
			}
		}
	}


	public SetData(data?) {

		this.data = data || this.data
		if (this.is_loaded) {
			this._lb_content.text = this.data
			let content_h=this._lb_content.textField.textHeight+7
			this._lb_content.height=content_h-7
			this.display_obj.height=content_h
		} else {
			this.needRefreshData = true
		}
	}

	_Image1: Laya.Image
	_lb_content: Laya.Label
	public GetComponents() {
		[
			this._Image1,
			this._lb_content,
		]
			= this.GetChildrenByNames([

				"_Image1",
				"_lb_content",
			])
	}
}

window["EveningMainConItem"] = EveningMainConItem