import { BaseItem1 } from "../common/BaseItem1"
import { ResManager } from "../common/ResManager"
import { SYTweenFunc } from "../util/SYTweenFunc"
import { SYTweenLite } from "../util/SYTweenLite"
import { SetLocalScale, Util, SetAnchoredPosition } from "../util/Util"

export class PetRoundItem extends BaseItem1 {
	click_group: Laya.Box
	icon_bg: Laya.Image
	icon_bg_mask: Laya.Image
	icon: Laya.Image
	bottom_text: Laya.Label
	red_dot: Laya.Image
	num_group: Laya.Box
	up_arrow: Laya.Image
	count_label: Laya.Label


	public effect_group
	public tween_id
	public is_lock

	AddEffect
	SetCanUseCount
	SetNumber
	SetLock
	SetRedDot
	SetClickCallBack
	SetGary
	LoadSuccess
	InitEvent
	SetData
	Local_DeleteMe

	public constructor(parent?) {
		super(parent)

		this.base_file = "pet"
		this.layout_file = "PetRoundItem"

		let need_refresh_ = false,
			call_back_,
			lock_stage_,
			source_str_,
			goods_num_,
			show_red_,
			max_count_,
			show_number_,
			red_type_,
			canUseCount_

		this.load_callback = () => {
			this.LoadSuccess()
			this.InitEvent()
		}

		this.SetData = (source_str?, click_callback?, is_lock?, lock_stage?, goods_num?, max_count?, show_red?, show_number?, red_type?, canUseCount?) => {
			source_str_ = source_str
			call_back_ = click_callback
			this.is_lock = is_lock
			goods_num_ = goods_num
			max_count_ = max_count
			show_red_ = show_red
			lock_stage_ = lock_stage
			show_number_ = show_number
			red_type_ = red_type
			canUseCount_ = canUseCount
			if (this.is_loaded) {
				need_refresh_ = false
				ResManager.GetInstance().SetTexture(this, this.icon, source_str)
				this.SetLock(this.is_lock)
				this.SetNumber()
				this.SetRedDot(show_red_)
				this.SetCanUseCount()
				if (red_type == 2) {
					this.icon.scaleX = this.icon.scaleY = 1.2
				}
			} else {
				need_refresh_ = true
			}
		}

		this.LoadSuccess = () => {
			if (need_refresh_) {
				this.SetData(source_str_, call_back_, this.is_lock, lock_stage_, goods_num_, max_count_, show_red_, show_number_, red_type_, canUseCount_)
			}
		}

		this.InitEvent = () => {
			let OnClick = () => {
				if (call_back_) {
					call_back_()
				}
			}
			Util.AddClickEvent(this.click_group, OnClick, this, true)
		}

		this.SetGary = (gary?) => {
			Util.SetImageGray(this.icon, gary)
		}

		this.SetClickCallBack = (callback?) => {
			call_back_ = callback
		}

		this.SetRedDot = (reddot?) => {
			if (red_type_ == 2) {
				// if (this.tween_id) {
				// 	SYTweenLite.Stop(this.tween_id)
				// }
				// Laya.Tween.removeTweens(this.num_group)

				if (reddot) {
					this.num_group.y = -10
					// this.tween_id = SYTweenLite.to(this, this.num_group, SYTweenLite.UiAnimationType.POSY, 9.5, 1.4, null, SYTweenFunc.PINGPONG, true)
					// Laya.Tween.get(this.num_group, { loop: true }).to({ y: -3 }, 700).to({ y: 9.5 }, 700)
					this.num_group.visible = true
				} else {
					this.num_group.visible = false
				}

				this.red_dot.visible = false
			} else {
				if (reddot) {
					this.red_dot.visible = true
				} else {
					this.red_dot.visible = false
				}
				this.num_group.visible = false
			}
		}

		this.SetLock = (is_lock?) => {
			if (is_lock) {
				this.SetGary(true)
			} else {
				this.SetGary(false)
			}
			this.is_lock = is_lock
		}

		this.SetNumber = () => {
			if (show_number_) {
				this.bottom_text.text = `${goods_num_}`
			} else {
				this.bottom_text.text = ""
			}
		}

		this.SetCanUseCount = () => {
			if (canUseCount_) {
				this.count_label.text = `+${canUseCount_}`
			} else {
				this.count_label.text = ""
			}
		}

		this.AddEffect = (effect_str?, layer_value?) => {
			if (this.effect_group) {
				this.ClearUIEffect(this.effect_group)
			}
			if (!this.effect_group) {
				this.effect_group = new Laya.Box()
				this.effect_group.verticalCenter = 0
				this.effect_group.horizontalCenter = 0
				// this.addChild(this.effect_group)
			}
			this.AddUIEffect(effect_str, this.effect_group)
		}

		this.Local_DeleteMe = () => {
			// if (this.tween_id) {
			// 	SYTweenLite.Stop(this.tween_id)
			// }
			if (this.num_group) {
				// Laya.Tween.removeTweens(this.num_group)
			}
			if (this.effect_group) {
				this.ClearUIEffect(this.effect_group)
			}
		}
	}

	public DeleteMe() {
		this.Local_DeleteMe()
		super.DeleteMe()
	}


	public GetComponents() {
		[
			this.click_group,
			this.icon_bg,
			this.icon_bg_mask,
			this.icon,
			this.bottom_text,
			this.red_dot,
			this.num_group,
			this.up_arrow,
			this.count_label,
		]
			= this.GetChildrenByNames([

				"click_group",
				"icon_bg",
				"icon_bg_mask",
				"icon",
				"bottom_text",
				"red_dot",
				"num_group",
				"up_arrow",
				"count_label",
			])
		ResManager.GetInstance().LoadFont(this,"figth_big_green_fnt",this.count_label,null,false)
	}
}
window["PetRoundItem"] = PetRoundItem