	public Clear() {

		this.ClearTimer()
		if (this._btn_list) {
			this._btn_list = []
		}
		if (this._ac_rank) {
			this._ac_rank.DeleteMe()
			this._ac_rank = null
		}


		for (let i = 0; i < this.item_list.length; i++) {
			if (!this.item_list[i]) continue
			this.item_list[i].DeleteMe()
			this.item_list[i] = null
		}
		this.item_list.length = 0
	}

