	public SelectAnswer(i?) {

		// let radioGroup = e.target
		// this._select_idx = Number(radioGroup.selectedValue)
		if (i == this._select_idx) {
			console.log("已选择", i)
			return
		}
		this._select_idx = i
		this._is_select = true
		// radioGroup.enabled = false
		this.EnableToggleGroup(false)
		this.model.Fire(GuildActEvent.REQUEST_PROTO, 40259, "c", this._select_idx)
		this.SendMsg(this._btn_list[this._select_idx].Find("labelDisplay").GetComponent("Text").text)
	}

	public UpdateRankData(data?) {

		this._ac_rank.replaceAll(data.guild_list)
		this.scmd40214 = data
		let my_guild_data = this.GetMyGuildData()
		this._lb_rank.text = (my_guild_data.guild_rank <= 0 && ("无") || (my_guild_data.guild_rank + ""))
		this._lb_score.text = my_guild_data.guild_score + ""
		this._lb_rank_tips.visible = data.guild_list.length < 1
	}

	public GetMyGuildData() {

		if (this.scmd40214) {
			for (let i = 0; i < this.scmd40214.guild_list.length; i++) {
				var v = this.scmd40214.guild_list[i]
				if (v.guild_id == this.guild_id) {
					return v
				}
			}
			return { guild_rank: 0, guild_score: 0 }
		}
	}

	public UpdateQuestion(data?) {

		//题号为0用来判断答题结束，关闭界面
		if (0 == data.no) {
			this.SetVisible(false)
		}
		if (data.status == 0) {
			return
		}
		this.SetQuestionType(data.no <= this.choose_count)
		let cfg = ResManager.GetInstance().GetGameConfigFromCache(this, "config_guild_reply_title", false)[data.id]
		if (!cfg) {
			return
		}

		this.PerHtml_lb()
		this._lb_content.innerHTML = Util.StrToHTML("<font color=\"#ff6519\">第" + data.no + "/" + this.quest_count + "题：</font>" + Trim(cfg.question))
		this._right_idx = cfg.right
		this.UpdateAnswer(cfg)
		this.SetTimer(data)
	}

	PerHtml_lb() {
		this._lb_content.style.color = "#5a1c20"
		this._lb_content.style.fontSize = 20
		this._lb_content.style.wordWrap = true
		this._lb_content.width = 260
	}


	PerHtml_lb2() {
		this._lb_time.style.color = "#7b5250"
		this._lb_time.style.fontSize = 18
		this._lb_time.style.wordWrap = true
		this._lb_time.width = 260
	}

	public UpdateAnswer(cfg?) {

		let is_show = false
		let answer = null
		let btn = null

		for (let i = 1; i <= GuildActDefine.ANSWER_COUNT; i++) {
			answer = cfg["answer" + i]
			is_show = answer != ""
			btn = this._btn_list[i]
			btn.visible = is_show
			if (is_show) {
				// btn.label = this._answer_list[i - 1] + answer
				//btn.Find("labelDisplay").GetComponent("Text").text = this._answer_list[i] + answer
			}
		}
	}

	public SetTimer(data?) {

		this.ClearTimer()
		let status = data.status
		if (status == 1) {
			// this._btn_rbg.selectedValue = null
			// this._btn_rbg.enabled = true
			this.EnableToggleGroup(true)
			this.HideTipsImage()
		} else {
			// this._btn_rbg.enabled = false
			this.EnableToggleGroup(false)
			this.SetTipsImage()
		}
		this.SetTimeText(status, data.etime - TimeUtil.getServerTime())

		this.ClearTimer()
		this._timer_id = GlobalTimerQuest.AddPeriodQuest(() => {
			this.UpdateTimer()
		}, 1, -1)
		this.UpdateTimer()
	}

	public Test() {

		this.EnableToggleGroup(true)
	}

	public UpdateTimer() {

		let rtime = this._quest_info.etime - TimeUtil.getServerTime()
		if (rtime < 0) {
			this.ClearTimer()
			// this._btn_rbg.enabled = false
			this.EnableToggleGroup(false)
			//test
			// this.EnableToggleGroup(true)
		} else {
			this.SetTimeText(this._quest_info.status, rtime)
		}
	}

	public SetTimeText(status?, rtime?) {
		this.PerHtml_lb2()
		let str = HtmlColorTxt(rtime, "'#ff6519'")//Enum_ColorUtil_Dark.GREEN)
		if (status == 1) {
			this._lb_time.innerHTML = `答题时间：${str}秒`   //Util.StrToHTML("答题时间：" + str + "秒")
		} else if (status == 2) {
			this._lb_time.innerHTML = `${str}秒后开始下一题，请做好准备！` // Util.StrToHTML(str + "秒后开始下一题，请做好准备！")
		}
	}

