        //大多数活动，需要在安全区域和主城洛兰王国才能报名、参加活动，进入到活动场景
        //在野外场景需要寻路到安全区
        this.FindSafePosAndGoActivity = (call_back?) => {
            let pos = Scene.Instance.GetMainRole().GetRealPos()
            if (SceneManager.GetInstance().IsOutdoorScene() && !SceneManager.GetInstance().IsSafePos(pos.x, pos.y)) {
                let [birth_x, birth_y] = SceneManager.Instance.GetSceneBirthPos()
                if (birth_x && birth_y) {
                    Message.show("战斗状态不可参加，正寻路到安全区")
                    GlobalEventSystem.Fire(EventName.STOPAUTOFIGHT, false, true)//寻路要先切换掉自动挂机状态
                    if (this.timer) {
                        GlobalTimerQuest.CancelQuest(this.timer)
                        this.timer = null
                    }
                    let main_role = Scene.Instance.GetMainRole()
                    if (main_role && main_role.CanMove()) {
                        this.GoFun(birth_x, birth_y, call_back)
                    } else {
                        let timer_func = () => {
                            if (main_role && main_role.CanMove()) {
                                this.GoFun(birth_x, birth_y, call_back)
                                if (this.timer) {
                                    GlobalTimerQuest.CancelQuest(this.timer)
                                    this.timer = null
                                }
                            }
                        }
                        this.timer = GlobalTimerQuest.AddPeriodQuest(timer_func, 0.1, -1)
                    }
                }
            }
        }

        this.GoFun = (birth_x?, birth_y?, call_back?) => {
            if (birth_x && birth_y) {
                let findVo = new FindVo()
                findVo.type = FindVo.POINT
                findVo.sceneId = SceneManager.Instance.GetSceneId()
                findVo.id = 0
                findVo.x = birth_x / SceneObj.GetLogicRealRatio().x
                findVo.y = birth_y / SceneObj.GetLogicRealRatio().y
                findVo.call_back = call_back
                console.log("//////野外场景的安全区//////-", findVo.sceneId, findVo.x, findVo.y)
                GlobalEventSystem.Fire(EventName.FIND, findVo)

                if (this.event_id) {
                    GlobalEventSystem.UnBind(this.event_id)
                    this.event_id = null
                }
                //脱离战斗状态5秒，允许进入活动 
                let quit_fun = () => {
                    if (call_back) {
                        call_back()
                        if (this.event_id) {
                            GlobalEventSystem.UnBind(this.event_id)
                            this.event_id = null
                        }
                        call_back = null
                        if (findVo) {
                            findVo.call_back = null
                        }
                    }
                }
                this.event_id = GlobalEventSystem.Bind(EventName.QUIT_FIGHT_STATE, quit_fun)
            }
        }

