	public static ActivityOpenName(jump_id) {
		let list = jump_id.toString().split("_")
		let type_id = 0
		if (list.length >= 2) {
			type_id = Number(list[2])
		}

		if (type_id == 98) {
			return "超值礼包"
		}

	}

	public static OpenIcon(jump_id) {
		jump_id = Number(jump_id)
		if (jump_id == 53) {
			return `icon_json.16_png`
		}
		if ((jump_id == 60 || jump_id == 87) || jump_id >= 140 && jump_id <= 145) {
			return `icon_json.22_png`
		}
		if (jump_id == 31) {
			return `icon_json.15_png`
		}
		if (jump_id == 48) {
			return `icon_json.19_png`
		}
		if (jump_id == 67) {
			return `icon_json.153_png`
		}
	}

