import { UserMsgAdapter } from "./UserMsgAdapter";
import { GlobalEventSystem } from "../util/DeclareGlobalVar";
import { BaseClass } from "./BaseClass";
import { GlobalTimerQuest } from "../util/Util";
// TypeScript file
export class BaseController extends BaseClass {
    static request_protocals_list: Array<any> = [];
    static handle_protocals = {};
    static is_delay_send_protocal = false;
    static delay_timer_id;
    RegisterProtocal;
    SendFmtToGame;
    WriteBegin;
    WriteFMT;
    SendToGame;
    SendFmtToGameImme
    ReadFmt;
    Bind;
    UnBind;
    Fire;
    public constructor() {
        super();
        let self = this, user_msg_adapter = UserMsgAdapter.GetInstance(), Global_Event_System = GlobalEventSystem, local_BaseController = BaseController;
        /**
        功能:	注册一条协议的响应函数
        参数:
                id 协议号
                func_name 继承ProtocalBase类的成员函数名称
        返回值:
                无
        其它:	无
        */
        self.RegisterProtocal = (id, register_func) => {
            if (typeof(register_func) == "string"){
                register_func = this[register_func]
            }
            user_msg_adapter.RegisterMsgOperate(id, register_func);
        };
        self.SendFmtToGame = (cmd, fmt_str?, ...other) => {
            if (local_BaseController.is_delay_send_protocal || local_BaseController.request_protocals_list.length > 0) {
                let vo = { cmd: cmd, fmt_str: fmt_str, args: other };
                local_BaseController.request_protocals_list.push(vo);
                if (!local_BaseController.delay_timer_id) {
                    local_BaseController.delay_timer_id = GlobalTimerQuest.AddPeriodQuest(local_BaseController.DelaySendFmtToGame, 20);
                }
            }
            else {
                user_msg_adapter.SendAllFmtToGame(cmd, fmt_str, other);
            }
        };
        self.WriteBegin = (cmd) => {
            user_msg_adapter.WriteBegin(cmd);
        };
        self.WriteFMT = (fmt_str, ...other) => {
            user_msg_adapter.WriteFMT(fmt_str, other);
        };
        self.SendToGame = () => {
            user_msg_adapter.SendToGame();
        };
        /**
        功能:	从协议缓冲区按格式化字符串读取内容
        参数:
                fmt_str 格式化字符串(参见文件头部说明) string
        返回值:
                根据格式化字符串返回多个值
        其它:	无
       */
        self.ReadFmt = (fmt_str) => {
            return user_msg_adapter.ReadFmt(fmt_str);
        };
        self.Bind = (event_id, event_func) => {
            return Global_Event_System.Bind(event_id, event_func);
        };
        self.UnBind = (obj) => {
            Global_Event_System.UnBind(obj);
        };
        self.Fire = (event_id, ...other) => {
            Global_Event_System.Fire(event_id, ...other);
        };
        self.SendFmtToGameImme = (cmd,fmt_str,...other) =>{
            user_msg_adapter.SendAllFmtToGame(cmd, fmt_str, other);
        }
    }
    public static DelaySendFmtToGame() {
        let base_con = BaseController;
        let size = base_con.request_protocals_list.length;
        if (size <= 10 && !base_con.is_delay_send_protocal) {
            if (base_con.delay_timer_id) {
                GlobalTimerQuest.CancelQuest(base_con.delay_timer_id);
                base_con.delay_timer_id = null;
            }
        }
        if (size > 0) {
            size = Math.min(size, 10);
            for (let i = 0; i < size; i++) {
                let vo = base_con.request_protocals_list.shift();
                if (vo) {
                    UserMsgAdapter.GetInstance().SendAllFmtToGame(vo.cmd, vo.fmt_str, vo.args);
                }
            }
        }
    }
}

window["BaseController"] = BaseController