import { BaseController } from "../common/BaseController"
import { Util } from "../util/Util"
import { EventName } from "../common/EventName"
import { UserMsgAdapter } from "../common/UserMsgAdapter"
import { GoodsModel } from "../commonModel/GoodsModel"
import { UIToolTipMgr } from "../common/UIToolTipMgr"
import { DragonBallModel } from "../commonModel/DragonBallModel"
import { DragonBallView } from "../dragonBall/DragonBallView"

export class DragonBallController extends BaseController {
	model
	user_msg_adapter
	view
	goods_model

	public constructor() {
		super()

		this.user_msg_adapter = UserMsgAdapter.GetInstance()
		this.model = DragonBallModel.GetInstance()
		this.goods_model = GoodsModel.GetInstance()

		this.RegisterAll()
		this.InitEvent()
	}


	public InitEvent() {
		this.Bind(EventName.GAME_START, () => {
			this.SendFmtToGame(14300)
		})

		this.model.Bind(DragonBallModel.OPEN_VIEW, () => {
			if (!this.view) {
				this.view = new DragonBallView()
			}
			this.view.Open()
		})

		this.model.Bind(DragonBallModel.OPEN_TIPS, (red_state?) => {
			UIToolTipMgr.GetInstance().AppendDragonBallTips(this.model.type_id, this.model.act_num, this.model.dragon_list, red_state)
		})

		this.model.Bind(DragonBallModel.REQUEST_SCMD, (...new_args) => {
			let arg = new_args
			if (arg[0] == 14300) {
				this.SendFmtToGame(14300)
			} else if (arg[0] == 14301) {
				this.SendFmtToGame(14301, "i", arg[1])
			} else if (arg[0] == 14302) {
				this.SendFmtToGame(14302, "i", arg[1])
			}
		})

		this.model.Bind(DragonBallModel.ACTIVE_UPDATE, (ball_id?, ball_lv?, good_id?) => {
			if (ball_lv == 0) {
				this.model.Fire(DragonBallModel.REQUEST_SCMD, 14301, ball_id)
			} else {
				this.model.Fire(DragonBallModel.REQUEST_SCMD, 14302, ball_id)
			}
		})

		// 背包中物品变动时进行红点检测
		this.goods_model.Bind(GoodsModel.CHANGE_BAG_LIST, () => {
			this.model.CheckRedState()
		})
	}


	public RegisterAll() {
		// 获取龙珠列表
		let On14300 = () => {
			let scmd = this.user_msg_adapter.GetSCMD(14300)
			this.model.SetData(scmd.dragon_list, scmd.sum_power)
		}

		// 龙珠激活
		let On14301 = () => {
			let scmd = this.user_msg_adapter.GetSCMD(14301)
			if (scmd.errcode == 1) {
				this.model.UpdateData(scmd.dragon_id, 1, scmd.sum_power)	// 激活默认1级
				this.view.ShowEffect(true)
			} else {
				Util.ErrorCodeShow(scmd.errcode)
			}
		}

		// 龙珠升级
		let On14302 = () => {
			let scmd = this.user_msg_adapter.GetSCMD(14302)
			if (scmd.errcode == 1) {
				this.model.UpdateData(scmd.dragon_id, scmd.dragon_lv, scmd.sum_power)
				this.view.ShowEffect()
			} else {
				Util.ErrorCodeShow(scmd.errcode)
			}
		}

		this.RegisterProtocal(14300, On14300)
		this.RegisterProtocal(14301, On14301)
		this.RegisterProtocal(14302, On14302)
	}
}

window["DragonBallController"] = DragonBallController