import { ArrowComponent } from "../common/ArrowComponent"
import { BaseAwardItem } from "../common/BaseAwardItem"
import { BaseItemRenderer } from "../common/BaseItemRenderer"
import { BaseView1 } from "../common/BaseView1"
import { EventName } from "../common/EventName"
import { Enum_UILayer } from "../common/LayerManager"
import { LoopScrCon, LoopScrowViewMgr } from "../common/LoopScrowViewMgr"
import { UIToolTipMgr } from "../common/UIToolTipMgr"
import { GoodsModel } from "../commonModel/GoodsModel"
import { RuneTreasureEvent, RuneTreasureModel } from "../commonModel/RuneTreasureModel"
import { StoryModel } from "../commonModel/StoryModel"
import { PlatformManager } from "../PlatformManager"
import { GlobalEventSystem } from "../util/DeclareGlobalVar"
import { Util } from "../util/Util"
import { TreasureBagItemRender } from "./TreasureBagItemRender"

export class EquipTreasureBagView extends BaseView1 {
    public close_btn
    public bag_scroller
    public bag_group
    public get_btn
    public tip_text
    bg: Laya.Image
    item_bg: Laya.Image
    Content
    _Image1: Laya.Image
    labelDisplay: Laya.Label
    _Image11: Laya.Image
    _Image2: Laya.Image

    FirstTreasure
    InitView
    LoadSuccess
    InitEvent
    Local_DeleteMe
    public constructor() {
        super()
        this.base_file = "runeTreasure"
        this.layout_file = "EquipTreasureBagView"
        this.layer_value = Enum_UILayer.Activity
        this.use_background = true
        this.click_bg_toClose = true
        this.is_center = true
        this.destroy_imm = true
        let local_global = GlobalEventSystem
        let local_event = RuneTreasureEvent
        let local_eventname = EventName
        let local_util = Util
        let model = RuneTreasureModel.GetInstance()
        let local_gmodel = GoodsModel.GetInstance(),
            arr_collection_: LoopScrowViewMgr,
            full_list_ = [],
            pos_
        this.load_callback = function () {
            this.LoadSuccess()
            this.InitEvent()
        }
        this.open_callback = function () {
            // this.InitView()
        }
        this.close_callback = function () {
            if (model.first) {
                model.first = false
                model.Fire(local_event.FIRST, false)
                local_global.Fire(local_eventname.HIDE_FINGER, this.get_btn)
            }
        }

        this.Close=()=>{
            if (arr_collection_ ) {
                arr_collection_.DeleteMe()
                arr_collection_ = null
            }
            super.Close()
        }


        this.LoadSuccess = () => {
            if (PlatformManager.IsEyouEnPlatform()) {
                this.tip_text.size = 22;
            }
            // arr_collection_ = new eui.ArrayCollection()
            // this.bag_group.dataProvider = arr_collection_
            // this.bag_group.itemRenderer = TreasureBagItemRender
            this.InitView()
        }

        this.InitEvent = () => {
            let OnCloseBtnClick = () => {
                this.Close()
            }
            local_util.AddClickEvent(this.close_btn, OnCloseBtnClick, this, true)

            local_util.AddClickEvent(this.get_btn, () => {
                model.Fire(local_event.RUNE_TREASURE_REQUEST_PROTO, 41606)
                this.Close()
            }, this, true)

            this.BindEvent(local_gmodel, GoodsModel.UPDATE_GOODS_NUM, () => {
                if (this.use_delete_method) return
                this.InitView()
            })

            this.BindEvent(model, local_event.GET_ONE_REWARD, (scmd) => {
                if (scmd) {
                    let goodsids = []
                    if (scmd.gtyp_id == 32010095) {
                        goodsids.push([3, 0, 200])
                    } else {
                        goodsids.push([0, scmd.gtyp_id, 1]);
                    }
                    local_global.Fire(local_eventname.REWARD_FLY, goodsids, RuneTreasureModel.show_bag_pos)
                }
            })
        }

        this.InitView = () => {
            // full_list_ = local_gmodel.treasure_goods_list
            full_list_=[]
            for(let key in local_gmodel.treasure_goods_list){
                full_list_.push(local_gmodel.treasure_goods_list[key])
            }
            let rem = local_gmodel.treasure_goods_list.length % 4
            for (let i = 0; i < (20 - rem); i++) {
                full_list_.push({ })
            }
            if(!arr_collection_){
                arr_collection_=new LoopScrowViewMgr()
                arr_collection_.SetData(this.Content, TreasureBagItemRender, full_list_, LoopScrCon.Vertical, 1)
            }else{
                arr_collection_.replaceAll(full_list_)
            }
            if (model.first) {
                this.FirstTreasure()
            }
        }

        /**装备寻宝首次抽奖引导*/
        this.FirstTreasure = () => {
            let setp_cfg = { "direction": 8, "text": "快来领取奖励吧" }
            local_global.Fire(local_eventname.SHOW_FINGER, this.get_btn, undefined, undefined, undefined, undefined, setp_cfg, true)
            let arrow: ArrowComponent = StoryModel.GetInstance().GetFinger(this.get_btn)
        }

        
	this.Local_DeleteMe = () => {
		if (arr_collection_ ) {
			arr_collection_.DeleteMe()
			arr_collection_ = null
		}
	}
    }

    
	public DeleteMe() {

		this.Local_DeleteMe()
		super.DeleteMe()
	}



    

    public GetComponents() {
        [
            this.bg,
            this.item_bg,
            this.bag_scroller,
            this.Content,
            this.close_btn,
            this.tip_text,
            this.get_btn,
            this._Image1,
            this.labelDisplay,
            this._Image11,
            this._Image2,
        ]
            = this.GetChildrenByNames([

                "bg",
                "item_bg",
                "bag_scroller",
                "Content",
                "close_btn",
                "tip_text",
                "get_btn",
                "_Image1",
                "labelDisplay",
                "_Image11",
                "_Image2",
            ])
    }
}

window["EquipTreasureBagView"] = EquipTreasureBagView