	public DeleteMe() {
		this.ReleaseObj()
		if (this.modelObj_transform ) {
			 this.modelObj_transform.owner.destroy()
			 this.modelObj_transform = null
		}

		if (this.force_set_height_id) {
			GlobalEventSystem.UnBind(this.force_set_height_id)
			this.force_set_height_id = null
		}

		if (this.name_board) {
			this.name_board.DeleteMe()
			this.name_board = null
		}
		if (this.talk_board) {
			this.talk_board.DeleteMe()
			this.talk_board = null
		}
		super.DeleteMe()
	}

