	public ReleaseSceneObj() {
		if (this.is_in_cache_pool) { return }
		this._state_machine_manager.ChangeState(PoseState.NULL)
		GlobalEventSystem.Fire(ObjectEventType.REMOVE_SCENE_OBJECT, this.vo)
		this.SetModelHideFlag(SceneObj.ModelHideFlag.All, false)
		this.is_in_cache_pool = true

		this.is_first_objs_pos_height = true
		this.model_res_size.x = 90
		this.model_res_size.y = 160
		this.res_size.x = 90
		this.res_size.y = 160
		this.direction.x = 0
		this.direction.y = -1
		this.scale = 1
		this.direction_angle = 90
		this.rotateY = 0
		//this.ratateZ = SceneRotateZ
		this.RemoveScreenObj()
		this.RemoveGameObject()
		this.model_abName = false
		this.model_resName = false
		this.is_model_hiden = false
		this.ignore_pool = false
		this.hide_name_by_model = false
		this.is_add_scene = false
		this.custom_speed = null
		// if (this.parent_gameObject && this.parent_gameObject.activeSelf ) {
		//	 this.parent_gameObject.visible = false 
		// }
		if (this.name_board) {
			this.name_board.ReleaseData()
		}
		if (this.talk_board) {
			this.talk_board.DeleteMe()
			this.talk_board = null
		}
		// this.has_alpha_shader_list = []
		// this.mat_shader_name_before_replace = []
		this.shadow2_mat = false
		this.SetShadowVisible(false)
		ResManager.GetInstance().DestroyAllReferenceRes(this.hashCode);
		// lua_resM.ClearReference(this)
	}

	public SetModelHideFlag(flag?, hide?) {

		if (!this.model_hide_flag || !flag) {
			return
		}

		let now_flag = 0
		if (hide) {
			now_flag = this.model_hide_flag | flag
		} else {
			now_flag = this.model_hide_flag & ~flag
		}

		if (now_flag == this.model_hide_flag) {
			return
		}

		//如果剧情状态有变，就要刷新一下姓名板
		// let has_story_flag = this.model_hide_flag & SceneObj.ModelHideFlag.Story
		// let story_playing = false
		// if (has_story_flag != story_playing ) {
		// 	 this.UpdateNameBoardVisible()
		// }

		this.model_hide_flag = now_flag
		this.RefreshHideFlag()
	}

