	//根据model_hide_flag刷新Visible
	public RefreshHideFlag() {

		let old_hide_name_by_model = this.hide_name_by_model
		this.hide_name_by_model = false
		let show_talk_board = true

		if ((this.model_hide_flag & SceneObj.ModelHideFlag.ServerHide) != 0
			|| (this.model_hide_flag & SceneObj.ModelHideFlag.Story) != 0
			|| (this.model_hide_flag & SceneObj.ModelHideFlag.LogicHide) != 0
			|| (this.model_hide_flag & SceneObj.ModelHideFlag.BlockHide) != 0
			|| (this.model_hide_flag & SceneObj.ModelHideFlag.Skill) != 0
			|| (this.model_hide_flag & SceneObj.ModelHideFlag.IndependentHide) != 0
			|| (this.model_hide_flag & SceneObj.ModelHideFlag.IndependentHide2) != 0
			|| (this.model_hide_flag & SceneObj.ModelHideFlag.PerformanceHide) != 0
			|| (this.model_hide_flag & SceneObj.ModelHideFlag.Fly) != 0
			|| (this.model_hide_flag & SceneObj.ModelHideFlag.JumpPoint) != 0
			|| (this.model_hide_flag & SceneObj.ModelHideFlag.IndependenRole) != 0) {

			if (this.modelObj_transform && this.modelObj_transform.owner.active) {
				this.modelObj_transform.owner.active = false
			}
			this.SetBodyEffectVisible(false)
			this.is_model_hiden = true
			if (this.name_board) {
				this.hide_name_by_model = true
			}
			show_talk_board = false
		} else if ((this.model_hide_flag & SceneObj.ModelHideFlag.OnlyShowHorse) != 0) {
			if (this.modelObj_transform && !this.modelObj_transform.owner.active) {
				this.modelObj_transform.owner.active = true
			}
			if (this["horse_gameObject"] && !this["horse_gameObject"].active) {
				this["horse_gameObject"].active = true
			}
			if (this.gameObject && this.gameObject.active) {
				this.gameObject.active = false
			}
			this.SetBodyEffectVisible(false)
			this.is_model_hiden = true
			if (this.name_board) {
				this.hide_name_by_model = true
			}
			show_talk_board = false
			//设置界面隐藏其他玩家，只是隐藏model
		} else if ((this.model_hide_flag & SceneObj.ModelHideFlag.RoleNumLimit) != 0) {
			this.SetBodyEffectVisible(true)
			if (this.modelObj_transform && this.modelObj_transform.owner.active) {
				this.modelObj_transform.owner.active = false
			}

			this.SetShadowVisible(true)

			this.is_model_hiden = true
			// if (this.name_board ) {
			// 	this.hide_name_by_model = true
			// }
			show_talk_board = false
		} else {
			this.SetBodyEffectVisible(true)
			if (this.modelObj_transform && !this.modelObj_transform.owner.active) {
				this.modelObj_transform.owner.active = true
			}
			this.SetShadowVisible(true)
			if (this.gameObject && !this.gameObject.active) {
				this.gameObject.active = true
			}
			this.is_model_hiden = false
		}

		if (old_hide_name_by_model != this.hide_name_by_model) {
			this.UpdateNameBoardVisible()
		}

		if (this.talk_board) {
			this.talk_board.Show(show_talk_board)
		}
	}

