import { BaseItem1 } from "../common/BaseItem1"
import { Enum_UILayer } from "../common/LayerManager"
import { ResManager } from "../common/ResManager"
import { FashionModel } from "../commonModel/FashionModel"
import { Message } from "../sysinfo/SysInfoController"
import { Util } from "../util/Util"

//-@class FashionColorItem
export class FashionColorItem extends BaseItem1 {
	bg: Laya.Image
	select: Laya.Image
	icon: Laya.Image
	lock: Laya.Image
	color_id: Laya.Label
	red: Laya.Image
	click:Laya.Image
	info
	model




	public constructor(parent) {
		super(parent)

		this.base_file = "fashion"
		this.layout_file = "FashionColorItem"
		this.layer_value = Enum_UILayer.UI
		this.model = FashionModel.GetInstance()
		this.load_callback = () => {
			this.InitEvent()
		}
	}

	public InitEvent() {


		Util.AddClickEvent(this.click, () => {
			if (this.info && this.info.fashion_info != null) {
				this.model.Fire(FashionModel.SELECTCOLOR, this.info.pos, this.info.color_id)
			} else if (this.info && this.info.color_id && this.info.color_id != 0) {
				Message.show("激活初始时装后解锁")
			}
		}, this, true)

		this.BindEvent(this.model, FashionModel.SELECTCOLOR, (pos_id?, color_id?) => {
			if (pos_id && this.info && this.info.pos == pos_id) {
				if (this.info.color_id == color_id) {
					this.select.visible = true
				} else {
					this.select.visible = false
				}
			}
		})
	}

	public InitView() {

		if (!this.info) { return }
		let color_id = this.info.color_id
		let is_active = this.info.fashion_info != null
		this.select.visible = this.info.is_select
		this.lock.visible = !is_active && color_id != 0
		let icon
		let bg = "uiszv3_0013a"
		if (this.info.pos == 1) {
			icon = color_id == 0 && "uirw_045b" || "uirw_048b"
		} else {
			icon = color_id == 0 && "uirw_047b" || "uirw_049b"
		}
		if (is_active) {
			for (let k in this.info.fashion_info.color_list) {
				var v = this.info.fashion_info.color_list[k]
				if (v.color_id == color_id) {
					if (this.info.pos == 1) {
						icon = color_id == 0 && "uirw_046a" || "uirw_048a"
					} else {
						icon = color_id == 0 && "uirw_047a" || "uirw_049a"
					}
					bg = "uiszv3_0012a"
					break
				}
			}
		}
		ResManager.GetInstance().SetImageSprite(this, this.icon, "fashion_asset", icon)
		ResManager.GetInstance().SetImageSprite(this, this.bg, "fashion_asset", bg)
		this.color_id.text = color_id + 1
		let red
		if (color_id == 0) {
			let redList = this.model.fashion_red_list[this.info.pos]
			if (redList && redList[this.info.fashion_id] && redList[this.info.fashion_id] > 0) {
				red = true
			} else {
				red = false
			}
		} else {
			red = this.model.GetColorRed(this.info.pos, this.info.fashion_id, this.info.color_id)
		}
		this.red.visible = red
	}

	public SetData(data?) {

		this.info = data
		this.InitView()
	}

	public DeleteMe() {


	}


	public GetComponents() {
		[
			this.bg,
			this.select,
			this.icon,
			this.lock,
			this.color_id,
			this.red,
			this.click
		]
			= this.GetChildrenByNames([

				"bg",
				"select",
				"icon",
				"lock",
				"color_id",
				"red",
				"click",
			])
	}
}
window["FashionColorItem"] = FashionColorItem