import { CommonManager } from "../common/CommonManager"
import { Config } from "../common/Config"
import { SkillManager } from "../skill/SkillManager"
import { ErlangParser } from "../util/ErlangParser"
import { EventDispatcher } from "../util/EventDispatcher"
import { GoodsModel } from "./GoodsModel"

export class DragonBallModel extends EventDispatcher {
	sum_power
	act_num
	red_state
	type_id
	currn_index
	max_lv
	ball_num
	dragon_list

	public static OPEN_VIEW = "OPEN_VIEW"
	public static UPDATE_VIEW = "UPDATE_VIEW"
	public static OPEN_TIPS = "OPEN_TIPS"
	public static REQUEST_SCMD = "REQUEST_SCMD"
	public static SELECT_ITEM = "SELECT_ITEM"
	public static ACTIVE_UPDATE = "ACTIVE_UPDATE"
	public static UPDATE_ICON_RED = "UPDATE_ICON_RED"

	id_to_set = Config.PRELOAD_CLIENT_CONFIG.ConfigDragonBallMsg
	congfig_dragonball = Config.PRELOAD_SERVER_CONFIG.config_dragon_ball
	erlang_parser
	goods_model
	skill_mgr
	static Instance: any

	public constructor() {
		super()

		if (DragonBallModel.Instance) {
			return
		}

		this.erlang_parser = ErlangParser.GetInstance()
		this.goods_model = GoodsModel.GetInstance()
		this.skill_mgr = SkillManager.GetInstance()

		this.dragon_list = []							// 当前龙珠数据
		this.ball_num = 0								// 龙珠总数量
		this.act_num = 0								// 当前激活的龙珠数
		this.type_id = 0								// 龙珠物品id
		this.currn_index = 1							// 当前选中龙珠，默认为1
		this.max_lv = 11 //Config.Dragonballkv[2].value		// 龙珠最高等级
		this.red_state = false							// 红点
		this.sum_power = 0								// 龙珠总战力

		this.InitData()
	}

	public static GetInstance() {
		if (!DragonBallModel.Instance) {
			DragonBallModel.Instance = new DragonBallModel()
		}
		return DragonBallModel.Instance
	}

	// 返回龙珠功能状态：false/功能未开启,true/开启
	public GetState() {
		return CommonManager.GetInstance().CheckFuncOpenState("DragonBallView", true)
	}

	// 处理数据相关函数
	public InitData() {
		this.act_num = 0
		this.type_id = 0
		this.ball_num = 0

		for (let k in this.id_to_set) {
			var v = this.id_to_set[k]
			this.dragon_list[v.set] = { dragon_id: Number(k) , dragon_lv: 0, red_state: false }
			this.ball_num = this.ball_num + 1
		}
	}

	// 设置龙珠数据，协议14300调用
	public SetData(dragon_list?, sum_power?) {
		let index = 0
		this.InitData()
		for (let _ in dragon_list) {
			var v = dragon_list[_]
			index = this.id_to_set[v.dragon_id].set
			this.dragon_list[index].dragon_lv = v.dragon_lv
			this.act_num = this.act_num + 1
		}
		this.sum_power = sum_power
		this.CheckRedState()
	}

	// 更新龙珠数据，激活/升级时触发
	public UpdateData(dragon_id?, dragon_lv?, sum_power?) {
		let index = this.id_to_set[dragon_id].set
		this.dragon_list[index].dragon_lv = dragon_lv
		this.sum_power = sum_power
		this.CheckRedState()
		if (dragon_lv == 1) {
			this.act_num = this.act_num + 1
			this.Fire(DragonBallModel.UPDATE_VIEW, index, true, this.dragon_list[index].red_state)
		} else {
			this.Fire(DragonBallModel.UPDATE_VIEW, index, false, this.dragon_list[index].red_state)
		}
	}

	// Model提供的Get类函数
	public GetVobySet(index?) {
		return this.dragon_list[index]
	}

	public GetIdbySet(index?) {
		return this.dragon_list[index].dragon_id
	}

	public GetLvbySet(index?) {
		return this.dragon_list[index].dragon_lv
	}

	public GetFightNum() {
		return this.sum_power
	}

	public GetSkillMsg(id?, lv?) {
		let index = id + "@" + lv
		let skill_info = this.erlang_parser.Parse(this.congfig_dragonball[index].skill)
		let skill_id = Number(skill_info[1][1])
		let config = this.skill_mgr.getSkillFromConfig(skill_id)
		return config
	}

	// 根据索引获取龙珠升级的信息
	public GetUpdateMsg(index?) {
		let id = this.dragon_list[index].dragon_id,
			lv = this.dragon_list[index].dragon_lv
		lv = lv + 1
		if (lv > this.max_lv) {
			lv = this.max_lv
		}
		let config_index = id + "@" + lv
		let cost_info = this.erlang_parser.Parse(this.congfig_dragonball[config_index].cost)
		let type_id = Number(cost_info[0][1])
		let count = Number(cost_info[0][2])
		return [type_id, count]
	}

	// 检查龙珠模块的红点状态
	public CheckRedState() {
		if (!this.GetState()) {
			return
		}
		let type_id, need_count, now_count = 0
		this.red_state = false
		for (let k in this.dragon_list) {
			var v = this.dragon_list[k]
			if (v.dragon_lv < this.max_lv) {
				[type_id, need_count] = this.GetUpdateMsg(k)
				now_count = this.goods_model.GetTypeGoodsNum(type_id)
				if (now_count >= need_count) {
					v.red_state = true
					this.red_state = this.red_state || true
				} else {
					v.red_state = false
					this.red_state = this.red_state || false
				}
			} else {
				v.red_state = false
			}
		}
		this.Fire(DragonBallModel.UPDATE_ICON_RED)
	}

	// 红点查询函数
	public GetRed() {
		return this.red_state
	}

	// 根据索引获取单个龙珠红点状态
	public GetRedbySet(index?) {
		return this.dragon_list[index].red_state
	}

	// 根据红点状态来设置默认选中的龙珠
	public GetCurrnIndex() {
		this.currn_index = 0
		for (let k in this.dragon_list) {
			var v = this.dragon_list[k]
			if (v.red_state) {
				this.currn_index = k
				break
			}
		}
		return this.currn_index
	}
}
window["DragonBallModel"] = DragonBallModel