import { BaseAwardItem } from "../common/BaseAwardItem"
import { BaseView1 } from "../common/BaseView1"
import { Config } from "../common/Config"
import { Enum_UILayer } from "../common/LayerManager"
import { ResManager } from "../common/ResManager"
import { WithBtnHSlider } from "../common/WithBtnHSlider"
import { GoodsModel } from "../commonModel/GoodsModel"
import { GameResPath } from "../util/GameResPath"
import { Util, SetHtmlCenter } from "../util/Util"

export class SellView extends BaseView1 {
	public _Image111: Laya.Image;
	public _Image2: Laya.Image;
	public _Image3: Laya.Image;
	public _Image4: Laya.Image;
	public _Image5: Laya.Image;
	public goods_name: Laya.HTMLDivElement;
	public item_group: Laya.Box;
	public price_text: Laya.Label;
	public price_label: Laya.Label;
	public price_image: Laya.Image;
	public slider_group: Laya.Box;
	public close_btn: Laya.Image;
	public cancel_btn: Laya.Box;
	public _Image11: Laya.Image;
	public labelDisplay1: Laya.Label;
	public enter_btn: Laya.Box;
	public _Image1: Laya.Image;
	public labelDisplay: Laya.Label;
	public _Group1: Laya.Box;
	public _Image6: Laya.Image;
	public title_label0: Laya.Label;

	CloseCallback
	InitEvent
	show_open_movie
	slider
	use_background
	click_bg_toClose
	sell_count
	min
	sell_price
	close_callback
	goods_vo
	goodsmodel
	destroy_imm
	award_item
	SetText
	is_center
	InitView
	Local_Open

	public constructor() {
		super()
		this.base_file = "common"
		this.layout_file = "GoodsFuncView"
		this.goodsmodel = GoodsModel.GetInstance();
		this.min = 1;
		this.sell_price = 0;
		this.layer_value = Enum_UILayer.Activity
		this.destroy_imm = true
		this.use_background = true
		this.click_bg_toClose = true
		this.show_open_movie = true
		this.is_center = true
		let local_Util = Util
		let local_GoodsModel = GoodsModel

		this.load_callback = () => {
			this.goods_name.width = 239.33
			this.goods_name.height = 50
			this.goods_name.style.fontSize = 24
			this.goods_name.style.color = "#ffffff"
			this.goods_name.style.align = "#center"
			this.goods_name.style.valign = "#middle"

			ResManager.GetInstance().SetOutsideImageSprite(this, this._Image111, GameResPath.GetIcon("common", "uisy_023"))
			if (this.goods_vo) {
				this.InitView()
			}
			this.InitEvent()
		}

		this.close_callback = () => {
			this.CloseCallback()
		}

		this.Local_Open = (goods_vo?) => {
			this.goods_vo = goods_vo
			if (this.is_loaded) {
				this.InitView()
			}
			super.Open()
		}

		this.InitView = () => {
			if (!this.goods_vo) {
				return
			}
			if (!this.award_item) {
				this.award_item = new BaseAwardItem(this.item_group)
				this.award_item.Load()
				this.award_item.ChangeCountVisible(false)
				this.award_item.SetShowTips(false)
			}
			this.award_item.SetData(this.goods_vo.type_id)
			this.goods_name.innerHTML = Util.StrToHTML(local_GoodsModel.GetGoodsNameWithColorLight(this.goods_vo.type_id))
			SetHtmlCenter(this.goods_name, { x: 181, w: 239.33 }, { y: 106, h: 50 })
			let cfg = ResManager.GetInstance().GetGameConfigFromCache(this, "config_goods_price", false)
			let price_cfg = cfg[this.goods_vo.type_id]
			if (price_cfg) {
				this.sell_price = price_cfg.sell_price
				let sell_price_type = price_cfg.sell_price_type
				if (sell_price_type == 1) {
					ResManager.GetInstance().SetImageSprite(this, this.price_image, "common_asset", "com_diamond")
					//this.price_image.source = "common_json.com_diamond_png"
				} else if (sell_price_type == 2) {
					ResManager.GetInstance().SetImageSprite(this, this.price_image, "common_asset", "com_cind_diamond")
					//this.price_image.source = "common_json.com_cind_diamond_png"
				} else if (sell_price_type == 3) {
					ResManager.GetInstance().SetImageSprite(this, this.price_image, "common_asset", "com_gold")
					//this.price_image.source = "common_json.com_gold_png"
				}
			}

			this.slider = new WithBtnHSlider(this.slider_group)
			this.slider.SetData(this.goods_vo.goods_num, 1, 0, this.goods_vo.goods_num, true, (value?) => {
				this.sell_count = value
				this.price_label.text = String(this.sell_price * value)
			}
			)
			this.slider.Load()
			this.slider.ExcuteCallback(() => {
				this.slider.x = -289
				this.slider.y = 33
			})

			this.SetText()
		}

		this.InitEvent = () => {
			let OnCloseBtnClick = () => {
				this.Close()
			}

			Util.AddClickEvent(this.close_btn, OnCloseBtnClick, this, true)
			let OnCancelBtnClick = () => {
				this.Close()
			}

			Util.AddClickEvent(this.cancel_btn, OnCancelBtnClick, this, true)
			let OnEnterBtnClick = () => {
				let num = this.slider.GetValue()
				let list = [{ goods_id: this.goods_vo.goods_id, num: num }]
				this.goodsmodel.Fire(local_GoodsModel.SELL_GOODS, list)
				this.Close()
			}

			Util.AddClickEvent(this.enter_btn, OnEnterBtnClick, this, true)
		}

		this.SetText = () => {
			this.title_label0.text = "出售"
			this.price_text.text = "价格:"
			this.price_text.visible = true
			this.price_image.visible = true
			this.price_label.visible = true
			//this.cancel_btn.GetComponent("Text").text = "取消"
			//this.enter_btn.label = "确定"
		}

		this.CloseCallback = () => {
			if (this.slider) {
				this.slider.DeleteMe()
				this.slider = null
			}
			if (this.award_item) {
				this.award_item.DeleteMe()
				this.award_item = null
			}
		}
	}

	public Open(goods_vo?) {
		this.Local_Open(goods_vo)
	}


	public GetComponents() {
		[
			this._Image111,
			this._Image2,
			this._Image3,
			this._Image4,
			this._Image5,
			this.goods_name,
			this.item_group,
			this.price_text,
			this.price_label,
			this.price_image,
			this.slider_group,
			this.close_btn,
			this.cancel_btn,
			this._Image11,
			this.labelDisplay1,
			this.enter_btn,
			this._Image1,
			this.labelDisplay,
			this._Group1,
			this._Image6,
			this.title_label0
		]
			= this.GetChildrenByNames([
				"_Image111",
				"_Image2",
				"_Image3",
				"_Image4",
				"_Image5",
				"goods_name",
				"item_group",
				"price_text",
				"price_label",
				"price_image",
				"slider_group",
				"close_btn",
				"cancel_btn",
				"_Image11",
				"labelDisplay1",
				"enter_btn",
				"_Image1",
				"labelDisplay",
				"_Group1",
				"_Image6",
				"title_label0"
			])
	}
}
window["SellView"] = SellView