    //检测屏蔽字 目前只有QQ审核用的到
    public MsgSecCheck(content, call_back) {
        if (!Util.IsQQGame() || !ClientConfig.msg_sec_check_php) {
            if (call_back) {
                call_back(true, content);
            }
            return;
        }
        // ClientConfig.msg_sec_check_php = "https://uploadlog.suyougame.com/api/special.php"
        let local_json_cfg = window["local_json_cfg"], package_code;
        if (local_json_cfg) {
            local_json_cfg = JSON.parse(local_json_cfg);
            let is_android = false;
            if (Util.GetDeviceOS() == DEVICE_OS.ANDORID) {
                is_android = true;
            }
            package_code = is_android ? local_json_cfg["android_number"] : local_json_cfg["ios_number"];
        }
        if (!package_code) {
            if (call_back) {
                call_back(true, content);
            }
            return;
        }
        let cur_time = String(Math.floor(new Date().getTime() / 1000)), login_key = ClientConfig.login_key, now_method = "word", get_params = {
            "time": cur_time,
            "sign": md5.hex_md5(String(login_key + cur_time + now_method)).toLowerCase(),
            "method": now_method,
            "game": "yyhx",
            "package_code": package_code,
            "content": content,
        };
        let call_func = (data) => {
            if (data) {
                data = JSON.parse(data);
                if (call_back) {
                    call_back(data.code == 0, content);
                }
            }
            else if (call_back) {
                call_back(true, content);
            }
        };
        /**time=1569147732&sign=facf1869109662cd06fb2696e5baea30&method=word&game=yyhx */
        HttpUtil.HttpGetRequest(ClientConfig.msg_sec_check_php, get_params, call_func);
    }
