    public EyouDataPlacement(_type, role_id?) {
        if (PlatformManager.IsEyouEnPlatform() && Util.IsRuntime2()) {
            let playerInfo = LoginManager.GetInstance().GetPlatUserInfo();
            if (!playerInfo) {
                return;
            }
            let RoleManager = window["RoleManager"]
            let main_role_vo = RoleManager.GetInstance().GetMainRoleVo();
            let data = {
                role_id: (role_id != undefined) ? role_id : (main_role_vo ? main_role_vo.role_id : 0),
                server_id: playerInfo.server_id,
                event: _type,
                count: main_role_vo ? main_role_vo.level : 0
            };
            if (_type) {
                this.CallNativeFunction("EventRecord", data);
            }
        }
    }
