			this.UpdateChat = (vo?, is_del?) => {
				if (this.is_loaded) {
					// if (is_del ) {
					// 	_arrayCollection_.replaceAll(chat_model.allChat)
					// }else{
					// 	if (_arrayCollection_.source.length > chat_model.chatMax ) {
					// 		_arrayCollection_.removeItemAt(0)
					// 	}
					// 	_arrayCollection_.addItem(chat)
					// }

					//如果更新的数据是已加载的数据，直接更新item
					let item = this.FindItemWithVo(left_item_list, vo)
					if (item && !Util.IsNull(item.transform.owner)) {
						item.SetData(vo, true)
						item.transform.SetAsLastSibling()
						return
					}

					var getCacheItem = () => {
						for (let i = 0; i < left_item_list.length; i++) {
							var v = left_item_list[i]
							let item = left_item_list[i]
							if (!Util.IsNull(item.transform.owner)) {
								table.remove(left_item_list, i)
								table.insert(left_item_list, item)
								item.transform.SetAsLastSibling()
								return item
							}
						}
					}

					if (left_item_list.length >= MainUIChatView.MAX_SHOW_ITEM_NUM) {
						item = getCacheItem()
						if (!item) {
							return
						}
					} else {
						let index = left_item_list.length + 1
						left_item_list[index] = new MainUIChatItem(chat_list)
						item = left_item_list[index]
					}
					item.SetData(vo, true)
				}
			}

