	public FindItemWithVo(list?, vo?) {

		//如果更新的数据是已加载的数据，直接更新item
		for (let i = 0; i < list.length; i++) {
			var item = list[i]
			if (item.data == vo) {
				return item
			}
		}
		return null
	}

