	public DeleteMe() {

		//this:ClearModel()
		if (this.fashion_awarditem_) {
			this.fashion_awarditem_.DeleteMe()
			this.fashion_awarditem_ = null
		}
		if (this.attr_item_list_.length > 0) {
			for (let _tmpi in this.attr_item_list_) {
				var item = this.attr_item_list_[_tmpi]
				item.DeleteMe()
			}
			this.attr_item_list_ = []
		}
		if (this.fashion_list) {
			this.fashion_list.DeleteMe()
			this.fashion_list = null
		}
		if (this.color_shape) {
			this.color_shape.DeleteMe()
			// destroy(this.color_shape)
			this.color_shape = null
		}
		if (this.color_items) {
			for (let k in this.color_items) {
				var v = this.color_items[k]
				v.DeleteMe()
			}
			this.color_items = []
		}
		super.DeleteMe()
	}


