import { Alert, Alert_Type } from "../alert/Alert"
import { VoiceChatView } from "../chat/VoiceChatView"
import { BaseItem1 } from "../common/BaseItem1"
import { BaseItemRenderer } from "../common/BaseItemRenderer"
import { EventName } from "../common/EventName"
import { ResManager } from "../common/ResManager"
import { GuildModel, GuildEvent } from "../commonModel/GuildModel"
import { MainFunc } from "../commonModel/MainUIModel"
import { ShopIndex } from "../commonModel/ShopModel"
import { RedPacketEvent, RedPacketModel } from "../redPacket/RedPacketModel"
import { GlobalEventSystem } from "../util/DeclareGlobalVar"
import { Util } from "../util/Util"

export class GuildMainItem extends BaseItemRenderer {
	data
	model
	red_model

	public static width = 90
	public static height = 100
	public constructor(parent) {
		super()


		this.model = GuildModel.GetInstance();
		this.red_model=RedPacketModel.GetInstance()
		this.base_file = "guild"
		this.layout_file = "GuildMainItem"
		this.load_callback = () => {

			// if (PlatformMgr.GetInstance().IsEyouEnPlatform() ) {
			// 	this._lb_name.size  = 18
			// }
			this.InitEvent()
		}

		this.Load()

	}

	public DeleteMe() {

		this.data = null
		super.DeleteMe()
	}

	public CheckRedDot() {

		if (!this.data) {
			return
		}
		let visible = false
		if (this.data.id == 1) {
			visible = this.model.CheckGiftRedDot()
		} else if (this.data.id == 2) {
			visible = this.model.CheckDonateRedDot() || this.model.CheckActivityRedDot()
		} else if (this.data.id == 3) {
			visible = this.model.CheckSkillRedDotAll() || this.model.guildIdolRed()
		} else if (this.data.id == 4) {
			visible = this.model.exchang_red
		} else if (this.data.id == 5) {
			visible = this.model.CheckEveningRedDot()
		} else if (this.data.id == 6) {
			visible = this.model.CheckExploreRedDot()
		} else if (this.data.id == 9) {
			visible = RedPacketModel.GetInstance().GetAllRedStatus()
		} else if (this.data.id == 10) {
			visible = this.model.CheckGuildguardRedDot()
		}
		this._reddot.visible = visible
	}

	public InitEvent() {

		Util.AddClickEvent(this._img_icon, () => {
			if (!this.data) {
				return
			}
			if (this.data.id == 1) {
				this.ClickGift()
			} else if (this.data.id == 2) {
				this.ClickDonate()
			} else if (this.data.id == 3) {
				this.ClickSkill()
			} else if (this.data.id == 4) {
				this.ChickDepot()
			} else if (this.data.id == 5) {
				this.ClickFire()
			} else if (this.data.id == 6) {
				this.ClickExplore()
			} else if (this.data.id == 7) {
				this.ClickOther()
			} else if (this.data.id == 8) {
				this.ClickDisband()
			} else if (this.data.id == 9) {
				this.ClickRedPacket()
			} else if (this.data.id == 10) {
				this.ClickGuard()
			} else if (this.data.id == 11) {
				this.ClickShop()
			}
		}
			, this, true)
		this.BindEvent(GlobalEventSystem, EventName.REFRESH_FUNCTION_ICON_RED_DOT, (id?) => {
			if (id != MainFunc.Guild) {
				return
			}
			this.CheckRedDot()
		}
		)
	}


	public dataChanged() {
		if(!super.dataChanged())return
		this._lb_name.text = this.data.title
		ResManager.GetInstance().SetImageSprite(this, this._img_icon, "guild_asset", this.data.icon)
		//this._img_icon.source = data.icon
		this.CheckRedDot()

	}

	public SetData(data?) {

		this.data = data
		this._lb_name.text = data.title
		ResManager.GetInstance().SetImageSprite(this, this._img_icon, "guild_asset", data.icon)
		//this._img_icon.source = data.icon
		this.CheckRedDot()
	}

	public ClickGift() {
		this.model.Fire(GuildEvent.OPEN_VIEW, "GuildGiftView")
		// let idol_open = this.model.GuildIdolIsOpen()
		// if (idol_open) {
		// 	this.model.Fire(GuildEvent.OPEN_VIEW, "GuildGiftView")
		// } else {
		// 	this.model.Fire(GuildEvent.OPEN_VIEW, "GuildGiftViewOne")
		// }

	}

	public ClickDonate() {

		this.model.check_donate_red_once = true
		this.CheckRedDot()
		GlobalEventSystem.Fire(EventName.REFRESH_FUNCTION_ICON_RED_DOT, MainFunc.Guild)
		this.model.Fire(GuildEvent.OPEN_VIEW, "GuildDonateView")
	}

	public ClickFire() {
		GlobalEventSystem.Fire(EventName.OPEN_VIEW,"EveningMainBaseView")
	}

	public ClickSkill() {

		this.model.Fire(GuildEvent.OPEN_VIEW, "GuildSkillBaseView")
	}

	public ChickDepot() {

		this.model.Fire(GuildEvent.OPEN_VIEW, "GuildDepotBaseView")
	}

	public ClickDisband() {

		Alert.Show(Util.StrToHTML("解散公会后自动遣散所有公会成员<br>解散公会后将保留<font color=\"#60aeff\">公会技能等级</font>，但<font color=\"#a376ff\">公会贡献</font>、<font color=\"#ff9015\">仓库积分</font>、<font color=\"#ff9015\">公会头衔</font>将被清空\n是否确定解散公会？"), Alert_Type.Two, () => {
			this.model.Fire(GuildEvent.REQUEST_PROTO, 40027)
		}
		)
	}

	public ClickOther() {

		this.model.Fire(GuildEvent.OPEN_VIEW, "GuildJoinBaseView")
	}

	public ClickExplore() {

		let can_open = this.model.CanOpenGuildExplore()
		if (can_open) {
			this.model.Fire(GuildEvent.OPEN_VIEW, "GuildExploreBaseView")
		}
	}

	public ClickRedPacket() {
		//this.red_model.Fire(RedPacketEvent.OPEN_VIEW, "RedPacketMainView")
		GlobalEventSystem.Fire(EventName.OPEN_VIEW, "RedPacketMainView")
	}

	public ClickGuard() {

		//let activity = DailyModel.GetInstance().GetAcCfg(402, 3, 1)
		//if (activity ) {
		//GlobalEventSystem:Fire(EventName.OPEN_VIEW, "GuildGuardBaseView", activity)
		//}
	}

	//声望商店
	public ClickShop() {

		GlobalEventSystem.Fire(EventName.OPEN_SHOP_MAIN_VIEW, ShopIndex.Guild, null, 4)
	}


	_img_icon: Laya.Image
	_lb_name: Laya.Label
	_reddot: Laya.Image
	public GetComponents() {
		[
			this._img_icon,
			this._lb_name,
			this._reddot,
		]
			= this.GetChildrenByNames([

				"_img_icon",
				"_lb_name",
				"_reddot",
			])
	}
}
window["GuildMainItem"] = GuildMainItem