	public GetAngle(pos1?, pos2?, real_pos?) {

		let x = 0
		let y = 0
		if (real_pos) {
			x = pos2.x - pos1.x
			y = pos2.y - pos1.y
		} else {
			x = pos1
			y = pos2
		}
		let radian = Math.atan2(y, x)
		// let angle = 180 / (Math.pi / radian)
		let angle = 57.295779 * radian
		return Math.floor(angle + 0.5)
	}
