import { GameResPath } from "./GameResPath";
// console.warn("EventDispatcher@GameError")
// import { GameError } from "./GameError";
import { Status } from "./Status";
import { LOAD_QUEUE } from "../util/DeclareGlobalVar";
import { BaseClass, HashObject } from "../common/BaseClass";
// import { GlobalTimerQuest } from "./Util";
// import { LOAD_QUEUE, ResManager } from "../common/ResManager";
// TypeScript file
export class EventDispatcher extends BaseClass {
    static ALL_VAR = "ALL";
    static ALL_CHANGED = "EventDispatcher.ALL_CHANGED";
    static CHANGE_VAR = "vo_change_var";
    delay_fire_BindId = 0;
    fire_event_startTime = 0;
    private static all_event_count = 88888888;

    all_event_dic: {
        [key: string]: {
            [key: number]: any;
        };
    } = {};
    bind_id_to_event_id_dic: {
        [key: number]: string;
    } = {};
    calling_event_dic: {
        [key: string]: Boolean | {
            [key: number]: Boolean;
        };
    } = {};
    use_delete_method: Boolean = false;
    Bind;
    UnBind;
    UnBindAll;
    Fire;
    ChangeAllVar;
    ChangeVar;
    BindOne;
    BindAll;
    DelayFire
    /**config_name, call_back, is_client_cfg = false, load_queue: LOAD_QUEUE = LOAD_QUEUE.HIGHT */
    /**config_name, is_client_cfg = false */

    public DeleteMe() {
        let self = this;
        if (self.delay_fire_BindId) {
            // GlobalTimerQuest.CancelQuest(self.delay_fire_BindId);
            self.delay_fire_BindId = 0;
        }
        self.fire_event_startTime = 0;
        self.UnBindAll();
    }
    _cfg_hash_obj = new HashObject();
    public constructor() {
        super();
        let self = this, Event_Dispatcher = EventDispatcher, local_GameResPath = GameResPath;
        self.Bind = (event_id: string, call_back: Function) => {
            if (event_id == null) {
                console.error("Try to bind to a nil event_id");
                return;
            }
            if (call_back == null) {
                console.error("Try to bind to a nil event_func");
                return;
            }
            let event_list = self.all_event_dic[event_id];
            if (event_list == null) {
                event_list = {};
                self.all_event_dic[event_id] = event_list;
            }
            ++Event_Dispatcher.all_event_count;
            self.bind_id_to_event_id_dic[Event_Dispatcher.all_event_count] = event_id;
            event_list[Event_Dispatcher.all_event_count] = call_back;
            return Event_Dispatcher.all_event_count;
        };
        self.UnBind = (bind_id) => {
            if (bind_id == null) {
                return;
            }
            let event_id = self.bind_id_to_event_id_dic[bind_id];
            if (event_id) {
                let calling_event = self.calling_event_dic[event_id];
                if (calling_event != null) {
                    if (calling_event == false) {
                        calling_event = {};
                        self.calling_event_dic[event_id] = calling_event;
                    }
                    calling_event[bind_id] = true;
                    let event_list = self.all_event_dic[event_id];
                    if (event_list) {
                        event_list[bind_id] = false;
                    }
                    return;
                }
                delete self.bind_id_to_event_id_dic[bind_id];
                let event_list = self.all_event_dic[event_id];
                if (event_list) {
                    delete event_list[bind_id];
                }
            }
        };
        self.UnBindAll = () => {
            // if (self.update_id > 0)
            // {
            //     Runner.GetInstance().RemoveRunObj(self.update_id)
            //     self.update_id = 0
            // }
            self.all_event_dic = {};
            self.bind_id_to_event_id_dic = {};
            // self.calling_event_dic = {}
            // delete self.need_fire_events
            // delete self.fire_callback_queue
        };
        self.Fire = (event_id, ...other) => {
            if (event_id == null) {
                console.log("Try to call EventDispatcher:Fire() with a nil event_id");
                return;
            }
            let event_list = self.all_event_dic[event_id];
            let n = 0;
            if (event_list) {
                self.calling_event_dic[event_id] = false;
                let vo;
                for (let bind_id in event_list) {
                    vo = event_list[bind_id];
                    n++;
                    if (n > 1000) {
                        let GameError = window["GameError"]
                        GameError.GetInstance().SendErrorToPHP("事件触发过多， event_id = " + event_id, true);
                    }
                    if (vo && vo != false) {
                        if (other && other.length > 0) {
                            vo(...other);
                        }
                        else {
                            vo();
                        }
                    }
                }
                let calling_event = self.calling_event_dic[event_id];
                delete self.calling_event_dic[event_id];
                if (calling_event && calling_event != false) {
                    for (let bind_id in calling_event) {
                        self.UnBind(bind_id);
                    }
                }
            }
        };
        self.ChangeAllVar = () => {
            for (let pro in self) {
                if (typeof self[pro] != "function") {
                    // console.log("ChangeVar", pro)
                    self.Fire(pro, pro, self[pro]);
                }
            }
            self.Fire(Event_Dispatcher.ALL_CHANGED);
        };
        self.ChangeVar = (var_type: string, value?, delay_to_fire: Boolean = false, force_fire: Boolean = false, param: any = null) => {
            let old_value = self[var_type];
            if (old_value != value || force_fire) {
                self[var_type] = value;
                if (delay_to_fire) {
                    let fire_func = () => {
                        self.fire_event_startTime = Status.NowTime;
                        if (self.delay_fire_BindId) {
                            // GlobalTimerQuest.CancelQuest(self.delay_fire_BindId);
                            self.delay_fire_BindId = 0;
                        }
                        self.Fire(var_type, var_type, value, old_value, param);
                    };
                    if (!self.fire_event_startTime || Status.NowTime - self.fire_event_startTime >= 0.02) {
                        fire_func();
                    }
                    else {
                        if (!self.delay_fire_BindId) {
                            let delayFunc = () => {
                                fire_func();
                            };
                            // self.delay_fire_BindId = GlobalTimerQuest.AddDelayQuest(delayFunc, 20);
                        }
                    }
                }
                else {
                    self.Fire(var_type, var_type, value, old_value, param);
                }
            }
        };
        self.BindOne = (var_type, func) => {
            let event_name = var_type;
            let eventId = self.Bind(event_name, func);
            return eventId;
        };
        self.BindAll = (func) => {
            let eventId = self.Bind(Event_Dispatcher.ALL_CHANGED, func);
            return eventId;
        };
        self.DelayFire = (event_id, ...other) =>{
            self.Fire(event_id, ...other)
        }
    }
}

window["EventDispatcher"] = EventDispatcher