import { BaseView1 } from "../common/BaseView1"
import { Enum_UILayer } from "../common/LayerManager"
import { LoopScrCon, LoopScrowViewMgr } from "../common/LoopScrowViewMgr"
import { ResManager } from "../common/ResManager"
import { table } from "../common/table"
import { BagModel } from "../commonModel/BagModel"
import { GoodsModel } from "../commonModel/GoodsModel"
import { Message } from "../sysinfo/SysInfoController"
import { GameResPath } from "../util/GameResPath"
import { Util } from "../util/Util"
import { OneKeyTabItem } from "./OneKeyTabItem"
import { OneKeyUseItem } from "./OneKeyUseItem"

export class OneKeyUseView extends BaseView1 {
	_img_bg: Laya.Image
	closeBtn: Laya.Image
	_Image3: Laya.Image
	_Label1: Laya.Label
	_Image4: Laya.Image
	_Image5: Laya.Image
	_Scroller1: Laya.Panel
	Content1: Laya.HBox
	_Scroller2: Laya.List
	nothingLb: Laya.Label
	useBtn: Laya.Box

	destroy_imm
	itemArr
	destroy_callback
	loop_mgr: LoopScrowViewMgr
	Clear
	show_open_movie
	is_center
	Scroll
	bag_Model
	goodsModel
	open_callback
	click_bg_toClose
	itemGp
	InitEvent
	TabList
	use_background
	tabGroup
	InitView
	public constructor() {
		super()

		this.base_file = "bag"
		this.layout_file = "OneKeyUseView"
		this.bag_Model = BagModel.GetInstance();
		this.goodsModel = GoodsModel.GetInstance();
		this.layer_value = Enum_UILayer.Activity
		this.use_background = true
		this.show_open_movie = true
		this.is_center = true
		this.click_bg_toClose = true
		let local_GoodsModel = GoodsModel
		this.destroy_imm = false
		//let local_Util = Util
		//this.preload_server_config = [Goods=false]
		this.load_callback = () => {

			this.InitEvent()
			this.InitView()
			ResManager.GetInstance().SetOutsideImageSprite(this, this._img_bg, GameResPath.GetIcon("common", "uisy_023"))
		}

		this.open_callback = () => {
			this.bag_Model.allUse = true
			this.bag_Model.onekeySelectList = []
		}

		this.destroy_callback = () => {
			this.Clear()
		}

		this.InitEvent = () => {
			this.BindEvent(this.goodsModel, local_GoodsModel.UPDATE_GOODS_NUM, () => {
				if (this.use_delete_method) {
					return
				}
				let cfgs = ResManager.GetInstance().GetGameConfigFromCache(this, "config_goods", false)
				let list = this.bag_Model.GetOneKeyUseList(cfgs)
				this.loop_mgr.replaceAll(list)
				this.nothingLb.visible = list.length == 0
			}
			)
			Util.AddClickEvent(this.closeBtn, () => {
				this.Close()
			}
				, this, true)

			Util.AddClickEvent(this.useBtn, () => {
				for (let key in this.bag_Model.UseSelectList) {

					let goodsVo = this.goodsModel.GetGoodsVoByGoodsId(key)
					if (goodsVo) {
						this.goodsModel.Fire(local_GoodsModel.USE_BAG_GOODS, goodsVo.goods_id, goodsVo.goods_num)
					}
				}
				if (Util.TableSize(this.bag_Model.UseSelectList) == 0) {
					Message.show("当前无可一键使用的道具")
				}
			}
				, this, true)
		}

		this.InitView = () => {
			let cfgs = ResManager.GetInstance().GetGameConfigFromCache(this, "config_goods", false)
			let list = this.bag_Model.GetOneKeyUseList(cfgs, true)
			//this.itemArr = eui. new ArrayCollection()
			//this.itemGroup.itemRenderer = OneKeyUseItem
			//this.itemGroup.dataProvider = this.itemArr
			if (list.length == 0) {
				this.nothingLb.visible = true
				//this.itemArr.source = []
				//this.itemArr.refresh()
			} else {
				this.nothingLb.visible = false
				//this.itemArr.replaceAll(list)
			}
			if (!this.loop_mgr) {
				this.loop_mgr = new LoopScrowViewMgr()
				this.loop_mgr.SetData(this._Scroller2, OneKeyUseItem, list, LoopScrCon.Vertical, 6)
			} else {
				this.loop_mgr.replaceAll(list)
			}

			this.TabList = []
			for (let _tmpi in this.bag_Model.typeList) {
				let vo = this.bag_Model.typeList[_tmpi]
				let tabItem = new OneKeyTabItem(this.Content1)
				tabItem.Load()
				tabItem.ExcuteCallback(() => {
					tabItem.SetData(vo)
				})
				table.insert(this.TabList, tabItem)
			}
			// ResManager.GetInstance().SetOutsideImageSprite(this, this._img_bg, "client/assets/icon/common/uisy_023.png")
		}

		this.Clear = () => {
			if (this.TabList) {
				for (let _tmpi in this.TabList) {
					let vo = this.TabList[_tmpi]
					vo.DeleteMe()
				}
				this.TabList = null
			}
			this.bag_Model.UseSelectList = []
			if (this.loop_mgr) {
				this.loop_mgr.DeleteMe()
				this.loop_mgr = null
			}
		}
	}

	public GetComponents() {
		[
			this._img_bg,
			this.closeBtn,
			this._Image3,
			this._Label1,
			this._Image4,
			this._Image5,
			this._Scroller1,
			this.Content1,
			this._Scroller2,
			this.nothingLb,
			this.useBtn,
		]
			= this.GetChildrenByNames([

				"_img_bg",
				"closeBtn",
				"_Image3",
				"_Label1",
				"_Image4",
				"_Image5",
				"_Scroller1",
				"Content1",
				"_Scroller2",
				"nothingLb",
				"useBtn",
			])
	}
}
window["OneKeyUseView"] = OneKeyUseView