	public AddIgnoreUpdateIndex(){ 
		
		this.ignore_update_index = this.ignore_update_index + 1
	}
	
	
	//每种状态都设置自己的更新频率 还有更新条件
	public CanUpdate(){ 
		
		return ! ((this.IsInState(PoseState.STAND) && this.ignore_update_index < 45)
					|| (this.IsInState(PoseState.ATTACK) && this.ignore_update_index < 3)
					|| (this.IsInState(PoseState.HITED) && this.ignore_update_index < 4)
					|| (this.IsInState(PoseState.DEAD) && this.ignore_update_index < 1)
					|| (this.IsInState(PoseState.WAITSTAND) && this.ignore_update_index < 6)
					|| (this.IsInState(PoseState.DOWN) && this.ignore_update_index < 3)
					|| (this.IsInState(PoseState.RISE) && this.ignore_update_index < 3)
					|| (this.IsInState(PoseState.DIZZY) && this.ignore_update_index < 3)
					|| (this.IsInState(PoseState.PAUSE) && this.ignore_update_index < 5)
					|| (this.IsInState(PoseState.SIT) && this.ignore_update_index < 8)
					|| (this.IsInState(PoseState.MAGIC) && this.ignore_update_index < 6)
				)
	}
	
	public ChangeState(value?){ 
		
		//为了防止状态切换嵌套。上一个状态没执行完，则缓存在队列中
		if (this.change_state_flag ) {
	
			this.delay_change_state_queue.push(value)
			return
		}
	
		if (value != PoseState.HITFLY && this.is_hit_fly) {	   //如果处于击飞状态不能切换 任何状态
			return  
		}
	
		// if (value != PoseState.FISHING && RoleManager.GetInstance().GetMainRoleVo().is_fishing_flag != 0  ) {	   //如果处于钓鱼阶段就不能切换任何状态	
		//	 return 
		// }
	
		if (value != PoseState.TRANSFER && this.is_transfer ) { //在传送状态下不可切换
			return
		}
	
		if (value != PoseState.HITED && (this.is_hit_heighting) ) {//悬空中不能切换任何状态 受击状态除外
			return
		}
	
		// if (value != PoseState.FLY_SHOE_EFFECT && this.is_shoe_flying ) { //在传送状态下不可切换
		//	 return
		// }
	
		//主角切掉打坐状态要发协议告诉服务端
		if (this.GetType() == SceneBaseType.MainRole ) {
			if (value != PoseState.STAND && value != PoseState.WAITSTAND && value != PoseState.COLLECT ) {
			//if (value != PoseState.COLLECT ) {
				GlobalEventSystem.Fire(EventName.CANCEL_TO_COLLECT,value)
			}
	
			if (this.main_role_move_start_time && value != PoseState.MOVE ) {
				this.main_role_move_start_time = false
			}
		}
	
		this.change_state_flag = true
		this.last_state = this.GetCurState()
		if (value == PoseState.WAITSTAND ) {
			this.waitstand_prev_state = this.last_state
		}
		// console.log("ChangeState")
		super.ChangeState(value)
		this.change_state_flag = false
	
		//上一状态切换完成。执行缓存的状态队列
		while (this.delay_change_state_queue.length > 0 ) {
			let temp_value =  this.delay_change_state_queue.pop()
			this.ChangeState(temp_value)
		}
		return true
	}
	
	
