	public DoHunluan(time?, offset?, wait_time?){ 
		
		if (this.GetType() == SceneBaseType.MainRole ) {
			OperateManager.Instance.StopMove()
		}
		if (this.IsDead() ) {
			return
		}
	
		let t = {	start_time : Status.NowTime,
		end_time : null,
		origin_pos : new Vector2(this.real_pos.x, this.real_pos.y),
		rand_pos : null,
		offset : offset || 80,
		wait_time : wait_time || 0,
		next_time : 0}
	
		t.end_time = t.start_time + (time || 1.0)
		this.rand_move_info = t
	
		if (! this.IsInState(PoseState.HUNLUAN) ) {
			this.ChangeState(PoseState.HUNLUAN)
		}
	}
	
