	public DoAttack(dir_vec?, movie_cfg?, rush_cfg?, attack_skill_id?){ 
		
		if (this.IsDead() ) {
			return false
		}
		// if (this.GetType() != SceneBaseType.MainRole && ! lua_viewM.main_cancas_last_visible ) {
		//	 return false
		// }
	
		this.attack_start_time = Status.NowTime
		this.attack_skill_id = attack_skill_id  //当前的攻击技能
		this.pre_swing = this.GetTimeWithAttackSpeed(movie_cfg.pre_swing || 0, this.attack_skill_id)
		this.spell_time = this.GetTimeWithAttackSpeed(movie_cfg.spell_time || 0, this.attack_skill_id)
		this.back_swing = this.GetTimeWithAttackSpeed(movie_cfg.back_swing || 0, this.attack_skill_id)
		this.rigidity_time = this.pre_swing + this.spell_time + this.back_swing //僵直时长
		this.movie_cfg = movie_cfg
		this.rush_cfg = rush_cfg
	
	
		if (dir_vec ) {
			this.attack_dir = dir_vec
		}
	
		this.SetLandInfo()//处理强制使用技能的情况 比如悬空中强制释放技能
		if (this.IsDead() ) {
			return false
		}
		if (this.rigidity_time == 0 ) {
			return false
		}
		if (this.IsInState(PoseState.DIZZY) || this.IsInState(PoseState.HUNLUAN) || this.IsInState(PoseState.PAUSE) ) {
			return false
		}
		this.ChangeState(PoseState.ATTACK)
		return true
	}
	
	//是否在前摇过程
	public IsInPreSwingState(){ 
		
		if (this.IsInState(PoseState.ATTACK) && Status.NowTime - this.attack_start_time <= this.pre_swing ) {
			return true
		}
	}
	
	
	//是否在施法过程
	public IsInSpellState(){ 
		
		if (this.IsInState(PoseState.ATTACK) &&
			! this.IsInPreSwingState() &&
			Status.NowTime - this.attack_start_time <= (this.pre_swing + this.spell_time) ) {
			return true
		}
	}
	
	//是否在后摇过程
	public IsInBackSwingState(){ 
		
		if (this.IsInState(PoseState.ATTACK) &&
			! this.IsInPreSwingState() &&
			! this.IsInSpellState() &&
			Status.NowTime - this.attack_start_time <= (this.pre_swing + this.spell_time + this.back_swing) ) {
			return true
		}
	}
	
