	public RemoveWeapon(bone_name?){ 
		if (this.weapon_container ) {
			let weapon_info = this.weapon_container[bone_name]
			if (weapon_info ) {
				this.weapon_container[bone_name] = null
				weapon_info.bone_name = bone_name
				weapon_info.go.active = true 
				this.weapon_animator = false
				this.remove_weapon = true
				return weapon_info
			}
		}
	}
	
	public AddWeapon(weapon_info?){ 
		if (this.weapon_container && weapon_info && weapon_info.bone_name ) {
			let bone_go = Util.FindBone(this.transform.owner, weapon_info.bone_name)
			if (bone_go ) {
			//  weapon_info.go.setParent(bone_go)
				bone_go.addChild(weapon_info.go)
				this.weapon_container[weapon_info.bone_name] = weapon_info
				this.remove_weapon = null
				if (this.weapon_hide_flag_list[weapon_info.bone_name] && this.weapon_hide_flag_list[weapon_info.bone_name] > 0 ) {
					weapon_info.go.active = false 
				}else{
					weapon_info.go.active = true 
				}
				this.BaseResLoadCallback()
			}
		}
	}
	
