	public DoBeAttacked(dir?, pos?, force_hited?, movie_cfg?, attacker?, skill_id?){ 
		
		if (this.IsDead() || this.vo == null ) {
			return false
		}
		this.ShowHittedEffect(movie_cfg, attacker)
		if (this.buff_manager.hasNoEffectBuff() ) {
			return false
		}
		if (this.IsInState(PoseState.JUMP) ) {
			return false
		}
		if (movie_cfg && movie_cfg.isHitedDown ) {
			this.DoDown()
			return false
		}
		this.hited_cfg = movie_cfg
		this.isHitHeightSkill = false //this.hited_cfg.isHitHeight_Skill && this.buff_manager.hasHitHeightBuff() 	//是否悬空技能
		this.isHitHeight_Again_Skill = false//this.hited_cfg.isHitHeight_Again_Skill && this.buff_manager.hasHitHeightAgainBuff() //是否继续悬空技能
		this.is_need_hit_height = false//(this.isHitHeightSkill && ! this.is_hit_heighting) || (this.is_hit_heighting && this.isHitHeight_Again_Skill)  //是否需要被击高
		return true
	}
	
