	public UpdateStateHited(state_name?, elapse_time?){ 
		
		let info = this.s_hited_info
		if (info ) {
			let past_time = Status.NowTime - info.start_time
			if (this.show_hit_color_end_time == null && this.hited_cfg && this.hited_cfg.hiter_color_info && past_time >= this.hited_cfg.hiter_color_info.delay_time ) { //处理变色
				this.SetColorFlag(Character.ColorFlag.Hited,true,this.hited_cfg.hiter_color_info.color[1], this.hited_cfg.hiter_color_info.color[2], this.hited_cfg.hiter_color_info.color[3])
				this.show_hit_color_end_time = Status.NowTime + this.hited_cfg.hiter_color_info.last_time
			}
			let p = null
			let move_time = this.is_need_hit_height && this.hitHeightSkill_info.complete_time || 0.1 //需要浮空的时候用浮空的总时间 或者就是默认的0.1
			if (past_time <= (move_time + elapse_time) && info.end_pos != null ) {
				p = past_time / move_time
				p = p > 1 && 1 || p
			}
	
			if (p != null ) {
				let x = info.start_pos.x * (1-p) + info.end_pos.x * p
				let y = info.start_pos.y * (1-p) + info.end_pos.y * p
				if (! this.scene_mgr.IsBlockXY(Math.floor(x / SceneObj.GetLogicRealRatio().x), Math.floor(y / SceneObj.GetLogicRealRatio().y)) ) {
					this.SetRealPos(x, y)
				}
			}
	
			//受击时间结束
			if (Status.NowTime >= info.stop_time ) {
				if (info.end_pos ) {
					let x = info.end_pos.x
					let y = info.end_pos.y
					if (! this.scene_mgr.IsBlockXY(Math.floor(x / SceneObj.GetLogicRealRatio().x), Math.floor(y / SceneObj.GetLogicRealRatio().y)) ) {
						this.SetRealPos(x, y)
					}
				}
				this.s_hited_info = null
			}
			if (this.s_hited_info && this.s_hited_info.hit_animation_time && past_time > this.s_hited_info.hit_animation_time ) { //回复待机动作
				let action_name = this.GetActionName("idle")
				this.PlayAction(action_name)
				this.s_hited_info.hit_animation_time = null
			}
		}
		// let hitHeightSkill_info = this.hitHeightSkill_info
		// if (hitHeightSkill_info ) {
		//	 past_time = Status.NowTime - this.hit_height_start_time
		//	 if (past_time > hitHeightSkill_info.jump_t1 ) {
		//		 this.AddRotateY(hitHeightSkill_info.rotate)
		//		 this.hit_height_rotate = this.hit_height_rotate + hitHeightSkill_info.rotate
		//		 let h = 0
		//		 //上升阶段
		//		 if (past_time < hitHeightSkill_info.jump_t2 ) {
		//			 let p = (past_time - hitHeightSkill_info.jump_t1) / (hitHeightSkill_info.jump_t2 - hitHeightSkill_info.jump_t1)
		//			 h = (1-(1-p)*(1-p)) * hitHeightSkill_info.jump_height
		//			 h = h + (this.add_model_y || 0)
		//		 //最高点停留时间
		//		 } else if (this.buff_manager.hasHitHeightBuff() || this.buff_manager.hasHitHeightAgainBuff() ) {
		//			 h = hitHeightSkill_info.jump_height
		//			 h = h + (this.add_model_y || 0)
		//		 //下落阶段
		//		 }else{
		//			 h = 0
		//			 this.is_hit_heighting = null
		//			 this.hitHeightSkill_info = null
		//			 this.is_need_hit_height = null
		//			 this.AddRotateY(-this.hit_height_rotate)
		//			 this.hit_height_rotate = 0
		//		 }
		//		 this.SetBodyXY(0, h) //注意这里只修改身体model的坐标，和前冲动作是不同的
		//	 }
		// }
	
		if (this.s_hited_info == null && this.hitHeightSkill_info == null ) {
			this.SetLandInfo()
			//因为受击状态会和晕眩、睡眠、恐惧等特殊状态冲突，所以在受击结束后检查这些状态
			if (! this.buff_manager.CheckBuffControl(true) ) {
				this.DoStand()
			}
		}
	
	}
	
