	public Update(now_time?, elapse_time?){ 
		
		if (this.show_attack_color_end_time && now_time >= this.show_attack_color_end_time ) {
			this.SetColorFlag(Character.ColorFlag.Attack,false)
			this.show_attack_color_end_time = null
		}
	
		if (this.show_hit_color_end_time && now_time >= this.show_hit_color_end_time ) {
			this.SetColorFlag(Character.ColorFlag.Hited,false)
			this.show_hit_color_end_time = null
		}
		
		super.Update(now_time, elapse_time)
		this.buff_manager.Update(now_time, elapse_time)
		this.ignore_update_index = 1
	}
	
