	public LoadHorseRes(not_cross?){ 
		if (this.HasBlockSetting("horse") || this.IsSwimState() || this.scene_mgr.HideOnlyRoleScene() || this.IsMoveBrickState() ) {
			return
		}
		if (this.GetHorseId() && this.GetHorseId() > 0 && this.gameObject && ! this.horse_res_loaded_and_show && this.scene_mgr.showHorseScene() ) {
			this.last_horse_id = this.GetHorseId()
			let local_horse_abName = GameResPath.GetModelClotheRes(SceneBaseType.Horse, this.last_horse_id)
			this.horse_abName = local_horse_abName
			let load_call_back =(obj, is_gameObject = true)=> {
				if (! obj  ) {
					console.warn("cannot find horse res = " + this.GetHorseId())
					return
				}
				if (this.use_delete_method || this.is_in_cache_pool || ! local_horse_abName || ! this.horse_abName ) {
					if (is_gameObject ) { 
						obj.destroy() 
					}
					return
				}
				if (! this.GetHorseId() || this.GetHorseId() == 0 ) {
					if (is_gameObject ) { 
						obj.destroy() 
					}
					return
				}
				let new_go:Laya.Sprite3D = obj
				if (this.horse_gameObject ) {
					let tem_ignore_pool = this.ignore_pool
					if (local_horse_abName == this.horse_abName ) { //最后加载的模型是最新的
						this.ignore_pool = true
						this.RemoveHorse()
						this.ignore_pool = tem_ignore_pool
					}else{
						obj.destroy()  //最后加载的模型不是最新的 就删掉该模型
						return
					}
				}
	
				this.horse_gameObject = new_go
				this.horse_transform = this.horse_gameObject.transform
				this.horse_animator = new_go.getComponent(Laya.Animator)
	
				let horse_skin_mesh_renderer:Laya.SkinnedMeshSprite3D = new_go.getChildAt(0) as Laya.SkinnedMeshSprite3D
				if (horse_skin_mesh_renderer) {
					this.horse_skin_mesh_renderer = horse_skin_mesh_renderer
				}
				this.horse_res_loaded_and_show = true
				this.modelObj_transform.owner.addChild(new_go)


				this.horse_transform.localPosition = new Laya.Vector3(0, 0, 0)
				this.horse_transform.localRotationEuler = new Laya.Vector3(0, 0, 0)
				this.horse_transform.localScale = new Laya.Vector3(1, 1, 1)
	
				// 移动特效列表
				// let effect_list = Config.PRELOAD_CLIENT_CONFIG.ConfigOtherFightInfo.horse_run_effect[this.last_horse_id]
				// if (effect_list && this.horse_transform ) {
				//	 let effect = null
				//	 for (let i = 0; i < effect_list.length; i++) {
				//		 let v = effect_list[i]
				//		 effect = this.horse_transform.Find(v)
				//		 if (effect ) {
				//			 table.insert(this.horse_run_effect_list,effect.gameObject)
				//		 }
				//	 }
				// }
	
				if (this.horse_skin_mesh_renderer ) {
					let horse_size = Config.PRELOAD_CLIENT_CONFIG.ConfigOtherFightInfo.horse_res_bound&&Config.PRELOAD_CLIENT_CONFIG.ConfigOtherFightInfo.horse_res_bound[this.last_horse_id]
					if (horse_size ) {
						this.horse_res_size.x = horse_size.x * SceneModelScale
						this.horse_res_size.y = horse_size.y * SceneModelScale
						this.horse_res_size.z = horse_size.fly_height || 100
					}else{
						this.horse_res_size.x = 200 * SceneModelScale
						this.horse_res_size.y = 200 * SceneModelScale
						this.horse_res_size.z = 100 
					}
					this.ori_horse_shader = null
				}
	
				//下马可能之前存在标志，导致模型透明
				if (this.alpha_flag_value_list ) {//上坐骑的过程中
					this.alpha_flag_value_list[Character.AlphaFlag.HorseUp] = null
					this.alpha_flag_value_list[Character.AlphaFlag.HorseDown] = null
				}

				// not_cross 是否不需要渐变过程，切换场景时不需要
				this.UpHorseCross(not_cross)

				this.ResetResSize()
	
				if (this.ReceiveShadow() ) {
					this.SetShadowVisible(false)
				}else{
					this.SetShadowVisible(true)
				}
				this.LoadHorseResComplete()	//加载坐骑资源完成 回调
			}
			if (this.horse_abName ) {
				let full_url = GameResPath.GetTypePath(SceneBaseType.Horse, this.horse_abName)
				// let entity = await window["EngineFactory"].createPrefab(full_url)
				// load_call_back(entity)
				let load_level = LOAD_QUEUE.LOW
				if (this._type == SceneBaseType.MainRole ) {
					load_level = LOAD_QUEUE.HIGHT
				}
				ResManager.GetInstance().CreatePrefab(this.hashCode, full_url, load_call_back, load_level)
				// lua_resM.LoadPrefab(this, this.horse_abName, this.horse_resName, load_call_back, this.ignore_pool)
			}
		}
	}
	
	public ResetResSize(){ 
		
		if (this.horse_res_loaded_and_show ) {
			this.res_size.x = Math.max(this.horse_res_size.x, this.model_res_size.x)
			this.res_size.y = Math.max(this.horse_res_size.y, this.model_res_size.y) * Math.cos(SceneObj.StartRotate.x / 180 * Math.PI)
		}else{
			this.res_size.x = this.model_res_size.x
			this.res_size.y = this.model_res_size.y * Math.cos(SceneObj.StartRotate.x / 180 * Math.PI)
		}
	
		this.SetScale(this.scale)
	}
	
