	public GetBaseSkill(){ 
		
		if (this.skill_list == null ) {
			 return
		}
	
		if (this.GetType() == SceneBaseType.Monster ) {
			 return (this.vo.attack_mode == 0) && 900101 || 900102
	
		}else{
			 if (this.base_skill_index == null ) {
				 this.base_skill_index = 1
			 }
			 if (this.skill_backswing == null || Status.NowTime - this.skill_backswing >= 0.3 ) {
				 this.base_skill_index = 1
			 }
	
			 let id = SkillManager.Instance.getBaseSkill(this.vo.career, this.base_skill_index,true)
			 return [id, this.skill_list[id]]
		}
	}
	
	public GetCanUseSkill(){ 
		
		if (this.skill_list == null || this.IsInBackswing() ) {
			 return
		}
	
		//找出一个可用的技能
		let now_time = Status.NowTime
		let can_use_list = []
		let main_skill_cd = this.main_skill_cd || 5  //主技能要隔几秒才放一次
	
		if (! this.IsInBackswing() ) {
			 if (now_time - this.main_skill_use_time >= main_skill_cd  ) {  //主要技能每隔几秒才能放一个
				 for (let id in this.skill_list) {
					 let skill_vo = this.skill_list[id]
					 if (skill_vo.last_use_time == null || (now_time - skill_vo.last_use_time > (skill_vo.getCd() / 1000)) ) {
						can_use_list.push(id)
					 }
				 }
			 }
		}
	
		if (can_use_list.length > 0 ) {
			 let i = Util.RandomRange(1, can_use_list.length)
			 let id = can_use_list[i]
			 return [id, this.skill_list[id]]
		}
	
		let id, skill_vo = this.GetBaseSkill()
		return [id, skill_vo]
	}
	
	public IsInBackswing(){ 
		
		return (this.skill_backswing && Status.NowTime <= this.skill_backswing)
	}
	
	public RecordSkillUseTime(skill_id?){ 
		
		if (this.skill_list == null ) {
			return
		}
	
		//记下施法后援的到期时间
		let cfg = SkillManager.Instance.GetFightSkillMovie(skill_id)
		if (cfg ) {
			if (cfg.back_swing ) {
				this.skill_backswing = Status.NowTime + cfg.back_swing
			}
		}else{
			this.skill_backswing = Status.NowTime + 0.5
		}
	
		//记录技能的使用时间以便计算cd
		if (SkillManager.Instance.IsThreeAttackSkill(skill_id) ) {
			this.base_skill_index = this.base_skill_index + 1
			if (this.base_skill_index > SkillManager.ThreeAttackSkillInfo[skill_id] ) {
				this.base_skill_index = 1
			}
		}else{
			//使用了其他技能时要把三连击复位
			//因为副技能不在技能表里，所以可以这样排除一下
			if (this.skill_list[skill_id] != null ) {
				this.base_skill_index = 1
				this.main_skill_use_time = Status.NowTime
			}
	
			let skill_vo = this.skill_list[skill_id]
			if (skill_vo ) {
				skill_vo.last_use_time = Status.NowTime
			}
		}
	}
	
