	//角色对话内容<br>ROLE=1
	ROLE=1,						// 角色对话内容
	//确定<br>YES=2
	YES=2,						// 确定
	//取消<br>NO=3
	NO=3,						// 取消
	//发生战斗<br>FIGHT=4
	FIGHT=4,					// 发生战斗
	//触发任务，附加参数，ARRAY(任务ID)<br>TRIGGER=5
	TRIGGER=5,					// 触发任务，附加参数，ARRAY(任务ID)
	//完成任务，附加参数，ARRAY(任务ID)<br>FINISH=6
	FINISH=6,					// 完成任务，附加参数，ARRAY(任务ID)
	//触发并完成任务<br>TRIGGER_AND_FINISH=7
	TRIGGER_AND_FINISH=7,		// 触发并完成任务
