export class DialogueModel extends EventDispatcher {
	isAuto
	dialogue_is_open
	ignore_double_exp_alert
	copyTimesVoList
	hide_view
	view_visible


	/*/**
	 * 飞行副本ID
	 */
	public static FLY_COPY_ID = 224
	public static TASK_TEXT = "task_text"
	public static INTO_TIMES = "INTO_TIMES"

	public static SELECT_TASK = "SELECT_TASK"
	public static CLICK_ANSWER = "CLICK_ANSWER"
	public static FLASH_INTO_TIMES = "FLASH_INTO_TIMES" // 请求刷新进入副本次数
	public static REQUEST_CCMD_EVENT = "DialogueModel.REQUEST_CCMD_EVENT" //请求协议

	// 没有对话时容错使用
	public static DEFAULT_TALK = { "id": 1, "total_content": 1, "content": [{ "total_list": 1, "id": 10002, "list": [{ "type": 0, "text": ["听说这里而有好多好多的神话", "other"] }] }] }
	static Instance: any

	GetDialogueId
	setIntoCopyTimes
	getIntoCopyTimes
	FilterTheTaskBtn
	GetNpcCfg
	GetTalkCfg
	public constructor() {
		super()
		if (DialogueModel.Instance) {
			return
		}
		DialogueModel.Instance = this
		this.copyTimesVoList = []
		this.view_visible = []
		this.hide_view = 0 //大于0就隐藏对话框
		this.dialogue_is_open = false   	//对话框界面是否显示
		this.ignore_double_exp_alert = false  //是否不判断双倍经验领取
		this.isAuto = false


		this.GetDialogueId = (npc_id?)=> {
			let npc_config = Config.GetConfigVo("config_npc", npc_id, false)
			let dialogueId = null
			if (npc_config) {
				dialogueId = Number(npc_config.talk)    //npc默认对话
			}
			return dialogueId
		}

		this.GetNpcCfg = (npc_id)=>{
			return Config.GetConfigVo("config_npc", npc_id, false)
		}
		
		this.GetTalkCfg = (talk_id)=>{
			return Config.GetConfigVo("config_talk", talk_id, false)
		}
	
		//CopyTimesVo的指点
		this.setIntoCopyTimes = (copyTimesVo?)=> {
			this.copyTimesVoList[copyTimesVo.copyId] = copyTimesVo;
			this.Fire(DialogueModel.INTO_TIMES, copyTimesVo)
		}
	
		//返回CopyTimesVo
		this.getIntoCopyTimes = (copyId?)=> {
			return this.copyTimesVoList[copyId]
		}
	
		//npc配置action中的任务type去过滤显示
		this.FilterTheTaskBtn = (task_type?)=> {
			let show = false
			// let _type = task_type.type
	
			// if (_type == 1 || _type == 2 || _type == 3 ) { 			//工会护送	是否有足够公会职位显示这些任务，1接护送，2提升品质，3开车
			// 	show = ConvoyModel.GetInstance().HavUnionAuthority(task_type)
			// }else{
			// 	show = true
			// }
	
			return show
		}

	}
	

	public static GetInstance() {
		if (DialogueModel.Instance == null) {
			new DialogueModel()
		}
		return DialogueModel.Instance
	}
}
	

window["DialogueModel"] = DialogueModel