import { BaseItem1 } from "../common/BaseItem1"
import { RoleManager } from "../role/RoleManager"
import { BaseDungeonModel } from "../commonModel/BaseDungeonModel"
import { DUN_TYPE } from "../commonModel/BaseDungeonModel"
import { ResManager } from "../common/ResManager"
import { table } from "../common/table"
import { CommonManager } from "../common/CommonManager"
import { DungeonMaterialEnterItem } from "./DungeonMaterialEnterItem"

export class DungeonMaterialEnterView extends BaseItem1 {
	_Scroller1: Laya.Panel
	Content: Laya.VBox
	InitEvent
	LoadSuccess
	UpdateView
	_gp_content
	createChildren
	item_list_


	public constructor(parent?) {
		super(parent)

		let role_mgr = RoleManager.GetInstance()
		let dungeon_model = BaseDungeonModel.GetInstance()
		let local_DUN_TYPE = DUN_TYPE
		this.item_list_ = []
		let group_type_ = 1
		let material_type_dic_ = null
		this.base_file = "dungeonMaterial"
		this.layout_file = "DungeonMaterialEnterView"
		this.preload_server_config = {
			"config_dungeon_ui_tab": false,
			"config_num_by_vip": false,
			"config_num_by_vip_info": false
		}
		this.load_callback = () => {
			this._Scroller1.vScrollBar.visible = false
			this.LoadSuccess()
			this.InitEvent()
		}

		// this.createChildren = () => {
		// 	super.createChildren()
		// }

		this.LoadSuccess = () => {
			if (!material_type_dic_) {
				material_type_dic_ = []
			}
			let cfg = ResManager.GetInstance().GetGameConfigFromCache(this, "config_dungeon_ui_tab", false)
			for (let key in cfg) {

				// [ts2lua]cfg下标访问可能不正确
				let v = cfg[key]
				if (v.group == group_type_) {
					// [ts2lua]material_type_dic_下标访问可能不正确
					material_type_dic_[v.dun_type] = v.index
				}
			}
			this.UpdateView()
			//this.RegisterMask(this._gp_content)
		}

		this.UpdateView = () => {
			let list = []
			if (material_type_dic_) {
				let role_lv = role_mgr.GetMainRoleVo() && role_mgr.GetMainRoleVo().level
				for (let dun_type in material_type_dic_) {

					let data = dungeon_model.GetDungeonInfo(dun_type)
					let class_name = null
					if (String(local_DUN_TYPE.Material_Mount) == dun_type) {
						class_name = "MountDungeon"
					} else if (String(local_DUN_TYPE.Material_Partner) == dun_type) {
						class_name = "PartnerDungeon"
					} else if (String(local_DUN_TYPE.Material_WING) == dun_type) {
						class_name = "WingDungeon"
					}
					let bool = true
					if (class_name) {
						bool = CommonManager.GetInstance().CheckFuncOpenState(class_name, true)
					}
					if (((bool && data) && data[0]) && Number(data[0].level) <= role_lv) {
						// [ts2lua]material_type_dic_下标访问可能不正确
						table.insert(list, { dun_type: dun_type, index: material_type_dic_[dun_type] })
					}
				}
			}
			table.sort(list, (a?, b?) => {
				return a.index < b.index
			}
			)
			if (list.length > 0) {
				// let count = 0
				// let call_func = () => {
				// 	count=count+1
				// 	if (count == list.length ) {
				// 		let i = 0
				// 		do {
				// 			this._gp_content.swapChildrenAt(i, this.item_list_.length - i - 1)
				// 			i=i+1
				// 		} while ((i < this.item_list_.length / 2))
				// 		if (this.task_model.MainTaskIsCopperDungeonTaskType() ) {
				// 			this._gp_content.scrollV = 200
				// 		}
				// 	}
				// }

				for (let key in list) {

					// [ts2lua]list下标访问可能不正确
					let vo = list[key]
					// [ts2lua]this.item_list_下标访问可能不正确
					let item = this.item_list_[key]
					if (!item) {
						item = new DungeonMaterialEnterItem(this.Content)
						// [ts2lua]this.item_list_下标访问可能不正确
						this.item_list_[key] = item
						item.SetData(vo.dun_type)
						item.Load()
						item.x = 10
						item.y = 292 * Number(key)
						// item.ExcuteCallback(call_func)
					} else {
						item.SetData(vo.dun_type)
					}
				}
			}
		}

		this.InitEvent = () => {
			this.BindEvent(dungeon_model, BaseDungeonModel.UPDATE_DUNGEON_TYPE_VIEW, (dun_type?) => {
				// [ts2lua]material_type_dic_下标访问可能不正确
				if (material_type_dic_ && material_type_dic_[dun_type]) {
					this.UpdateView()
				}
			}
			)
		}
	}

	public DeleteMe() {

		for (let _tmpi in this.item_list_) {
			var v = this.item_list_[_tmpi]
			v.DeleteMe()
		}
		this.item_list_ = []
	}


	public GetComponents() {
		[
			this._Scroller1,
			this.Content,
		]
			= this.GetChildrenByNames([

				"_Scroller1",
				"Content",
			])
	}
}
window["DungeonMaterialEnterView"] = DungeonMaterialEnterView
