import { MainUIModel } from "../commonModel/MainUIModel"
import { Runner } from "../util/Runner"
import { SetLocalPositionY, SetLocalPositionX, Util } from "../util/Util"
import { BaseClass } from "./BaseClass"
import { table } from "./table"
import { Mathf } from "../util/Mathf"
import { EventDispatcher } from "../util/EventDispatcher"
import { LayerManager } from "./LayerManager"
import { TimeUtil } from "../util/TimeUtil"
export class MainUIManager extends EventDispatcher {

	public static UPDATE_MOVE_STATE = "MainUIManager.UPDATE_MOVE_STATE"

	public static MOVE_TYPE = {
		Top: 1,
		Buttom: 2,
		Left: 3,
		Right: 4,
		Stay: 5	//原地不动
	}
	move_com_dic
	static Instance: any
	main_ui_move_timer: number
	update_timer: boolean
	reset: boolean
	/*
	show_type true/false 主界面同时显示/隐藏主界面时显示
	move_type 移动类型  MainUIManager.MOVE_TYPE
	*/
	public AddMoveComponent(ref?: BaseClass, transform?, show_type?, move_type?) {
		let ScreenWidth = LayerManager.GetInstance().stageWidth
		let ScreenHeight = LayerManager.GetInstance().stageHeight
		if (!ref || ref.use_delete_method || !transform) { return }
		if (this.move_com_dic == null) {
			this.move_com_dic = {}
		}
		if (this.move_com_dic[ref.hashCode] == null) {
			this.move_com_dic[ref.hashCode] = { "ref": ref }
		}
		let end_value
		let start_value
		// let value

		if (move_type == MainUIManager.MOVE_TYPE.Top) {
			start_value = transform.y
			// value = transform.height
			end_value = 0 - transform.height

		} else if (move_type == MainUIManager.MOVE_TYPE.Buttom) {
			start_value = transform.y
			// value = - (ScreenHeight / 2 + Mathf.Floor(transform.y / transform.y))
			end_value = ScreenHeight

		} else if (move_type == MainUIManager.MOVE_TYPE.Left) {
			start_value = transform.x
			// value = - (ScreenWidth / 2 + Mathf.Floor(transform.x / transform.x)) //+ (1 - transform.pivot.x) * transform.rect.width)
			end_value = -transform.width

		} else if (move_type == MainUIManager.MOVE_TYPE.Right) {
			start_value = transform.x
			// value = ScreenWidth / 2 - Mathf.Floor(transform.x / transform.x) //+ transform.x * transform.rect.width
			end_value = transform.width + ScreenWidth
		}

		// let canvas_group = transform.GetComponent("CanvasGroup")
		// if (canvas_group == null) {
		// 	canvas_group = transform.gameObject.AddComponent(typeof (UnityEngine.CanvasGroup))
		// }

		this.move_com_dic[ref.hashCode][transform.hashCode] = {
			transform: transform,
			move_type: move_type,
			show_type: show_type,
			start_value: start_value,
			end_value: end_value,
			// canvas_group : canvas_group
		}

		if (show_type != MainUIModel.GetInstance().activity_icon_in_show) {

			if (move_type == MainUIManager.MOVE_TYPE.Top || move_type == MainUIManager.MOVE_TYPE.Buttom) {
				SetLocalPositionY(transform, end_value)
			} else if (move_type == MainUIManager.MOVE_TYPE.Left || move_type == MainUIManager.MOVE_TYPE.Right) {
				SetLocalPositionX(transform, end_value)
			}
			transform.visible = false
			transform.alpha = 0
		} else {
			if (move_type == MainUIManager.MOVE_TYPE.Top || move_type == MainUIManager.MOVE_TYPE.Buttom) {
				SetLocalPositionY(transform, start_value)
			} else if (move_type == MainUIManager.MOVE_TYPE.Left || move_type == MainUIManager.MOVE_TYPE.Right) {
				SetLocalPositionX(transform, start_value)
			}
			transform.visible = true
			transform.alpha = 1
		}

	}

	public RemoveMoveComponent(ref?: BaseClass) {

		if (this.move_com_dic && this.move_com_dic[ref.hashCode]) {
			delete this.move_com_dic[ref.hashCode]
		}
	}

	public RemoveMoveOneComponent(ref?, transform?) {

		if (transform && this.move_com_dic && this.move_com_dic[ref.hashCode] && this.move_com_dic[ref.hashCode][transform.hashCode]) {
			delete this.move_com_dic[ref.hashCode][transform.hashCode]
		}
	}

	public HasMoveComponent(ref?, transform?) {

		return this.move_com_dic && this.move_com_dic[ref.hashCode] && this.move_com_dic[ref.hashCode][transform.hashCode]
	}

	public Update() {

		let show_type = MainUIModel.GetInstance().activity_icon_in_show

		let ratio = Mathf.Min((Laya.timer.currTimer - this.main_ui_move_timer) / 1000 / MainUIModel.Move_Time_Interval  , 1)
		let delete_com_dic = []
		if (this.move_com_dic) {
			for (let ref_hashcode in this.move_com_dic) {
				var com_list = this.move_com_dic[ref_hashcode]
				if (com_list && com_list.ref) {
					if (com_list.ref.use_delete_method) {
						delete this.move_com_dic[ref_hashcode]
					} else {
						for (let transform_hashcode in com_list) {
							var data = com_list[transform_hashcode]
							if (data && !Util.IsNull(data.transform)) {
								let transform = data.transform
								if (this.reset) {
									let start_value
									if (data.move_type == MainUIManager.MOVE_TYPE.Top || data.move_type == MainUIManager.MOVE_TYPE.Buttom) {
										start_value = transform.y //and transform.y || transform.anchoredPosition.y
									} else if (data.move_type == MainUIManager.MOVE_TYPE.Left || data.move_type == MainUIManager.MOVE_TYPE.Right) {
										start_value = transform.x //and transform.localPosition.x || transform.anchoredPosition.x
									}
									if (show_type == data.show_type) {
										transform.visible = true
										data.move_data = { end_value: data.start_value, start_value: start_value, end_alpha: 1, start_alpha: transform.alpha }
									} else {
										data.move_data = { end_value: data.end_value, start_value: start_value, end_alpha: 0, start_alpha: transform.alpha }
									}
								}

								//没有move_data 说明是 循环过程中添加进来的 添加时已经设置过默认值了 不需要播动画
								if (data.move_data) {
									if (data.move_type == MainUIManager.MOVE_TYPE.Top || data.move_type == MainUIManager.MOVE_TYPE.Buttom) {
										SetLocalPositionY(transform, data.move_data.start_value + ratio * (data.move_data.end_value - data.move_data.start_value))
									} else if (data.move_type == MainUIManager.MOVE_TYPE.Left || data.move_type == MainUIManager.MOVE_TYPE.Right) {
										SetLocalPositionX(transform, data.move_data.start_value + ratio * (data.move_data.end_value - data.move_data.start_value))
									}

									transform.alpha = Mathf.Floor((data.move_data.start_alpha + ratio * (data.move_data.end_alpha - data.move_data.start_alpha)) * 10) / 10

									if (ratio == 1 && show_type != data.show_type) {
										transform.visible = false
									}
								}
							}
						}
					}
				}
			}
		}

		// for (let _ in delete_com_dic) {
		// 	var ref = delete_com_dic[_]
		// 	this.move_com_dic[ref] = null
		// }
		this.reset = false
		if (ratio == 1) {
			// Runner.GetInstance().RemoveRunObj(this.hashCode)
			if (this.update_timer) {
				Laya.timer.clear(this, this.Update)
				this.update_timer = false
			}
		}
	}


	public constructor() {
		super()
		if (MainUIManager.Instance) {
			return
		}
		// MainUIManager.Instance = this
		this.InitEvent()
	}


	public InitEvent() {
		this.Bind(MainUIManager.UPDATE_MOVE_STATE, () => {
			Laya.timer.frameLoop(2, this, this.Update)
			this.main_ui_move_timer = Laya.timer.currTimer
			this.update_timer = true
			this.reset = true
		})
	}

	public static GetInstance() {
		if (MainUIManager.Instance == null) {
			MainUIManager.Instance = new MainUIManager()
		}
		return MainUIManager.Instance
	}
}




window["MainUIManager"] = MainUIManager