import { BaseItem1 } from "../common/BaseItem1"
import { ResManager } from "../common/ResManager"
import { BaseDungeonModel } from "../commonModel/BaseDungeonModel"
import { PlatformManager } from "../PlatformManager"
import { GameResPath } from "../util/GameResPath"
import { Util } from "../util/Util"

export class DungeonFailureStrengItem extends BaseItem1 {
	InitEvent
	LoadSuccess
	SetData
	UpdateView

	public constructor(parent?) {
		super(parent)

		let dungeon_model = BaseDungeonModel.GetInstance()
		let vo_ = null
		let call_back_ = null
		let need_refresh_data_ = null
		this.base_file = "dungeonCommon"
		this.layout_file = "DungeonFailureStrengItem"
		this.load_callback = () => {
			this.LoadSuccess()
		}

		this.InitEvent = () => {

			this._lb_jump.text = "前往"

			//AddUnderLineAndClick(this,this._lb_jump)

			Util.AddClickEvent(this._lb_jump, () => {
				if (vo_) {
					dungeon_model.SetDunFailureJumpData(vo_.jump_id)
					dungeon_model.streng_item_click = true
				}
				if (call_back_) {
					call_back_()
				}
			}, this, true)
		}

		this.LoadSuccess = () => {

			this.InitEvent()

			if (need_refresh_data_) {
				this.UpdateView()
				need_refresh_data_ = false
			}

			if (PlatformManager.IsEyouEnPlatform()) {
				// this._lb_desc.size  = 20
				// this._lb_desc.verticalAlign = "middle"
				// this._lb_desc.textAlign = "left"
				// let csf = this._lb_desc.GetComponent("ContentSizeFitter")
				// // csf.horizontalFit = UnityEngine.UI.ContentSizeFitter.FitMode.Unconstrained
				// // csf.verticalFit = UnityEngine.UI.ContentSizeFitter.FitMode.Unconstrained
				// // SetSizeDelta(this._lb_desc,250,65)
				// // SetAnchoredPosition(this._lb_desc,94,-5)

				// this._lb_desc.width = 250
				// this._lb_desc.height = 65
				// this._lb_desc.x = 94
				// this._lb_desc.y = -5

			}
			if (PlatformManager.IsEyouIdnPlatform()) {
				// this._lb_desc.size  = 20
				// this._lb_desc.verticalAlign = "middle"
				// this._lb_desc.textAlign = "left"
				// let csf = this._lb_desc.GetComponent("ContentSizeFitter")
				// csf.horizontalFit = UnityEngine.UI.ContentSizeFitter.FitMode.Unconstrained
				// csf.verticalFit = UnityEngine.UI.ContentSizeFitter.FitMode.Unconstrained
				// SetSizeDelta(this._lb_desc,250,65)
				// SetAnchoredPosition(this._lb_desc,94,-5)
				this._lb_desc.width = 250
				this._lb_desc.height = 65
				this._lb_desc.x = 94
				this._lb_desc.y = -5
			}
		}

		this.SetData = (vo?, call_back?) => {
			vo_ = vo
			call_back_ = call_back
			if (this.is_loaded) {
				this.UpdateView()
			} else {
				need_refresh_data_ = true
			}
		}

		this.UpdateView = () => {
			if (vo_) {
				this._lb_desc.text = vo_.desc
				ResManager.GetInstance().SetOutsideImageSprite(this, this._img_icon, GameResPath.GetIcon("dailyIcon", vo_.icon_id))
			}
		}
	}
	_img_bg: Laya.Image
	_img_icon: Laya.Image
	_lb_desc: Laya.Label
	_lb_jump: Laya.Label
	public GetComponents() {
		[
			this._img_bg,
			this._img_icon,
			this._lb_desc,
			this._lb_jump,
		]
			= this.GetChildrenByNames([

				"_img_bg",
				"_img_icon",
				"_lb_desc",
				"_lb_jump",
			])
	}
}

window["DungeonFailureStrengItem"] = DungeonFailureStrengItem