import { BaseView1 } from "../common/BaseView1"
import { EventName } from "../common/EventName";
import { Enum_UILayer } from "../common/LayerManager"
import { LoopScrowViewMgr } from "../common/LoopScrowViewMgr";
import { ResManager } from "../common/ResManager"
import { MainFunc } from "../commonModel/MainUIModel";
import { MonBookModel } from "../commonModel/MonBookModel"
import { GlobalEventSystem } from "../util/DeclareGlobalVar";
import { GameResPath } from "../util/GameResPath";
import { Util } from "../util/Util";
import { MonBookGroupItem } from "./MonBookGroupItem";
import { MonBookTabItem } from "./MonBookTabItem";

export class MonBookGroupView extends BaseView1 {
	LoadSuccess
	InitEvent
	SwitchFunc
	UpdateView
	Remove
	RefreshTabRed
	SetDefaultIndex
	tab_loop_mgr:LoopScrowViewMgr
	set_time_out_id
	delay_id
	public constructor() {
		super()
		this.base_file = "monBook"
		this.layout_file = "MonBookGroupView"
		this.layer_value = Enum_UILayer.Activity
		this.change_scene_close = true
		this.destroy_imm = true
		this.is_center = true
		this.use_background = true
		this.click_bg_toClose = true
		this.show_open_movie = true
		let model = MonBookModel.GetInstance(),
			local_MonBookModel = MonBookModel,
			radio_btn_list_,
			group_item_list_,
			now_index_,
			default_index_ = 0
		this.load_callback = function () {
			this.LoadSuccess()
			this.InitEvent()
		}
		this.destroy_callback = function () {
			this.Remove()
		}

		this.LoadSuccess = () => {
			this._gp_tab_con.scrollBar.visible = false
			this.scroller.vScrollBar.visible = false
			let name_list = Util.DeepCopy(model.GetTabNameList())
			for (let k in name_list) {
				var v = name_list[k]
				v.is_group = true
			}
			// ResManager.GetInstance().SetOutsideImageSprite(this, this.bg_img, GameResPath.GetIcon("common2","uitc_001"))
			let red_index = this.RefreshTabRed()	//打点红点index
			if (red_index != undefined){
				default_index_ = red_index
			}

			if (! this.tab_loop_mgr ) {
				this.tab_loop_mgr =  new LoopScrowViewMgr()
				this.tab_loop_mgr.SetData(this._gp_tab_con, MonBookTabItem,name_list,this.ScrollView,1,(item?) => {
						let index = this._gp_tab_con.selectedIndex
						if (index == now_index_ ) {
							return
						}
						now_index_ = index
						model.now_select_group_type = now_index_ + 1
						this.UpdateView()
					}, default_index_)
			}else{
				this.tab_loop_mgr.replaceAll(name_list)
			}
			
			// this.tab_loop_mgr.SetSelectIndex(default_index_)

			// this.set_time_out_id = setTimeout(() => {
					
			// 	},1000)

			
			// let name_list = model.GetTabNameList()
			// ResManager.GetInstance().SetTexture(this, this.bg_img, "resource/game/common2/texture/uitc_001.png")
			// if (!radio_btn_list_)
			// 	radio_btn_list_ = []
			// for (let key in name_list) {
			// 	let radio_btn: Laya.RadioButton = new Laya.RadioButton()
			// 	radio_btn.skinName = `resource/game/monBook/exml/MonBookRadioBtnExml.exml`
			// 	radio_btn.value = Number(key) + 1
			// 	radio_btn.label = name_list[key]
			// 	radio_btn.groupName = this["constructor"].name
			// 	this._gp_tab_con.addChild(radio_btn)
			// 	radio_btn_list_[key] = radio_btn
			// }
			// let first_dot_index = this.RefreshTabRed()
			// default_index_ = first_dot_index ? first_dot_index : 1
			// radio_btn_list_[0].group.selectedValue = String(default_index_)
			// now_index_ = default_index_
			// this.UpdateView()

		}

		this.InitEvent = () => {
			Util.AddClickEvent(this._img_close, () => {
				this.Close()
			}, this, true)

			// if (radio_btn_list_[0]) {
			// 	radio_btn_list_[0].group.addEventListener(Laya.UIEvent.CHANGE, this.SwitchFunc, this)
			// }

			let RefreshBookInfo = (type) => {
				let current_index = now_index_ + 1
				if (current_index == type)
					this.UpdateView()
			}
			this.BindEvent(model, local_MonBookModel.REFRESH_BOOK_INFO, RefreshBookInfo)

			this.BindEvent(model, local_MonBookModel.REFRESH_TAB_DOT, (index, type) => {
				let is_show = null
				if (index && index != 0 ) {
					is_show = model.IsShowMonGroupRedDot()
					let red = model.IsShowGroupDot(type)
					model.Fire(local_MonBookModel.REFUSE_TAB_RED, type,red,true)
				}
				// let is_show
				// if (index) {
				// 	is_show = model.IsShowMonGroupRedDot()
				// 	// GlobalEventSystem.Fire(EventName.UPDATE_BASE_WINDOWS_COMPONENT_RED_STATE, "SecretTreasureMainView", 1, is_show)
				// 	let bit = model.monGroupRedDotBit
				// 	radio_btn_list_[type - 1]._img_red.visible = bit & 1 << type
				// }
			})
			let show_effect = (index) => {
				switch (index) {
					case 0:
						this.AddUIEffect("ui_jihuochenggong_glow", this._gp_effect, { x: 0, y: 0 }, null, false)
						break
					case 1:
						this.AddUIEffect("ui_shengjichenggong_glow", this._gp_effect, { x: 0, y: 0 }, null, false)
						break
				}
			}
			this.BindEvent(model, local_MonBookModel.PLAY_EFFECT, show_effect)


			let LevelSuccess = (type) => {
				let current_index = now_index_ + 1
				if (current_index == type)
					this.UpdateView()
			}
			this.BindEvent(model, local_MonBookModel.LEVEL_SUCCESS, LevelSuccess)

			let goods_change_fun = (_type)=>{
				if (_type && _type == MainFunc.Treasure){
					this.RefreshTabRed()
				}
			}
			this.BindEvent(GlobalEventSystem, EventName.REFRESH_FUNCTION_ICON_RED_DOT, goods_change_fun)
		}

		// this.SwitchFunc = (evt: Laya.UIEvent) => {
		// 	let index = Number(evt.target.selectedValue)
		// 	if (index == now_index_) return
		// 	now_index_ = index
		// 	this.UpdateView()
		// }

		this.UpdateView = () => {
			let book_list = model.GetBookComposeList(now_index_ + 1)
			if (!book_list)
				return
			let len = book_list.length
			if (!group_item_list_)
				group_item_list_ = []

			if (group_item_list_.length > len) {
				for (let i = len; i < group_item_list_.length; i++) {
					if (group_item_list_[i]) {
						group_item_list_[i].DeleteMe()
						group_item_list_[i] = null
					}
				}
			}

			if (len > 0) {
				let red_index
				let i = 1
				let show_red_dot = false
				for (let key in book_list) {
					let data = book_list[key]
					if (data) {
						let item = group_item_list_[key]
						if (!item) {
							item = new MonBookGroupItem(this._gp_item_con)
							group_item_list_[key] = item
							item.Load()
						}
						item.SetDate(data)
						item.visible = true
						show_red_dot = model.IsShowSingleGroupDot(data.type, data.id)
						if (show_red_dot && red_index == undefined) {
							red_index = i
						}
						i++
					}
				}
				if (!red_index) {
					red_index = 1
				}
				let pos_y = (red_index + 1) * MonBookGroupItem.Height + (red_index - 1) * 5
				let need_to = 0
				if (pos_y > this.scroller.height) {
					need_to = pos_y - this.scroller.height
				}
				if (this.delay_id){
					clearTimeout(this.delay_id)
					this.delay_id = null
				}
				this.delay_id = setTimeout(() => {
					this.scroller.scrollTo(0, need_to)
					this.scroller.refresh()
				}, 500);
			}

		}

		this.Remove = () => {
			// if (radio_btn_list_[0] && radio_btn_list_[0].group)
			// 	radio_btn_list_[0].group.removeEventListener(Laya.UIEvent.CHANGE, this.SwitchFunc, this)
			if (group_item_list_) {
				for (let obj of group_item_list_) {
					if (obj) {
						obj.DeleteMe()
					}
				}
				group_item_list_ = undefined
			}
			if (this.tab_loop_mgr){
				this.tab_loop_mgr.DeleteMe()
				this.tab_loop_mgr = null
			}
			if (this.set_time_out_id){
				clearTimeout(this.set_time_out_id)
				this.set_time_out_id = null
			}
			if (this.delay_id){
				clearTimeout(this.delay_id)
				this.delay_id = null
			}
		}

		this.RefreshTabRed = () => {
			// let bit = model.monGroupRedDotBit
			let cfg = model.GetMonPicTypeCfg()
			let first_dot_index
			for (let key in cfg) {
				let data = cfg[key]
				let type = data.type
				if (type ) {
					let red = model.IsShowGroupDot(type)
					model.Fire(local_MonBookModel.REFUSE_TAB_RED, type,red,true)
					if (red && first_dot_index == undefined) {
						first_dot_index = type - 1
					}
				}
			}
			return first_dot_index
			// let bit = model.monGroupRedDotBit
			// let cfg = model.GetMonPicTypeCfg()
			// let first_dot_index
			// let show
			// for (let key in cfg) {
			// 	let data = cfg[key]
			// 	let type = data.type
			// 	if (type) {
			// 		show = bit & 1 << type
			// 		radio_btn_list_[type - 1]._img_red.visible = show
			// 		if (show && !first_dot_index) {
			// 			first_dot_index = type
			// 		}

			// 	}
			// }
			// return first_dot_index
		}



		this.SetDefaultIndex = (index) => {
			default_index_ = index || default_index_
		}
	}

	public Open(...parms) {
		if (parms) {
			this.SetDefaultIndex(parms[0])
		}
		super.Open()
	}
	

	bg_img: Laya.Image
	_Image1: Laya.Image
	_Group1: Laya.Box
	_Image2: Laya.Image
	_img_title: Laya.Label
	_img_close: Laya.Image
	scroller: Laya.Panel
	_gp_item_con: Laya.VBox
	_img_arrow: Laya.Image
	_gp_effect: Laya.Box
	ScrollView: Laya.Panel
	_gp_tab_con: Laya.List
	none_gp: Laya.Box
	Image: Laya.Image
	Text: Laya.Label
	public GetComponents() {
		[
			this.bg_img,
			this._Image1,
			this._Group1,
			this._Image2,
			this._img_title,
			this._img_close,
			this.scroller,
			this._gp_item_con,
			this._img_arrow,
			this._gp_effect,
			this.ScrollView,
			this._gp_tab_con,
			this.none_gp,
			this.Image,
			this.Text,
		]
			= this.GetChildrenByNames([

				"bg_img",
				"_Image1",
				"_Group1",
				"_Image2",
				"_img_title",
				"_img_close",
				"scroller",
				"_gp_item_con",
				"_img_arrow",
				"_gp_effect",
				"ScrollView",
				"_gp_tab_con",
				"none_gp",
				"Image",
				"Text",
			])
	}
}

window["MonBookGroupView"] = MonBookGroupView