import { GoodsModel } from "../commonModel/GoodsModel"
import { Util, SetAnchoredPositionY } from "../util/Util"
import { BaseView1 } from "./BaseView1"
import { CongratulationObtainItem } from "./CongratulationObtainItem"
import { CongratulationRareView } from "./CongratulationRareView"
import { Enum_UILayer } from "./LayerManager"
import { ResManager } from "./ResManager"

export class CongratulationObtainAutoView extends BaseView1 {
	public _gp_view: Laya.Box;
	public _gp_borderglow_effect: Laya.Box;
	public click_bg: Laya.Box;
	public mainGp: Laya.Box;
	public _gp_blackline_effect: Laya.Box;
	public _gp_got_img: Laya.Box;
	public light: Laya.Image;
	public _img_item_bg_left: Laya.Image;
	public _img_item_bg_right: Laya.Image;
	public effect_group: Laya.Box;
	public right_bg: Laya.Image;
	public left_bg: Laya.Image;
	public _Image11: Laya.Image;
	public goods_scroller: Laya.Panel;
	public Content: Laya.Box;
	public _gp_effect: Laya.Box;
	public _img_point: Laya.Image;
	public _gp_hit: Laya.Box;
	public btn: Laya.Box;
	public _Image1: Laya.Image;
	public labelDisplay: Laya.Label;
	public _Group1: Laya.Box;
	public bottom_label: Laya.Label;



	private cache_data

	SetBtnData
	SetGoodsData
	SetItemData
	CreateOneItem
	SetBtn
	Init
	Open_Callback
	percentWidth
	percentHeight
	public constructor(base_type, sub_type) {
		super()

		this.base_file = "common"
		this.layout_file = "CongratulationObtainAutoView"
		this.layer_value = Enum_UILayer.Activity
		this.background_alpha = 0.7
		this.is_center = true
		this.use_background = true
		this.destroy_imm = true
		this.click_bg_toClose = false
		this.percentWidth = 100
		this.percentHeight = 100
		this.not_show_item_use = true
		let goods_model = GoodsModel.GetInstance()
		let _item_list = []
		let count = 0
		let _goods_data = null
		let _btn_data = null
		let _item_data = null
		let item_size = 95
		let anim_index = 0
		let is_anime = true
		let needs_load = false
		let base_type_ = base_type
		let sub_type_ = sub_type
		this.load_callback = () => {
			this.goods_scroller.vScrollBar.visible = false
			if (needs_load && this.cache_data) {
				_goods_data = this.cache_data
				this.SetItemData()
				this.CreateOneItem()
			}
			this.SetBtn()
			this.Init()
			//this:LoadSuccess()
		}

		this.open_callback = () => {
			// this.cache_sort_order = this.AddCurrLayerSortingOrder(this.layer_value)
			this.Open_Callback()
		}

		this.close_callback = () => {
			/*
			CustomActivityModel.GetInstance().Fire(CustomActivityDefine.EVENT.CLEAR_AUTO_VIEW)
			if (_item_list) {
				let i = 0
				if (i < _item_list.length) {
					do {
						let item = _item_list[i]
						if (item) {
							item.DeleteMe()
						}
						i = i + 1
					} while ((i < _item_list.length)
					)
				}

				_item_list = []
			}
			*/
			is_anime = true
			needs_load = false
			this.cache_data = null

		}

		this.Open_Callback = () => {
			// lua_soundM.PlayEffect(this, "double_box", false, LuaSoundManager.SOUND_TYPE.UI, null, null)
			// ResManager.GetInstance().SetUIEffect(this, "UI_1103_gongxihuode", this.layer_value, this.effect_group, null, null, false, { custom_sorting_order = this.cache_sort_order })

			// this.CoverEffect(this.right_bg, "Activity", this.cache_sort_order)
			// this.CoverEffect(this.left_bg, "Activity", this.cache_sort_order)
			// this.CoverEffect(this.goods_scroller, "Activity", this.cache_sort_order)
			// this.CoverEffect(this._img_point_obj.transform, "Activity", this.cache_sort_order)

			// this.RegisterMask(this.goods_group)

			//lua_soundM:PlayEffect(this,"3_huode")
			this.bottom_label.visible = false// this.bottom_label.includeInLayout = false


		}

		this.Init = () => {
			ResManager.GetInstance().SetTexture(this, this.left_bg, "resource/game/common4/texture/uijs_062.png")
			ResManager.GetInstance().SetTexture(this, this.right_bg, "resource/game/common4/texture/uijs_062.png")

			Util.AddClickEvent(this.click_bg, () => {
				// if (is_anime == false) {
					this.Close()
				// }
			}
				, this, false)
			/*
						this.BindEvent(CustomActivityModel.GetInstance(), CustomActivityDefine.EVENT.STOP_AUTO, () => {
							is_anime = false
							this.bottom_label.visible = this.bottom_label.includeInLayout = true
							this.btn.visible = this.btn.includeInLayout = false
						})
						*/

		}

		this.SetBtnData = (btn_data?) => {
			_btn_data = btn_data
		}

		this.SetGoodsData = (data?) => {
			_goods_data = data
			if (this.is_loaded) {
				this.SetItemData()
				this.CreateOneItem()
			} else {
				needs_load = true
				this.cache_data = data
			}
		}

		this.SetItemData = () => {
			let good_item_num = 0
			let data = []
			let i = 0
			if (i < _goods_data.length) {
				do {
					let [type_id, lock] = goods_model.GetMappingTypeId(_goods_data[i][0], _goods_data[i][1])
					let goods_vo = goods_model.GetGoodsBasicByTypeId(type_id)
					let max_overlap = (goods_vo && goods_vo.max_overlap && (goods_vo.max_overlap) || (999))
					let goods_num = (goods_vo && goods_vo.max_overlap == 0 && (1) || (_goods_data[i][2]))
					let create_num = (goods_vo && goods_vo.max_overlap == 0 && (_goods_data[i][2]) || (1))
					create_num = Number(create_num)
					good_item_num = good_item_num + create_num
					let j = 0
					if (j < Number(create_num)) {
						do {
							//如果有[3] 则表示数据中有goods_id 显示背包里对应的装备
							if (_goods_data[i] && _goods_data[i][3]) {
								data.push([type_id, goods_num, lock, _goods_data[i][3]])
							} else {
								data.push([type_id, goods_num, lock])
							}
							j = j + 1
						}
						while ((j < create_num))
					}
					i = i + 1
				}
				while ((i < _goods_data.length))
			}

			_item_data = data
		}

		this.CreateOneItem = () => {
			count = count + 1
			let item = _item_list[count]
			if (!item) {
				item = new CongratulationObtainItem(this.Content)
				// item.SetItemCacheSortOrder(this.cache_sort_order)
				// item.SetItemLayerValue(this.layer_value)
				item.Load()
				_item_list.push(item)
			}

			item.ExcuteCallback(() => {

				item.SetData(_item_data[0][0], _item_data[0][1], _item_data[0][2], null, item_size)

				let goods_base = goods_model.GetGoodsBasicByTypeId(_item_data[0][0])
				if ((goods_base && goods_base.color >= 4) && item.award_item) {
					item.award_item.ExcuteCallback(() => {
						if (item.award_item) {
							item.award_item.SetBoxEffect(goods_base.color)
						}
					}
					)

				}

				// UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(this.content)
				if (count > (10 + 5 * anim_index)) {
					anim_index = anim_index + 1
					let y = this.Content.height - 260
					SetAnchoredPositionY(this.Content, y)
				}
				item.SetAlpha(1)
				item.AddEffect(1)
			}
			)
			/*
			if (base_type_ == 102 && CustomActivityModel.GetInstance().IsRareReward(_goods_data)) {
				let view = new CongratulationRareView()
				view.SetData(_item_data[1], 1)
				view.Open()
			}
			*/
		}

		this.SetBtn = () => {
			if (!_btn_data) { return }
			this.labelDisplay.text = _btn_data.text && _btn_data.text || "停止"
			if (_btn_data.call_back_func) {
				let func = _btn_data.call_back_func
				Util.AddClickEvent(this.btn, func, this, true)

			}
			this.btn.visible = true
		}
	}

	public GetComponents() {
		[
			this._gp_view,
			this._gp_borderglow_effect,
			this.click_bg,
			this.mainGp,
			this._gp_blackline_effect,
			this._gp_got_img,
			this.light,
			this._img_item_bg_left,
			this._img_item_bg_right,
			this.effect_group,
			this.right_bg,
			this.left_bg,
			this._Image11,
			this.goods_scroller,
			this.Content,
			this._gp_effect,
			this._img_point,
			this._gp_hit,
			this.btn,
			this._Image1,
			this.labelDisplay,
			this._Group1,
			this.bottom_label,
		]
			= this.GetChildrenByNames([

				"_gp_view",
				"_gp_borderglow_effect",
				"click_bg",
				"mainGp",
				"_gp_blackline_effect",
				"_gp_got_img",
				"light",
				"_img_item_bg_left",
				"_img_item_bg_right",
				"effect_group",
				"right_bg",
				"left_bg",
				"_Image11",
				"goods_scroller",
				"Content",
				"_gp_effect",
				"_img_point",
				"_gp_hit",
				"btn",
				"_Image1",
				"labelDisplay",
				"_Group1",
				"bottom_label",
			])
	}
}
window["CongratulationObtainAutoView"] = CongratulationObtainAutoView