import { BaseView1 } from "../common/BaseView1"
import { Config } from "../common/Config"
import { Util, Color } from "../util/Util"
import { Message } from "../sysinfo/SysInfoController"
import { Enum_UILayer } from "../common/LayerManager"
import { ResManager } from "../common/ResManager"
import { GameResPath } from "../util/GameResPath"
import { BaseAwardItem } from "../common/BaseAwardItem"
import { GoodsModel } from "../commonModel/GoodsModel"
import { SkillManager } from "../skill/SkillManager"
import { MaterialsTool } from "../common/MaterialsTool"
import { ErlangParser } from "../util/ErlangParser"
import { DragonBallModel } from "../commonModel/DragonBallModel"
import { DragonBallItem } from "./DragonBallItem"

export class DragonBallView extends BaseView1 {
	model
	skill_mgr
	goods_model
	material_tool
	congfig_dragonball = Config.PRELOAD_SERVER_CONFIG.config_dragon_ball
	
	balls_item
	currn_index
	item
	line_btn_update

	public constructor() {
		super()
		this.base_file = "dragonBall"
		this.layout_file = "DragonBallView"
		this.layer_value = Enum_UILayer.Activity
		this.show_open_movie = true
		this.is_center = true
		this.destroy_imm = true
		this.use_background = true
		this.click_bg_toClose = true

		this.model = DragonBallModel.GetInstance()
		this.goods_model = GoodsModel.GetInstance()
		this.skill_mgr = SkillManager.GetInstance()
		this.material_tool = MaterialsTool.GetInstance()

		this.currn_index = 0
		this.item = false
		this.balls_item = []

		this.load_callback = () => {
			this.LoadSucess()
			this.InitEvent()
			/*
			if (PlatformMgr.GetInstance().IsEyouEnPlatform()) {
				SetAnchoredPositionX(this.lb_tips1, 85)
				SetAnchoredPositionX(this.lb_tips2, 438)
				this._lb_currn.size = 18
				this._lb_next.size = 18
			}
			*/
		}

		this.open_callback = () => {
			this.InitView()
		}

		this.destroy_callback = () => {
			this.Remove()
		}
	}

	public LoadSucess() {
		ResManager.GetInstance().SetImageSprite(this, this.img_bg2, "dragonBall", "ui_guard_08")
		this.currn_index = this.model.GetCurrnIndex()
		this.InitHtmlText()
	}
	
	private InitHtmlText() {
		this.lb_currn.width = 215
		this.lb_currn.style.fontSize = 22
		this.lb_currn.style.color = "#4a3a32"
		this.lb_currn.style.leading = 8
		
		this.lb_next.width = 215
		this.lb_next.style.fontSize = 22
		this.lb_next.style.color = "#4a3a32"
		this.lb_next.style.leading = 8
	}

	public InitEvent() {
		Util.AddClickEvent(this.btn_close, () => {
			this.Close()
		}, this, true)

		let update_event = () => {
			// TODO 激活/升级
			// 先判断是否升级到最高
			let ball_vo = this.model.GetVobySet(this.currn_index)
			if (ball_vo.dragon_lv == this.model.max_lv) {
				Message.show("已到最高等级！")
				return
			}

			let [type_id, need_count] = this.model.GetUpdateMsg(this.currn_index)
			let now_count = this.goods_model.GetTypeGoodsNum(type_id)
			if (need_count > now_count) {
				// 道具不足
				this.material_tool.materialsTips(ball_vo.dragon_id)
				return
			} else {
				ball_vo = this.model.GetVobySet(this.currn_index)
				let type_id = this.model.GetUpdateMsg(this.currn_index)
				this.model.Fire(DragonBallModel.ACTIVE_UPDATE, ball_vo.dragon_id, ball_vo.dragon_lv, type_id)
			}
		}

		Util.AddClickEvent(this.btn_use, update_event, this, true)
		Util.AddClickEvent(this.btn_update, update_event, this, true)

		this.BindEvent(this.model, DragonBallModel.SELECT_ITEM, (item_index?) => {
			// 点击后更新对应龙珠的描述
			this.model.currn_index = item_index		// 暂时先同步更新Model中的值
			this.currn_index = item_index
			this.UpdateDownUI()
		})

		this.BindEvent(this.model, DragonBallModel.UPDATE_VIEW, (index?, value?, red_state?) => {
			this.UpdateBall(index, value, red_state)
			this.UpdateDownUI()
		})

		this.BindEvent(this.goods_model, GoodsModel.CHANGE_BAG_LIST, () => {
			this.UpdateBalls()
			this.UpdateDownUI()
		})

	}

	public InitView() {
		//ResManager.GetInstance().SetOutsideImageSprite(this, this.img_bg, GameResPath.GetIcon("common", "uisy_023"))
		//ResManager.GetInstance().SetOutsideImageSprite(this, this.img_bg2, GameResPath.GetIconJpg("bigBg", "uilz_003"))

		this.InitBalls()		// 刷新所有龙珠
		this.UpdateDownUI()		// 刷新下方技能显示
	}

	public Remove() {
		if (this.item) {
			this.item.DeleteMe()
			this.item = false
		}

		for (let _ in this.balls_item) {
			var v = this.balls_item[_]
			v.DeleteMe()
		}
		this.balls_item = []
	}

	public InitBalls() {
		let item
		let pos
		for (let i = 0; i < this.model.ball_num; i++) {
			item = this.balls_item[i]
			if (!item) {
				item = new DragonBallItem(this.gp_balls)
				item.Load()
				this.balls_item[i] = item
			}
			pos = this.GetPos(i)
			item.SetPosition(pos.x, pos.y)
			item.SetData(i)
		}

		// 设置当前龙珠为选中状态
		this.balls_item[this.currn_index].ShowSelect(true)
	}

	public UpdateBall(index?, value?, red_state?) {
		if (this.balls_item[index]) {
			this.balls_item[index].UpdateShow(value, red_state)
		}
	}

	// 更新所有龙珠红点显示
	public UpdateBalls() {
		let red = false
		for (let k in this.balls_item) {
			var v = this.balls_item[k]
			red = this.model.GetRedbySet(k)
			v.UpdateShow(null, red)
		}
	}

	public UpdateDownUI() {
		if (this.use_delete_method) {
			return
		}
		let lv = this.model.GetLvbySet(this.currn_index)
		let id = this.model.GetIdbySet(this.currn_index)
		let red = false
		if (this.balls_item[this.currn_index]) {
			red = this.balls_item[this.currn_index].red_state
		}

		let is_new = false
		let is_max = false
		if (lv == 0) {
			is_new = true
			this.lb_tips1.text = "激活预览"
			this.red_use.visible = red
		} else {
			is_new = false
			this.lb_tips1.text = "当前效果"
			this.red_update.visible = red
			if (lv == this.model.max_lv) {
				is_max = true
				this.lb_text.text = "已满级"
				//this.line_btn_update.effectColor = Color(120 / 255, 120 / 255, 120 / 255, 1)
			} else {
				is_max = false
				this.lb_text.text = "升级"
				//this.line_btn_update.effectColor = Color(204 / 255, 118 / 255, 82 / 255, 1)
			}
		}

		this.btn_use.visible = is_new
		this.btn_update.visible = !is_new
		Util.SetImageGray(this.btn_update, is_max)
		this.img_max.visible = (!is_new && is_max)
		this.lb_next.visible = is_new || (!is_max)

		if (lv == 0) {
			lv = 1
		}
		let index = id + "@" + lv
		let skill_info = ErlangParser.GetInstance().Parse(this.congfig_dragonball[index].skill)
		let skill_id = Number(skill_info[0][0])
		let config = this.skill_mgr.getSkillFromConfig(skill_id)
		let skill_vo = this.skill_mgr.getSkill(skill_id)
		let skill_desc_currn = Util.StrToHTML(skill_vo.getDesc(lv))
		let skill_desc_next = Util.StrToHTML(skill_vo.getDesc(lv + 1))

		this.lb_skill.text = config.name + " Lv." + lv
		this.lb_currn.innerHTML = skill_desc_currn
		this.lb_next.innerHTML = skill_desc_next
		this.lb_currn.width = 215
		this.lb_next.width = 215

		this.UpdateItem(is_max)
	}

	public UpdateItem(is_max?) {
		let [type_id, need_count] = this.model.GetUpdateMsg(this.currn_index)
		let now_count = this.goods_model.GetTypeGoodsNum(type_id)
		if (!this.item) {
			this.item = new BaseAwardItem(this.gp_item)
			this.item.Load()
		}
		this.item.SetItemSize(82, 82)
		this.item.SetData(type_id)

		if (is_max) {
			this.lb_cost.visible = false
		} else {
			this.lb_cost.visible = true
			this.lb_cost.text = now_count + "/" + need_count
			this.lb_cost.color = now_count >= need_count ? "#0a953e" : "#ff4f50"
		}
	}

	public ShowEffect(value?) {
		let res_name = "UI_1102_shengjichenggong"
		if (value) {
			res_name = "UI_1102_jihuochenggong"
		}
		//this.AddUIEffect(res_name, this.layer_value, this._gp_effect)
	}

	public GetPos(index?) {
		return ([{ x: -9, y: -195 },
			{ x: 150, y: -105 },
			{ x: 150, y: 80 },
			{ x: -9, y: 170 },
			{ x: -170, y: 80 },
			{ x: -170, y: -105 },
			{ x: -9, y: -15 }])[index]
	}

	img_bg1: Laya.Image
	img_bg2: Laya.Image
	img_bg4: Laya.Image
	img_bg3: Laya.Image
	img_des: Laya.Image
	img_skill: Laya.Image
	img_currn: Laya.Image
	img_next: Laya.Image
	img_arro: Laya.Image
	lb_tips1: Laya.Label
	lb_tips2: Laya.Label
	lb_tips3: Laya.Label
	lb_skill: Laya.Label
	lb_currn: Laya.HTMLDivElement
	lb_next: Laya.HTMLDivElement
	gp_item: Laya.Box
	lb_cost: Laya.Label
	btn_close: Laya.Image
	gp_btns: Laya.Box
	btn_use: Laya.Box
	img_bg11: Laya.Image
	lb_text1: Laya.Label
	red_use: Laya.Image
	btn_update: Laya.Box
	img_bg: Laya.Image
	lb_text: Laya.Label
	red_update: Laya.Image
	gp_balls: Laya.Box
	gp_effect: Laya.Box
	img_max: Laya.Image
	public GetComponents() {
		[
			this.img_bg1,
			this.img_bg2,
			this.img_bg4,
			this.img_bg3,
			this.img_des,
			this.img_skill,
			this.img_currn,
			this.img_next,
			this.img_arro,
			this.lb_tips1,
			this.lb_tips2,
			this.lb_tips3,
			this.lb_skill,
			this.lb_currn,
			this.lb_next,
			this.gp_item,
			this.lb_cost,
			this.btn_close,
			this.gp_btns,
			this.btn_use,
			this.img_bg11,
			this.lb_text1,
			this.red_use,
			this.btn_update,
			this.img_bg,
			this.lb_text,
			this.red_update,
			this.gp_balls,
			this.gp_effect,
			this.img_max,
		]
			= this.GetChildrenByNames([
				"img_bg1",
				"img_bg2",
				"img_bg4",
				"img_bg3",
				"img_des",
				"img_skill",
				"img_currn",
				"img_next",
				"img_arro",
				"lb_tips1",
				"lb_tips2",
				"lb_tips3",
				"lb_skill",
				"lb_currn",
				"lb_next",
				"gp_item",
				"lb_cost",
				"btn_close",
				"gp_btns",
				"btn_use",
				"img_bg11",
				"lb_text1",
				"red_use",
				"btn_update",
				"img_bg",
				"lb_text",
				"red_update",
				"gp_balls",
				"gp_effect",
				"img_max",
			])
	}
}
window["DragonBallView"] = DragonBallView