import { BaseItem1 } from "../common/BaseItem1"
import { EventName } from "../common/EventName"
import { LoopScrowViewMgr } from "../common/LoopScrowViewMgr"
import { ResManager } from "../common/ResManager"
import { FriendModel, FriendEvent } from "../commonModel/FriendModel"
import { GuildActivityModel } from "../commonModel/GuildActivityModel"
import { RedPacketModel, RedPacketEvent } from "../redPacket/RedPacketModel"
import { GlobalEventSystem } from "../util/DeclareGlobalVar"
import { ErlangParser } from "../util/ErlangParser"
import { Util } from "../util/Util"
import { EveningDragonCallItem } from "./EveningDragonCallItem"

export class EveningDragonFightView extends BaseItem1 {
	UpdateRedPacketEffect
	_ac_item
	_ac_rank
	_god_btn
	model
	percentHeight
	percentWidth
	preload_server_config
	updateEmailEffect


	public constructor(parent?) {
		super(parent)

		this.UpdateRedPacketEffect = (is_show?) => {
			this._img_redPacket.visible = is_show
			// Laya.Tween.removeTweens(this._img_redPacket)
			if (this._img_redPacket.visible) {
				// Laya.Tween.get(this._img_redPacket, {loop=true}):to({scaleX=0.8, scaleY=0.8}, 500):wait(250):to({scaleX=1, scaleY=1}, 500).wait(250)
			}
		}
		this.updateEmailEffect = () => {
			// this._img_email.visible = FriendModel.GetInstance( .is_unread_mail)
			// // Laya.Tween.removeTweens(this._img_email)
			// if (this._img_email.visible ) {
			// 	// Laya.Tween.get(this._img_email, {loop=true}):to({scaleX=0.5, scaleY=0.5}, 500):wait(250):to({scaleX=0.6, scaleY=0.6}, 500).wait(250)
			// }
		}
		this.base_file = "evening"
		this.layout_file = "EveningDragonFightView"
		this.model = GuildActivityModel.GetInstance()
		this.percentWidth = 100
		this.percentHeight = 100
		this.preload_server_config = { "config_gfeast": false }
		this.load_callback = () => {

			this.LoadSuccess()
			this.InitEvent()
		}
	}

	public DeleteMe() {

		// if (this._img_redPacket ) {
		// 	Laya.Tween.removeTweens(this._img_redPacket)
		// }
		// if (this._img_email ) {
		// 	Laya.Tween.removeTweens(this._img_email)
		// }
		if (this._ac_rank) {
			this._ac_rank.DeleteMe()
			this._ac_rank = null
		}
		this.ClearGodBtn()
		super.DeleteMe()
	}

	public LoadSuccess() {

		// [ts2lua]lua_resM:GetGameConfigFromCache(this, "Gfeast", false)下标访问可能不正确
		// [ts2lua]lua_resM:GetGameConfigFromCache(this, "Gfeast", false)[56]下标访问可能不正确
		let list = ErlangParser.GetInstance().Parse(ResManager.GetInstance().GetGameConfigFromCache(this, "Gfeast", false)[56]["value"])

		// this._ac_item = eui. new ArrayCollection()
		// this._dg_item.dataProvider = this._ac_item
		// this._dg_item.itemRenderer = EveningDragonCallItem
		// this._ac_item.source = list
		this._ac_rank = new LoopScrowViewMgr()
		this._ac_rank.SetData(this.Content, EveningDragonCallItem, list, this._Scroller1)

		let red = RedPacketModel.GetInstance().GetAllRedStatus()
		this.UpdateRedPacketEffect(red)
		this.CreateGodBtn()
	}

	public InitEvent() {

		Util.AddClickEvent(this._img_redPacket, () => {
			GlobalEventSystem.Fire(EventName.OPEN_VIEW, "RedPacketMainView")
		}
			, this, true)
		Util.AddClickEvent(this._img_email, () => {
			GlobalEventSystem.Fire(EventName.OPEN_FRIEND_VIEW, { index: 1 })
		}
			, this, true)
		this.BindEvent(RedPacketModel.GetInstance(), RedPacketEvent.RED_TIPS, (is_show?) => {
			this.UpdateRedPacketEffect(is_show)
		}
		)
		this.BindEvent(FriendModel.GetInstance(), FriendEvent.EMAIL_ICON_UPDATE, () => {
			this.updateEmailEffect()
		}
		)
		this.BindEvent(FriendModel.GetInstance(), FriendEvent.EMAIL_VIEW_OPEN, () => {
			this.updateEmailEffect()
		}
		)
	}

	public CreateGodBtn() {

		// this._god_btn =  new MainUIGodBtn(this._gp_god)
	}

	public ClearGodBtn() {

		if (this._god_btn) {
			this._god_btn.DeleteMe()
			this._god_btn = null
		}
	}

	_group_tips: Laya.Box
	_Image1: Laya.Image
	_lb_tips: Laya.Label
	_Label1: Laya.Label
	_group_call: Laya.Box
	_Image2: Laya.Image
	_Image3: Laya.Image
	_Scroller1: Laya.Panel
	Content: Laya.HBox
	_gp_redPacket: Laya.Box
	_img_redPacket: Laya.Image
	_gp_email: Laya.Box
	_img_email: Laya.Image
	_gp_god: Laya.Box
	public GetComponents() {
		[
			this._group_tips,
			this._Image1,
			this._lb_tips,
			this._Label1,
			this._group_call,
			this._Image2,
			this._Image3,
			this._Scroller1,
			this.Content,
			this._gp_redPacket,
			this._img_redPacket,
			this._gp_email,
			this._img_email,
			this._gp_god,
		]
			= this.GetChildrenByNames([

				"_group_tips",
				"_Image1",
				"_lb_tips",
				"_Label1",
				"_group_call",
				"_Image2",
				"_Image3",
				"_Scroller1",
				"Content",
				"_gp_redPacket",
				"_img_redPacket",
				"_gp_email",
				"_img_email",
				"_gp_god",
			])
	}
}
window["EveningDragonFightView"]=EveningDragonFightView
