import { BaseView1 } from "../common/BaseView1"
import { Enum_UILayer } from "../common/LayerManager"
import { LuaSoundManager } from "../common/SoundManager"
import { GuildModel, GuildEvent } from "../commonModel/GuildModel"
import { PlatformManager } from "../PlatformManager"
import { Util } from "../util/Util"

export class GuildBoardView extends BaseView1 {
	Clear
	InitEvent
	LoadSuccess
	board_content
	board_limit
	click_bg_toClose
	destroy_callback
	destroy_imm
	is_center
	model
	show_open_movie
	use_background

	public constructor() {
		super()


		this.model = GuildModel.GetInstance();
		this.board_content = "";
		this.board_limit = 40;
		this.base_file = "guild"
		this.layout_file = "GuildBoardView"
		this.layer_value = Enum_UILayer.Top
		this.is_center = true
		this.use_background = true
		this.click_bg_toClose = true
		this.show_open_movie = true
		this.destroy_imm = true
		let local_GuildEvent = GuildEvent
		let local_PlatformManager = PlatformManager.GetInstance()
		let local_Util = Util
		this.load_callback = () => {

			this.LoadSuccess()
			this.InitEvent()
		}

		this.destroy_callback = () => {
			this.Clear()
		}

		this.Clear = () => {

		}

		this.LoadSuccess = () => {
			this._edit_text.maxChars = this.board_limit
			this._edit_text.text = this.board_content
			//this._lb_limit.text = this.board_content.length + "/" + this.board_limit
			this.InputChanged()

			// this._edit_text.onValueChanged.AddListener(() => {
			// 	this._lb_limit.text = this._edit_text.textl.length + "/" + this.board_limit
			// })
			this._edit_text.on(Laya.Event.INPUT,this,this.InputChanged)
		}

		this.InitEvent = () => {
			Util.AddClickEvent(this._btn_go, () => {
				//this.model.announce = this._edit_text.text
				if (this.board_content == this._edit_text.text) {
					this.Close()
					return
				}
				let board_func = () => {
					// var callback = (new_word) => {
					this.model.Fire(local_GuildEvent.REQUEST_PROTO, 40012, "cs", 2, this._edit_text.text)
					this.Close()
					// }
					// HttpMaskWord(this._edit_text.text, callback)
				}

				if (Util.IsQQGame() && local_PlatformManager.is_wx_alpha) {
					local_PlatformManager.MsgSecCheck(this._edit_text.text, board_func)
				} else {
					board_func()
				}
			}
				, this, true)
			Util.AddClickEvent(this._btn_close, () => {
				this.Close()
			}
				, this, true, null, null, null, null, LuaSoundManager.SOUND_UI.CLOSE)
		}


	}

	InputChanged(){
		this._lb_limit.text = this._edit_text.text.length + "/" + this.board_limit
	}

	public Open(...new_args) {

		this.board_content = new_args
		this.board_limit = this.model.GetGuildKVCfg(3)
		super.Open()
	}


	public DeleteMe() {
		this._edit_text.off(Laya.Event.INPUT,this,this.InputChanged)
		super.DeleteMe()
	}

	_Image111: Laya.Image
	_Image4: Laya.Image
	_Group1: Laya.Box
	_Image5: Laya.Image
	_Image6: Laya.Image
	//_text_input: Laya.Image
	Placeholder: Laya.Label
	Text1: Laya.Label
	_btn_go: Laya.Box
	_Image1: Laya.Image
	labelDisplay: Laya.Label
	_btn_close: Laya.Box
	_Image11: Laya.Image
	_edit_text: Laya.TextInput
	Text: Laya.Label
	_lb_limit: Laya.Label
	Image: Laya.Image
	public GetComponents() {
		[
			this._Image111,
			this._Image4,
			this._Group1,
			this._Image5,
			this._Image6,
			//this._text_input,
			this.Placeholder,
			this.Text1,
			this._btn_go,
			this._Image1,
			this.labelDisplay,
			this._btn_close,
			this._Image11,
			this._edit_text,
			//this.Text,
			this._lb_limit,
			this.Image,
		]
			= this.GetChildrenByNames([

				"_Image111",
				"_Image4",
				"_Group1",
				"_Image5",
				"_Image6",
				//"_text_input",
				"Placeholder",
				"Text1",
				"_btn_go",
				"_Image1",
				"labelDisplay",
				"_btn_close",
				"_Image11",
				"_edit_text",
				//"Text",
				"_lb_limit",
				"Image",
			])
	}
}

window["GuildBoardView"]=GuildBoardView