import { BaseView1 } from "./BaseView1"
import { GoodsModel } from "../commonModel/GoodsModel"
import { Mathf } from "../util/Mathf"
import { GlobalTimerQuest, SetSizeDelta, SetAnchoredPosition, Util } from "../util/Util"
import { Vector2 } from "../util/Vector2"
import { BaseAwardItem } from "./BaseAwardItem"
import { Enum_UILayer } from "./LayerManager"
import { table } from "./table"
import { ResManager } from "./ResManager"
import { GameResPath } from "../util/GameResPath"
export class GoodsExpiredView extends BaseView1 {
	CancelTimer
	CloseFunc
	InitEvent
	InitView
	Local_Open
	SetOkText
	award_list
	click_bg_toClose
	close_callback
	close_time
	destroy_imm
	goodsData
	is_center
	timer_id
	use_background
	goods_group: any
	_close_btn: any
	_cancel_btn: any
	ok_btn: any
	Content: any
	_ok_btn
	bg

	public constructor() {
		super()


		this.award_list = [];
		this.close_time = 10;
		let goods_model = GoodsModel.GetInstance()
		let request_proto = GoodsModel.REQUEST_CCMD_EVENT
		this.base_file = "common"
		this.layout_file = "GoodsExpiredView"
		this.layer_value = Enum_UILayer.Activity
		this.use_background = true
		this.click_bg_toClose = true
		this.is_center = true
		this.destroy_imm = true
		this.load_callback = () => {
			if (this.goodsData) {
				this.InitView()
				this.InitEvent()
			}
		}

		this.close_callback = () => {
			this.CloseFunc()
		}

		this.Local_Open = (goodsData?) => {
			this.goodsData = goodsData
			if (this.is_loaded) {
				this.InitView()
				this.InitEvent()
			}
		}

		this.InitView = () => {
			// this.ok_btn,
			// this.close_btn,
			// this.cancelbtn
			// = GetChildGameObjects(this.form, {
			// 		"ok_btn",
			// 		"close_btn",
			// 		"cancelbtn"
			// 	})
			// this.goods_group,
			// this.goods_mask,
			// this._Image4
			// = GetChildTransforms(this.form, {
			// 		"goods_scroller/goods_group/Content",
			// 		"goods_scroller/goods_group",
			// 		"_Group1/_Image4"
			// 	})
			// this.ok_btn_text = this.GetChild("ok_btn/labelDisplay").GetComponent("Text")

			if (!this.goodsData) {
				return
			}
			// this.RegisterMask(this.goods_mask.GetComponent("Image"))
			for (let _tmpi in this.goodsData.goods_list) {
				var vo = this.goodsData.goods_list[_tmpi]
				let goodsbasic = goods_model.GetGoodsBasicByTypeId(vo.type_id)
				if (goodsbasic) {
					let item = new BaseAwardItem(this.Content, null, "Activity")
					item.SetUseMask(true)
					item.Load()
					item.SetData(goodsbasic.type_id, vo.goods_num)
					item.SetScale(0.7)
					table.insert(this.award_list, item)
				}
			}
			this.Content.width = Mathf.Max(this.award_list.length * 102, 532)
			this.CancelTimer()
			this.timer_id = GlobalTimerQuest.AddPeriodQuest(() => {
				this.SetOkText()
			}, 1, -1)
			this._ok_btn.label = "确定(" + this.close_time + ")"

			ResManager.GetInstance().SetTexture(this, this.bg, GameResPath.GetIcon("common", "uisy_023"))
			// if (PlatformMgr.GetInstance().IsEyouEnPlatform() ) {
			// 	SetSizeDelta(this._Image4,120,28)
			// 	SetAnchoredPosition(this._Image4,213,-13)
			// }
		}

		this.InitEvent = () => {
			Util.AddClickEvent(this._close_btn, () => {
				this.Close()
			}
				, this, true)
			Util.AddClickEvent(this._cancel_btn, () => {
				this.Close()
			}
				, this, true)
			Util.AddClickEvent(this._ok_btn, () => {
				goods_model.Fire(request_proto, 15027, "c", 2)
				this.Close()
			}
				, this, true)
		}

		this.CancelTimer = () => {
			if (this.timer_id) {
				GlobalTimerQuest.CancelQuest(this.timer_id)
				this.timer_id = null
			}
		}

		this.SetOkText = () => {
			this.close_time = this.close_time - 1
			if (this.close_time < 0) {
				goods_model.Fire(request_proto, 15027, "c", 2)
				this.Close()
			} else {
				this._ok_btn.label = "确定(" + this.close_time + ")"
			}
		}

		this.CloseFunc = () => {
			this.CancelTimer()
			if (this.award_list) {
				for (let _tmpi in this.award_list) {
					var vo = this.award_list[_tmpi]
					if (vo) {
						vo.DeleteMe()
					}
				}
				this.award_list = []
			}
		}
	}

	public Open(goodsData?) {
		this.Local_Open(goodsData)
		super.Open()
	}
}
window["GoodsExpiredView"] = GoodsExpiredView