import { BaseItem1 } from "../common/BaseItem1"
import { Config } from "../common/Config"
import { Util, SetLocalScale } from "../util/Util"
import { ResManager } from "../common/ResManager"
import { DragonBallModel } from "../commonModel/DragonBallModel"

export class DragonBallItem extends BaseItem1 {
	need_refresh = false
	need_select = false
	cache_select = false
	ball_index
	model
	res_mgr
	red_state
	config_ball_msg = Config.PRELOAD_CLIENT_CONFIG.ConfigDragonBallMsg

	public constructor(parent?) {
		super(parent)

		this.base_file = "dragonBall"
		this.layout_file = "DragonBallItem"

		this.model = DragonBallModel.GetInstance()
		this.res_mgr = ResManager.GetInstance()
		this.ball_index = 1
		this.red_state = false

		this.load_callback = () => {
			this.InitEvent()

			if (this.need_refresh) {
				this.need_refresh = false
				this.InitView()
			}
			if (this.need_select){
				this.need_select = false
				this.ShowSelect(this.cache_select)
			}
		}
	}

	public InitView() {
		let vo = this.model.GetVobySet(this.ball_index)
		let res_name = this.config_ball_msg[vo.dragon_id].res
		this.res_mgr.SetImageSprite(this, this.img_icon, "dragonBall", res_name, true)
		if (vo.dragon_lv == 0) {
			Util.SetImageGray(this.img_icon, true)
		} else {
			//this.AddUIEffect("UI_partner_skillicon_01", this.layer_value, this.gp_effect, null, null, true)
		}
		Util.SetImageGray(this.img_icon, vo.dragon_lv == 0)
		this.red_state = vo.red_state
		this.img_red.visible = vo.red_state

		// 七号珠UI尺寸大一些，特殊处理
		if (this.ball_index == 6) {
			SetLocalScale(this.img_select, 1.3, 1.3, 1)
			this.res_mgr.SetImageSprite(this, this.img_bg, "dragonBall", "ui_forge_12")
		}
	}

	public InitEvent() {
		Util.AddClickEvent(this.img_icon, () => {
			this.model.Fire(DragonBallModel.SELECT_ITEM, this.ball_index)
		}, this, true)

		this.BindEvent(this.model, DragonBallModel.SELECT_ITEM, (item_index?) => {
			if (this.ball_index == item_index) {
				this.img_select.visible = true
			} else {
				this.img_select.visible = false
			}
		})
	}

	public SetData(data?) {
		this.ball_index = data
		
		if (this.is_loaded){
			this.InitView()
		}
		else{
			this.need_refresh = true
		}
	}

	public ShowSelect(value?) {
		if (this.is_loaded){
			this.img_select.visible = value
		}else{
			this.need_select = true
			this.cache_select = value
		}
	}

	public UpdateShow(value?, red?) {
		if (value) {
			Util.SetImageGray(this.img_icon, false)
			this.AddUIEffect("UI_partner_skillicon_01", this.layer_value, this.gp_effect, null, null, true)
		}
		this.img_red.visible = red
		this.red_state = red
	}
	
	img_bg: Laya.Image
	img_icon: Laya.Image
	img_select: Laya.Image
	img_red: Laya.Image
	gp_effect: Laya.Box
	public GetComponents() {
		[
			this.img_bg,
			this.img_icon,
			this.img_select,
			this.img_red,
			this.gp_effect,
		]
			= this.GetChildrenByNames([
				"img_bg",
				"img_icon",
				"img_select",
				"img_red",
				"gp_effect",
			])
	}
}
window["DragonBallItem"] = DragonBallItem