import { BaseItem1 } from "../common/BaseItem1"
import { WordManager } from "../common/WordManager"
import { Util, HtmlColorTxt } from "../util/Util"

export class TitleAttrItem extends BaseItem1 {
	need_refresh_data
	next_attr
	next_attr_lb
	next_gp
	now_attr
	now_attr_lb

	public constructor(parent?) {
		super(parent)


		this.need_refresh_data = false;
		this.base_file = "title"
		this.layout_file = "TitleAttrItem"
		this.load_callback = () => {

			this.LoadSuccess()
		}
	}

	public LoadSuccess() {

		if (this.need_refresh_data) {
			this.need_refresh_data = false
			this.UpdataView()
		}
	}

	public Setdata(now_attr?, next_attr?) {

		this.now_attr = now_attr
		this.next_attr = next_attr
		if (this.is_loaded) {
			this.UpdataView()
		} else {
			this.need_refresh_data = true
		}
	}

	public UpdataView() {
		this.now_attr_lb.style.fontSize=20
		this.now_attr_lb.style.color="#663915"
		let now_str = this.SetNowAttr(this.now_attr)
		this.now_attr_lb.innerHTML = Util.StrToHTML(now_str)
		this.now_attr_lb.width=500
		if (this.next_attr.attr_val == 0) {
			this.next_gp.visible = false
			//SetAnchoredPositionX(this.next_attr_lb,-20)
			//this.now_attr_lb.horizontalCenter = -20
		} else {
			//SetAnchoredPositionX(this.next_attr_lb,-115)
			//this.now_attr_lb.horizontalCenter = -115
			this.next_gp.visible = true
			let next_str = this.SetNextAttr(this.next_attr)
			this.next_attr_lb.style.fontSize=20
			this.next_attr_lb.style.color="#0a953e"
			this.next_attr_lb.innerHTML = Util.StrToHTML(next_str)
			this.next_attr_lb.width=500
		}
	}

	public DeleteMe() {
	}
	public SetNowAttr(now_attr?) {

		let str = null
		let value = null
		value = WordManager.ConvertToPercentValue(Number(now_attr.attr_id), Number(now_attr.attr_val))
		let value_str = String(value)
		//let percent = string.find(value_str, "%")
		str = WordManager.GetProperties(now_attr.attr_id) + "：" + value
		if (value_str.indexOf("%") != -1) {
			str = HtmlColorTxt(str, "'#fe1a1a'")
		} else {
			str = HtmlColorTxt(str, "'#c85a37'")
		}
		return str
	}

	public SetNextAttr(next_attr?) {

		let str = null
		let value = null
		value = WordManager.ConvertToPercentValue(Number(next_attr.attr_id), Number(next_attr.attr_val))
		let value_str = String(value)
		if (value_str.indexOf("%") != -1) {
			str = HtmlColorTxt(value, "'#fe1a1a'")
		} else {
			str = HtmlColorTxt(value, "'#0a953e'") + " "
		}
		return str
	}



	_Image1: Laya.Image
	public GetComponents() {
		[
			this.now_attr_lb,
			this.next_gp,
			this.next_attr_lb,
			this._Image1,
		]
			= this.GetChildrenByNames([

				"now_attr_lb",
				"next_gp",
				"next_attr_lb",
				"_Image1",
			])
	}
}
window["TitleAttrItem"] = TitleAttrItem